'@
            $maintenanceOrchestrationProbeScript = @'
param([string]$Scenario, [string]$RepositoryRoot, [string]$ProbeRoot)
$ErrorActionPreference = 'Stop'
$probeResultPath = Join-Path $ProbeRoot 'result.json'
$probeUtf8 = New-Object Text.UTF8Encoding($false)
try {
    $probeRuntimeText = [IO.File]::ReadAllText(
        (Join-Path $RepositoryRoot 'modules\BRAVO.Maintenance\BRAVO.Maintenance.Runtime.ps1'), [Text.Encoding]::UTF8)
    $probeParseErrors = $null
    $probeAst = [Management.Automation.Language.Parser]::ParseInput($probeRuntimeText, [ref]$null, [ref]$probeParseErrors)
    if (@($probeParseErrors).Count -gt 0) { throw "runtime не парситься: $($probeParseErrors[0].Message)" }
    $probeWrapper = @($probeAst.EndBlock.Statements | Where-Object {
            $_ -is [Management.Automation.Language.FunctionDefinitionAst] -and $_.Name -eq 'Invoke-BRAVOMaintenance'
        }) | Select-Object -First 1
    if ($null -eq $probeWrapper) { throw 'у runtime немає функції Invoke-BRAVOMaintenance' }
    $probeOuterTry = @($probeWrapper.Body.EndBlock.Statements | Where-Object {
            $_ -is [Management.Automation.Language.TryStatementAst]
        }) | Select-Object -First 1
    if ($null -eq $probeOuterTry -or $null -eq $probeOuterTry.Finally) { throw 'у тілі немає зовнішнього try/finally' }
    $probeStatements = @($probeOuterTry.Body.Statements)
    $probeStepsStart = -1
    for ($probeIndex = 0; $probeIndex -lt $probeStatements.Count; $probeIndex++) {
        if ($probeStatements[$probeIndex].Extent.Text -match '^Initialize-BRAVOMaintenanceSteps\s+-Total\s+8\s*$') {
            $probeStepsStart = $probeIndex
            break
        }
    }
    if ($probeStepsStart -lt 0) { throw 'у тілі немає Initialize-BRAVOMaintenanceSteps -Total 8' }

    $probeStubs = [IO.File]::ReadAllText((Join-Path (Split-Path -Parent $ProbeRoot) 'stubs.ps1'), [Text.Encoding]::UTF8)
    $probeStubNames = @{}
    foreach ($probeStubAst in @([Management.Automation.Language.Parser]::ParseInput($probeStubs, [ref]$null, [ref]$null).EndBlock.Statements)) {
        if ($probeStubAst -is [Management.Automation.Language.FunctionDefinitionAst]) { $probeStubNames[$probeStubAst.Name] = $true }
    }
    # Справжні функції тіла, визначені до кроків (крім затінених стабами).
    $probeFunctionTexts = New-Object System.Collections.Generic.List[string]
    for ($probeIndex = 0; $probeIndex -lt $probeStepsStart; $probeIndex++) {
        $probeStatement = $probeStatements[$probeIndex]
        if ($probeStatement -is [Management.Automation.Language.FunctionDefinitionAst] -and
            -not $probeStubNames.ContainsKey($probeStatement.Name)) {
            $probeFunctionTexts.Add($probeStatement.Extent.Text)
        }
    }
    # Дослівна оркестрація до кінця зовнішнього try (включно з exit).
    # Затінені стабами визначення функцій усередині неї замінюються
    # пробілами, інакше вони перевизначили б стаб під час виконання.
    $probeRegionStart = $probeStatements[$probeStepsStart].Extent.StartOffset
    $probeRegionEnd = $probeStatements[$probeStatements.Count - 1].Extent.EndOffset
    $probeRegion = New-Object Text.StringBuilder($probeRuntimeText.Substring($probeRegionStart, $probeRegionEnd - $probeRegionStart))
    foreach ($probeDefinition in @($probeOuterTry.Body.FindAll({
                    param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst]
                }, $true) | Where-Object {
                $_.Extent.StartOffset -ge $probeRegionStart -and $probeStubNames.ContainsKey($_.Name)
            })) {
        $probeLength = $probeDefinition.Extent.EndOffset - $probeDefinition.Extent.StartOffset
        [void]$probeRegion.Remove($probeDefinition.Extent.StartOffset - $probeRegionStart, $probeLength)
        [void]$probeRegion.Insert($probeDefinition.Extent.StartOffset - $probeRegionStart, (' ' * $probeLength))
    }

    $probeEventsPath = Join-Path $ProbeRoot 'events.txt'
    # ThrowInSizeCheck: exchangAPI зупинена до прогону. #349 *InitiallyStopped:
    # BravoWeb зупинена до прогону (поза restart-intent, але має утримуватись).
    # Lifecycle-race: LateStart* і BootRecoveryLateStart стартують зі
    # зупиненими службами, які інший актор запускає вже після знімка.
    $probeServiceTable = if ($Scenario -eq 'ThrowInSizeCheck') {
        "@{ 'BRAVO' = 'Running'; 'exchangAPI' = 'Stopped'; 'BravoWeb' = 'Running' }"
    } elseif (@('LateStartAllStopped', 'LateStartPending', 'LateStartThrow', 'BootRecoveryLateStart', 'LateStartSelfStoppedBeforeStop', 'StartModeAllStoppedLateAfterStop', 'LateStartPendingFailsBeforeStop', 'LateStartStopPendingBeforeStop', 'LateStartStopRejectedSelfStopped', 'LateStartStopPendingStuck', 'StartModeAllStoppedLateAfterMarker', 'AllStoppedExchangeApiUnreadable') -contains $Scenario) {
        "@{ 'BRAVO' = 'Stopped'; 'exchangAPI' = 'Stopped'; 'BravoWeb' = 'Stopped' }"
    } elseif ($Scenario -eq 'LateStartPartial') {
        "@{ 'BRAVO' = 'Running'; 'exchangAPI' = 'Stopped'; 'BravoWeb' = 'Stopped' }"
    } elseif ($Scenario -eq 'InitiallyStartPending' -or $Scenario -eq 'StuckStartPending' -or $Scenario -eq 'InitiallyStartPendingFails') {
        "@{ 'BRAVO' = 'StartPending'; 'exchangAPI' = 'Running'; 'BravoWeb' = 'Running' }"
    } elseif ($Scenario -eq 'LateStartOperatorDisabled') {
        "@{ 'BRAVO' = 'Stopped'; 'exchangAPI' = 'Running'; 'BravoWeb' = 'Stopped' }"
    } elseif ($Scenario -eq 'LateStartAfterMarker') {
        "@{ 'BRAVO' = 'Running'; 'exchangAPI' = 'Running'; 'BravoWeb' = 'Stopped' }"
    } elseif ($Scenario -eq 'PausedServicesPreserved') {
        "@{ 'BRAVO' = 'Running'; 'exchangAPI' = 'Paused'; 'BravoWeb' = 'Paused' }"
    } elseif ($Scenario -eq 'BravoPausedPreserved') {
        "@{ 'BRAVO' = 'Paused'; 'exchangAPI' = 'Running'; 'BravoWeb' = 'Running' }"
    } elseif ($Scenario -eq 'StartModePausedHeld') {
        "@{ 'BRAVO' = 'Running'; 'exchangAPI' = 'Running'; 'BravoWeb' = 'Paused' }"
    } elseif ($Scenario -like '*InitiallyStopped') {
        "@{ 'BRAVO' = 'Running'; 'exchangAPI' = 'Running'; 'BravoWeb' = 'Stopped' }"
    } else {
        "@{ 'BRAVO' = 'Running'; 'exchangAPI' = 'Running'; 'BravoWeb' = 'Running' }"
    }
    $probeScenarioSeed = @(
        ('$script:ProbeEventsPath = ''{0}''' -f $probeEventsPath.Replace("'", "''")),
        ('$probeWorkRoot = ''{0}''' -f $ProbeRoot.Replace("'", "''")),
        ('$script:ProbeServices = {0}' -f $probeServiceTable),
        ('$script:ProbeThrowInSizeCheck = {0}' -f $(if ($Scenario -eq 'ThrowInSizeCheck' -or $Scenario -eq 'LateStartThrow') { '$true' } else { '$false' })),
        ('$script:ProbeStopFailures = {0}' -f $(if ($Scenario -eq 'StopFailure') { "@('BravoWeb')" } else { '@()' })),
        ('$script:ProbeForeignRestartIntent = {0}' -f $(if ($Scenario -like 'StartMode*IntentInitiallyStopped' -or $Scenario -eq 'StartModeSuppressedLateStartInitiallyStopped') { "@('BravoWeb')" } else { '@()' })),
        ('$script:ProbeForeignRestartSuppressed = {0}' -f $(if ($Scenario -eq 'StartModeSuppressedIntentInitiallyStopped' -or $Scenario -eq 'StartModeSuppressedLateStartInitiallyStopped') { '$true' } else { '$false' })),
        '$script:ProbePendingReads = @{}',
        '$script:ProbeMarkerWrites = 0',
        ('$script:ProbeMarkerWriteFailFrom = {0}' -f $(if ($Scenario -eq 'StartModeLateAfterStopMarkerFailInitiallyStopped') { '2' } else { '0' })),
        # StuckStartPending: старт BRAVO не завершується (StartPending назавжди).
        ('$script:ProbeStickyPending = {0}' -f $(if ($Scenario -eq 'StuckStartPending') { "@('BRAVO')" } else { '@()' })),
        # LateStartStopPendingStuck: чужа зупинка не завершується до таймауту.
        ('$script:ProbeStickyStopPending = {0}' -f $(if ($Scenario -eq 'LateStartStopPendingStuck') { "@('BRAVO')" } else { '@()' })),
        ('$script:ProbeStopRejected = {0}' -f $(if ($Scenario -eq 'LateStartStopRejectedSelfStopped') { "@('BRAVO')" } else { '@()' })),
        ('$script:ProbeStartFails = {0}' -f $(if ($Scenario -eq 'LateStartPendingFailsBeforeStop' -or $Scenario -eq 'InitiallyStartPendingFails') { "@('BRAVO')" } else { '@()' })),
        ('$script:ProbeLateStart = {0}' -f $(switch ($Scenario) {
                'LateStartAllStopped' { "@{ 'BRAVO' = 'Running' }" }
                'LateStartSelfStoppedBeforeStop' { "@{ 'BRAVO' = 'Running' }" }
                'LateStartStopPendingBeforeStop' { "@{ 'BRAVO' = 'Running' }" }
                'LateStartStopRejectedSelfStopped' { "@{ 'BRAVO' = 'Running' }" }
                'LateStartStopPendingStuck' { "@{ 'BRAVO' = 'Running' }" }
                'LateStartThrow' { "@{ 'BRAVO' = 'Running' }" }
                'BootRecoveryLateStart' { "@{ 'BRAVO' = 'Running' }" }
                'LateStartOperatorDisabled' { "@{ 'BRAVO' = 'Running' }" }
                'LateStartPartial' { "@{ 'exchangAPI' = 'Running'; 'BravoWeb' = 'StartPending' }" }
                'LateStartPending' { "@{ 'BRAVO' = 'StartPending' }" }
                'LateStartPendingFailsBeforeStop' { "@{ 'BRAVO' = 'StartPending' }" }
                'StartModeLateStartInitiallyStopped' { "@{ 'BravoWeb' = 'Running' }" }
                'StartModeSuppressedLateStartInitiallyStopped' { "@{ 'BravoWeb' = 'Running' }" }
                'PausedAfterSnapshot' { "@{ 'exchangAPI' = 'Paused' }" }
                'AllStoppedExchangeApiUnreadable' { "@{ 'exchangAPI' = 'UNREADABLE' }" }
                default { '@{}' }
            })),
        ('$script:ProbeLateStartBeforeBarrier = {0}' -f $(if ($Scenario -eq 'StartModeLateBeforeBarrierInitiallyStopped') { "@{ 'BravoWeb' = 'Running' }" } else { '@{}' })),
        ('$script:ProbeLateStartBeforeTrace = {0}' -f $(if ($Scenario -eq 'LateStartBeforeTrace') { "@{ 'BRAVO' = 'Running' }" } else { '@{}' })),
        ('$script:ProbePauseBeforeStop = {0}' -f $(switch ($Scenario) {
                'PausedBeforeStop' { "@{ 'exchangAPI' = 'Paused' }" }
                # Інший актор уже зупиняє службу між контрактом і Stop-Service.
                'LateStartStopPendingBeforeStop' { "@{ 'BRAVO' = 'StopPending' }" }
                'LateStartStopPendingStuck' { "@{ 'BRAVO' = 'StopPending' }" }
                default { '@{}' }
            })),
        ('$script:ProbeLateStartAfterStop = {0}' -f $(switch ($Scenario) {
                'StartModeLateAfterStopInitiallyStopped' { "@{ 'BravoWeb' = 'Running' }" }
                'StartModeAllStoppedLateAfterStop' { "@{ 'BravoWeb' = 'Running' }" }
                'StartModeLateAfterStopMarkerFailInitiallyStopped' { "@{ 'BravoWeb' = 'Running' }" }
                'StartModeLatePendingAfterStopInitiallyStopped' { "@{ 'BravoWeb' = 'StartPending' }" }
                # Інший актор піднімає і призупиняє служби вже після фази зупинки.
                'PausePendingBeforeRestart' { "@{ 'exchangAPI' = 'ContinuePending'; 'BravoWeb' = 'PausePending' }" }
                'BravoPausePendingBeforeRestart' { "@{ 'BRAVO' = 'PausePending' }" }
                default { '@{}' }
            })),
        ('$script:ProbeLateStartAfterMarker = {0}' -f $(switch ($Scenario) {
                'LateStartAfterMarker' { "@{ 'BravoWeb' = 'Running' }" }
                'StartModeLateAfterMarkerInitiallyStopped' { "@{ 'BravoWeb' = 'Running' }" }
                # Служба, запущена після знімка, сама зупиняється до фази зупинки.
                'LateStartSelfStoppedBeforeStop' { "@{ 'BRAVO' = 'Stopped' }" }
                # Стан exchangAPI не читається саме у фазі зупинки.
                'ExchangeApiUnreadableAtStop' { "@{ 'exchangAPI' = 'UNREADABLE' }" }
                # Усі служби стояли на обох читаннях; BravoWeb стартує вже після маркера.
                'StartModeAllStoppedLateAfterMarker' { "@{ 'BravoWeb' = 'Running' }" }
                default { '@{}' }
            })),
        # #349: типи запуску служб (лише сценарії утримання; інакше — стаби до #297).
        ('$script:ProbeStartModes = {0}' -f $(switch ($Scenario) {
                'StartModeOther' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'Other'; 'BravoWeb' = 'Manual' }" }
                'StartModeUnreadable' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed' }" }
                'StartModeOtherAndUnreadable' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'Other' }" }
                'StartModeQueryThrows' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'THROW'; 'BravoWeb' = 'Manual' }" }
                'StartModeHeld' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeOperatorDisabled' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'Disabled'; 'BravoWeb' = 'Manual' }" }
                'StartModeOtherInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Other' }" }
                'StartModeHeldInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeOrphanIntentInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeSuppressedIntentInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeLateStartInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeLateAfterMarkerInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeLateAfterStopInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeAllStoppedLateAfterStop' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeLateBeforeBarrierInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeAllStoppedLateAfterMarker' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeLateAfterStopMarkerFailInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeLatePendingAfterStopInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModePausedHeld' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                'StartModeSuppressedLateStartInitiallyStopped' { "@{ 'BRAVO' = 'Automatic'; 'exchangAPI' = 'AutomaticDelayed'; 'BravoWeb' = 'Manual' }" }
                default { '$null' }
            })),
        # #297: результат раннього самовідновлення типів запуску (у production
        # його виставляє преамбула, яку seed замінює).
        '$script:startModeRepairResult = [pscustomobject]@{ Status = ''NoMarker''; Owner = $null; Snapshot = @(); Restored = @(); Failed = @(); Foreign = @() }'
    ) -join "`n"
    # #349: сценарії утримання вмикають реставрацію (після seed) — щоб довести,
    # що fail-closed зупиняє її ДО архіву перед реставрацією й bravocmd.
    $probeRestoreSeed = ''
    if ($Scenario -like 'StartMode*') {
        $probeRestoreSeed = @(
            '$shouldRestore = $true',
            '$ForceRestore = $true',
            '$restoreReason = ''self-test''',
            '$script:BRAVOMaintenanceRestoreStepEnabled = $true',
            '$ARCH_NAME1 = ''self-test_before.mdz''',
            '$SIZES_FILE = Join-Path $probeWorkRoot ''logs\file_sizes_before.csv''',
            '$arcCommonParams = @()',
            '$MODEL_PROJECT_PATH = $MODEL_PATH',
            '$MODEL_NAME = ''self-test''',
            '$MAIN_MODEL_FILE = ''self-test.md''',
            '$BRAVOCMD_PATH = Join-Path $probeWorkRoot ''lims\bravocmd.exe''',
            '[void][IO.Directory]::CreateDirectory($MODEL_PATH)',
            '[IO.File]::WriteAllText((Join-Path $MODEL_PATH ''self-test.md''), ''self-test'')',
            '[void][IO.Directory]::CreateDirectory($LOG_DIR)',
            '[void][IO.Directory]::CreateDirectory($ARC_DIR)'
        ) -join "`n"
    } elseif ($Scenario -eq 'BootRecoveryLateStart') {
        # Профіль boot-recovery: «hold» усіх увімкнених керованих служб.
        $probeRestoreSeed = '$bootRestoreIgnoresWindow = $true'
    } elseif ($Scenario -eq 'LateStartOperatorDisabled') {
        # exchangAPI вимкнена оператором (Disabled) — працює, але не керується.
        $probeRestoreSeed = @('$exchangAPIServiceEnabled = $false', '$exchangAPIServiceDisabled = $true') -join "`n"
    }
    $probeGenerated = @(
        $probeAst.ParamBlock.Extent.Text,
        'function Invoke-BRAVOMaintenanceOrchestrationProbe {',
        'Set-StrictMode -Version 2.0',
        ($probeFunctionTexts -join "`n`n"),
        $probeStubs,
        $probeScenarioSeed,
        [IO.File]::ReadAllText((Join-Path (Split-Path -Parent $ProbeRoot) 'seed.ps1'), [Text.Encoding]::UTF8),
        $probeRestoreSeed,
        'try {',
        $probeRegion.ToString(),
        ('} finally ' + $probeOuterTry.Finally.Extent.Text),
        '}',
        'Invoke-BRAVOMaintenanceOrchestrationProbe'
    ) -join "`n"
    $probeGeneratedPath = Join-Path $ProbeRoot 'runtime.ps1'
    [IO.File]::WriteAllText($probeGeneratedPath, $probeGenerated, (New-Object Text.UTF8Encoding($true)))

    foreach ($probeModule in @('BRAVO.Console', 'BRAVO.ExitCodes', 'BRAVO.Maintenance')) {
        Import-Module -Name (Join-Path $RepositoryRoot "modules\$probeModule\$probeModule.psd1") -Force
    }
    & (Get-Module -Name 'BRAVO.Maintenance') { param($Path) $script:runtimePath = $Path } $probeGeneratedPath
    $global:LASTEXITCODE = 77
    $probeErrors = $null
    $ErrorActionPreference = 'Continue'
    $probeExitCode = Invoke-BRAVOMaintenanceEntrypoint -Parameters @{
        RuntimeRoot = $ProbeRoot
        EntryScriptPath = (Join-Path $ProbeRoot 'BRAVO_MAINTENANCE.ps1')
        NoPause = $true
    } -ErrorVariable probeErrors 2>$null
    $probeEvents = @()
    if (Test-Path -LiteralPath $probeEventsPath -PathType Leaf) {
        $probeEvents = @([IO.File]::ReadAllLines($probeEventsPath, [Text.Encoding]::UTF8))
    }
    $probeResult = [pscustomobject]@{
        ExitCode = [int]$probeExitCode
        ExitCodeName = [string](Get-BRAVOExitCodeName -Code ([int]$probeExitCode))
        Events = $probeEvents
        Errors = @(@($probeErrors) | ForEach-Object { [string]$_ })
    }
} catch {
    $probeResult = [pscustomobject]@{ ProbeError = [string]$_.Exception.Message }
}
[IO.File]::WriteAllText($probeResultPath, ($probeResult | ConvertTo-Json -Compress -Depth 4), $probeUtf8)
'@
            $maintenanceOrchestrationUtf8 = New-Object Text.UTF8Encoding($false)
            [IO.File]::WriteAllText((Join-Path $maintenanceOrchestrationRoot 'stubs.ps1'), $maintenanceOrchestrationStubs, $maintenanceOrchestrationUtf8)
            [IO.File]::WriteAllText((Join-Path $maintenanceOrchestrationRoot 'seed.ps1'), $maintenanceOrchestrationSeed, $maintenanceOrchestrationUtf8)
            $maintenanceOrchestrationProbePath = Join-Path $maintenanceOrchestrationRoot 'probe.ps1'
            [IO.File]::WriteAllText($maintenanceOrchestrationProbePath, $maintenanceOrchestrationProbeScript, (New-Object Text.UTF8Encoding($true)))
            $maintenanceOrchestrationHost = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
            $maintenanceOrchestrationResults = @{}
            foreach ($maintenanceOrchestrationScenario in @('Happy', 'ThrowInSizeCheck', 'StopFailure', 'StartModeOther', 'StartModeUnreadable', 'StartModeOtherAndUnreadable', 'StartModeQueryThrows', 'StartModeHeld', 'StartModeOperatorDisabled', 'StartModeOtherInitiallyStopped', 'StartModeHeldInitiallyStopped', 'StartModeOrphanIntentInitiallyStopped', 'StartModeSuppressedIntentInitiallyStopped', 'LateStartAllStopped', 'LateStartPartial', 'LateStartPending', 'InitiallyStartPending', 'LateStartThrow', 'LateStartOperatorDisabled', 'LateStartAfterMarker', 'StartModeLateStartInitiallyStopped', 'StartModeLateAfterMarkerInitiallyStopped', 'StartModeSuppressedLateStartInitiallyStopped', 'StartModeLateAfterStopInitiallyStopped', 'BootRecoveryLateStart', 'StuckStartPending', 'StartModeLateAfterStopMarkerFailInitiallyStopped', 'StartModeLatePendingAfterStopInitiallyStopped', 'PausedServicesPreserved', 'BravoPausedPreserved', 'StartModePausedHeld', 'PausedAfterSnapshot', 'LateStartBeforeTrace', 'PausedBeforeStop', 'LateStartSelfStoppedBeforeStop', 'StartModeAllStoppedLateAfterStop', 'LateStartPendingFailsBeforeStop', 'InitiallyStartPendingFails', 'LateStartStopPendingBeforeStop', 'LateStartStopRejectedSelfStopped', 'LateStartStopPendingStuck', 'StartModeLateBeforeBarrierInitiallyStopped', 'ExchangeApiUnreadableAtStop', 'PausePendingBeforeRestart', 'BravoPausePendingBeforeRestart', 'StartModeAllStoppedLateAfterMarker', 'AllStoppedExchangeApiUnreadable')) {
                $maintenanceOrchestrationScenarioRoot = Join-Path $maintenanceOrchestrationRoot $maintenanceOrchestrationScenario
                [void][IO.Directory]::CreateDirectory($maintenanceOrchestrationScenarioRoot)
                $null = & $maintenanceOrchestrationHost -NoLogo -NoProfile -NonInteractive `
                    -ExecutionPolicy Bypass -File $maintenanceOrchestrationProbePath `
                    -Scenario $maintenanceOrchestrationScenario -RepositoryRoot $root -ProbeRoot $maintenanceOrchestrationScenarioRoot
                $maintenanceOrchestrationResultPath = Join-Path $maintenanceOrchestrationScenarioRoot 'result.json'
                $maintenanceOrchestrationResults[$maintenanceOrchestrationScenario] = if (Test-Path -LiteralPath $maintenanceOrchestrationResultPath -PathType Leaf) {
                    [IO.File]::ReadAllText($maintenanceOrchestrationResultPath, [Text.Encoding]::UTF8) | ConvertFrom-Json
                } else {
                    [pscustomobject]@{ ProbeError = "проба не записала result.json (код виходу $LASTEXITCODE)" }
                }
            }
            $maintenanceOrchestrationStepPattern = '^STEP (\d+)/(\d+) (.+) (OK|SKIPPED|WARN|FAIL)$'
            $maintenanceOrchestrationEventIndex = {
                param([object[]]$Events, [string]$Pattern)
                for ($eventIndex = 0; $eventIndex -lt $Events.Count; $eventIndex++) {
                    if ([string]$Events[$eventIndex] -match $Pattern) { return $eventIndex }
                }
                return -1
            }
            # Хвіст журналу в БУДЬ-якому сценарії: lock звільняє finally
            # операційного блоку, а за ним — лише справжній зовнішній finally
            # (call site №2 вивантаження власного логу й Wait-BRAVOManualExit з
            # -NoPause, переданим через Invoke-BRAVOMaintenanceEntrypoint).
            $maintenanceOrchestrationFinallyTail = {
                param([object[]]$Events)
                $tailCount = $Events.Count
                return ($tailCount -ge 3 -and
                    [string]$Events[$tailCount - 3] -ceq 'LOCK-EXIT' -and
                    [string]$Events[$tailCount - 2] -ceq 'OWNLOG-UPLOAD' -and
                    [string]$Events[$tailCount - 1] -ceq 'MANUAL-EXIT NoPause=True' -and
                    @($Events | Where-Object { $_ -ceq 'LOCK-EXIT' }).Count -eq 1 -and
                    @($Events | Where-Object { $_ -ceq 'LOCK-ENTER' }).Count -eq 1)
            }

            # (1) Щасливий шлях: рівно 8 кроків у затвердженому порядку [1/8]..[8/8];
            # маркер quiescence до першої зупинки, зупинки — між кроками 2 і 3,
            # старти — між кроками 6 і 7 (finally), маркер прибрано до кроку 7,
            # статус-файл записано з кодом 0, далі lock і зовнішній finally;
            # код завершення 0 (Success).
            $maintenanceHappy = $maintenanceOrchestrationResults['Happy']
            $maintenanceHappyEvents = @()
            $maintenanceHappyStepLabels = @()
            if ($null -eq $maintenanceHappy.PSObject.Properties['ProbeError']) {
                $maintenanceHappyEvents = @($maintenanceHappy.Events | ForEach-Object { [string]$_ })
                $maintenanceHappyStepLabels = @($maintenanceHappyEvents | Where-Object { $_ -match $maintenanceOrchestrationStepPattern } | ForEach-Object {
                        [void]($_ -match $maintenanceOrchestrationStepPattern)
                        "[{0}/{1}] {2}" -f $Matches[1], $Matches[2], $Matches[3]
                    })
            }
            $maintenanceExpectedStepLabels = @(
                '[1/8] Перевірка вільного місця',
                '[2/8] Створення необхідних директорій',
                '[3/8] Зупинка служб',
                '[4/8] Перевірка розмірів .md',
                '[5/8] Реставрація моделі',
                '[6/8] Обробка trace і логів',
                '[7/8] Відновлення стану служб',
                '[8/8] Контроль діапазонів ID'
            )
            $maintenanceOrchestrationHappyStep2 = & $maintenanceOrchestrationEventIndex $maintenanceHappyEvents '^STEP 2/8 '
            $maintenanceOrchestrationHappyStep3 = & $maintenanceOrchestrationEventIndex $maintenanceHappyEvents '^STEP 3/8 '
            $maintenanceOrchestrationHappyStep6 = & $maintenanceOrchestrationEventIndex $maintenanceHappyEvents '^STEP 6/8 '
            $maintenanceOrchestrationHappyStep7 = & $maintenanceOrchestrationEventIndex $maintenanceHappyEvents '^STEP 7/8 '
            $maintenanceOrchestrationHappyMarkerWrite = & $maintenanceOrchestrationEventIndex $maintenanceHappyEvents '^MARKER-WRITE '
            $maintenanceOrchestrationHappyMarkerClear = & $maintenanceOrchestrationEventIndex $maintenanceHappyEvents '^MARKER-CLEAR$'
            $maintenanceOrchestrationHappyStops = @(foreach ($maintenanceOrchestrationServiceName in @('BRAVO', 'exchangAPI', 'BravoWeb')) { & $maintenanceOrchestrationEventIndex $maintenanceHappyEvents ('^STOP {0}$' -f $maintenanceOrchestrationServiceName) })
            $maintenanceOrchestrationHappyStarts = @(foreach ($maintenanceOrchestrationServiceName in @('BRAVO', 'exchangAPI', 'BravoWeb')) { & $maintenanceOrchestrationEventIndex $maintenanceHappyEvents ('^START {0}$' -f $maintenanceOrchestrationServiceName) })
            Test-BRAVOCondition `
                -Condition (
                    $null -eq $maintenanceHappy.PSObject.Properties['ProbeError'] -and
                    $maintenanceHappy.ExitCode -eq 0 -and
                    ($maintenanceHappyStepLabels -join '|') -ceq ($maintenanceExpectedStepLabels -join '|') -and
                    @($maintenanceHappyEvents | Where-Object { $_ -match '^STEP .* FAIL$' }).Count -eq 0 -and
                    $maintenanceOrchestrationHappyMarkerWrite -ge 0 -and $maintenanceOrchestrationHappyMarkerWrite -gt $maintenanceOrchestrationHappyStep2 -and
                    @($maintenanceOrchestrationHappyStops | Where-Object { $_ -le $maintenanceOrchestrationHappyMarkerWrite -or $_ -ge $maintenanceOrchestrationHappyStep3 }).Count -eq 0 -and
                    @($maintenanceOrchestrationHappyStarts | Where-Object { $_ -le $maintenanceOrchestrationHappyStep6 -or $_ -ge $maintenanceOrchestrationHappyStep7 }).Count -eq 0 -and
                    $maintenanceOrchestrationHappyMarkerClear -gt ($maintenanceOrchestrationHappyStarts | Measure-Object -Maximum).Maximum -and
                    $maintenanceOrchestrationHappyMarkerClear -lt $maintenanceOrchestrationHappyStep7 -and
                    (@($maintenanceHappyEvents | Where-Object { $_ -like 'STATUS *' }) -join '|') -ceq 'STATUS 0' -and
                    (& $maintenanceOrchestrationFinallyTail $maintenanceHappyEvents)
                ) `
                -Name "Maintenance/OrchestrationRunsStepsInContractOrder" `
                -Failure "Maintenance на щасливому шляху має виконати рівно [1/8]..[8/8] у затвердженому порядку (зупинка служб між 2 і 3, старт між 6 і 7, маркер до першої зупинки й прибраний до [7/8], статус-файл з кодом 0, потім звільнення lock і зовнішній finally) і завершитися кодом 0; проба: $($maintenanceHappy | ConvertTo-Json -Compress -Depth 4)"

            # (2) Виняток у кроці [4/8]: finally служб усе одно відновлює служби
            # (крок 'Відновлення стану служб'), маркер прибрано, lock звільнено;
            # кроки 4–6 і 8 не рендеряться, а виняток доходить до catch
            # Invoke-BRAVOMaintenanceEntrypoint -> 90 (InternalError). Номер кроку
            # відновлення тут не фіксується: лічильник кроків послідовний, тому
            # після пропущених 4–6 він показує не 7.
            $maintenanceThrow = $maintenanceOrchestrationResults['ThrowInSizeCheck']
            $maintenanceThrowEvents = @()
            if ($null -eq $maintenanceThrow.PSObject.Properties['ProbeError']) {
                $maintenanceThrowEvents = @($maintenanceThrow.Events | ForEach-Object { [string]$_ })
            }
            $maintenanceOrchestrationThrowSizeCheck = & $maintenanceOrchestrationEventIndex $maintenanceThrowEvents '^SIZE-CHECK$'
            $maintenanceOrchestrationThrowRestoreStep = & $maintenanceOrchestrationEventIndex $maintenanceThrowEvents '^STEP \d+/8 Відновлення стану служб (OK|WARN)$'
            $maintenanceOrchestrationThrowStarts = @(foreach ($maintenanceOrchestrationServiceName in @('BRAVO', 'BravoWeb')) { & $maintenanceOrchestrationEventIndex $maintenanceThrowEvents ('^START {0}$' -f $maintenanceOrchestrationServiceName) })
            $maintenanceOrchestrationThrowMarkerClear = & $maintenanceOrchestrationEventIndex $maintenanceThrowEvents '^MARKER-CLEAR$'
            $maintenanceOrchestrationThrowLockExit = & $maintenanceOrchestrationEventIndex $maintenanceThrowEvents '^LOCK-EXIT$'
            Test-BRAVOCondition `
                -Condition (
                    $null -eq $maintenanceThrow.PSObject.Properties['ProbeError'] -and
                    $maintenanceThrow.ExitCode -eq 90 -and
                    $maintenanceThrow.ExitCodeName -eq 'InternalError' -and
                    @($maintenanceThrow.Errors | Where-Object { ([string]$_).Contains('self-test: імітований збій кроку перевірки розмірів .md') }).Count -gt 0 -and
                    $maintenanceOrchestrationThrowSizeCheck -ge 0 -and
                    $maintenanceOrchestrationThrowRestoreStep -gt $maintenanceOrchestrationThrowSizeCheck -and
                    @($maintenanceOrchestrationThrowStarts | Where-Object { $_ -le $maintenanceOrchestrationThrowSizeCheck -or $_ -ge $maintenanceOrchestrationThrowRestoreStep }).Count -eq 0 -and
                    $maintenanceOrchestrationThrowMarkerClear -gt ($maintenanceOrchestrationThrowStarts | Measure-Object -Maximum).Maximum -and
                    $maintenanceOrchestrationThrowMarkerClear -lt $maintenanceOrchestrationThrowRestoreStep -and
                    $maintenanceOrchestrationThrowLockExit -gt $maintenanceOrchestrationThrowRestoreStep -and
                    (& $maintenanceOrchestrationFinallyTail $maintenanceThrowEvents) -and
                    @($maintenanceThrowEvents | Where-Object {
                            $_ -match '^STEP \d+/8 (Перевірка розмірів \.md|Реставрація моделі|Обробка trace і логів|Контроль діапазонів ID) ' -or
                            $_ -eq 'FINAL-REPORT' -or $_ -like 'STATUS *'
                        }).Count -eq 0
                ) `
                -Name "Maintenance/OrchestrationRestoresServicesWhenStepThrows" `
                -Failure "виняток у кроці [4/8] має пройти крізь finally служб: служби, зупинені прогоном, запущено, маркер прибрано, lock звільнено, зовнішній finally виконано, а Invoke-BRAVOMaintenanceEntrypoint повертає 90 (InternalError); проба: $($maintenanceThrow | ConvertTo-Json -Compress -Depth 4)"

            # (3) Служба, що була зупинена ДО прогону (exchangAPI), не потрапляє
            # в маркер, не зупиняється й не запускається відновленням; решта
            # запускається рівно по одному разу.
            Test-BRAVOCondition `
                -Condition (
                    $null -eq $maintenanceThrow.PSObject.Properties['ProbeError'] -and
                    (@($maintenanceThrowEvents | Where-Object { $_ -like 'MARKER-WRITE *' }) -join '|') -ceq 'MARKER-WRITE BRAVO,BravoWeb' -and
                    (@($maintenanceThrowEvents | Where-Object { $_ -like 'START *' } | Sort-Object) -join '|') -ceq 'START BRAVO|START BravoWeb' -and
                    (@($maintenanceThrowEvents | Where-Object { $_ -like 'STOP *' } | Sort-Object) -join '|') -ceq 'STOP BRAVO|STOP BravoWeb' -and
                    (@($maintenanceHappyEvents | Where-Object { $_ -like 'START *' } | Sort-Object) -join '|') -ceq 'START BRAVO|START BravoWeb|START exchangAPI'
                ) `
                -Name "Maintenance/OrchestrationRestoreSkipsServicesStoppedBeforeRun" `
                -Failure "відновлення служб має запускати лише служби, що працювали до прогону (зупинена exchangAPI не запускається); події: $($maintenanceThrowEvents -join ' || ')"

            # (4) Контрольований збій: служба BravoWeb «не зупиняється» (справжній
            # Invoke-ServiceStateChange дочекався таймауту, справжня обробка
            # позначила критичну помилку). Прогін не переривається: усі 8 кроків
            # у тому самому порядку, [3/8] — FAIL, служби, які прогін таки
            # зупинив (BRAVO, exchangAPI), запускаються у finally між [6/8] і
            # [7/8], BravoWeb (лишилась Running) повторно не стартує; статус-файл
            # і код завершення — 60 (MaintenanceFailed), не 0 і не 90.
            $maintenanceStopFailure = $maintenanceOrchestrationResults['StopFailure']
            $maintenanceStopFailureEvents = @()
            $maintenanceStopFailureStepLabels = @()
            if ($null -eq $maintenanceStopFailure.PSObject.Properties['ProbeError']) {
                $maintenanceStopFailureEvents = @($maintenanceStopFailure.Events | ForEach-Object { [string]$_ })
                $maintenanceStopFailureStepLabels = @($maintenanceStopFailureEvents | Where-Object { $_ -match $maintenanceOrchestrationStepPattern } | ForEach-Object {
                        [void]($_ -match $maintenanceOrchestrationStepPattern)
                        "[{0}/{1}] {2}" -f $Matches[1], $Matches[2], $Matches[3]
                    })
            }
            $maintenanceOrchestrationStopFailureStep3 = & $maintenanceOrchestrationEventIndex $maintenanceStopFailureEvents '^STEP 3/8 Зупинка служб FAIL$'
            $maintenanceOrchestrationStopFailureStep6 = & $maintenanceOrchestrationEventIndex $maintenanceStopFailureEvents '^STEP 6/8 '
            $maintenanceOrchestrationStopFailureStep7 = & $maintenanceOrchestrationEventIndex $maintenanceStopFailureEvents '^STEP 7/8 Відновлення стану служб OK$'
            $maintenanceOrchestrationStopFailureStarts = @(foreach ($maintenanceOrchestrationServiceName in @('BRAVO', 'exchangAPI')) { & $maintenanceOrchestrationEventIndex $maintenanceStopFailureEvents ('^START {0}$' -f $maintenanceOrchestrationServiceName) })
            Test-BRAVOCondition `
                -Condition (
                    $null -eq $maintenanceStopFailure.PSObject.Properties['ProbeError'] -and
                    $maintenanceStopFailure.ExitCode -eq 60 -and
                    $maintenanceStopFailure.ExitCodeName -eq 'MaintenanceFailed' -and
                    ($maintenanceStopFailureStepLabels -join '|') -ceq ($maintenanceExpectedStepLabels -join '|') -and
                    (@($maintenanceStopFailureEvents | Where-Object { $_ -match '^STEP .* FAIL$' }) -join '|') -ceq 'STEP 3/8 Зупинка служб FAIL' -and
                    $maintenanceOrchestrationStopFailureStep3 -gt (& $maintenanceOrchestrationEventIndex $maintenanceStopFailureEvents '^STOP-FAIL BravoWeb$') -and
                    @($maintenanceOrchestrationStopFailureStarts | Where-Object { $_ -le $maintenanceOrchestrationStopFailureStep6 -or $_ -ge $maintenanceOrchestrationStopFailureStep7 }).Count -eq 0 -and
                    (@($maintenanceStopFailureEvents | Where-Object { $_ -like 'START *' } | Sort-Object) -join '|') -ceq 'START BRAVO|START exchangAPI' -and
                    (& $maintenanceOrchestrationEventIndex $maintenanceStopFailureEvents '^MARKER-CLEAR$') -gt ($maintenanceOrchestrationStopFailureStarts | Measure-Object -Maximum).Maximum -and
                    (& $maintenanceOrchestrationEventIndex $maintenanceStopFailureEvents '^MARKER-CLEAR$') -lt $maintenanceOrchestrationStopFailureStep7 -and
                    (@($maintenanceStopFailureEvents | Where-Object { $_ -like 'STATUS *' }) -join '|') -ceq 'STATUS 60' -and
                    (& $maintenanceOrchestrationFinallyTail $maintenanceStopFailureEvents)
                ) `
                -Name "Maintenance/OrchestrationRestoresServicesAfterControlledStopFailure" `
                -Failure "контрольований збій зупинки BravoWeb має дати [3/8] FAIL без переривання порядку [1/8]..[8/8], запуск у finally зупинених прогоном BRAVO й exchangAPI, прибраний маркер quiescence, статус-файл і код 60 (MaintenanceFailed), звільнений lock і зовнішній finally; проба: $($maintenanceStopFailure | ConvertTo-Json -Compress -Depth 4)"

            # (4) #349: Maintenance з реставрацією, коли службу неможливо
            # утримати від автостарту (тип запуску Other, нечитаний або збій
            # читання реєстру). Справжня оркестрація: збій утримання видно в
            # журналі (ERROR), реставрацію скасовано fail-closed ДО першої
            # native-операції (архів перед реставрацією, bravocmd), служба не
            # «утримана» мовчки, а решта обслуговування триває за контрактом
            # (кроки [1/8]..[8/8], служби підняті у finally, маркер прибрано).
            # Контроль (Automatic/AutomaticDelayed/Manual і Disabled
            # оператором) доходить до архіву перед реставрацією — сценарії
            # не вакуумні.
            $maintenanceStartModeOutcome = {
                param([string]$Scenario)
                $outcome = $maintenanceOrchestrationResults[$Scenario]
                $events = @()
                $labels = @()
                $probeOk = ($null -ne $outcome -and $null -eq $outcome.PSObject.Properties['ProbeError'])
                if ($probeOk) {
                    $events = @($outcome.Events | ForEach-Object { [string]$_ })
                    $labels = @($events | Where-Object { $_ -match $maintenanceOrchestrationStepPattern } | ForEach-Object {
                            [void]($_ -match $maintenanceOrchestrationStepPattern)
                            "[{0}/{1}] {2}" -f $Matches[1], $Matches[2], $Matches[3]
                        })
                }
                return [pscustomobject]@{
                    ProbeOk = $probeOk
                    ExitCode = $(if ($probeOk) { [int]$outcome.ExitCode } else { -1 })
                    Events = $events
                    StepOrderOk = (($labels -join '|') -ceq ($maintenanceExpectedStepLabels -join '|'))
                    Native = @($events | Where-Object { $_ -like 'NATIVE *' })
                    RestoreCancelled = @($events | Where-Object { $_ -like 'LOG-ERROR ПОМИЛКА: Реставрацію скасовано ДО архівації*' }).Count -eq 1
                    RestoreStepFailed = @($events | Where-Object { $_ -ceq 'STEP 5/8 Реставрація моделі FAIL' }).Count -eq 1
                    ServicesStarted = (@($events | Where-Object { $_ -ceq 'START BRAVO' -or $_ -ceq 'START exchangAPI' -or $_ -ceq 'START BravoWeb' }).Count -eq 3)
                    MarkerCleared = @($events | Where-Object { $_ -ceq 'MARKER-CLEAR' }).Count -eq 1
                    Held = @($events | Where-Object { $_ -like 'HOLD *' } | ForEach-Object { $_.Substring(5) })
                    UnrestorableErrors = @($events | Where-Object { $_ -like 'LOG-ERROR *(#349)' })
                    FirstStop = (& $maintenanceOrchestrationEventIndex $events '^STOP ')
                    UnrestorableErrorIndex = (& $maintenanceOrchestrationEventIndex $events '^LOG-ERROR .*\(#349\)$')
                    MarkerWriteIndex = (& $maintenanceOrchestrationEventIndex $events '^MARKER-WRITE ')
                }
            }
            $maintenanceStartModeFailClosed = {
                param($Outcome)
                return ($Outcome.ProbeOk -and
                    $Outcome.ExitCode -eq 40 -and
                    $Outcome.StepOrderOk -and
                    @($Outcome.Native).Count -eq 0 -and
                    $Outcome.RestoreCancelled -and
                    $Outcome.RestoreStepFailed -and
                    $Outcome.ServicesStarted -and
                    $Outcome.MarkerCleared -and
                    (& $maintenanceOrchestrationFinallyTail $Outcome.Events))
            }
            $maintenanceStartModeOther = & $maintenanceStartModeOutcome 'StartModeOther'
            Test-BRAVOCondition `
                -Condition (
                    (& $maintenanceStartModeFailClosed $maintenanceStartModeOther) -and
                    @($maintenanceStartModeOther.UnrestorableErrors).Count -eq 1 -and
                    [string]$maintenanceStartModeOther.UnrestorableErrors[0] -like '*exchangAPI (тип запуску: Other)*' -and
                    $maintenanceStartModeOther.UnrestorableErrorIndex -ge 0 -and
                    $maintenanceStartModeOther.UnrestorableErrorIndex -lt $maintenanceStartModeOther.MarkerWriteIndex -and
                    $maintenanceStartModeOther.MarkerWriteIndex -lt $maintenanceStartModeOther.FirstStop -and
                    ($maintenanceStartModeOther.Held -join ',') -ceq 'BRAVO,BravoWeb'
                ) `
                -Name "Maintenance/StartModeOtherCancelsRestoreFailClosed" `
                -Failure ("Maintenance (#349): служба з типом запуску Other має дати ERROR до зупинки служб і скасувати реставрацію ДО архіву й bravocmd (без native-операцій), а решта обслуговування — тривати; події: " + ($maintenanceStartModeOther.Events -join ' | '))
            $maintenanceStartModeUnreadable = & $maintenanceStartModeOutcome 'StartModeUnreadable'
            Test-BRAVOCondition `
                -Condition (
                    (& $maintenanceStartModeFailClosed $maintenanceStartModeUnreadable) -and
                    @($maintenanceStartModeUnreadable.UnrestorableErrors).Count -eq 1 -and
                    [string]$maintenanceStartModeUnreadable.UnrestorableErrors[0] -like '*BravoWeb (тип запуску: не прочитано)*' -and
                    ($maintenanceStartModeUnreadable.Held -join ',') -ceq 'BRAVO,exchangAPI'
                ) `
                -Name "Maintenance/StartModeUnreadableCancelsRestoreFailClosed" `
                -Failure ("Maintenance (#349): служба з нечитаним типом запуску має дати ERROR і скасувати реставрацію ДО архіву й bravocmd; події: " + ($maintenanceStartModeUnreadable.Events -join ' | '))
            $maintenanceStartModeOtherAndUnreadable = & $maintenanceStartModeOutcome 'StartModeOtherAndUnreadable'
            Test-BRAVOCondition `
                -Condition (
                    (& $maintenanceStartModeFailClosed $maintenanceStartModeOtherAndUnreadable) -and
                    @($maintenanceStartModeOtherAndUnreadable.UnrestorableErrors).Count -eq 1 -and
                    [string]$maintenanceStartModeOtherAndUnreadable.UnrestorableErrors[0] -like '*exchangAPI (тип запуску: Other)*' -and
                    [string]$maintenanceStartModeOtherAndUnreadable.UnrestorableErrors[0] -like '*BravoWeb (тип запуску: не прочитано)*' -and
                    ($maintenanceStartModeOtherAndUnreadable.Held -join ',') -ceq 'BRAVO'
                ) `
                -Name "Maintenance/StartModeSeveralUnrestorableAllReported" `
                -Failure ("Maintenance (#349): кілька неутримуваних служб мають бути названі всі в одному ERROR, реставрацію скасовано ДО архіву й bravocmd; події: " + ($maintenanceStartModeOtherAndUnreadable.Events -join ' | '))
            $maintenanceStartModeQueryThrows = & $maintenanceStartModeOutcome 'StartModeQueryThrows'
            Test-BRAVOCondition `
                -Condition (
                    (& $maintenanceStartModeFailClosed $maintenanceStartModeQueryThrows) -and
                    @($maintenanceStartModeQueryThrows.Held).Count -eq 0 -and
                    @($maintenanceStartModeQueryThrows.Events | Where-Object { $_ -like 'LOG-WARNING Не вдалося утримати служби від автостарту (#297): знімок типів запуску не знято:*' }).Count -eq 1
                ) `
                -Name "Maintenance/StartModeQueryFailureCancelsRestoreFailClosed" `
                -Failure ("Maintenance (#349): збій читання типу запуску з реєстру має бути збоєм утримання і скасувати реставрацію ДО архіву й bravocmd; події: " + ($maintenanceStartModeQueryThrows.Events -join ' | '))
            $maintenanceStartModeHeld = & $maintenanceStartModeOutcome 'StartModeHeld'
            $maintenanceStartModeOperatorDisabled = & $maintenanceStartModeOutcome 'StartModeOperatorDisabled'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceStartModeHeld.ProbeOk -and $maintenanceStartModeHeld.StepOrderOk -and
                    ($maintenanceStartModeHeld.Held -join ',') -ceq 'BRAVO,exchangAPI,BravoWeb' -and
                    @($maintenanceStartModeHeld.UnrestorableErrors).Count -eq 0 -and
                    -not $maintenanceStartModeHeld.RestoreCancelled -and
                    ($maintenanceStartModeHeld.Native -join '|') -ceq 'NATIVE Архівація моделі перед реставрацією' -and
                    $maintenanceStartModeOperatorDisabled.ProbeOk -and $maintenanceStartModeOperatorDisabled.StepOrderOk -and
                    ($maintenanceStartModeOperatorDisabled.Held -join ',') -ceq 'BRAVO,BravoWeb' -and
                    @($maintenanceStartModeOperatorDisabled.UnrestorableErrors).Count -eq 0 -and
                    -not $maintenanceStartModeOperatorDisabled.RestoreCancelled -and
                    ($maintenanceStartModeOperatorDisabled.Native -join '|') -ceq 'NATIVE Архівація моделі перед реставрацією'
                ) `
                -Name "Maintenance/StartModeHeldOrOperatorDisabledReachesRestore" `
                -Failure ("Maintenance (#349): Automatic/AutomaticDelayed/Manual утримуються, Disabled оператором не змінюється й не є збоєм — реставрація доходить до архіву перед реставрацією; події: " + ($maintenanceStartModeHeld.Events -join ' | ') + ' || ' + ($maintenanceStartModeOperatorDisabled.Events -join ' | '))
            # #349 (рев'ю): служба, зупинена ДО прогону, при запланованій реставрації
            # теж утримується й перевіряється (зупинка діє за фактичним станом, тож
            # служба, що встигла запуститися, інакше була б поза знімком і бар'єрами),
            # але без наміру перезапуску: у finally вона не стартує.
            $maintenanceStartModeOtherStopped = & $maintenanceStartModeOutcome 'StartModeOtherInitiallyStopped'
            $maintenanceStartModeHeldStopped = & $maintenanceStartModeOutcome 'StartModeHeldInitiallyStopped'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceStartModeOtherStopped.ProbeOk -and
                    $maintenanceStartModeOtherStopped.ExitCode -eq 40 -and
                    $maintenanceStartModeOtherStopped.StepOrderOk -and
                    @($maintenanceStartModeOtherStopped.Native).Count -eq 0 -and
                    $maintenanceStartModeOtherStopped.RestoreCancelled -and
                    @($maintenanceStartModeOtherStopped.UnrestorableErrors).Count -eq 1 -and
                    [string]$maintenanceStartModeOtherStopped.UnrestorableErrors[0] -like '*BravoWeb (тип запуску: Other)*' -and
                    (@($maintenanceStartModeOtherStopped.Events | Where-Object { $_ -like 'START *' }) -join ',') -ceq 'START BRAVO,START exchangAPI' -and
                    $maintenanceStartModeHeldStopped.ProbeOk -and $maintenanceStartModeHeldStopped.StepOrderOk -and
                    @($maintenanceStartModeHeldStopped.Events | Where-Object { $_ -ceq 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb' }).Count -eq 1 -and
                    (@($maintenanceStartModeHeldStopped.Events | Where-Object { $_ -like 'MARKER-NO-RESTART *' }) -join ',') -ceq 'MARKER-NO-RESTART BravoWeb' -and
                    ($maintenanceStartModeHeldStopped.Held -join ',') -ceq 'BRAVO,exchangAPI,BravoWeb' -and
                    ($maintenanceStartModeHeldStopped.Native -join '|') -ceq 'NATIVE Архівація моделі перед реставрацією' -and
                    @($maintenanceStartModeHeldStopped.Events | Where-Object { $_ -ceq 'START BravoWeb' }).Count -eq 0
                ) `
                -Name "Maintenance/StartModeInitiallyStoppedServiceIsHeldWithoutRestart" `
                -Failure ("Maintenance (#349): служба, зупинена до прогону, при запланованій реставрації має утримуватись і перевірятись (Other -> fail-closed), але не стартувати у finally; події: " + ($maintenanceStartModeOtherStopped.Events -join ' | ') + ' || ' + ($maintenanceStartModeHeldStopped.Events -join ' | '))
            # #349 (рев'ю): служба, яку зупинив аварійно перерваний прогін із наміром
            # перезапуску, не втрачає цей намір, коли маркер перезаписується: вона
            # утримується з RestartIntent і стартує у finally. Маркер із
            # restartSuppressed (свідома відмова від перезапуску) не успадковується.
            $maintenanceStartModeOrphanIntent = & $maintenanceStartModeOutcome 'StartModeOrphanIntentInitiallyStopped'
            $maintenanceStartModeSuppressedIntent = & $maintenanceStartModeOutcome 'StartModeSuppressedIntentInitiallyStopped'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceStartModeOrphanIntent.ProbeOk -and $maintenanceStartModeOrphanIntent.StepOrderOk -and
                    @($maintenanceStartModeOrphanIntent.Events | Where-Object { $_ -ceq 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb' }).Count -eq 1 -and
                    @($maintenanceStartModeOrphanIntent.Events | Where-Object { $_ -like 'MARKER-NO-RESTART *' }).Count -eq 0 -and
                    ($maintenanceStartModeOrphanIntent.Held -join ',') -ceq 'BRAVO,exchangAPI,BravoWeb' -and
                    $maintenanceStartModeOrphanIntent.ServicesStarted -and
                    $maintenanceStartModeOrphanIntent.MarkerCleared -and
                    $maintenanceStartModeSuppressedIntent.ProbeOk -and $maintenanceStartModeSuppressedIntent.StepOrderOk -and
                    (@($maintenanceStartModeSuppressedIntent.Events | Where-Object { $_ -like 'MARKER-NO-RESTART *' }) -join ',') -ceq 'MARKER-NO-RESTART BravoWeb' -and
                    @($maintenanceStartModeSuppressedIntent.Events | Where-Object { $_ -ceq 'START BravoWeb' }).Count -eq 0
                ) `
                -Name "Maintenance/StartModeOrphanRestartIntentSurvivesMarkerRewrite" `
                -Failure ("Maintenance (#349): намір перезапуску служби, зупиненої аварійно перерваним прогоном, має зберегтися в маркері й служба має стартувати у finally, а restartSuppressed — не успадковуватись; події: " + ($maintenanceStartModeOrphanIntent.Events -join ' | ') + ' || ' + ($maintenanceStartModeSuppressedIntent.Events -join ' | '))

            # Lifecycle-інваріант (усі сценарії оркестрації): Maintenance зупиняє
            # службу ЛИШЕ коли чинний ownership-маркер уже містить її з наміром
            # перезапуску, і кожну зупинену службу запускає у finally. Служба,
            # яку інший актор запустив після початкового знімка, інакше
            # зупинялася б поза маркером/утриманням і лишалася б лежати.
            $maintenanceLifecycleViolations = @()
            foreach ($maintenanceLifecycleScenario in @($maintenanceOrchestrationResults.Keys | Sort-Object)) {
                $maintenanceLifecycleOutcome = $maintenanceOrchestrationResults[$maintenanceLifecycleScenario]
                if ($null -ne $maintenanceLifecycleOutcome.PSObject.Properties['ProbeError']) {
                    $maintenanceLifecycleViolations += "${maintenanceLifecycleScenario}: проба не виконалась ($($maintenanceLifecycleOutcome.ProbeError))"
                    continue
                }
                $maintenanceLifecycleIntent = @{}
                $maintenanceLifecycleStopped = @()
                $maintenanceLifecycleStarted = @()
                foreach ($maintenanceLifecycleEvent in @($maintenanceLifecycleOutcome.Events | ForEach-Object { [string]$_ })) {
                    if ($maintenanceLifecycleEvent -like 'MARKER-WRITE *') {
                        $maintenanceLifecycleIntent = @{}
                        foreach ($maintenanceLifecycleName in $maintenanceLifecycleEvent.Substring(13).Split(',')) {
                            if ($maintenanceLifecycleName) { $maintenanceLifecycleIntent[$maintenanceLifecycleName] = $true }
                        }
                    } elseif ($maintenanceLifecycleEvent -like 'MARKER-NO-RESTART *') {
                        $maintenanceLifecycleIntent[$maintenanceLifecycleEvent.Substring(18)] = $false
                    } elseif ($maintenanceLifecycleEvent -like 'STOP *') {
                        $maintenanceLifecycleName = $maintenanceLifecycleEvent.Substring(5)
                        $maintenanceLifecycleStopped += $maintenanceLifecycleName
                        if (-not ($maintenanceLifecycleIntent.ContainsKey($maintenanceLifecycleName) -and $maintenanceLifecycleIntent[$maintenanceLifecycleName])) {
                            $maintenanceLifecycleViolations += "${maintenanceLifecycleScenario}: STOP $maintenanceLifecycleName без маркера з наміром перезапуску"
                        }
                    } elseif ($maintenanceLifecycleEvent -like 'START *') {
                        $maintenanceLifecycleStarted += $maintenanceLifecycleEvent.Substring(6)
                    } elseif ($maintenanceLifecycleEvent -match '^LATE-START (\S+) (Running|StartPending|Paused|PausePending|ContinuePending)$' -and $maintenanceLifecycleStopped -contains $Matches[1]) {
                        # Зупинену прогоном службу знову підняв інший актор — зупиненою вона не лишилась.
                        $maintenanceLifecycleStarted += $Matches[1]
                    }
                }
                foreach ($maintenanceLifecycleName in $maintenanceLifecycleStopped) {
                    if ($maintenanceLifecycleStarted -notcontains $maintenanceLifecycleName) {
                        $maintenanceLifecycleViolations += "${maintenanceLifecycleScenario}: $maintenanceLifecycleName зупинено, але не запущено у finally"
                    }
                }
            }
            Test-BRAVOCondition `
                -Condition ($maintenanceLifecycleViolations.Count -eq 0) `
                -Name "Maintenance/LifecycleEveryStopHasRestartContract" `
                -Failure ("Maintenance: кожна зупинка служби має йти після ownership-маркера з наміром її перезапуску, а зупинена служба — стартувати у finally; порушення: " + ($maintenanceLifecycleViolations -join ' | '))

            # Lifecycle-race (не-restore прогін): служба, зупинена на момент
            # початкового знімка, яку інший актор запустив до фази зупинки,
            # потрапляє в маркер із наміром перезапуску, зупиняється (крок
            # [3/8] не SKIPPED) і запускається у finally. exchangAPI
            # зупиняється за свіжим, а не закешованим на старті станом. Код 10
            # (SuccessWithWarnings) — від попередження про неактивні на старті
            # служби; інших WARNING немає.
            # Намір перезапуску пізно запущеної служби записується не за знімком
            # перед фазою зупинки, а за свіжим станом безпосередньо перед її
            # зупинкою: перший маркер містить службу без наміру, наступний — з
            # наміром, і лише після нього йде STOP.
            $maintenanceMarkerTrail = {
                param([string[]]$Events)
                @($Events | Where-Object { $_ -like 'MARKER-WRITE *' -or $_ -like 'MARKER-NO-RESTART *' }) -join '|'
            }
            # Служби без наміру перезапуску в ОСТАННЬОМУ записаному маркері.
            $maintenanceFinalMarkerNoRestart = {
                param([string[]]$Events)
                $finalMarkerIndex = -1
                for ($eventIndex = 0; $eventIndex -lt $Events.Count; $eventIndex++) {
                    if ($Events[$eventIndex] -like 'MARKER-WRITE *') { $finalMarkerIndex = $eventIndex }
                }
                $finalNoRestart = @()
                if ($finalMarkerIndex -ge 0) {
                    for ($eventIndex = $finalMarkerIndex + 1; $eventIndex -lt $Events.Count -and $Events[$eventIndex] -like 'MARKER-NO-RESTART *'; $eventIndex++) {
                        $finalNoRestart += $Events[$eventIndex].Substring('MARKER-NO-RESTART '.Length)
                    }
                }
                $finalNoRestart -join ','
            }
            $maintenanceLateAll = & $maintenanceStartModeOutcome 'LateStartAllStopped'
            $maintenanceLatePartial = & $maintenanceStartModeOutcome 'LateStartPartial'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceLateAll.ProbeOk -and $maintenanceLateAll.ExitCode -eq 10 -and $maintenanceLateAll.StepOrderOk -and
                    (& $maintenanceMarkerTrail $maintenanceLateAll.Events) -ceq 'MARKER-WRITE BRAVO|MARKER-NO-RESTART BRAVO|MARKER-WRITE BRAVO' -and
                    (& $maintenanceOrchestrationEventIndex $maintenanceLateAll.Events '^STOP BRAVO$') -gt ([array]::LastIndexOf([string[]]$maintenanceLateAll.Events, 'MARKER-WRITE BRAVO')) -and
                    @($maintenanceLateAll.Events | Where-Object { $_ -ceq 'STEP 3/8 Зупинка служб OK' }).Count -eq 1 -and
                    (@($maintenanceLateAll.Events | Where-Object { $_ -like 'STOP *' -or $_ -like 'START *' }) -join '|') -ceq 'STOP BRAVO|START BRAVO' -and
                    $maintenanceLateAll.MarkerCleared -and
                    $maintenanceLatePartial.ProbeOk -and $maintenanceLatePartial.ExitCode -eq 10 -and $maintenanceLatePartial.StepOrderOk -and
                    (& $maintenanceMarkerTrail $maintenanceLatePartial.Events) -ceq 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb|MARKER-NO-RESTART exchangAPI|MARKER-NO-RESTART BravoWeb|MARKER-WRITE BRAVO,exchangAPI,BravoWeb|MARKER-NO-RESTART exchangAPI|MARKER-WRITE BRAVO,exchangAPI,BravoWeb' -and
                    (& $maintenanceOrchestrationEventIndex $maintenanceLatePartial.Events '^STOP exchangAPI$') -gt ([array]::LastIndexOf([string[]]$maintenanceLatePartial.Events, 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb')) -and
                    (@($maintenanceLatePartial.Events | Where-Object { $_ -like 'STOP *' } | Sort-Object) -join '|') -ceq 'STOP BRAVO|STOP BravoWeb|STOP exchangAPI' -and
                    (@($maintenanceLatePartial.Events | Where-Object { $_ -like 'START *' } | Sort-Object) -join '|') -ceq 'START BRAVO|START BravoWeb|START exchangAPI' -and
                    @($maintenanceLatePartial.Events | Where-Object { $_ -like 'LOG-WARNING*' -and $_ -notlike 'LOG-WARNING До початку maintenance не запущені служби:*' }).Count -eq 0 -and
                    $maintenanceLatePartial.MarkerCleared
                ) `
                -Name "Maintenance/LifecycleLateStartBeforeStopIsOwnedAndRestarted" `
                -Failure ("Maintenance: служба, запущена іншим актором після початкового знімка, має отримати намір перезапуску в маркері безпосередньо перед зупинкою за свіжим станом і бути запущеною у finally; події: " + ($maintenanceLateAll.Events -join ' | ') + ' || ' + ($maintenanceLatePartial.Events -join ' | '))

            # Служба, запущена після знімка, але зупинена іншим актором ще до
            # фази зупинки, наміру перезапуску не отримує: Maintenance її не
            # зупиняє й не запускає, а маркер лишає її без наміру.
            $maintenanceLateSelfStopped = & $maintenanceStartModeOutcome 'LateStartSelfStoppedBeforeStop'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceLateSelfStopped.ProbeOk -and $maintenanceLateSelfStopped.StepOrderOk -and
                    @($maintenanceLateSelfStopped.Events | Where-Object { $_ -like 'STOP*BRAVO' -or $_ -ceq 'START BRAVO' }).Count -eq 0 -and
                    (& $maintenanceMarkerTrail $maintenanceLateSelfStopped.Events) -ceq 'MARKER-WRITE BRAVO|MARKER-NO-RESTART BRAVO' -and
                    (& $maintenanceFinalMarkerNoRestart $maintenanceLateSelfStopped.Events) -ceq 'BRAVO'
                ) `
                -Name "Maintenance/LifecycleLateStartIntentRecordedOnlyAtStop" `
                -Failure ("Maintenance: служба, запущена після знімка й зупинена іншим актором до фази зупинки, не повинна отримати намір перезапуску (Maintenance її не зупиняла й не запускає); події: " + ($maintenanceLateSelfStopped.Events -join ' | '))

            # Служба у StartPending, намір якої записано перед зупинкою, але старт
            # якої завершився невдачею (сама стала Stopped) ще до Stop-Service:
            # Maintenance її не зупиняла, тож намір знято й з маркера, а finally
            # її не запускає.
            $maintenanceLatePendingFails = & $maintenanceStartModeOutcome 'LateStartPendingFailsBeforeStop'
            $maintenanceInitialPendingFails = & $maintenanceStartModeOutcome 'InitiallyStartPendingFails'
            $maintenanceLateStopPending = & $maintenanceStartModeOutcome 'LateStartStopPendingBeforeStop'
            $maintenanceLateStopRejected = & $maintenanceStartModeOutcome 'LateStartStopRejectedSelfStopped'
            $maintenanceLateStopPendingStuck = & $maintenanceStartModeOutcome 'LateStartStopPendingStuck'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceLatePendingFails.ProbeOk -and $maintenanceLatePendingFails.StepOrderOk -and
                    @($maintenanceLatePendingFails.Events | Where-Object { $_ -like 'STOP*BRAVO' -or $_ -ceq 'START BRAVO' }).Count -eq 0 -and
                    (& $maintenanceMarkerTrail $maintenanceLatePendingFails.Events) -ceq 'MARKER-WRITE BRAVO|MARKER-NO-RESTART BRAVO|MARKER-WRITE BRAVO|MARKER-WRITE BRAVO|MARKER-NO-RESTART BRAVO' -and
                    (& $maintenanceFinalMarkerNoRestart $maintenanceLatePendingFails.Events) -ceq 'BRAVO' -and
                    # Характеризація до #360: намір, що був на старті (StartPending
                    # на початковому знімку), не знімається — finally запускає службу.
                    $maintenanceInitialPendingFails.ProbeOk -and $maintenanceInitialPendingFails.StepOrderOk -and
                    @($maintenanceInitialPendingFails.Events | Where-Object { $_ -ceq 'START BRAVO' }).Count -eq 1 -and
                    (& $maintenanceFinalMarkerNoRestart $maintenanceInitialPendingFails.Events) -ceq '' -and
                    # Службу вже зупиняє інший актор (StopPending): Stop-Service не
                    # надсилається, намір знято, finally її не запускає.
                    $maintenanceLateStopPending.ProbeOk -and $maintenanceLateStopPending.StepOrderOk -and
                    @($maintenanceLateStopPending.Events | Where-Object { $_ -like 'STOP*BRAVO' -or $_ -ceq 'START BRAVO' }).Count -eq 0 -and
                    (& $maintenanceFinalMarkerNoRestart $maintenanceLateStopPending.Events) -ceq 'BRAVO' -and
                    # Stop-Service відхилено, а службу зупинив інший актор: зупинку
                    # Maintenance собі не приписує, намір знято.
                    $maintenanceLateStopRejected.ProbeOk -and $maintenanceLateStopRejected.StepOrderOk -and
                    @($maintenanceLateStopRejected.Events | Where-Object { $_ -ceq 'STOP-REJECTED BRAVO' }).Count -eq 1 -and
                    @($maintenanceLateStopRejected.Events | Where-Object { $_ -ceq 'START BRAVO' }).Count -eq 0 -and
                    (& $maintenanceFinalMarkerNoRestart $maintenanceLateStopRejected.Events) -ceq 'BRAVO' -and
                    # Чужа зупинка (StopPending) не завершилась до таймауту: операція
                    # невдала, але Stop-Service не надсилався — намір теж знято.
                    $maintenanceLateStopPendingStuck.ProbeOk -and $maintenanceLateStopPendingStuck.StepOrderOk -and
                    @($maintenanceLateStopPendingStuck.Events | Where-Object { $_ -like 'STOP*BRAVO' -or $_ -ceq 'START BRAVO' }).Count -eq 0 -and
                    (& $maintenanceFinalMarkerNoRestart $maintenanceLateStopPendingStuck.Events) -ceq 'BRAVO'
                ) `
                -Name "Maintenance/LifecycleIntentRevokedWhenServiceStopsByItself" `
                -Failure ("Maintenance: намір перезапуску, записаний перед зупинкою, має бути знятий (і в маркері), якщо служба зупинилася сама до Stop-Service — finally її не запускає; події: " + ($maintenanceLatePendingFails.Events -join ' | ') + ' || ' + ($maintenanceInitialPendingFails.Events -join ' | ') + ' || ' + ($maintenanceLateStopPending.Events -join ' | ') + ' || ' + ($maintenanceLateStopRejected.Events -join ' | ') + ' || ' + ($maintenanceLateStopPendingStuck.Events -join ' | '))

            # #287: служба у StartPending (на момент знімка або після нього)
            # зупиняється після завершення старту (stop не надсилається, поки SCM
            # його відхиляє) і запускається у finally; ротація trace не
            # починається на службі, що саме піднімається.
            $maintenanceLatePending = & $maintenanceStartModeOutcome 'LateStartPending'
            $maintenanceInitialPending = & $maintenanceStartModeOutcome 'InitiallyStartPending'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceLatePending.ProbeOk -and $maintenanceLatePending.ExitCode -eq 10 -and $maintenanceLatePending.StepOrderOk -and
                    (& $maintenanceMarkerTrail $maintenanceLatePending.Events) -ceq 'MARKER-WRITE BRAVO|MARKER-NO-RESTART BRAVO|MARKER-WRITE BRAVO' -and
                    (@($maintenanceLatePending.Events | Where-Object { $_ -like 'STOP*' -or $_ -like 'START *' }) -join '|') -ceq 'STOP BRAVO|START BRAVO' -and
                    @($maintenanceLatePending.Events | Where-Object { $_ -ceq 'STEP 3/8 Зупинка служб OK' }).Count -eq 1 -and
                    $maintenanceInitialPending.ProbeOk -and $maintenanceInitialPending.ExitCode -eq 0 -and $maintenanceInitialPending.StepOrderOk -and
                    @($maintenanceInitialPending.Events | Where-Object { $_ -like 'STOP-REFUSED*' }).Count -eq 0 -and
                    (@($maintenanceInitialPending.Events | Where-Object { $_ -like 'STOP *' } | Sort-Object) -join '|') -ceq 'STOP BRAVO|STOP BravoWeb|STOP exchangAPI' -and
                    (@($maintenanceInitialPending.Events | Where-Object { $_ -like 'START *' } | Sort-Object) -join '|') -ceq 'START BRAVO|START BravoWeb|START exchangAPI' -and
                    @($maintenanceInitialPending.Events | Where-Object { $_ -like 'LOG-ERROR*' }).Count -eq 0
                ) `
                -Name "Maintenance/LifecycleStartPendingIsStoppedAndRestarted" `
                -Failure ("Maintenance (#287): служба у StartPending має бути зупинена після завершення старту (без відхиленого stop) і запущена у finally; події: " + ($maintenanceLatePending.Events -join ' | ') + ' || ' + ($maintenanceInitialPending.Events -join ' | '))

            # #287: служба BRAVO, яка так і не вийшла зі StartPending (stop
            # неможливий), не отримує обробки trace: бар'єр вимагає Stopped (чи
            # Paused), а не «не Running»; критична помилка, код 60.
            $maintenanceStuckPending = & $maintenanceStartModeOutcome 'StuckStartPending'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceStuckPending.ProbeOk -and $maintenanceStuckPending.StepOrderOk -and
                    $maintenanceStuckPending.ExitCode -eq 60 -and
                    @($maintenanceStuckPending.Events | Where-Object { $_ -ceq 'TRACE-ROTATION' }).Count -eq 0 -and
                    @($maintenanceStuckPending.Events | Where-Object { $_ -like 'LOG-ERROR Сервіс BRAVO все ще працює*' }).Count -eq 1 -and
                    @($maintenanceStuckPending.Events | Where-Object { $_ -ceq 'STEP 6/8 Обробка trace і логів SKIPPED' }).Count -eq 1 -and
                    @(& $maintenanceStartModeOutcome 'InitiallyStartPending' | ForEach-Object { $_.Events } | Where-Object { $_ -ceq 'TRACE-ROTATION' }).Count -eq 1
                ) `
                -Name "Maintenance/LifecycleStuckStartPendingGetsNoTraceProcessing" `
                -Failure ("Maintenance (#287): служба BRAVO, що не вийшла зі StartPending, не повинна отримати обробку trace (бар'єр вимагає Stopped), а прогін має завершитися критичною помилкою з кодом 60; події: " + ($maintenanceStuckPending.Events -join ' | '))

            # Виняток після зупинки: служба, запущена після знімка й зупинена
            # прогоном, стартує у finally навіть коли крок [4/8] кидає виняток.
            $maintenanceLateThrow = & $maintenanceStartModeOutcome 'LateStartThrow'
            $maintenanceLateThrowSizeCheck = & $maintenanceOrchestrationEventIndex $maintenanceLateThrow.Events '^SIZE-CHECK$'
            $maintenanceLateThrowStart = & $maintenanceOrchestrationEventIndex $maintenanceLateThrow.Events '^START BRAVO$'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceLateThrow.ProbeOk -and $maintenanceLateThrow.ExitCode -eq 90 -and
                    (& $maintenanceMarkerTrail $maintenanceLateThrow.Events) -ceq 'MARKER-WRITE BRAVO|MARKER-NO-RESTART BRAVO|MARKER-WRITE BRAVO' -and
                    $maintenanceLateThrowSizeCheck -ge 0 -and $maintenanceLateThrowStart -gt $maintenanceLateThrowSizeCheck -and
                    $maintenanceLateThrow.MarkerCleared
                ) `
                -Name "Maintenance/LifecycleLateStartRestartedAfterStepThrows" `
                -Failure ("Maintenance: служба, запущена після знімка й зупинена прогоном, має стартувати у finally після винятку в кроці [4/8]; події: " + ($maintenanceLateThrow.Events -join ' | '))

            # Disabled = оператор свідомо вимкнув службу: Maintenance її не
            # зупиняє, не утримує й не запускає, навіть коли вона працює.
            $maintenanceLateDisabled = & $maintenanceStartModeOutcome 'LateStartOperatorDisabled'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceLateDisabled.ProbeOk -and $maintenanceLateDisabled.StepOrderOk -and
                    @($maintenanceLateDisabled.Events | Where-Object { ($_ -like 'STOP*' -or $_ -like 'START *' -or $_ -like 'MARKER-WRITE *' -or $_ -like 'HOLD *') -and $_ -like '*exchangAPI*' }).Count -eq 0 -and
                    (@($maintenanceLateDisabled.Events | Where-Object { $_ -like 'STOP *' -or $_ -like 'START *' }) -join '|') -ceq 'STOP BRAVO|START BRAVO'
                ) `
                -Name "Maintenance/LifecycleOperatorDisabledServiceNeverTouched" `
                -Failure ("Maintenance: служба з типом запуску Disabled (вимкнена оператором) не зупиняється, не утримується й не запускається; події: " + ($maintenanceLateDisabled.Events -join ' | '))

            # Служба, запущена вже ПІСЛЯ запису маркера в не-restore прогоні
            # (поза lifecycle-контрактом прогону), не зупиняється: WARNING, її
            # стан лишається як є, маркер її не містить.
            $maintenanceLateAfterMarker = & $maintenanceStartModeOutcome 'LateStartAfterMarker'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceLateAfterMarker.ProbeOk -and $maintenanceLateAfterMarker.StepOrderOk -and
                    (@($maintenanceLateAfterMarker.Events | Where-Object { $_ -like 'MARKER-WRITE *' }) -join '|') -ceq 'MARKER-WRITE BRAVO,exchangAPI' -and
                    @($maintenanceLateAfterMarker.Events | Where-Object { ($_ -like 'STOP*' -or $_ -like 'START *') -and $_ -like '*BravoWeb*' }).Count -eq 0 -and
                    @($maintenanceLateAfterMarker.Events | Where-Object { $_ -like 'LOG-WARNING *BravoWeb*поза lifecycle-контрактом*' }).Count -eq 1
                ) `
                -Name "Maintenance/LifecycleServiceStartedAfterContractIsNotStopped" `
                -Failure ("Maintenance: служба, запущена після запису ownership-маркера не-restore прогону, не зупиняється (WARNING), щоб не лишитися зупиненою без контракту; події: " + ($maintenanceLateAfterMarker.Events -join ' | '))

            # Restore-прогін: утримувана служба, зупинена на момент знімка, але
            # запущена до фази зупинки (до або після запису маркера), отримує
            # намір перезапуску ДО зупинки й стартує у finally. Чужий маркер із
            # restartSuppressed не скасовує намір служби, яка фактично працювала.
            $maintenanceRestoreLate = & $maintenanceStartModeOutcome 'StartModeLateStartInitiallyStopped'
            $maintenanceRestoreLateAfterMarker = & $maintenanceStartModeOutcome 'StartModeLateAfterMarkerInitiallyStopped'
            $maintenanceRestoreLateSuppressed = & $maintenanceStartModeOutcome 'StartModeSuppressedLateStartInitiallyStopped'
            $maintenanceRestoreLateAfterStop = & $maintenanceStartModeOutcome 'StartModeLateAfterStopInitiallyStopped'
            $maintenanceRestoreLateAfterStopBarrierStop = & $maintenanceOrchestrationEventIndex $maintenanceRestoreLateAfterStop.Events '^STOP BravoWeb$'
            $maintenanceRestoreLateAfterMarkerWrites = @($maintenanceRestoreLateAfterMarker.Events | Where-Object { $_ -like 'MARKER-WRITE *' -or $_ -like 'MARKER-NO-RESTART *' })
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceRestoreLate.ProbeOk -and $maintenanceRestoreLate.StepOrderOk -and
                    (& $maintenanceMarkerTrail $maintenanceRestoreLate.Events) -ceq 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb|MARKER-NO-RESTART BravoWeb|MARKER-WRITE BRAVO,exchangAPI,BravoWeb' -and
                    (& $maintenanceOrchestrationEventIndex $maintenanceRestoreLate.Events '^STOP BravoWeb$') -gt ([array]::LastIndexOf([string[]]$maintenanceRestoreLate.Events, 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb')) -and
                    @($maintenanceRestoreLate.Events | Where-Object { $_ -ceq 'START BravoWeb' }).Count -eq 1 -and
                    $maintenanceRestoreLateAfterMarker.ProbeOk -and $maintenanceRestoreLateAfterMarker.StepOrderOk -and
                    ($maintenanceRestoreLateAfterMarkerWrites -join '|') -ceq 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb|MARKER-NO-RESTART BravoWeb|MARKER-WRITE BRAVO,exchangAPI,BravoWeb' -and
                    (& $maintenanceOrchestrationEventIndex $maintenanceRestoreLateAfterMarker.Events '^STOP BravoWeb$') -gt ([array]::LastIndexOf([string[]]$maintenanceRestoreLateAfterMarker.Events, 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb')) -and
                    @($maintenanceRestoreLateAfterMarker.Events | Where-Object { $_ -ceq 'START BravoWeb' }).Count -eq 1 -and
                    $maintenanceRestoreLateSuppressed.ProbeOk -and $maintenanceRestoreLateSuppressed.StepOrderOk -and
                    (& $maintenanceFinalMarkerNoRestart $maintenanceRestoreLateSuppressed.Events) -ceq '' -and
                    @($maintenanceRestoreLateSuppressed.Events | Where-Object { $_ -ceq 'START BravoWeb' }).Count -eq 1 -and
                    $maintenanceRestoreLateAfterStop.ProbeOk -and $maintenanceRestoreLateAfterStop.StepOrderOk -and
                    $maintenanceRestoreLateAfterStopBarrierStop -gt (& $maintenanceOrchestrationEventIndex $maintenanceRestoreLateAfterStop.Events '^SIZE-CHECK$') -and
                    $maintenanceRestoreLateAfterStopBarrierStop -gt ([array]::LastIndexOf([string[]]$maintenanceRestoreLateAfterStop.Events, 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb')) -and
                    @($maintenanceRestoreLateAfterStop.Events | Where-Object { $_ -ceq 'START BravoWeb' }).Count -eq 1
                ) `
                -Name "Maintenance/LifecycleRestoreLateStartGetsRestartIntentBeforeStop" `
                -Failure ("Maintenance: утримувана служба, запущена після знімка (до чи після фази зупинки), має отримати намір перезапуску в маркері ДО зупинки (і повторної зупинки бар'єром перед before-архівом) й стартувати у finally; події: " + ($maintenanceRestoreLate.Events -join ' | ') + ' || ' + ($maintenanceRestoreLateAfterMarker.Events -join ' | ') + ' || ' + ($maintenanceRestoreLateSuppressed.Events -join ' | ') + ' || ' + ($maintenanceRestoreLateAfterStop.Events -join ' | '))

            # Подвійний збій: службу запущено після фази зупинки, а намір її
            # перезапуску не вдалося записати в маркер. Бар'єр перед
            # before-архівом її не зупиняє (вона лишається працювати), а
            # реставрацію скасовано fail-closed ДО архіву.
            $maintenanceRestoreMarkerFail = & $maintenanceStartModeOutcome 'StartModeLateAfterStopMarkerFailInitiallyStopped'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceRestoreMarkerFail.ProbeOk -and $maintenanceRestoreMarkerFail.StepOrderOk -and
                    @($maintenanceRestoreMarkerFail.Events | Where-Object { $_ -ceq 'MARKER-WRITE-FAIL' }).Count -eq 1 -and
                    @($maintenanceRestoreMarkerFail.Events | Where-Object { $_ -like 'STOP*BravoWeb' -or $_ -ceq 'START BravoWeb' }).Count -eq 0 -and
                    @($maintenanceRestoreMarkerFail.Native).Count -eq 0 -and
                    $maintenanceRestoreMarkerFail.RestoreCancelled -and
                    @($maintenanceRestoreMarkerFail.Events | Where-Object { $_ -like 'LOG-ERROR ПОМИЛКА: Службу BravoWeb (стан: Running) не зупинено*' }).Count -eq 1
                ) `
                -Name "Maintenance/LifecycleIntentWriteFailureNeverStopsService" `
                -Failure ("Maintenance: служба, намір перезапуску якої не вдалося записати в маркер, не зупиняється бар'єром перед before-архівом, а реставрацію скасовано fail-closed; події: " + ($maintenanceRestoreMarkerFail.Events -join ' | '))

            # #287 у бар'єрі перед before-архівом: службу, яка після фази
            # зупинки перейшла у StartPending, бар'єр зупиняє після завершення
            # старту (без відхиленого stop), тож реставрація не скасовується, а
            # служба стартує у finally.
            $maintenanceRestoreLatePending = & $maintenanceStartModeOutcome 'StartModeLatePendingAfterStopInitiallyStopped'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceRestoreLatePending.ProbeOk -and $maintenanceRestoreLatePending.StepOrderOk -and
                    @($maintenanceRestoreLatePending.Events | Where-Object { $_ -like 'STOP-REFUSED*' }).Count -eq 0 -and
                    -not $maintenanceRestoreLatePending.RestoreCancelled -and
                    (& $maintenanceOrchestrationEventIndex $maintenanceRestoreLatePending.Events '^STOP BravoWeb$') -gt (& $maintenanceOrchestrationEventIndex $maintenanceRestoreLatePending.Events '^SIZE-CHECK$') -and
                    @($maintenanceRestoreLatePending.Events | Where-Object { $_ -ceq 'START BravoWeb' }).Count -eq 1
                ) `
                -Name "Maintenance/LifecyclePreArchiveBarrierWaitsOutStartPending" `
                -Failure ("Maintenance (#287): службу у StartPending бар'єр перед before-архівом має зупинити після завершення старту, не скасовуючи реставрацію, і запустити у finally; події: " + ($maintenanceRestoreLatePending.Events -join ' | '))

            # Restore-прогін, де на старті всі служби стояли: крок [3/8]
            # звітує SKIPPED, а службу, яку запустили вже після нього, зупиняє
            # бар'єр перед before-архівом. Ця зупинка не ховається — її фіксує
            # окремий результат WARN (консоль, підсумок, фінальне сповіщення).
            $maintenanceRestoreAllStoppedLate = & $maintenanceStartModeOutcome 'StartModeAllStoppedLateAfterStop'
            $maintenanceRestoreAllStoppedLateStop = & $maintenanceOrchestrationEventIndex $maintenanceRestoreAllStoppedLate.Events '^STOP BravoWeb$'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceRestoreAllStoppedLate.ProbeOk -and $maintenanceRestoreAllStoppedLate.StepOrderOk -and
                    -not $maintenanceRestoreAllStoppedLate.RestoreCancelled -and
                    @($maintenanceRestoreAllStoppedLate.Events | Where-Object { $_ -ceq 'STEP 3/8 Зупинка служб SKIPPED' }).Count -eq 1 -and
                    $maintenanceRestoreAllStoppedLateStop -gt (& $maintenanceOrchestrationEventIndex $maintenanceRestoreAllStoppedLate.Events '^SIZE-CHECK$') -and
                    @($maintenanceRestoreAllStoppedLate.Events | Where-Object { $_ -ceq 'OPERATION Повторна зупинка служб перед архівацією WARN' }).Count -eq 1 -and
                    (& $maintenanceOrchestrationEventIndex $maintenanceRestoreAllStoppedLate.Events '^OPERATION Повторна зупинка служб перед архівацією WARN$') -gt $maintenanceRestoreAllStoppedLateStop -and
                    (@($maintenanceRestoreAllStoppedLate.Events | Where-Object { $_ -like 'START *' }) -join '|') -ceq 'START BravoWeb'
                ) `
                -Name "Maintenance/LifecyclePreArchiveBarrierStopIsReported" `
                -Failure ("Maintenance: зупинка служби бар'єром перед before-архівом має бути видима у звіті кроків окремим результатом WARN, навіть коли [3/8] звітував SKIPPED, а служба має стартувати у finally; події: " + ($maintenanceRestoreAllStoppedLate.Events -join ' | '))

            # Службу запустили вже після плану бар'єра (між контрактною
            # зупинкою і фінальною перевіркою). Бар'єр не зупиняє її сам — його
            # Stop-Service обійшов би контракт маркера й лишив службу зупиненою
            # без наміру перезапуску. Вона — порушник: реставрацію скасовано
            # fail-closed, модель не торкнута, служба не зупинена й не стартує.
            $maintenanceRestoreLateBeforeBarrier = & $maintenanceStartModeOutcome 'StartModeLateBeforeBarrierInitiallyStopped'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceRestoreLateBeforeBarrier.ProbeOk -and $maintenanceRestoreLateBeforeBarrier.StepOrderOk -and
                    @($maintenanceRestoreLateBeforeBarrier.Events | Where-Object { $_ -ceq 'LATE-START BravoWeb Running' }).Count -eq 1 -and
                    @($maintenanceRestoreLateBeforeBarrier.Events | Where-Object { $_ -ceq 'BARRIER-OFFENDER BravoWeb' }).Count -eq 1 -and
                    @($maintenanceRestoreLateBeforeBarrier.Events | Where-Object { $_ -like 'STOP*BravoWeb' -or $_ -ceq 'START BravoWeb' }).Count -eq 0 -and
                    @($maintenanceRestoreLateBeforeBarrier.Native).Count -eq 0 -and
                    $maintenanceRestoreLateBeforeBarrier.RestoreCancelled
                ) `
                -Name "Maintenance/LifecycleFinalBarrierNeverStopsOutsideContract" `
                -Failure ("Maintenance: службу, запущену після плану бар'єра перед before-архівом, фінальна перевірка не зупиняє поза контрактом маркера, а скасовує реставрацію fail-closed; події: " + ($maintenanceRestoreLateBeforeBarrier.Events -join ' | '))

            # Нечитабельний стан exchangAPI у фазі зупинки — невідомий, а не
            # «зупинена»: критична помилка кроку [3/8], без Stop-Service і без
            # тихого «вже зупинена».
            $maintenanceExchangeUnreadable = & $maintenanceStartModeOutcome 'ExchangeApiUnreadableAtStop'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceExchangeUnreadable.ProbeOk -and $maintenanceExchangeUnreadable.StepOrderOk -and
                    @($maintenanceExchangeUnreadable.Events | Where-Object { $_ -ceq 'LATE-START exchangAPI UNREADABLE' }).Count -eq 1 -and
                    @($maintenanceExchangeUnreadable.Events | Where-Object { $_ -ceq 'LOG-ERROR ПОМИЛКА: Помилка при зупинці служби exchangAPI: self-test: стан служби exchangAPI не прочитано' }).Count -eq 1 -and
                    @($maintenanceExchangeUnreadable.Events | Where-Object { $_ -ceq 'STEP 3/8 Зупинка служб FAIL' }).Count -eq 1 -and
                    @($maintenanceExchangeUnreadable.Events | Where-Object { $_ -like 'STOP*exchangAPI' -or $_ -ceq 'START exchangAPI' }).Count -eq 0
                ) `
                -Name "Maintenance/LifecycleUnreadableServiceStateIsNotStopped" `
                -Failure ("Maintenance: збій читання стану exchangAPI у фазі зупинки має бути критичною помилкою кроку [3/8], а не «службу вже зупинено»; події: " + ($maintenanceExchangeUnreadable.Events -join ' | '))

            # Служба, яку після фази зупинки підняли й призупиняють
            # (PausePending/ContinuePending), у finally не запускається — той
            # самий набір станів паузи, що й у фазі зупинки; інакше Start-Service
            # чекав би до таймауту й позначав прогін критичним.
            $maintenancePausePendingRestart = & $maintenanceStartModeOutcome 'PausePendingBeforeRestart'
            $maintenanceBravoPausePendingRestart = & $maintenanceStartModeOutcome 'BravoPausePendingBeforeRestart'
            Test-BRAVOCondition `
                -Condition (
                    $maintenancePausePendingRestart.ProbeOk -and $maintenancePausePendingRestart.StepOrderOk -and
                    @($maintenancePausePendingRestart.Events | Where-Object { $_ -ceq 'STOP exchangAPI' -or $_ -ceq 'STOP BravoWeb' }).Count -eq 2 -and
                    (@($maintenancePausePendingRestart.Events | Where-Object { $_ -like 'START *' }) -join '|') -ceq 'START BRAVO' -and
                    @($maintenancePausePendingRestart.Events | Where-Object { $_ -like 'LOG-ERROR *' }).Count -eq 0 -and
                    $maintenanceBravoPausePendingRestart.ProbeOk -and $maintenanceBravoPausePendingRestart.StepOrderOk -and
                    (@($maintenanceBravoPausePendingRestart.Events | Where-Object { $_ -like 'START *' }) -join '|') -ceq 'START exchangAPI|START BravoWeb' -and
                    @($maintenanceBravoPausePendingRestart.Events | Where-Object { $_ -like 'LOG-ERROR *не запустився*' }).Count -eq 0
                ) `
                -Name "Maintenance/LifecyclePendingPauseIsNotRestarted" `
                -Failure ("Maintenance: службу у PausePending/ContinuePending finally не запускає (як і Paused), без критичної помилки; події: " + ($maintenancePausePendingRestart.Events -join ' | ') + ' || ' + ($maintenanceBravoPausePendingRestart.Events -join ' | '))

            # Restore-прогін, де на старті й на повторному читанні всі служби
            # стояли, а BravoWeb запустили вже після запису маркера: фаза зупинки
            # зупиняє її під контрактом, тож крок [3/8] не звітує SKIPPED, а
            # служба стартує у finally.
            $maintenanceAllStoppedLateAfterMarker = & $maintenanceStartModeOutcome 'StartModeAllStoppedLateAfterMarker'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceAllStoppedLateAfterMarker.ProbeOk -and $maintenanceAllStoppedLateAfterMarker.StepOrderOk -and
                    @($maintenanceAllStoppedLateAfterMarker.Events | Where-Object { $_ -ceq 'LATE-START BravoWeb Running' }).Count -eq 1 -and
                    @($maintenanceAllStoppedLateAfterMarker.Events | Where-Object { $_ -like 'STEP 3/8 Зупинка служб *' -and $_ -cne 'STEP 3/8 Зупинка служб SKIPPED' }).Count -eq 1 -and
                    (& $maintenanceOrchestrationEventIndex $maintenanceAllStoppedLateAfterMarker.Events '^STOP BravoWeb$') -lt (& $maintenanceOrchestrationEventIndex $maintenanceAllStoppedLateAfterMarker.Events '^STEP 3/8 ') -and
                    (@($maintenanceAllStoppedLateAfterMarker.Events | Where-Object { $_ -like 'START *' }) -join '|') -ceq 'START BravoWeb'
                ) `
                -Name "Maintenance/LifecycleStopStepNotSkippedAfterActualStop" `
                -Failure ("Maintenance: крок [3/8] не звітує SKIPPED, якщо фаза зупинки фактично зупинила службу, запущену вже після запису маркера, а служба стартує у finally; події: " + ($maintenanceAllStoppedLateAfterMarker.Events -join ' | '))

            # Усі служби стояли, а стан exchangAPI у фазі зупинки не прочитано:
            # критична помилка кроку [3/8] не ховається за SKIPPED.
            $maintenanceAllStoppedUnreadable = & $maintenanceStartModeOutcome 'AllStoppedExchangeApiUnreadable'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceAllStoppedUnreadable.ProbeOk -and $maintenanceAllStoppedUnreadable.StepOrderOk -and
                    @($maintenanceAllStoppedUnreadable.Events | Where-Object { $_ -ceq 'LOG-ERROR ПОМИЛКА: Помилка при зупинці служби exchangAPI: self-test: стан служби exchangAPI не прочитано' }).Count -eq 1 -and
                    @($maintenanceAllStoppedUnreadable.Events | Where-Object { $_ -ceq 'STEP 3/8 Зупинка служб FAIL' }).Count -eq 1 -and
                    @($maintenanceAllStoppedUnreadable.Events | Where-Object { $_ -like 'STOP *' -or $_ -like 'START *' }).Count -eq 0
                ) `
                -Name "Maintenance/LifecycleStopStepFailureNotHiddenBySkipped" `
                -Failure ("Maintenance: критична помилка у фазі зупинки, коли всі служби стояли, має давати [3/8] FAIL, а не SKIPPED; події: " + ($maintenanceAllStoppedUnreadable.Events -join ' | '))

            # Призупинена оператором служба (Paused) — на старті чи вже після
            # початкового знімка — Maintenance не зупиняє й не запускає (стан
            # зберігається; намір її перезапуску знято й з маркера, щоб
            # Health-watchdog не запустив її за осиротілим маркером), а
            # призупинена BRAVO, як і до #360, не блокує обробку trace. У
            # restore-прогоні утримувану призупинену службу без наміру бар'єр
            # теж не зупиняє: реставрацію скасовано fail-closed ДО архіву.
            $maintenancePausedOthers = & $maintenanceStartModeOutcome 'PausedServicesPreserved'
            $maintenancePausedBravo = & $maintenanceStartModeOutcome 'BravoPausedPreserved'
            $maintenancePausedHeld = & $maintenanceStartModeOutcome 'StartModePausedHeld'
            $maintenancePausedAfterSnapshot = & $maintenanceStartModeOutcome 'PausedAfterSnapshot'
            $maintenancePausedBeforeStop = & $maintenanceStartModeOutcome 'PausedBeforeStop'
            Test-BRAVOCondition `
                -Condition (
                    $maintenancePausedOthers.ProbeOk -and $maintenancePausedOthers.StepOrderOk -and
                    (@($maintenancePausedOthers.Events | Where-Object { $_ -like 'STOP*' -or $_ -like 'START *' }) -join '|') -ceq 'STOP BRAVO|START BRAVO' -and
                    (@($maintenancePausedOthers.Events | Where-Object { $_ -like 'MARKER-WRITE *' }) -join '|') -ceq 'MARKER-WRITE BRAVO' -and
                    @($maintenancePausedOthers.Events | Where-Object { $_ -ceq 'TRACE-ROTATION' }).Count -eq 1 -and
                    @($maintenancePausedOthers.Events | Where-Object { $_ -like 'LOG-ERROR*' }).Count -eq 0 -and
                    $maintenancePausedBravo.ProbeOk -and $maintenancePausedBravo.StepOrderOk -and
                    @($maintenancePausedBravo.Events | Where-Object { $_ -like 'STOP*BRAVO' -or $_ -ceq 'START BRAVO' }).Count -eq 0 -and
                    (@($maintenancePausedBravo.Events | Where-Object { $_ -like 'START *' } | Sort-Object) -join '|') -ceq 'START BravoWeb|START exchangAPI' -and
                    @($maintenancePausedBravo.Events | Where-Object { $_ -ceq 'TRACE-ROTATION' }).Count -eq 1 -and
                    @($maintenancePausedBravo.Events | Where-Object { $_ -like 'LOG-ERROR*' }).Count -eq 0 -and
                    $maintenancePausedHeld.ProbeOk -and $maintenancePausedHeld.StepOrderOk -and
                    @($maintenancePausedHeld.Events | Where-Object { $_ -like 'STOP*BravoWeb' -or $_ -ceq 'START BravoWeb' }).Count -eq 0 -and
                    @($maintenancePausedHeld.Native).Count -eq 0 -and
                    $maintenancePausedHeld.RestoreCancelled -and
                    $maintenancePausedAfterSnapshot.ProbeOk -and $maintenancePausedAfterSnapshot.StepOrderOk -and
                    @($maintenancePausedAfterSnapshot.Events | Where-Object { $_ -like 'STOP*exchangAPI' -or $_ -ceq 'START exchangAPI' }).Count -eq 0 -and
                    (@($maintenancePausedAfterSnapshot.Events | Where-Object { $_ -like 'START *' } | Sort-Object) -join '|') -ceq 'START BRAVO|START BravoWeb' -and
                    @($maintenancePausedAfterSnapshot.Events | Where-Object { $_ -like 'LOG-ERROR*' }).Count -eq 0 -and
                    (& $maintenanceFinalMarkerNoRestart $maintenancePausedAfterSnapshot.Events) -ceq 'exchangAPI' -and
                    $maintenancePausedBeforeStop.ProbeOk -and $maintenancePausedBeforeStop.StepOrderOk -and
                    @($maintenancePausedBeforeStop.Events | Where-Object { $_ -like 'STOP*exchangAPI' -or $_ -ceq 'START exchangAPI' }).Count -eq 0 -and
                    @($maintenancePausedBeforeStop.Events | Where-Object { $_ -like 'LOG-ERROR *exchangAPI*пауза зберігається (#360)' }).Count -eq 1 -and
                    (& $maintenanceFinalMarkerNoRestart $maintenancePausedBeforeStop.Events) -ceq 'exchangAPI'
                ) `
                -Name "Maintenance/LifecyclePausedServiceStateIsPreserved" `
                -Failure ("Maintenance: призупинена (Paused) служба без наміру перезапуску не зупиняється й не запускається, а призупинена BRAVO не блокує обробку trace; події: " + ($maintenancePausedOthers.Events -join ' | ') + ' || ' + ($maintenancePausedBravo.Events -join ' | ') + ' || ' + ($maintenancePausedHeld.Events -join ' | ') + ' || ' + ($maintenancePausedAfterSnapshot.Events -join ' | ') + ' || ' + ($maintenancePausedBeforeStop.Events -join ' | '))

            # Стан BRAVO перечитується безпосередньо перед ротацією trace: службу,
            # яку інший актор підняв після воріт фази, ротація не чіпає (критична
            # помилка), а знову піднята служба не лишається зупиненою.
            $maintenanceLateBeforeTrace = & $maintenanceStartModeOutcome 'LateStartBeforeTrace'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceLateBeforeTrace.ProbeOk -and $maintenanceLateBeforeTrace.StepOrderOk -and
                    $maintenanceLateBeforeTrace.ExitCode -eq 60 -and
                    @($maintenanceLateBeforeTrace.Events | Where-Object { $_ -ceq 'TRACE-ROTATION' }).Count -eq 0 -and
                    @($maintenanceLateBeforeTrace.Events | Where-Object { $_ -like 'LOG-ERROR *trace-файли не переміщено (#360)' }).Count -eq 1
                ) `
                -Name "Maintenance/LifecycleTraceRotationRechecksBravoState" `
                -Failure ("Maintenance: стан BRAVO має перечитуватися безпосередньо перед ротацією trace — службу, підняту після воріт фази, ротація не чіпає, прогін завершується критичною помилкою (60); події: " + ($maintenanceLateBeforeTrace.Events -join ' | '))

            # Boot-recovery (характеризація): усі увімкнені керовані служби
            # утримуються з наміром перезапуску незалежно від знімка.
            $maintenanceBootLate = & $maintenanceStartModeOutcome 'BootRecoveryLateStart'
            Test-BRAVOCondition `
                -Condition (
                    $maintenanceBootLate.ProbeOk -and $maintenanceBootLate.StepOrderOk -and
                    (@($maintenanceBootLate.Events | Where-Object { $_ -like 'MARKER-WRITE *' }) -join '|') -ceq 'MARKER-WRITE BRAVO,exchangAPI,BravoWeb' -and
                    @($maintenanceBootLate.Events | Where-Object { $_ -like 'MARKER-NO-RESTART *' }).Count -eq 0 -and
                    $maintenanceBootLate.ServicesStarted -and $maintenanceBootLate.MarkerCleared
                ) `
                -Name "Maintenance/LifecycleBootRecoveryHoldsAllManagedWithRestart" `
                -Failure ("Maintenance (boot-recovery): усі увімкнені керовані служби мають бути в маркері з наміром перезапуску й стартувати у finally; події: " + ($maintenanceBootLate.Events -join ' | '))
        } finally {
            if (Test-Path -LiteralPath $maintenanceOrchestrationRoot -PathType Container) {
                Remove-Item -LiteralPath $maintenanceOrchestrationRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    }

    # -NoPause має надходити у Maintenance.Runtime.ps1 через параметр,
    # інакше зовнішній try/finally вище нічим не керує.
    Test-BRAVOCondition `
        -Condition (
            [regex]::IsMatch($maintenanceRuntimeTextForPause, '(?m)^\s*\[switch\]\$NoPause,\s*$')
        ) `
        -Name "Console/MaintenanceAcceptsNoPauseParameter" `
        -Failure "modules\BRAVO.Maintenance\BRAVO.Maintenance.Runtime.ps1 має приймати -NoPause у param()"

    # Archive.Runtime.ps1: тіло runtime загорнуте в Invoke-BRAVOArchive за
    # зразком Invoke-BRAVOHealth. Структура (AST): на верхньому рівні — лише
    # функція-обгортка й invocation guard останнім оператором, КОЖЕН exit —
    # усередині обгортки, guard передає функції рівно параметри param()
    # скрипта (інакше забутий параметр мовчки перестав би доходити до тіла).
    # Окремо — клас пасток обгортання: ім'я, яке тіло пише БЕЗ scope, а
    # хтось у файлі читає/пише через $script:. До обгортання це була одна
    # script-змінна; у функції некваліфіковане присвоєння створює локальну
    # копію, що затінює $script:-значення для вкладених функцій (так було б
    # із $compatibilityMode: Main показав би «ВИМКНЕНО» замість фактичного
    # режиму, визначеного Test-Compatibility).
    $archiveRuntimePathForWrapper = Join-Path $root "modules\BRAVO.Archive\BRAVO.Archive.Runtime.ps1"
    $archiveWrapperParseErrors = $null
    $archiveWrapperAst = [Management.Automation.Language.Parser]::ParseFile(
        $archiveRuntimePathForWrapper, [ref]$null, [ref]$archiveWrapperParseErrors)
    $archiveWrapperTopStatements = @($archiveWrapperAst.EndBlock.Statements)
    $archiveWrapperFunctions = @($archiveWrapperTopStatements | Where-Object {
            $_ -is [Management.Automation.Language.FunctionDefinitionAst] -and $_.Name -eq 'Invoke-BRAVOArchive'
        })
    $archiveWrapperFunction = $archiveWrapperFunctions | Select-Object -First 1
    $archiveWrapperGuard = $archiveWrapperTopStatements | Select-Object -Last 1
    $archiveWrapperExits = @($archiveWrapperAst.FindAll({
                param($node) $node -is [Management.Automation.Language.ExitStatementAst]
            }, $true))
    $archiveWrapperExitsOutside = @($archiveWrapperExits | Where-Object {
            $null -eq $archiveWrapperFunction -or
            $_.Extent.StartOffset -lt $archiveWrapperFunction.Extent.StartOffset -or
            $_.Extent.EndOffset -gt $archiveWrapperFunction.Extent.EndOffset
        })
    $archiveWrapperFunctionParameters = ''
    $archiveWrapperShadowedScriptNames = @()
    if ($null -ne $archiveWrapperFunction) {
        $archiveWrapperFunctionParameters = (@($archiveWrapperFunction.Body.ParamBlock.Parameters |
                    ForEach-Object { $_.Name.VariablePath.UserPath }) | Sort-Object) -join ','
        $archiveWrapperScriptQualifiedNames = @{}
        foreach ($archiveWrapperVariable in @($archiveWrapperAst.FindAll({
                        param($node) $node -is [Management.Automation.Language.VariableExpressionAst]
                    }, $true))) {
            if ($archiveWrapperVariable.VariablePath.UserPath -match '^(?i)script:(.+)$') {
                $archiveWrapperScriptQualifiedNames[$Matches[1].ToLowerInvariant()] = $true
            }
        }
        $archiveWrapperBodyUnqualifiedNames = @{}
        foreach ($archiveWrapperAssignment in @($archiveWrapperFunction.Body.FindAll({
                        param($node) $node -is [Management.Automation.Language.AssignmentStatementAst]
                    }, $true))) {
            # Лише присвоєння рівня тіла обгортки: не у вкладеній функції й
            # не у scriptblock-літералі (ті мають власний scope і до
            # обгортання).
            $archiveWrapperOwner = $archiveWrapperAssignment.Parent
            while ($null -ne $archiveWrapperOwner -and
                -not ($archiveWrapperOwner -is [Management.Automation.Language.FunctionDefinitionAst]) -and
                -not ($archiveWrapperOwner -is [Management.Automation.Language.ScriptBlockExpressionAst])) {
                $archiveWrapperOwner = $archiveWrapperOwner.Parent
            }
            if (-not [object]::ReferenceEquals($archiveWrapperOwner, $archiveWrapperFunction)) {
                continue
            }
            $archiveWrapperTarget = $archiveWrapperAssignment.Left
            if ($archiveWrapperTarget -is [Management.Automation.Language.ConvertExpressionAst]) {
                $archiveWrapperTarget = $archiveWrapperTarget.Child
            }
            if ($archiveWrapperTarget -is [Management.Automation.Language.VariableExpressionAst] -and
                $archiveWrapperTarget.VariablePath.IsUnqualified) {
                $archiveWrapperBodyUnqualifiedNames[$archiveWrapperTarget.VariablePath.UserPath.ToLowerInvariant()] = $true
            }
        }
        $archiveWrapperShadowedScriptNames = @($archiveWrapperBodyUnqualifiedNames.Keys | Where-Object {
                $archiveWrapperScriptQualifiedNames.ContainsKey($_)
            } | Sort-Object)
    }
    $archiveWrapperScriptParameters = (@($archiveWrapperAst.ParamBlock.Parameters |
                ForEach-Object { $_.Name.VariablePath.UserPath }) | Sort-Object) -join ','
    $archiveWrapperGuardIsInvocation = $false
    $archiveWrapperGuardSplatKeys = ''
    if ($archiveWrapperGuard -is [Management.Automation.Language.IfStatementAst] -and
        @($archiveWrapperGuard.Clauses).Count -eq 1 -and
        $archiveWrapperGuard.Clauses[0].Item1.Extent.Text -eq "`$MyInvocation.InvocationName -ne '.'") {
        $archiveWrapperGuardIsInvocation = @($archiveWrapperGuard.FindAll({
                    param($node)
                    $node -is [Management.Automation.Language.CommandAst] -and
                    $node.GetCommandName() -eq 'Invoke-BRAVOArchive'
                }, $true)).Count -eq 1
        $archiveWrapperGuardSplat = @($archiveWrapperGuard.FindAll({
                    param($node) $node -is [Management.Automation.Language.HashtableAst]
                }, $true)) | Select-Object -First 1
        if ($null -ne $archiveWrapperGuardSplat) {
            $archiveWrapperGuardSplatKeys = (@($archiveWrapperGuardSplat.KeyValuePairs |
                        ForEach-Object { $_.Item1.Extent.Text }) | Sort-Object) -join ','
        }
    }
    Test-BRAVOCondition `
        -Condition (
            @($archiveWrapperParseErrors).Count -eq 0 -and
            $archiveWrapperFunctions.Count -eq 1 -and
            $archiveWrapperTopStatements.Count -eq 2 -and
            $archiveWrapperExits.Count -gt 0 -and
            $archiveWrapperExitsOutside.Count -eq 0 -and
            $archiveWrapperShadowedScriptNames.Count -eq 0 -and
            $archiveWrapperGuardIsInvocation -and
            -not [string]::IsNullOrEmpty($archiveWrapperScriptParameters) -and
            $archiveWrapperFunctionParameters -eq $archiveWrapperScriptParameters -and
            $archiveWrapperGuardSplatKeys -eq $archiveWrapperScriptParameters
        ) `
        -Name "Console/ArchiveRuntimeWrappedInFunction" `
        -Failure "Archive.Runtime.ps1: на верхньому рівні мають бути лише функція Invoke-BRAVOArchive (з усіма exit) і останнім оператором guard `$MyInvocation.InvocationName -ne '.', що передає рівно параметри param() скрипта; тіло не повинно писати без scope імена, які файл використовує через `$script: (операторів верхнього рівня: $($archiveWrapperTopStatements.Count); exit поза функцією: $($archiveWrapperExitsOutside.Count); затінені `$script:-імена: $($archiveWrapperShadowedScriptNames -join ', '); параметри функції: $archiveWrapperFunctionParameters; splat guard: $archiveWrapperGuardSplatKeys; param() скрипта: $archiveWrapperScriptParameters)"

    # Поведінка обгортки — у дочірньому процесі (runtime імпортує модулі й
    # перемикає кодування консолі, це не повинно торкатися сесії самотесту).
    # DotSource: dot-source лише визначає Invoke-BRAVOArchive — тіло НЕ
    # виконується (без guard-а воно б відпрацювало й завершило процес, а
    # функції runtime, як-от Main, лишилися б визначеними). Invoke: справжній
    # production-шлях Invoke-BRAVOArchiveEntrypoint -> & runtime -> guard ->
    # тіло; явно вказаний відсутній -ConfigPath дає exit 1 з catch
    # завантаження конфігурації ВСЕРЕДИНІ функції (поточний код; те, що це
    # 1, а не контрактний 30, — окремий відомий дефект, і його виправлення
    # має оновити цю перевірку). $LASTEXITCODE перед викликом = 77, тож
    # пропущене тіло не може випадково дати 1.
    $archiveWrapperProbeRoot = Join-Path `
        -Path ([IO.Path]::GetTempPath()) `
        -ChildPath ("BRAVO_ARCHIVE_WRAPPER_SELF_TEST_{0}" -f [guid]::NewGuid().ToString("N"))
    try {
        [void][IO.Directory]::CreateDirectory($archiveWrapperProbeRoot)
        $archiveWrapperProbeScript = @'
param([string]$Mode, [string]$RuntimeRoot, [string]$ProbeRoot)
$ErrorActionPreference = 'Stop'
$probeRuntimePath = Join-Path $RuntimeRoot 'modules\BRAVO.Archive\BRAVO.Archive.Runtime.ps1'
$probeParameters = @{
    RuntimeRoot = $RuntimeRoot
    EntryScriptPath = (Join-Path $RuntimeRoot 'BRAVO_ARCHIV.ps1')
    ConfigPath = (Join-Path $ProbeRoot 'missing\BRAVO.config')
    ConfigPathWasExplicit = $true
    NoPause = $true
}
try {
    if ($Mode -eq 'DotSource') {
        . $probeRuntimePath @probeParameters
        [pscustomobject]@{
            DotSourceReturned = $true
            FunctionDefined = [bool](Get-Command -Name 'Invoke-BRAVOArchive' -CommandType Function -ErrorAction SilentlyContinue)
            BodyStateAbsent = (-not (Test-Path -LiteralPath 'variable:bravoScriptDirectory')) -and
                (-not (Get-Command -Name 'Main' -CommandType Function -ErrorAction SilentlyContinue))
        } | ConvertTo-Json -Compress
    } else {
        Import-Module -Name (Join-Path $RuntimeRoot 'modules\BRAVO.Archive\BRAVO.Archive.psd1') -Force
        $global:LASTEXITCODE = 77
        $probeExitCode = Invoke-BRAVOArchiveEntrypoint -Parameters $probeParameters
        [pscustomobject]@{ ExitCode = [int]$probeExitCode } | ConvertTo-Json -Compress
    }
} catch {
    [pscustomobject]@{ ProbeError = [string]$_.Exception.Message } | ConvertTo-Json -Compress
}
'@
        $archiveWrapperProbePath = Join-Path $archiveWrapperProbeRoot 'probe.ps1'
        [IO.File]::WriteAllText($archiveWrapperProbePath, $archiveWrapperProbeScript, (New-Object Text.UTF8Encoding($false)))
        $archiveWrapperHost = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        $archiveWrapperResults = @{}
        foreach ($archiveWrapperMode in @('DotSource', 'Invoke')) {
            $archiveWrapperOutput = & $archiveWrapperHost -NoLogo -NoProfile -NonInteractive `
                -ExecutionPolicy Bypass -File $archiveWrapperProbePath `
                -Mode $archiveWrapperMode -RuntimeRoot $root -ProbeRoot $archiveWrapperProbeRoot
            $archiveWrapperJson = @($archiveWrapperOutput) |
                Where-Object { $_ -is [string] -and $_.Trim().StartsWith('{') } |
                Select-Object -Last 1
            $archiveWrapperResults[$archiveWrapperMode] = if ([string]::IsNullOrWhiteSpace([string]$archiveWrapperJson)) {
                [pscustomobject]@{ ProbeError = "проба не повернула JSON (код виходу $LASTEXITCODE)" }
            } else {
                [string]$archiveWrapperJson | ConvertFrom-Json
            }
        }
        $archiveWrapperDotSource = $archiveWrapperResults['DotSource']
        $archiveWrapperInvoke = $archiveWrapperResults['Invoke']
        Test-BRAVOCondition `
            -Condition (
                $null -eq $archiveWrapperDotSource.PSObject.Properties['ProbeError'] -and
                $archiveWrapperDotSource.DotSourceReturned -eq $true -and
                $archiveWrapperDotSource.FunctionDefined -eq $true -and
                $archiveWrapperDotSource.BodyStateAbsent -eq $true
            ) `
            -Name "Console/ArchiveRuntimeDotSourceDefinesWithoutRunning" `
            -Failure "dot-source Archive.Runtime.ps1 має лише визначити Invoke-BRAVOArchive, не виконуючи тіло; проба: $($archiveWrapperDotSource | ConvertTo-Json -Compress)"
        Test-BRAVOCondition `
            -Condition (
                $null -eq $archiveWrapperInvoke.PSObject.Properties['ProbeError'] -and
                $archiveWrapperInvoke.ExitCode -eq 1
            ) `
            -Name "Console/ArchiveRuntimeDirectInvocationRunsBody" `
            -Failure "Invoke-BRAVOArchiveEntrypoint з явно вказаним відсутнім -ConfigPath має виконати тіло через guard і повернути exit 1 з catch завантаження конфігурації; проба: $($archiveWrapperInvoke | ConvertTo-Json -Compress)"
    } finally {
        if (Test-Path -LiteralPath $archiveWrapperProbeRoot -PathType Container) {
            Remove-Item -LiteralPath $archiveWrapperProbeRoot -Recurse -Force -ErrorAction SilentlyContinue
        }
    }

    # Кожен entrypoint має прокидати -NoPause у свій runtime, інакше сам
    # параметр command-line нічого не змінює.
    $entrypointsNotForwardingNoPause = New-Object System.Collections.ArrayList
    foreach ($noPauseForwardCheck in @(
        @{ File = 'BRAVO_ARCHIV.ps1' },
        @{ File = 'BRAVO_HEALTH.ps1' },
        @{ File = 'BRAVO_MAINTENANCE.ps1' }
    )) {
        $forwardText = [IO.File]::ReadAllText((Join-Path $root $noPauseForwardCheck.File), [Text.Encoding]::UTF8)
        if (-not [regex]::IsMatch($forwardText, 'NoPause\s*=\s*\$NoPause')) {
            [void]$entrypointsNotForwardingNoPause.Add($noPauseForwardCheck.File)
        }
    }
    Test-BRAVOCondition `
        -Condition ($entrypointsNotForwardingNoPause.Count -eq 0) `
        -Name "Console/EntrypointsForwardNoPauseToRuntime" `
        -Failure "entrypoint має передавати NoPause = `$NoPause у параметри свого runtime; не передають: $($entrypointsNotForwardingNoPause -join ', ')"

    # BRAVO_TASKS_INSTALL.ps1: -NoPause має додаватись БЕЗУМОВНО для
    # кожного типу запланованого завдання, а не вибірково за TaskType —
    # саме вибіркове додавання лишило Recovery й Maintenance без нього.
    $tasksInstallTextForPause = [IO.File]::ReadAllText(
        (Join-Path $root "BRAVO_TASKS_INSTALL.ps1"), [Text.Encoding]::UTF8
    )
    # P0 Configuration Foundation (PR C, Секція 6): -ConfigPath тепер сам
    # умовний (лише EXPLICIT-режим, if ($ConfigPathWasExplicit) { ... }) —
    # анкер "одразу після -ConfigPath" більше не годиться буквально.
    # Перевіряємо той самий інваріант напряму: між рядком -File і першою
    # появою -NoPause НЕМАЄ жодного `if ($TaskType -eq` (тобто -NoPause не
    # потрапляє під вибіркову per-type умову).
    $noPauseAnchorMatch = [regex]::Match(
        $tasksInstallTextForPause,
        '\$actionArguments \+= " -File[^\r\n]*"\r?\n(?<between>.*?)\$actionArguments \+= " -NoPause"',
        [System.Text.RegularExpressions.RegexOptions]::Singleline
    )
    Test-BRAVOCondition `
        -Condition (
            $noPauseAnchorMatch.Success -and
            -not $noPauseAnchorMatch.Groups['between'].Value.Contains('if ($TaskType -eq')
        ) `
        -Name "Scheduler/EveryTaskTypeGetsNoPauseUnconditionally" `
        -Failure "BRAVO_TASKS_INSTALL.ps1 має додавати -NoPause безумовно (між -File і -NoPause не повинно бути `if (`$TaskType -eq ...)`) — інакше якийсь тип завдання лишиться без нього непомітно"

    # Об'єкти проблем Health мають різний набір полів: Kind = "Service" не
    # несе ні DifferenceCount, ні ActionCounts. Пряме $_.DifferenceCount під
    # Set-StrictMode валило весь runtime із кодом 90 щоразу, коли лежала
    # керована служба — тобто тривога "служба не працює" не доходила ніколи.
    $healthRuntimeText = [IO.File]::ReadAllText(
        (Join-Path $root "modules\BRAVO.Health\BRAVO.Health.Runtime.ps1"),
        [Text.Encoding]::UTF8
    )
    Test-BRAVOCondition `
        -Condition (
            $healthRuntimeText.Contains('function Get-BRAVOHealthIssueField') -and
            -not [regex]::IsMatch($healthRuntimeText, '\$\(\$_\.DifferenceCount\)\|')
        ) `
        -Name "Health/AlertFingerprintToleratesMissingIssueFields" `
        -Failure "Get-AlertFingerprint має читати поля проблеми через Get-BRAVOHealthIssueField — пряме звернення падає під Set-StrictMode для проблем без DifferenceCount"

    # Той самий клас бага, інше поле: лише ОДНА з чотирьох гілок побудови
    # проблеми "SFTPSynchronization" (Get-SFTPHealthIssues, "у хмарі
    # відсутні...") насправді встановлює ActionCounts. Реальний прогін
    # (BAZA-SFTP синхронізація увімкнена, локальний каталог BAZA відсутній)
    # падав із "The property 'ActionCounts' cannot be found on this
    # object" — Archive ловив це як відмову всього health-check, а не як
    # окрему проблему в звіті.
    Test-BRAVOCondition `
        -Condition (
            $healthRuntimeText.Contains('function Get-BRAVOHealthIssueActionCounts') -and
            $healthRuntimeText.Contains("`$property = `$Issue.PSObject.Properties['ActionCounts']") -and
            $healthRuntimeText.Contains('Get-BRAVOHealthIssueActionCounts -Issue $healthIssue') -and
            $healthRuntimeText.Contains('Get-BRAVOHealthIssueActionCounts -Issue $Issue') -and
            -not [regex]::IsMatch($healthRuntimeText, '\$healthIssue\.ActionCounts\b') -and
            -not [regex]::IsMatch($healthRuntimeText, '\$Issue\.ActionCounts\b')
        ) `
        -Name "Health/SFTPSynchronizationToleratesMissingActionCounts" `
        -Failure "три з чотирьох видів проблем SFTPSynchronization не несуть ActionCounts — читання має йти через Get-BRAVOHealthIssueActionCounts, пряме `$Issue.ActionCounts`/`$healthIssue.ActionCounts` падає під Set-StrictMode ще на порівнянні з `$null"

    # Реальний випадок (скріншот користувача): Archive викликає Health
    # усередині власного кроку "Перевірка резервних копій", і Health
    # безумовно друкував ПОВНИЙ заголовок "BRAVO HEALTH X.X.X / Установа /
    # Початок" — виглядало як друга незалежна програма всередині виводу
    # Archive. -SuppressHeader вимикає лише текст заголовка (не резервування
    # місця під прогрес-бар — Write-BRAVOHeader продовжує друкувати порожні
    # рядки навіть коли текст придушено), і передається лише зі шляху
    # Invoke-BRAVOHealthCheck (вбудований виклик з Archive) — самостійний
    # запуск BRAVO_HEALTH.ps1 його не бачить, заголовок там лишається.
    $healthPsmText = [IO.File]::ReadAllText(
        (Join-Path $root "modules\BRAVO.Health\BRAVO.Health.psm1"),
        [Text.Encoding]::UTF8
    )
    $consoleScriptText = [IO.File]::ReadAllText(
        (Join-Path $root "modules\BRAVO.Console\BRAVO.Console.psm1"),
        [Text.Encoding]::UTF8
    )
    $writeBravoHeaderFunctionText = if ($consoleScriptText -match
        '(?s)function Write-BRAVOHeader \{.*?\n\}') {
        $Matches[0]
    } else {
        ''
    }
    Test-BRAVOCondition `
        -Condition (
            $healthRuntimeText.Contains('[switch]$SuppressHeader') -and
            $healthRuntimeText.Contains('-SuppressText:$SuppressHeader') -and
            [regex]::IsMatch($healthPsmText, '-SkipIfBackupTaskRunning:\$SkipIfBackupTaskRunning\s*`\r?\n\s*-SuppressHeader\r?\n') -and
            -not [string]::IsNullOrWhiteSpace($writeBravoHeaderFunctionText) -and
            $writeBravoHeaderFunctionText.Contains('[switch]$SuppressText') -and
            $writeBravoHeaderFunctionText.Contains('if ($SuppressText) {') -and
            # Реальний випадок: фіксований блок порожніх рядків (раніше
            # безумовний) лишався видимим розривом навіть без жодного
            # тексту заголовка для захисту — SuppressText тепер вимикає
            # ВЕСЬ вивід Write-BRAVOHeader, і перевірка на це має стояти
            # РАНІШЕ за цикл резервування рядків, а не після нього.
            (
                $writeBravoHeaderFunctionText.IndexOf('if ($SuppressText) {')
            ) -lt (
                $writeBravoHeaderFunctionText.IndexOf('for ($i = 0; $i -lt $script:BRAVOConsoleProgressReservedLines')
            )
        ) `
        -Name "Console/EmbeddedHealthSuppressesDuplicateHeader" `
        -Failure "Invoke-BRAVOHealthCheck (вбудований виклик Health з Archive) має передавати -SuppressHeader у Invoke-BRAVOHealth, а Write-BRAVOHeader — повністю пропускати вивід (і текст, і резервування рядків під прогрес-бар), коли текст придушено"

    # Реальний випадок (скріншот користувача, після прибирання заголовка):
    # вбудований виклик Health усередині Archive все одно друкував ВЛАСНУ
    # покрокову нумерацію [N/5] поряд із нумерацією Archive [N/7] — виглядало
    # як два незалежні прогони. -SuppressHeader тепер вимикає й це.
    $writeBravoHealthStepFunctionText = if ($healthRuntimeText -match
        '(?s)function Write-BRAVOHealthStep \{.*?\n\}') {
        $Matches[0]
    } else {
        ''
    }
    Test-BRAVOCondition `
        -Condition (
            -not [string]::IsNullOrWhiteSpace($writeBravoHealthStepFunctionText) -and
            $writeBravoHealthStepFunctionText.Contains('if ($SuppressHeader) {') -and
            # Лічильник кроків має інкрементуватись РАНІШЕ за перевірку —
            # інакше номер кроку "Сповіщення" в кінці зіб'ється.
            (
                $writeBravoHealthStepFunctionText.IndexOf('$script:BRAVOHealthStepCurrent++')
            ) -lt (
                $writeBravoHealthStepFunctionText.IndexOf('if ($SuppressHeader) {')
            )
        ) `
        -Name "Health/EmbeddedCallSuppressesStepNumbering" `
        -Failure "Write-BRAVOHealthStep має пропускати власний друк [N/5] при -SuppressHeader (вбудований виклик з Archive), не збиваючи внутрішній лічильник кроків"

    # Той самий реальний випадок: власний підсумок Health
    # (РЕЗУЛЬТАТ/Тривалість/.../Детальний журнал) усе одно друкувався другим
    # блоком поряд із підсумком Archive — два "Детальний журнал:" на один
    # прогін. Complete-BRAVOProgress (очищення прогрес-бару) лишається
    # безумовним — лише текстовий підсумок (Write-BRAVOResultHeader і далі,
    # операторська консоль — TODO_FEATURES.md/docs/OPERATOR_CONSOLE_UX.md)
    # придушений.
    $completeHealthResultFunctionText = if ($healthRuntimeText -match
        '(?s)function Complete-BRAVOHealthResult \{.*?\n\}') {
        $Matches[0]
    } else {
        ''
    }
    Test-BRAVOCondition `
        -Condition (
            -not [string]::IsNullOrWhiteSpace($completeHealthResultFunctionText) -and
            $completeHealthResultFunctionText.Contains('if (-not $SuppressHeader) {') -and
            $completeHealthResultFunctionText.Contains('Write-BRAVOResultHeader') -and
            (
                $completeHealthResultFunctionText.IndexOf('Complete-BRAVOProgress')
            ) -lt (
                $completeHealthResultFunctionText.IndexOf('if (-not $SuppressHeader) {')
            ) -and
            (
                $completeHealthResultFunctionText.IndexOf('if (-not $SuppressHeader) {')
            ) -lt (
                $completeHealthResultFunctionText.IndexOf('Write-BRAVOResultHeader')
            )
        ) `
        -Name "Health/EmbeddedCallSuppressesOwnSummary" `
        -Failure "Complete-BRAVOHealthResult має придушувати власний Write-BRAVOResultHeader при -SuppressHeader (вбудований виклик з Archive), не чіпаючи Complete-BRAVOProgress"
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Console.MaintenanceRuntimeWrappedInFunction' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/Health.ServerSideHashFallbackIsInfoNotWarning' -DependsOn 'Root/Console.MaintenanceRuntimeWrappedInFunction') { try {

    # Реальний випадок: "SFTP MODEL: серверний SHA архіву недоступний;
    # використано повний збіг віддаленого hash-файлу" — перевірка все одно
    # УСПІШНА (через .sha512), тому це нотатка про метод, а не WARNING, що
    # привертає увагу оператора без причини.
    Test-BRAVOCondition `
        -Condition (
            $healthRuntimeText.Contains(
                '"SFTP $($ArchiveDefinition.Type): серверний SHA архіву недоступний; " +'
            ) -and
            [regex]::IsMatch(
                $healthRuntimeText,
                '(?s)серверний SHA архіву недоступний.*?використано повний збіг віддаленого hash-файлу"\s*\)\s*-Level "INFO"'
            )
        ) `
        -Name "Health/ServerSideHashFallbackIsInfoNotWarning" `
        -Failure "фолбек на .sha512-файл — це успішна перевірка іншим методом, а не WARNING; має логуватись як INFO"

    # 5.2.1 (реальний алерт SRV-LAB7 23:03): активний WinSCP.com іншої
    # BRAVO-операції робив SFTP health-check CRITICAL «ПОТРІБНА ДІЯ».
    # Transient-конкуренція = ВІДКЛАДЕННЯ: pre-check зайнятості ДО
    # конфігураційних/мережевих кроків -> WARNING + return без issues,
    # кроки SFTP — SKIPPED, SftpVerified не оголошується підтвердженим.
    Test-BRAVOCondition `
        -Condition (
            [regex]::IsMatch(
                $healthRuntimeText,
                '(?s)\$sftpWinScpAvailability = Test-BRAVOWinSCPAvailable -WinSCPPath \$winSCPPath.*?BRAVOHealthSftpCheckDeferredByBusyWinSCP = \$true.*?-Level "WARNING"\s*\r?\n\s*return @\(\)'
            ) -and
            $healthRuntimeText.Contains("'SKIPPED' } else { Get-BRAVOHealthStepStatus -IssueCount `$sftpArchivesStepIssues.Count }") -and
            $healthRuntimeText.Contains('$destinationSummary.SftpVerified = $false')
        ) `
        -Name "Health/BusyWinScpDefersSftpCheckAsWarning" `
        -Failure "зайнятий WinSCP.com має ВІДКЛАДАТИ SFTP health-check (WARNING + SKIPPED-кроки + SftpVerified=false), а не давати CRITICAL «ПОТРІБНА ДІЯ» — transient-конкуренція з іншою BRAVO-передачею не є збоєм SFTP"

    # T011: оркестрація Health — поведінкові перевірки порядку секцій
    # перевірок, незалежності перевірок одна від одної, розв'язання
    # підсумкового коду завершення через Complete-BRAVOHealthResult,
    # пропуску лише SFTP-гілки при порушенні цілісності інструментів (код 32,
    # README) і придушення доставки сповіщень параметром -NoSlack.
    # Наявні Health/* контракти вище — текстові (IndexOf/Contains); тут
    # runtime справді виконується. Повний прогін Invoke-BRAVOHealth
    # неможливий без реальної конфігурації, служб, Credential Manager і
    # WinSCP, тому дочірній процес збирає runtime з ДОСЛІВНОГО тексту
    # BRAVO.Health.Runtime.ps1 (AST): справжній param-блок, справжній
    # початковий стан прогону (лічильники кроків, історія,
    # $script:BRAVOToolManifest = $null), справжні функції кроків і
    # Complete-BRAVOHealthResult, а також дослівна оркестрація від
    # $script:BRAVOHealthLevelSeverity до кінця тіла (Initialize-BRAVOHealthSteps,
    # усі перевірки, гейти сповіщень, кожен return Complete-BRAVOHealthResult)
    # плюс справжній invocation guard (exit $script:healthRuntimeExitCode).
    # Справжніми лишаються й Get-SFTPHealthIssues/Test-SFTPHealthConfiguration
    # (саме там живе гейт цілісності), Write-HealthLog (лічильник
    # попереджень -> код 10) і Resolve-BRAVOExitCode. Преамбулу (імпорт
    # модулів, конфігурацію, облікові дані) замінює seed змінних, а самі
    # перевірки, WinSCP, стан алертів, статус-файл і доставку сповіщень —
    # стаби, що пишуть події у журнал. Зібраний runtime запускається через
    # справжній Invoke-BRAVOHealthEntrypoint. Стаби живуть лише в дочірньому
    # процесі; мережа, служби й реальні інструменти не чіпаються.
    # Увесь блок — у ДОЧІРНЬОМУ scope (`& { ... }`): жодна з його змінних
    # не лишається у script-scope цього flat-файлу (жорсткий ліміт 4096
    # змінних, див. Framework/BootstrapIntegrityCheckedBeforeManifestCoveredImports).
    & {
        $healthOrchestrationRoot = Join-Path `
            -Path ([IO.Path]::GetTempPath()) `
            -ChildPath ("BRAVO_HEALTH_ORCHESTRATION_SELF_TEST_{0}" -f [guid]::NewGuid().ToString("N"))
        try {
            [void][IO.Directory]::CreateDirectory($healthOrchestrationRoot)
            $healthOrchestrationStubs = @'
function Add-ProbeEvent { param([string]$Text) [IO.File]::AppendAllText($script:ProbeEventsPath, $Text + "`n", (New-Object Text.UTF8Encoding($false))) }
function Select-BRAVOExpectedArchiveDefinition { param($ArchiveDefinitions, [string[]]$NotInstalledComponents) return @(@($ArchiveDefinitions) | Where-Object { $_.Enabled -and @($NotInstalledComponents) -notcontains [string]$_.Type }) }
function New-ProbeIssue {
    param([string]$Kind, [string]$Component, [string]$Reason, [string]$Location)
    return [pscustomobject]@{ Kind = $Kind; Component = $Component; Reason = $Reason; FileName = 'немає даних'; LastWriteTime = $null; SizeBytes = $null; ActualSizeBytes = $null; Location = $Location; Details = @() }
}
function Write-BRAVOStepResult {
    param([int]$Current, [int]$Total, [string]$Name, [string]$Status, [string]$Details, $Duration)
    Add-ProbeEvent ("STEP {0}/{1} {2} {3}" -f $Current, $Total, $Name, $Status)
}
function Write-BRAVOOperationStatus { param($StateRoot, $Operation, $ExitCode, $ExitCodeName, $StartedAt, $FinishedAt, $Details) Add-ProbeEvent "STATUS $ExitCode" }
function Get-BRAVORestoreGenerationManifest { param($BackupRoot) throw 'self-test: маніфест поколінь не потрібен' }
function Get-BRAVORestoreVerifyStatePath { param($StateRoot) return 'self-test-restore-verify.json' }
function Get-BRAVORestoreVerifyState { param($Path) return [pscustomobject]@{ Exists = $false; Corrupt = $false; State = $null } }
function Get-BRAVOOSSupportTier { return [pscustomobject]@{ Tier = 'Supported'; OperatingSystem = 'self-test'; OperatingSystemVersion = '10.0'; Build = 0; PowerShellVersion = '5.1'; DotNetRelease = 0; Message = '' } }
function Get-BRAVOToolIntegrityRecommendation { param($ToolPaths, $ManifestPath) return [pscustomobject]@{ HasIntegrityIssue = $false; Message = '' } }
function Test-BRAVOToolManifestIntegrity {
    param($ToolsDirectory, $ManifestPath, $Mode)
    Add-ProbeEvent 'TOOL-MANIFEST'
    if ($script:ProbeToolIntegrityViolation) {
        return [pscustomobject]@{ IsValid = $false; ShouldBlock = $true; Message = 'self-test: хеш WinSCP.com не збігається з TOOLS_MANIFEST.json' }
    }
    return [pscustomobject]@{ IsValid = $true; ShouldBlock = $false; Message = '' }
}
function Test-BRAVOHealthEnvironmentPreflight {
    param($LogPath, $TemporaryRoot)
    Add-ProbeEvent 'PREFLIGHT'
    if ($script:ProbePreflightPrivilegeFailure) { return [pscustomobject]@{ IsWritable = $false; FailedPath = 'LOGS'; ErrorMessage = 'self-test: Access denied'; IsPrivilegeFailure = $true } }
    return [pscustomobject]@{ IsWritable = $true; FailedPath = $null; ErrorMessage = $null; IsPrivilegeFailure = $false }
}
function Get-HostInformation { return 'self-test-host' }
function New-BRAVOOperatorNotificationMessage { param($Severity, $Operation, $ActionText, $ReasonLines, $InstitutionName, $InstitutionCode, $HostInformation, $ResultLines, $Timestamp, $ProductName, $Version, $BuildId, $LogPath) return 'self-test environment alert' }
function Get-BRAVOHealthTemporaryRoot { return $script:ProbeTemporaryRoot }
function Remove-BRAVOHealthTemporaryDirectory { param($Path) }
function Invoke-BRAVOServiceQuiescenceWatchdog { Add-ProbeEvent 'CHECK watchdog'; return @() }
function Get-ManagedServiceHealthIssues {
    Add-ProbeEvent 'CHECK services'
    if ($script:ProbeFailServices) { return @(New-ProbeIssue -Kind 'Service' -Component 'Служба BRAVO' -Reason 'self-test: служба зупинена' -Location 'BRAVO') }
    return @()
}
function Get-BackupHealthIssues {
    Add-ProbeEvent 'CHECK local'
    $script:healthLatestArchives['MODEL'] = [pscustomobject]@{ FullName = $script:ProbeLocalArchivePath; LastWriteTime = (Get-Date); SizeBytes = 1; GenerationId = 'self-test' }
    return @()
}
function Get-RestoreVerifyHealthIssues { Add-ProbeEvent 'CHECK restore-verify'; return @() }
function Get-BAZALocalSyncHealthIssues { param([bool]$Enabled, $SourcePath, $DestinationPath, [string]$Label) Add-ProbeEvent "CHECK baza-local $Label"; return @() }
function Get-SMBHealthIssues {
    Add-ProbeEvent 'CHECK smb'
    if ($script:ProbeFailSmb) { return @(New-ProbeIssue -Kind 'SMBConnection' -Component 'NAS/SMB' -Reason 'self-test: NAS недоступний' -Location '\\nas\backup') }
    return @()
}
function Test-BRAVOWinSCPAvailable {
    param($WinSCPPath)
    Add-ProbeEvent 'WINSCP-AVAILABILITY'
    if ($script:ProbeWinScpBusy) { return [pscustomobject]@{ Available = $false; ProcessIds = @(4242) } }
    return [pscustomobject]@{ Available = $true; ProcessIds = @() }
}
function Get-BRAVOWinSCPBusyMessage { param($Availability, $Operation) return "self-test: WinSCP.com зайнятий ($Operation)" }
function Get-SFTPRemoteArchiveChecksumResults { param($ArchiveChecks) Add-ProbeEvent 'WINSCP-CHECKSUM'; return @{} }
function Invoke-WinSCPHealthSession { param($Commands) Add-ProbeEvent 'WINSCP-SESSION'; return [pscustomobject]@{ Success = $true; ExitCode = 0; Xml = $null; Error = $null } }
function Get-WinSCPRemoteListings { param($Xml) return @([pscustomobject]@{ Destination = '/self-test/model'; Files = @() }) }
function Get-WinSCPRemoteDownloads { param($Xml) return @() }
function Resolve-DownloadedRemoteHashPath { param($ArchiveCheck, $Downloads) return [pscustomobject]@{ Path = 'self-test.sha512'; Error = $null } }
function Test-SFTPArchiveCopy { param($ArchiveDefinition, $LocalArchive, $RemoteListing, $RemoteDirectory, $DownloadedRemoteHashPath, $RemoteArchiveChecksumResult) Add-ProbeEvent "WINSCP-COPY $($ArchiveDefinition.Type)"; return $null }
function New-SlackAlertMessage {
    param($Issues, $Duration)
    foreach ($probeIssue in @($Issues)) { Add-ProbeEvent ("ALERT-ISSUE {0} | {1}" -f $probeIssue.Component, $probeIssue.Reason) }
    return 'self-test alert'
}
function New-SlackSuccessMessage { param($Duration) return 'self-test success' }
function Get-AlertFingerprint { param($Issues) return 'self-test-alert-fingerprint' }
function Test-AlertSuppressed { param($Fingerprint) return $false }
function Save-AlertState { param($Fingerprint) Add-ProbeEvent 'ALERT-STATE-SAVE' }
function Clear-AlertState { Add-ProbeEvent 'ALERT-STATE-CLEAR' }
function Get-BRAVOHealthOperationalState { return [pscustomobject]@{ RecoveryPending = $false } }
function Save-BRAVOHealthOperationalState { param([bool]$RecoveryPending) Add-ProbeEvent "RECOVERY-PENDING $RecoveryPending" }
function Get-BRAVOHealthSuccessFingerprint { param($DestinationSummary, $SftpDeferred, $EnabledCheckNames, $ArchiveIdentities) return ('0' * 64) }
function Get-BRAVOHealthSuccessNotificationState { return $null }
function Save-BRAVOHealthSuccessNotificationState { param($Fingerprint) Add-ProbeEvent 'SUCCESS-STATE-SAVE' }
function Resolve-BRAVONotificationRoute { param($Severity, $NotificationMode, $RoutingTable) Add-ProbeEvent "NOTIFY-ROUTE $Severity"; if ($Severity -eq 'SUCCESS') { return 'general' } return 'alerts' }
function ConvertTo-BRAVONotificationPayloadText { param($Provider, $Message) return @([string]$Message) }
function Send-BRAVONotificationChunks {
    param($Provider, $WebhookUrl, $MessageChunks, $TimeoutSeconds)
    if ($script:ProbeNotificationThrows) { Add-ProbeEvent 'NOTIFY-FAIL'; throw 'self-test: webhook недоступний' }
    Add-ProbeEvent ("NOTIFY-SEND {0} {1}" -f $WebhookUrl, (@($MessageChunks) -join '|'))
}
'@
            $healthOrchestrationSeed = @'
$global:ScriptVersion = 'self-test'
$global:ScriptBuildId = 'self-test'
$global:archiveDefinitions = @([pscustomobject]@{ Type = 'MODEL'; Enabled = $true })
$archiveDefinitions = $global:archiveDefinitions
$bravoScriptDirectory = $probeWorkRoot
$ConfigPath = Join-Path $probeWorkRoot 'BRAVO.config'
$healthCheckStarted = Get-Date
$healthCheckStartedUtc = $healthCheckStarted.ToUniversalTime()
$script:healthLatestArchives = @{}
$backupMonitoring = [pscustomobject]@{
    Enabled = $probeMonitoringEnabled
    NotificationProvider = 'slack'
    NotificationMode = $probeNotificationMode
    NotificationRouting = $null
    MaxBackupAgeHours = 26
    InstitutionName = 'self-test'
    InstitutionCode = 'SELFTEST'
    SuccessDedupMinutes = 0
    LogFileNameTemplate = 'BRAVO_ARCHIV_HEALTH_{0}.log'
    SFTP = [pscustomobject]@{ Enabled = $true; CheckArchiveUploads = $true; CheckBAZASynchronization = $false; OperationTimeoutSeconds = 60; RemoteBackupMaxAgeHours = 26; VerifyRemoteArchiveHash = $false; BAZAPreviewOptions = '-preview'; DifferenceDetailLimit = 10 }
    SMB = [pscustomobject]@{ Enabled = $true }
}
$componentSettings = [pscustomobject]@{ SFTP = [pscustomobject]@{ ArchiveUpload = $true } }
$storageEffective = [pscustomobject]@{
    SFTP = [pscustomobject]@{ Enabled = $true; DisabledReason = '' }
    SMB = [pscustomobject]@{ Enabled = $true; DisabledReason = '' }
}
$bazaAppLocalHealthEnabled = $true
$bazaWWWLocalHealthEnabled = $true
$bazaAppSFTPHealthEnabled = $false
$bazaWWWSFTPHealthEnabled = $false
$bazaWWWDetection = [pscustomobject]@{ Success = $true; ServiceName = 'self-test'; Reason = '' }
$bazaAppPaths = [pscustomobject]@{ Source = (Join-Path $probeWorkRoot 'baza_app'); Destination = (Join-Path $probeWorkRoot 'backup\BAZA_APP') }
$bazaWWWPaths = [pscustomobject]@{ Source = (Join-Path $probeWorkRoot 'baza_www'); Destination = (Join-Path $probeWorkRoot 'backup\BAZA_WWW') }
$logPath = Join-Path $probeWorkRoot 'logs'
$healthLogFile = Join-Path $logPath 'health.log'
$logTimestampFormat = 'yyyy-MM-dd HH:mm:ss'
$logFileEncoding = 'UTF8'
$credentialHelperLoaded = $true
$credentialHelperError = $null
$notificationCredentialError = $null
$sftpCredentialError = $null
$smbCredentialError = $null
$script:smbCredential = $null
$script:BRAVOWarningCount = 0
$script:bravoHealthTemporaryRoot = $null
$script:BRAVOHealthLogWritable = $true
$NotificationProvider = 'slack'
$NotificationMode = $probeNotificationMode
$script:NotificationWebhookUrls = @{ alerts = $probeAlertsWebhook; general = 'https://self-test.invalid/general' }
$script:Login = 'self-test'
$script:resolvedSftpHost = 'self-test.invalid'
$script:sftpUrl = 'sftp://self-test.invalid/'
$sftpHostKey = 'ssh-ed25519 255 self-test'
$sftpArchivesHealthEnabled = $true
$sftpBazaAppHealthEnabled = $false
$sftpBazaWWWHealthEnabled = $false
$sftpCredentialRequired = $true
$smbCredentialRequired = $true
$NotificationRequestTimeoutSeconds = 5
$NotificationProviderDisplayName = 'Slack'
$consoleSettings = [pscustomobject]@{ ConsoleLevel = 'WARNING'; StepWidth = 58; ShowTimestampsInConsole = $false }
$progressSettings = [pscustomobject]@{ Enabled = $false }
$schedulerSettings = [pscustomobject]@{ TaskPath = '\'; Backup = [pscustomobject]@{ TaskName = 'self-test' }; Health = [pscustomobject]@{ BusyWaitMinutes = 0 }; RestoreVerify = [pscustomobject]@{ Enabled = $true } }
$restoreVerifySettings = [pscustomobject]@{ MaxVerificationAgeHours = 200 }
$bravoSettings = [pscustomobject]@{ InstitutionName = 'self-test'; InstitutionCode = 'SELFTEST' }
$script:BRAVOCompatibility = [pscustomobject]@{ WindowsVersion = 'self-test'; PowerShellVersion = 'self-test'; WmiProvider = 'self-test'; JsonProvider = 'self-test'; TaskSchedulerProvider = 'self-test' }
$script:BRAVOPowerShellUpdate = [pscustomobject]@{ IsUpdateRecommended = $false; Message = '' }
$script:BRAVOWindowsPatchLevel = [pscustomobject]@{ IsUpdateRecommended = $false; Message = '' }
$toolsPath = Join-Path $probeWorkRoot 'Tools'
$arcPath = Join-Path $toolsPath '7za.exe'
$winSCPPath = Join-Path $toolsPath 'WinSCP.com'
$winSCPAssemblyPath = Join-Path $toolsPath 'WinSCPnet.dll'
$toolIntegritySettings = $null
$sftpDirectories = @{ MODEL = '/self-test/model' }
$hashFileExtension = '.sha512'
$sftpSynchronizationOptions = ''
$sftpConnectionTimeoutSeconds = 15
$stateRoot = Join-Path $probeWorkRoot 'state'
$backupRootPath = Join-Path $probeWorkRoot 'backup'
$credentialSettings = $null
$operationsReportingSettings = $null
'@
            $healthOrchestrationProbeScript = @'
param([string]$Scenario, [string]$RepositoryRoot, [string]$ProbeRoot)
$ErrorActionPreference = 'Stop'
$probeResultPath = Join-Path $ProbeRoot 'result.json'
$probeUtf8 = New-Object Text.UTF8Encoding($false)
try {
    $probeRuntimeText = [IO.File]::ReadAllText(
        (Join-Path $RepositoryRoot 'modules\BRAVO.Health\BRAVO.Health.Runtime.ps1'), [Text.Encoding]::UTF8)
    $probeParseErrors = $null
    $probeAst = [Management.Automation.Language.Parser]::ParseInput($probeRuntimeText, [ref]$null, [ref]$probeParseErrors)
    if (@($probeParseErrors).Count -gt 0) { throw "runtime не парситься: $($probeParseErrors[0].Message)" }
    $probeTopStatements = @($probeAst.EndBlock.Statements)
    $probeWrapper = @($probeTopStatements | Where-Object {
            $_ -is [Management.Automation.Language.FunctionDefinitionAst] -and $_.Name -eq 'Invoke-BRAVOHealth'
        }) | Select-Object -First 1
    if ($null -eq $probeWrapper) { throw 'у runtime немає функції Invoke-BRAVOHealth' }
    $probeGuard = @($probeTopStatements | Where-Object {
            $_ -is [Management.Automation.Language.IfStatementAst] -and $_.Extent.Text -match '^if \(\$MyInvocation\.InvocationName -ne ''\.''\)'
        }) | Select-Object -First 1
    if ($null -eq $probeGuard) { throw 'у runtime немає invocation guard' }
    $probeStatements = @($probeWrapper.Body.EndBlock.Statements)
    $probeRegionIndex = -1
    $probeFirstFunctionIndex = -1
    for ($probeIndex = 0; $probeIndex -lt $probeStatements.Count; $probeIndex++) {
        if ($probeFirstFunctionIndex -lt 0 -and $probeStatements[$probeIndex] -is [Management.Automation.Language.FunctionDefinitionAst]) {
            $probeFirstFunctionIndex = $probeIndex
        }
        if ($probeStatements[$probeIndex].Extent.Text -match '^\$script:BRAVOHealthLevelSeverity = @\{') {
            $probeRegionIndex = $probeIndex
            break
        }
    }
    if ($probeRegionIndex -lt 0 -or $probeFirstFunctionIndex -lt 0) { throw 'у тілі Invoke-BRAVOHealth немає $script:BRAVOHealthLevelSeverity' }

    $probeStubs = [IO.File]::ReadAllText((Join-Path (Split-Path -Parent $ProbeRoot) 'stubs.ps1'), [Text.Encoding]::UTF8)
    $probeStubNames = @{}
    foreach ($probeStubAst in @([Management.Automation.Language.Parser]::ParseInput($probeStubs, [ref]$null, [ref]$null).EndBlock.Statements)) {
        if ($probeStubAst -is [Management.Automation.Language.FunctionDefinitionAst]) { $probeStubNames[$probeStubAst.Name] = $true }
    }
    # Дослівний стан прогону до першої функції (лічильники кроків, історія,
    # $script:BRAVOToolManifest = $null) і справжні функції до регіону.
    $probeLeadingTexts = New-Object System.Collections.Generic.List[string]
    for ($probeIndex = 0; $probeIndex -lt $probeFirstFunctionIndex; $probeIndex++) {
        $probeLeadingTexts.Add($probeStatements[$probeIndex].Extent.Text)
    }
    $probeFunctionTexts = New-Object System.Collections.Generic.List[string]
    for ($probeIndex = 0; $probeIndex -lt $probeRegionIndex; $probeIndex++) {
        $probeStatement = $probeStatements[$probeIndex]
        if ($probeStatement -is [Management.Automation.Language.FunctionDefinitionAst] -and
            -not $probeStubNames.ContainsKey($probeStatement.Name)) {
            $probeFunctionTexts.Add($probeStatement.Extent.Text)
        }
    }
    # Дослівна оркестрація від рівнів журналу до кінця тіла: ініціалізація
    # кроків, усі перевірки, сповіщення й кожен return Complete-BRAVOHealthResult.
    # Затінені стабами визначення функцій у ній замінюються пробілами.
    $probeRegionStart = $probeStatements[$probeRegionIndex].Extent.StartOffset
    $probeRegionEnd = $probeStatements[$probeStatements.Count - 1].Extent.EndOffset
    $probeRegion = New-Object Text.StringBuilder($probeRuntimeText.Substring($probeRegionStart, $probeRegionEnd - $probeRegionStart))
    foreach ($probeDefinition in @($probeWrapper.Body.FindAll({
                    param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst]
                }, $true) | Where-Object {
                $_.Extent.StartOffset -ge $probeRegionStart -and $probeStubNames.ContainsKey($_.Name)
            })) {
        $probeLength = $probeDefinition.Extent.EndOffset - $probeDefinition.Extent.StartOffset
        [void]$probeRegion.Remove($probeDefinition.Extent.StartOffset - $probeRegionStart, $probeLength)
        [void]$probeRegion.Insert($probeDefinition.Extent.StartOffset - $probeRegionStart, (' ' * $probeLength))
    }

    $probeEventsPath = Join-Path $ProbeRoot 'events.txt'
    $probeTemporaryRoot = Join-Path $ProbeRoot 'TEMP'
    $probeLocalArchivePath = Join-Path $ProbeRoot 'backup\MODEL\MODEL_self-test.7z'
    foreach ($probeDirectory in @($probeTemporaryRoot, (Split-Path -Parent $probeLocalArchivePath), (Join-Path $ProbeRoot 'Tools'))) {
        [void][IO.Directory]::CreateDirectory($probeDirectory)
    }
    [IO.File]::WriteAllText($probeLocalArchivePath, 'self-test', $probeUtf8)
    [IO.File]::WriteAllText((Join-Path $ProbeRoot 'Tools\WinSCP.com'), 'self-test', $probeUtf8)
    $probeFlag = { param([bool]$Value) if ($Value) { '$true' } else { '$false' } }
    $probeScenarioSeed = @(
        ('$script:ProbeEventsPath = ''{0}''' -f $probeEventsPath.Replace("'", "''")),
        ('$probeWorkRoot = ''{0}''' -f $ProbeRoot.Replace("'", "''")),
        ('$script:ProbeTemporaryRoot = ''{0}''' -f $probeTemporaryRoot.Replace("'", "''")),
        ('$script:ProbeLocalArchivePath = ''{0}''' -f $probeLocalArchivePath.Replace("'", "''")),
        '$probeNotificationMode = ''all''',
        ('$probeMonitoringEnabled = {0}' -f (& $probeFlag ($Scenario -ne 'MonitoringDisabled'))),
        ('$probeAlertsWebhook = ''{0}''' -f $(if ($Scenario -eq 'InsecureWebhook') { 'http://self-test.invalid/alerts' } else { 'https://self-test.invalid/alerts' })),
        ('$script:ProbeFailServices = {0}' -f (& $probeFlag ($Scenario -like 'Failures*' -or $Scenario -eq 'NotificationFailure'))),
        ('$script:ProbeFailSmb = {0}' -f (& $probeFlag ($Scenario -like 'Failures*'))),
        ('$script:ProbeNotificationThrows = {0}' -f (& $probeFlag ($Scenario -eq 'NotificationFailure'))),
        ('$script:ProbePreflightPrivilegeFailure = {0}' -f (& $probeFlag ($Scenario -eq 'EnvironmentPrivilege'))),
        ('$script:ProbeToolIntegrityViolation = {0}' -f (& $probeFlag ($Scenario -eq 'ToolIntegrity'))),
        ('$script:ProbeWinScpBusy = {0}' -f (& $probeFlag ($Scenario -eq 'WinScpBusy')))
    ) -join "`n"
    $probeGenerated = @(
        $probeAst.ParamBlock.Extent.Text,
        'function Invoke-BRAVOHealth {',
        $probeWrapper.Body.ParamBlock.Extent.Text,
        'Set-StrictMode -Version 2.0',
        ($probeLeadingTexts -join "`n"),
        ($probeFunctionTexts -join "`n`n"),
        $probeStubs,
        $probeScenarioSeed,
        [IO.File]::ReadAllText((Join-Path (Split-Path -Parent $ProbeRoot) 'seed.ps1'), [Text.Encoding]::UTF8),
        $probeRegion.ToString(),
        '}',
        $probeGuard.Extent.Text
    ) -join "`n"
    $probeGeneratedPath = Join-Path $ProbeRoot 'runtime.ps1'
    [IO.File]::WriteAllText($probeGeneratedPath, $probeGenerated, (New-Object Text.UTF8Encoding($true)))

    foreach ($probeModule in @('BRAVO.Console', 'BRAVO.ExitCodes', 'BRAVO.Logging', 'BRAVO.Health')) {
        Import-Module -Name (Join-Path $RepositoryRoot "modules\$probeModule\$probeModule.psd1") -Force
    }
    & (Get-Module -Name 'BRAVO.Health') { param($Path) $script:runtimePath = $Path } $probeGeneratedPath
    $probeParameters = @{
        RuntimeRoot = $ProbeRoot
        EntryScriptPath = (Join-Path $ProbeRoot 'BRAVO_HEALTH.ps1')
        NoPause = $true
    }
    if ($Scenario -like '*NoSlack') { $probeParameters['NoSlack'] = $true }
    if ($Scenario -like 'Happy*') { $probeParameters['NotifyOnSuccess'] = $true }
    $global:LASTEXITCODE = 77
    $probeErrors = $null
    $ErrorActionPreference = 'Continue'
    $probeExitCode = Invoke-BRAVOHealthEntrypoint -Parameters $probeParameters -ErrorVariable probeErrors 2>$null
    $probeEvents = @()
    if (Test-Path -LiteralPath $probeEventsPath -PathType Leaf) {
        $probeEvents = @([IO.File]::ReadAllLines($probeEventsPath, [Text.Encoding]::UTF8))
    }
    $probeLogPath = Join-Path $ProbeRoot 'logs\health.log'
    $probeLog = @()
    if (Test-Path -LiteralPath $probeLogPath -PathType Leaf) {
        $probeLog = @([IO.File]::ReadAllLines($probeLogPath, [Text.Encoding]::UTF8))
    }
    $probeResult = [pscustomobject]@{
        ExitCode = [int]$probeExitCode
        ExitCodeName = [string](Get-BRAVOExitCodeName -Code ([int]$probeExitCode))
        Events = $probeEvents
        Log = $probeLog
        Errors = @(@($probeErrors) | ForEach-Object { [string]$_ })
    }
} catch {
    $probeResult = [pscustomobject]@{ ProbeError = [string]$_.Exception.Message }
}
[IO.File]::WriteAllText($probeResultPath, ($probeResult | ConvertTo-Json -Compress -Depth 4), $probeUtf8)
'@
            $healthOrchestrationUtf8 = New-Object Text.UTF8Encoding($false)
            [IO.File]::WriteAllText((Join-Path $healthOrchestrationRoot 'stubs.ps1'), $healthOrchestrationStubs, $healthOrchestrationUtf8)
            [IO.File]::WriteAllText((Join-Path $healthOrchestrationRoot 'seed.ps1'), $healthOrchestrationSeed, $healthOrchestrationUtf8)
            $healthOrchestrationProbePath = Join-Path $healthOrchestrationRoot 'probe.ps1'
            [IO.File]::WriteAllText($healthOrchestrationProbePath, $healthOrchestrationProbeScript, (New-Object Text.UTF8Encoding($true)))
            $healthOrchestrationHost = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
            $healthOrchestrationResults = @{}
            foreach ($healthOrchestrationScenario in @(
                    'Happy', 'HappyNoSlack', 'Failures', 'FailuresNoSlack', 'ToolIntegrity',
                    'WinScpBusy', 'NotificationFailure', 'EnvironmentPrivilege', 'MonitoringDisabled', 'InsecureWebhook'
                )) {
                $healthOrchestrationScenarioRoot = Join-Path $healthOrchestrationRoot $healthOrchestrationScenario
                [void][IO.Directory]::CreateDirectory($healthOrchestrationScenarioRoot)
                $null = & $healthOrchestrationHost -NoLogo -NoProfile -NonInteractive `
                    -ExecutionPolicy Bypass -File $healthOrchestrationProbePath `
                    -Scenario $healthOrchestrationScenario -RepositoryRoot $root -ProbeRoot $healthOrchestrationScenarioRoot
                $healthOrchestrationResultPath = Join-Path $healthOrchestrationScenarioRoot 'result.json'
                $healthOrchestrationResults[$healthOrchestrationScenario] = if (Test-Path -LiteralPath $healthOrchestrationResultPath -PathType Leaf) {
                    [IO.File]::ReadAllText($healthOrchestrationResultPath, [Text.Encoding]::UTF8) | ConvertFrom-Json
                } else {
                    [pscustomobject]@{ ProbeError = "проба не записала result.json (код виходу $LASTEXITCODE)" }
                }
            }
            # Події сценарію (порожньо, якщо проба впала — тоді кожна умова
            # нижче також перевіряє відсутність ProbeError).
            $healthOrchestrationEvents = {
                param([string]$Scenario)
                $probeOutcome = $healthOrchestrationResults[$Scenario]
                if ($null -ne $probeOutcome.PSObject.Properties['ProbeError']) { return @() }
                return @($probeOutcome.Events | ForEach-Object { [string]$_ })
            }
            $healthOrchestrationProbeOk = {
                param([string]$Scenario)
                return ($null -eq $healthOrchestrationResults[$Scenario].PSObject.Properties['ProbeError'])
            }
            $healthOrchestrationSelect = {
                param([object[]]$Events, [string]$Pattern)
                return ((@($Events | Where-Object { $_ -match $Pattern })) -join '|')
            }
            $healthOrchestrationIndex = {
                param([object[]]$Events, [string]$Pattern)
                for ($eventIndex = 0; $eventIndex -lt $Events.Count; $eventIndex++) {
                    if ([string]$Events[$eventIndex] -match $Pattern) { return $eventIndex }
                }
                return -1
            }
            # Очікувана послідовність секцій [1..8]/Total разом із викликами
            # перевірок, які кожна секція рендерить: перевірка -> її крок ->
            # наступна перевірка. Порядок узято з коду runtime (Write-BRAVOHealthStep).
            $healthOrchestrationChecksPattern = '^(PREFLIGHT$|CHECK |WINSCP-SESSION$|STEP [1-8]/)'
            $healthOrchestrationExpectedChecks = {
                param([int]$Total, [string[]]$Status, [bool]$SftpSessionRan)
                $expectedLines = @(
                    'PREFLIGHT',
                    "STEP 1/$Total Середовище й цілісність інструментів $($Status[0])",
                    'CHECK watchdog',
                    'CHECK services',
                    "STEP 2/$Total Керовані служби $($Status[1])",
                    'CHECK local',
                    "STEP 3/$Total Локальні резервні копії $($Status[2])",
                    'CHECK restore-verify',
                    "STEP 4/$Total Відновлюваність (restore drill) $($Status[3])",
                    'CHECK baza-local BAZA APP',
                    "STEP 5/$Total BAZA_APP (локальна копія) $($Status[4])",
                    'CHECK baza-local BAZA WWW',
                    "STEP 6/$Total BAZA_WWW (локальна копія) $($Status[5])"
                )
                if ($SftpSessionRan) { $expectedLines += 'WINSCP-SESSION' }
                $expectedLines += @(
                    "STEP 7/$Total SFTP: резервні копії $($Status[6])",
                    'CHECK smb',
                    "STEP 8/$Total NAS/SMB $($Status[7])"
                )
                return ($expectedLines -join '|')
            }
            $healthOrchestrationAllOk = @('OK', 'OK', 'OK', 'OK', 'OK', 'OK', 'OK', 'OK')
            $healthOrchestrationFailedStatuses = @('OK', 'ERROR', 'OK', 'OK', 'OK', 'OK', 'OK', 'ERROR')
            $healthOrchestrationNotificationPattern = '^(NOTIFY-|ALERT-STATE-SAVE$|SUCCESS-STATE-SAVE$)'

            # (1) Щасливий шлях: рівно 9 секцій у порядку коду — середовище й
            # цілісність, керовані служби, локальні копії, відновлюваність,
            # BAZA_APP/BAZA_WWW локально, SFTP (справжня Get-SFTPHealthIssues
            # доходить до WinSCP-сесії), NAS/SMB, і лише після статус-файлу —
            # "Сповіщення" з Complete-BRAVOHealthResult; кожна перевірка
            # викликається рівно перед своїм кроком; код 0.
            $healthHappy = $healthOrchestrationResults['Happy']
            $healthHappyEvents = @(& $healthOrchestrationEvents 'Happy')
            Test-BRAVOCondition `
                -Condition (
                    (& $healthOrchestrationProbeOk 'Happy') -and
                    $healthHappy.ExitCode -eq 0 -and
                    (& $healthOrchestrationSelect $healthHappyEvents $healthOrchestrationChecksPattern) -ceq (& $healthOrchestrationExpectedChecks 9 $healthOrchestrationAllOk $true) -and
                    (& $healthOrchestrationSelect $healthHappyEvents '^(NOTIFY-SEND |STATUS |STEP 9/)') -ceq 'NOTIFY-SEND https://self-test.invalid/general self-test success|STATUS 0|STEP 9/9 Сповіщення OK' -and
                    $healthHappyEvents.Count -gt 0 -and
                    $healthHappyEvents[$healthHappyEvents.Count - 1] -ceq 'STEP 9/9 Сповіщення OK'
                ) `
                -Name "Health/OrchestrationRunsChecksInContractOrder" `
                -Failure "Health на щасливому шляху має виконати [1/9]..[9/9] у порядку коду (кожна перевірка — перед своїм кроком, 'Сповіщення' — останнім після статус-файлу) і завершитися кодом 0; проба: $($healthHappy | ConvertTo-Json -Compress -Depth 4)"

            # (2) Збій двох незалежних перевірок (керовані служби, NAS/SMB) не
            # ховає решту: усі наступні перевірки все одно виконуються (зокрема
            # SFTP-сесія), їхні кроки OK, обидві проблеми потрапляють в ОДНЕ
            # сповіщення CRITICAL, RecoveryPending фіксується ДО доставки, а
            # підсумок — 70 (HealthCritical).
            $healthFailures = $healthOrchestrationResults['Failures']
            $healthFailuresEvents = @(& $healthOrchestrationEvents 'Failures')
            $healthFailuresRecoveryPending = & $healthOrchestrationIndex $healthFailuresEvents '^RECOVERY-PENDING True$'
            $healthFailuresSend = & $healthOrchestrationIndex $healthFailuresEvents '^NOTIFY-SEND '
            Test-BRAVOCondition `
                -Condition (
                    (& $healthOrchestrationProbeOk 'Failures') -and
                    $healthFailures.ExitCode -eq 70 -and
                    $healthFailures.ExitCodeName -eq 'HealthCritical' -and
                    (& $healthOrchestrationSelect $healthFailuresEvents $healthOrchestrationChecksPattern) -ceq (& $healthOrchestrationExpectedChecks 9 $healthOrchestrationFailedStatuses $true) -and
                    (& $healthOrchestrationSelect $healthFailuresEvents '^ALERT-ISSUE ') -ceq 'ALERT-ISSUE Служба BRAVO | self-test: служба зупинена|ALERT-ISSUE NAS/SMB | self-test: NAS недоступний' -and
                    (& $healthOrchestrationSelect $healthFailuresEvents '^(NOTIFY-|ALERT-STATE-SAVE$|STATUS |STEP 9/)') -ceq 'NOTIFY-ROUTE CRITICAL|NOTIFY-SEND https://self-test.invalid/alerts self-test alert|ALERT-STATE-SAVE|STATUS 70|STEP 9/9 Сповіщення OK' -and
                    $healthFailuresRecoveryPending -ge 0 -and
                    $healthFailuresRecoveryPending -lt $healthFailuresSend
                ) `
                -Name "Health/OrchestrationFailedCheckDoesNotHideOtherChecks" `
                -Failure "збій перевірки служб і NAS/SMB не має переривати решту перевірок: усі секції мають виконатися, обидві проблеми — потрапити в одне CRITICAL-сповіщення, а код — бути 70 (HealthCritical); проба: $($healthFailures | ConvertTo-Json -Compress -Depth 4)"

            # (3) Порушення цілісності інструментів (README: пропускає всю
            # SFTP-гілку й завершується кодом 32): жодного виклику WinSCP,
            # SFTP-крок — ERROR із причиною гейту цілісності, а служби, локальні
            # копії, відновлюваність, BAZA локально й NAS/SMB виконуються й
            # проходять. Код 32 перекриває 70 від SFTP-проблеми. Контроль: у
            # сценарії (1) та сама справжня Get-SFTPHealthIssues доходить до
            # WINSCP-SESSION, тож відсутність сесії тут — ефект гейту.
            $healthToolIntegrity = $healthOrchestrationResults['ToolIntegrity']
            $healthToolIntegrityEvents = @(& $healthOrchestrationEvents 'ToolIntegrity')
            $healthToolIntegrityAlerts = @($healthToolIntegrityEvents | Where-Object { $_ -like 'ALERT-ISSUE *' })
            Test-BRAVOCondition `
                -Condition (
                    (& $healthOrchestrationProbeOk 'ToolIntegrity') -and
                    $healthToolIntegrity.ExitCode -eq 32 -and
                    $healthToolIntegrity.ExitCodeName -eq 'ToolIntegrityViolation' -and
                    (& $healthOrchestrationSelect $healthToolIntegrityEvents $healthOrchestrationChecksPattern) -ceq (& $healthOrchestrationExpectedChecks 9 @('ERROR', 'OK', 'OK', 'OK', 'OK', 'OK', 'ERROR', 'OK') $false) -and
                    @($healthToolIntegrityEvents | Where-Object { $_ -match '^WINSCP-(SESSION|CHECKSUM|COPY)' }).Count -eq 0 -and
                    $healthToolIntegrityAlerts.Count -eq 1 -and
                    $healthToolIntegrityAlerts[0].StartsWith('ALERT-ISSUE SFTP | ') -and
                    $healthToolIntegrityAlerts[0].Contains('SFTP-перевірки пропущено: не підтверджено цілісність інструментів') -and
                    (& $healthOrchestrationSelect $healthToolIntegrityEvents '^STATUS ') -ceq 'STATUS 32'
                ) `
                -Name "Health/OrchestrationToolIntegritySkipsOnlySftp" `
                -Failure "порушення цілісності інструментів має пропустити лише SFTP-гілку (без жодного виклику WinSCP), залишивши локальні перевірки виконаними, і завершити Health кодом 32 (ToolIntegrityViolation); проба: $($healthToolIntegrity | ConvertTo-Json -Compress -Depth 4)"

            # (4) -NoSlack придушує лише доставку: ті самі перевірки з тими
            # самими статусами й тим самим кодом (0 / 70), але без маршрутизації
            # і відправлення сповіщень, без запису стану алерту/success-звіту й
            # без кроку "Сповіщення" (Total 8). Контроль: сценарії (1) і (2) без
            # -NoSlack фактично відправляють.
            $healthHappyNoSlack = $healthOrchestrationResults['HappyNoSlack']
            $healthHappyNoSlackEvents = @(& $healthOrchestrationEvents 'HappyNoSlack')
            $healthFailuresNoSlack = $healthOrchestrationResults['FailuresNoSlack']
            $healthFailuresNoSlackEvents = @(& $healthOrchestrationEvents 'FailuresNoSlack')
            Test-BRAVOCondition `
                -Condition (
                    (& $healthOrchestrationProbeOk 'HappyNoSlack') -and
                    (& $healthOrchestrationProbeOk 'FailuresNoSlack') -and
                    $healthHappyNoSlack.ExitCode -eq 0 -and
                    $healthFailuresNoSlack.ExitCode -eq 70 -and
                    (& $healthOrchestrationSelect $healthHappyNoSlackEvents $healthOrchestrationChecksPattern) -ceq (& $healthOrchestrationExpectedChecks 8 $healthOrchestrationAllOk $true) -and
                    (& $healthOrchestrationSelect $healthFailuresNoSlackEvents $healthOrchestrationChecksPattern) -ceq (& $healthOrchestrationExpectedChecks 8 $healthOrchestrationFailedStatuses $true) -and
                    @($healthHappyNoSlackEvents + $healthFailuresNoSlackEvents | Where-Object { $_ -match $healthOrchestrationNotificationPattern -or $_ -match '^STEP \d+/\d+ Сповіщення ' }).Count -eq 0 -and
                    (& $healthOrchestrationSelect $healthHappyNoSlackEvents '^STATUS ') -ceq 'STATUS 0' -and
                    (& $healthOrchestrationSelect $healthFailuresNoSlackEvents '^STATUS ') -ceq 'STATUS 70' -and
                    @($healthFailuresNoSlack.Log | Where-Object { ([string]$_).Contains('Відправлення повідомлення вимкнено параметром -NoSlack') }).Count -eq 1 -and
                    @($healthHappyEvents | Where-Object { $_ -like 'NOTIFY-SEND *' }).Count -eq 1 -and
                    @($healthFailuresEvents | Where-Object { $_ -like 'NOTIFY-SEND *' }).Count -eq 1
                ) `
                -Name "Health/OrchestrationNoSlackSuppressesNotificationOnly" `
                -Failure "-NoSlack має придушувати лише доставку сповіщень (без маршруту, відправлення, стану алерту й кроку 'Сповіщення'), не змінюючи перевірок і коду завершення; проби: $($healthHappyNoSlack | ConvertTo-Json -Compress -Depth 4) || $($healthFailuresNoSlack | ConvertTo-Json -Compress -Depth 4)"

            # (5) Решта підсумкових кодів із пізніх шляхів виходу:
            # відкладена SFTP-перевірка (зайнятий WinSCP) — WARNING через
            # справжній Write-HealthLog -> 10 (SuccessWithWarnings), SFTP-крок
            # SKIPPED без WinSCP-сесії; збій доставки CRITICAL-сповіщення ->
            # NotificationError -> 70, крок "Сповіщення" ERROR, стан алерту не
            # записано (наступний прогін повторить).
            $healthWinScpBusy = $healthOrchestrationResults['WinScpBusy']
            $healthWinScpBusyEvents = @(& $healthOrchestrationEvents 'WinScpBusy')
            $healthNotificationFailure = $healthOrchestrationResults['NotificationFailure']
            $healthNotificationFailureEvents = @(& $healthOrchestrationEvents 'NotificationFailure')
            Test-BRAVOCondition `
                -Condition (
                    (& $healthOrchestrationProbeOk 'WinScpBusy') -and
                    (& $healthOrchestrationProbeOk 'NotificationFailure') -and
                    $healthWinScpBusy.ExitCode -eq 10 -and
                    $healthWinScpBusy.ExitCodeName -eq 'SuccessWithWarnings' -and
                    (& $healthOrchestrationSelect $healthWinScpBusyEvents $healthOrchestrationChecksPattern) -ceq (& $healthOrchestrationExpectedChecks 9 @('OK', 'OK', 'OK', 'OK', 'OK', 'OK', 'SKIPPED', 'OK') $false) -and
                    (& $healthOrchestrationSelect $healthWinScpBusyEvents '^(NOTIFY-|STATUS |STEP 9/)') -ceq 'STATUS 10|STEP 9/9 Сповіщення SKIPPED' -and
                    $healthNotificationFailure.ExitCode -eq 70 -and
                    (& $healthOrchestrationSelect $healthNotificationFailureEvents $healthOrchestrationChecksPattern) -ceq (& $healthOrchestrationExpectedChecks 9 @('OK', 'ERROR', 'OK', 'OK', 'OK', 'OK', 'OK', 'OK') $true) -and
                    (& $healthOrchestrationSelect $healthNotificationFailureEvents '^(NOTIFY-|ALERT-STATE-SAVE$|STATUS |STEP 9/)') -ceq 'NOTIFY-ROUTE CRITICAL|NOTIFY-FAIL|STATUS 70|STEP 9/9 Сповіщення ERROR'
                ) `
                -Name "Health/OrchestrationResolvesWarningAndDeliveryFailureCodes" `
                -Failure "відкладена SFTP-перевірка має давати 10 (SuccessWithWarnings) зі SKIPPED SFTP-кроком, а збій доставки CRITICAL-сповіщення — 70 з кроком 'Сповіщення' ERROR і без запису стану алерту; проби: $($healthWinScpBusy | ConvertTo-Json -Compress -Depth 4) || $($healthNotificationFailure | ConvertTo-Json -Compress -Depth 4)"

            # (6) Ранні шляхи виходу розв'язуються до перевірок: вимкнений
            # моніторинг -> 0 і жодної перевірки; небезпечний (не https) webhook
            # -> 30 (InvalidConfiguration) і жодної перевірки; недоступний LOGS
            # через права -> 36 (PrivilegeRequired) після кроку середовища, без
            # служб/копій/SFTP (жодного звернення навіть до перевірки зайнятості
            # WinSCP), з CRITICAL-сповіщенням про середовище. Кожен вихід пише
            # статус-файл із тим самим кодом.
            $healthMonitoringDisabled = $healthOrchestrationResults['MonitoringDisabled']
            $healthInsecureWebhook = $healthOrchestrationResults['InsecureWebhook']
            $healthEnvironmentPrivilege = $healthOrchestrationResults['EnvironmentPrivilege']
            $healthEnvironmentPrivilegeEvents = @(& $healthOrchestrationEvents 'EnvironmentPrivilege')
            Test-BRAVOCondition `
                -Condition (
                    (& $healthOrchestrationProbeOk 'MonitoringDisabled') -and
                    (& $healthOrchestrationProbeOk 'InsecureWebhook') -and
                    (& $healthOrchestrationProbeOk 'EnvironmentPrivilege') -and
                    $healthMonitoringDisabled.ExitCode -eq 0 -and
                    ((& $healthOrchestrationEvents 'MonitoringDisabled') -join '|') -ceq 'STATUS 0' -and
                    $healthInsecureWebhook.ExitCode -eq 30 -and
                    $healthInsecureWebhook.ExitCodeName -eq 'InvalidConfiguration' -and
                    ((& $healthOrchestrationEvents 'InsecureWebhook') -join '|') -ceq 'STATUS 30' -and
                    $healthEnvironmentPrivilege.ExitCode -eq 36 -and
                    $healthEnvironmentPrivilege.ExitCodeName -eq 'PrivilegeRequired' -and
                    ($healthEnvironmentPrivilegeEvents -join '|') -ceq 'TOOL-MANIFEST|PREFLIGHT|STEP 1/9 Середовище й цілісність інструментів ERROR|NOTIFY-ROUTE CRITICAL|NOTIFY-SEND https://self-test.invalid/alerts self-test environment alert|STATUS 36'
                ) `
                -Name "Health/OrchestrationEarlyExitsSkipChecks" `
                -Failure "ранні виходи Health мають завершуватися до перевірок: вимкнений моніторинг -> 0, небезпечний webhook -> 30, недоступний LOGS через права -> 36 без служб/копій/SFTP; проби: $($healthMonitoringDisabled | ConvertTo-Json -Compress -Depth 4) || $($healthInsecureWebhook | ConvertTo-Json -Compress -Depth 4) || $($healthEnvironmentPrivilege | ConvertTo-Json -Compress -Depth 4)"
        } finally {
            if (Test-Path -LiteralPath $healthOrchestrationRoot -PathType Container) {
                Remove-Item -LiteralPath $healthOrchestrationRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    }

    # CLAUDE_CODE_TZ_ARCHIV_LIMS_MONOLITH.md: автоматичний Discovery джерел
    # (BRAVO_ROOT/WEB_ROOT/MODEL/BLOG/BRAVOEXCH/BAZA_APP/BAZA_WWW) за
    # встановленою службою BRAVO і активним bravo.ini, з повним ручним
    # перевизначенням через BRAVO.config.
    Remove-Module -Name 'BRAVO.Discovery' -Force -ErrorAction SilentlyContinue
    Import-Module -Name (Join-Path $root "modules\BRAVO.Discovery\BRAVO.Discovery.psd1") -Force -ErrorAction Stop

    # Реальний фрагмент bravo.ini.example, наданий користувачем: секції
    # [system]/[model], закоментовані та задубльовані ключі. Перевіряємо,
    # що парсер бере останнє неекрановане значення й ігнорує ";"-рядки.
    $sampleIniContent = @(
        '[system]',
        'DBMEMLIMIT=0',
        '',
        '[model]',
        ';MODEL=G:\LIMS\LIMS_v020924\Poltava_fito\lims',
        'MODEL=D:\LIMS-OLD\Model\lims',
        'MODEL=C:\LIMS\Model\lims',
        ';MODEL=D:\LIMS\Model\lims',
        'BLOG=C:\LIMS\BLOG\',
        'BEXCH=C:\LIMS\bravoexch',
        'BLOGMAX=1000'
    )
    $parsedIni = ConvertFrom-BRAVOIniFile -Content $sampleIniContent
    Test-BRAVOCondition `
        -Condition (
            $parsedIni['model']['MODEL'] -eq 'C:\LIMS\Model\lims' -and
            $parsedIni['model']['BLOG'] -eq 'C:\LIMS\BLOG\' -and
            $parsedIni['model']['BEXCH'] -eq 'C:\LIMS\bravoexch' -and
            $parsedIni['system']['DBMEMLIMIT'] -eq '0' -and
            -not $parsedIni['model'].ContainsKey('')
        ) `
        -Name "Discovery/IniParserHandlesRealBravoIniFormat" `
        -Failure "ConvertFrom-BRAVOIniFile має правильно розбирати секції, коментарі ';' і брати останнє неекрановане значення для задубльованих ключів (формат наданого bravo.ini.example)"

    $discoveryTestRoot = Join-Path `
        -Path ([IO.Path]::GetTempPath()) `
        -ChildPath ("BRAVO_DISCOVERY_SELF_TEST_{0}" -f [guid]::NewGuid().ToString("N"))
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Health.ServerSideHashFallbackIsInfoNotWarning' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/Discovery' -DependsOn 'Root/Health.ServerSideHashFallbackIsInfoNotWarning') { try {
    try {
        if (Enter-BRAVOSelfTestSection -Name 'Root/Discovery.ResolvesFromServiceAndIniWithoutOverride' -DependsOn 'Root/Health.ServerSideHashFallbackIsInfoNotWarning') { try {
        [void][IO.Directory]::CreateDirectory($discoveryTestRoot)
        $fakeBravoExePath = Join-Path $discoveryTestRoot "bravo.exe"
        [IO.File]::WriteAllText($fakeBravoExePath, "stub")
        $fakeApacheBinDir = Join-Path $discoveryTestRoot "webroot\apache\bin"
        [void][IO.Directory]::CreateDirectory($fakeApacheBinDir)
        $fakeHttpdPath = Join-Path $fakeApacheBinDir "httpd.exe"
        [IO.File]::WriteAllText($fakeHttpdPath, "stub")
        $fakeBravoIniPath = Join-Path $discoveryTestRoot "bravo.ini"
        $discoveryTestIniContent = @(
            '[model]',
            ("MODEL={0}" -f (Join-Path $discoveryTestRoot "Model\lims")),
            ("BLOG={0}\" -f (Join-Path $discoveryTestRoot "BLOG")),
            ("BEXCH={0}" -f (Join-Path $discoveryTestRoot "bravoexch"))
        )
        [IO.File]::WriteAllLines($fakeBravoIniPath, $discoveryTestIniContent)

        $syntheticServices = @(
            [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeBravoExePath) },
            [pscustomobject]@{ Name = "Apache2.4"; DisplayName = "Apache2.4"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeHttpdPath) }
        )

        # -SystemRoot скрізь нижче ін'єктується синтетичним: без цього тест
        # підхоплював би РЕАЛЬНИЙ %SystemRoot%\SysWOW64\bravo.ini поточної
        # машини, якщо він там є (саме так і сталось під час розробки цієї
        # перевірки — на машині розробника він справді лежить там), і тест
        # ставав недетермінованим — залежав від оточення, а не лише від
        # синтетичних фікстур.
        #
        # $noSuchSystemRoot — для сценаріїв "bravo.ini недоступний";
        # $fixtureSystemRoot — єдине допустиме місце, звідки bravo.ini
        # тепер узагалі може бути прочитаний (архітектура ОС визначає
        # SysWOW64 проти System32, іншого шляху немає).
        $noSuchSystemRoot = Join-Path $discoveryTestRoot "NoSuchSystemRoot"
        $fixtureSystemRoot = Join-Path $discoveryTestRoot "FixtureWindows"
        $fixtureSystemIniPath = Join-Path $fixtureSystemRoot "SysWOW64\bravo.ini"
        [void][IO.Directory]::CreateDirectory((Split-Path -Path $fixtureSystemIniPath -Parent))
        [IO.File]::WriteAllLines($fixtureSystemIniPath, $discoveryTestIniContent)
        $autoDiscovery = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO" `
            -WebServiceCandidates @("Apache2.4") `
            -Services $syntheticServices `
            -SystemRoot $fixtureSystemRoot `
            -Is64BitOperatingSystem $true

        Test-BRAVOCondition `
            -Condition (
                $autoDiscovery.BRAVO_ROOT -eq $discoveryTestRoot -and
                $autoDiscovery.WEB_ROOT -eq (Join-Path $discoveryTestRoot "webroot") -and
                $autoDiscovery.MODEL_SOURCE -eq (Join-Path $discoveryTestRoot "Model") -and
                $autoDiscovery.BLOG_SOURCE -eq (Join-Path $discoveryTestRoot "BLOG") -and
                $autoDiscovery.BRAVOEXCH_SOURCE -eq (Join-Path $discoveryTestRoot "bravoexch") -and
                $autoDiscovery.BAZA_APP -eq (Join-Path $discoveryTestRoot "BAZA") -and
                [string]::IsNullOrWhiteSpace([string]$autoDiscovery.BAZA_WWW) -and
                $autoDiscovery.MODEL_PROJECT_FILE -eq (Join-Path $discoveryTestRoot "Model\lims") -and
                [string]::IsNullOrWhiteSpace([string]$autoDiscovery.BACKUP_ROOT)
            ) `
            -Name "Discovery/ResolvesFromServiceAndIniWithoutOverride" `
            -Failure "MODEL/BLOG/BRAVOEXCH мають походити з canonical bravo.ini; BAZA_WWW без DocumentRoot і BACKUP_ROOT без pathSettings не повинні виводитись евристично"

        # Explicit override тепер валідується (absolute + directory
        # existence, issue #216 ALLOW_WITH_VALIDATOR) перед прийняттям —
        # без реального каталогу override давав би Value=$null/помилку,
        # не перемогу над авто-визначеним значенням.
        $modelOverridePath = Join-Path $discoveryTestRoot "ExplicitOverrideModel"
        [void][IO.Directory]::CreateDirectory($modelOverridePath)
        $overriddenDiscovery = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO" `
            -WebServiceCandidates @("Apache2.4") `
            -Services $syntheticServices `
            -SystemRoot $noSuchSystemRoot `
            -DiscoverySettings @{ Sources = @{ MODEL = $modelOverridePath } }
        Test-BRAVOCondition `
            -Condition (
                $overriddenDiscovery.MODEL_SOURCE -eq $modelOverridePath -and
                [bool]$overriddenDiscovery.Overrides["MODEL"] -and
                [string]::IsNullOrWhiteSpace([string]$overriddenDiscovery.BLOG_SOURCE)
            ) `
            -Name "Discovery/ExplicitOverrideWinsAndIsNeverReplaced" `
            -Failure "явний, валідний (absolute + existing) discoverySettings.Sources.MODEL override має перемагати над автоматично знайденим значенням, не зачіпаючи інші поля"

        $noServiceDiscovery = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO_NOT_INSTALLED" `
            -WebServiceCandidates @("Apache2.4") `
            -Services @() `
            -SystemRoot $noSuchSystemRoot
        Test-BRAVOCondition `
            -Condition (
                [string]::IsNullOrWhiteSpace([string]$noServiceDiscovery.BRAVO_ROOT) -and
                [string]::IsNullOrWhiteSpace([string]$noServiceDiscovery.MODEL_SOURCE) -and
                [string]::IsNullOrWhiteSpace([string]$noServiceDiscovery.BLOG_SOURCE) -and
                [string]::IsNullOrWhiteSpace([string]$noServiceDiscovery.WEB_ROOT)
            ) `
            -Name "Discovery/NoSilentSourceFallbackWhenCanonicalIniMissing" `
            -Failure "без canonical bravo.ini MODEL/BLOG мають лишатись невизначеними; LIMSRoot-відносний fallback може архівувати іншу інсталяцію"

        # BACKUP_ROOT — інакше, ніж MODEL/BLOG: коли службу BRAVO не
        # знайдено, "LIMSRoot\ARCHIV" — це ГІРШИЙ здогад, ніж дефолт,
        # який BRAVO.config уже має сам (каталог скрипта). Тому в цьому
        # випадку BACKUP_ROOT має лишатись порожнім, а не пропонувати
        # другу здогадку поверх першої.
        Test-BRAVOCondition `
            -Condition ([string]::IsNullOrWhiteSpace([string]$noServiceDiscovery.BACKUP_ROOT)) `
            -Name "Discovery/BackupRootStaysEmptyWithoutRealService" `
            -Failure "без реально знайденої служби BRAVO BACKUP_ROOT має лишатись порожнім — LIMSRoot-відносна здогадка гірша за власний дефолт BRAVO.config (pathSettings.ArchiveRoot)"

        # Реальний випадок (звіт користувача, реальна dev-машина): служби
        # BRAVO немає взагалі, але системний bravo.ini є — і MODEL/BLOG у
        # ньому вказують на зовсім інший диск/каталог, ніж LimsRoot
        # ("C:\LIMS\..." проти "C:\Users\...\Documents"). BRAVO_ROOT
        # тоді лишається невизначеним, але BAZA_APP усе одно має братись
        # поруч із реальним MODEL/BLOG із canonical bravo.ini.
        $iniOnlyInstallRoot = Join-Path $discoveryTestRoot "IniOnlyInstall"
        [void][IO.Directory]::CreateDirectory($iniOnlyInstallRoot)
        $iniOnlySystemRoot = Join-Path $discoveryTestRoot "IniOnlyWindows"
        $iniOnlySysWow64Dir = Join-Path $iniOnlySystemRoot "SysWOW64"
        [void][IO.Directory]::CreateDirectory($iniOnlySysWow64Dir)
        [IO.File]::WriteAllLines((Join-Path $iniOnlySysWow64Dir "bravo.ini"), @(
            '[model]',
            ("MODEL={0}" -f (Join-Path $iniOnlyInstallRoot "Model\lims")),
            ("BLOG={0}\" -f (Join-Path $iniOnlyInstallRoot "BLOG"))
        ))
        $iniOnlyDiscovery = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO_NOT_INSTALLED" `
            -Services @() `
            -SystemRoot $iniOnlySystemRoot `
            -Is64BitOperatingSystem $true
        Test-BRAVOCondition `
            -Condition (
                [string]::IsNullOrWhiteSpace([string]$iniOnlyDiscovery.BRAVO_ROOT) -and
                $iniOnlyDiscovery.MODEL_SOURCE -eq (Join-Path $iniOnlyInstallRoot "Model") -and
                $iniOnlyDiscovery.BAZA_APP -eq (Join-Path $iniOnlyInstallRoot "BAZA") -and
                $iniOnlyDiscovery.Reasons.BAZA_APP.Contains("MODEL/BLOG з bravo.ini")
            ) `
            -Name "Discovery/BazaAppFollowsIniInstallationRootNotBravoRootFallback" `
            -Failure "коли canonical bravo.ini знайдено, а служби BRAVO немає, BRAVO_ROOT має лишитись null, а BAZA_APP — братись поруч із MODEL/BLOG з ini"

        # Мінімальний парсер httpd.conf: реальний зразок, наданий
        # користувачем — DocumentRoot у лапках, слеші "/" (Apache на
        # Windows традиційно пише шлях так, навіть коли сам процес — Win32).
        $sampleHttpdConfContent = @(
            '# приклад, наданий користувачем',
            '',
            'ServerRoot "c:/br-a-vo.web/apache"',
            'Listen 80',
            'DocumentRoot "c:/br-a-vo.web/www"',
            '<Directory "c:/br-a-vo.web/www">',
            '    Require all granted',
            '</Directory>'
        )
        Test-BRAVOCondition `
            -Condition (
                (Get-BRAVOApacheDocumentRoot -Content $sampleHttpdConfContent) -eq 'c:\br-a-vo.web\www'
            ) `
            -Name "Discovery/ApacheDocumentRootParserReadsQuotedForwardSlashPath" `
            -Failure "Get-BRAVOApacheDocumentRoot має правильно розбирати DocumentRoot у лапках зі слешами '/' (реальний формат httpd.conf) і конвертувати їх у '\'"
        Test-BRAVOCondition `
            -Condition (
                $null -eq (Get-BRAVOApacheDocumentRoot -Content @('# DocumentRoot "c:/ignored"', 'Listen 80'))
            ) `
            -Name "Discovery/ApacheDocumentRootParserIgnoresCommentedDirective" `
            -Failure "Get-BRAVOApacheDocumentRoot не повинен сприймати закоментовану директиву DocumentRoot"

        # BAZA_WWW має братись САМЕ з DocumentRoot реального httpd.conf, а
        # не з фолбек-здогадки "<WEB_ROOT>\www" — попередній тест вище
        # (без httpd.conf на диску) уже перевірив саму здогадку; тут
        # httpd.conf з'являється на диску вперше й має її перебити.
        $fakeApacheConfDir = Join-Path $discoveryTestRoot "webroot\apache\conf"
        [void][IO.Directory]::CreateDirectory($fakeApacheConfDir)
        $fakeHttpdConfPath = Join-Path $fakeApacheConfDir "httpd.conf"
        $fakeDocumentRoot = Join-Path $discoveryTestRoot "custom-web-root"
        [IO.File]::WriteAllLines($fakeHttpdConfPath, @(
            'ServerRoot "c:/br-a-vo.web/apache"',
            ("DocumentRoot ""{0}""" -f $fakeDocumentRoot.Replace('\', '/'))
        ))
        # Test-BRAVOBazaWwwInstallation (структурна перевірка кандидата)
        # вимагає реальний, непорожній, не-reparse каталог <DocumentRoot>\BAZA
        # — без нього Presence був би Absent, а BAZA_WWW лишався б $null,
        # хоча цей фікстур навмисно моделює "справжній" BAZA_WWW.
        $fakeBazaWwwDir = Join-Path $fakeDocumentRoot "BAZA"
        [void][IO.Directory]::CreateDirectory($fakeBazaWwwDir)
        [IO.File]::WriteAllText((Join-Path $fakeBazaWwwDir 'placeholder.txt'), 'baza-www-fixture', (New-Object Text.UTF8Encoding($false)))
        $discoveryWithHttpdConf = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO" `
            -WebServiceCandidates @("Apache2.4") `
            -Services $syntheticServices `
            -SystemRoot $noSuchSystemRoot
        Test-BRAVOCondition `
            -Condition (
                $discoveryWithHttpdConf.HttpdConfPath -eq $fakeHttpdConfPath -and
                $discoveryWithHttpdConf.BAZA_WWW -eq (Join-Path $fakeDocumentRoot "BAZA") -and
                $discoveryWithHttpdConf.WebServiceName -eq "Apache2.4" -and
                $discoveryWithHttpdConf.WebServiceExecutable -eq $fakeHttpdPath -and
                $discoveryWithHttpdConf.Reasons.BAZA_WWW.Contains("httpd.conf") -and
                $discoveryWithHttpdConf.Reasons.BAZA_WWW.Contains("DocumentRoot=$fakeDocumentRoot")
            ) `
            -Name "Discovery/BazaWwwUsesHttpdConfDocumentRoot" `
            -Failure "BAZA_WWW має братись з DocumentRoot реального httpd.conf встановленої Apache-служби, а не з фолбек-здогадки <WEB_ROOT>\www"

        # Архітектурний інваріант (safety-review): стан Windows-служб не
        # повинен керувати можливістю створення backup. Ці тести — про
        # DISCOVERY (Resolve-BRAVOInstallationDiscovery: чи резолвиться
        # джерело), НЕ про виконання backup — тому в просторі назв
        # "Discovery/", а не "Backup/" (виправлення після ревʼю: попередня
        # назва "Backup/WorksWhenBravoService*" оманливо звучала як
        # перевірка виконання; реальна перевірка "backup command/archive
        # invoked" — окремо нижче, "Backup/ArchiveInvokedWhenBravoService*").
        # MODEL/BLOG/BRAVOEXCH/BAZA_APP/BRAVO_ROOT мають резолвитись
        # ОДНАКОВО незалежно від Running/Stopped/Disabled служби BRAVO —
        # варіюємо лише службу BRAVO, Apache фіксований Running, щоб
        # ізолювати саме цю змінну.
        foreach ($bravoServiceStateCase in @(
            @{ Name = 'Running'; State = 'Running'; StartMode = 'Auto' },
            @{ Name = 'Stopped'; State = 'Stopped'; StartMode = 'Manual' },
            @{ Name = 'Disabled'; State = 'Stopped'; StartMode = 'Disabled' }
        )) {
            $servicesForBravoStateCase = @(
                [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = $bravoServiceStateCase.State; StartMode = $bravoServiceStateCase.StartMode; PathName = ('"{0}"' -f $fakeBravoExePath) },
                [pscustomobject]@{ Name = "Apache2.4"; DisplayName = "Apache2.4"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeHttpdPath) }
            )
            $discoveryForBravoStateCase = Resolve-BRAVOInstallationDiscovery `
                -LimsRoot $discoveryTestRoot `
                -BravoServiceName "BRAVO" `
                -WebServiceCandidates @("Apache2.4") `
                -Services $servicesForBravoStateCase `
                -SystemRoot $fixtureSystemRoot `
                -Is64BitOperatingSystem $true
            Test-BRAVOCondition `
                -Condition (
                    $discoveryForBravoStateCase.BRAVO_ROOT -eq $discoveryTestRoot -and
                    $discoveryForBravoStateCase.MODEL_SOURCE -eq (Join-Path $discoveryTestRoot "Model") -and
                    $discoveryForBravoStateCase.BLOG_SOURCE -eq (Join-Path $discoveryTestRoot "BLOG") -and
                    $discoveryForBravoStateCase.BRAVOEXCH_SOURCE -eq (Join-Path $discoveryTestRoot "bravoexch") -and
                    $discoveryForBravoStateCase.BAZA_APP -eq (Join-Path $discoveryTestRoot "BAZA")
                ) `
                -Name "Discovery/BackupSourcesResolveWhenBravo$($bravoServiceStateCase.Name)" `
                -Failure "стан служби BRAVO ($($bravoServiceStateCase.Name)) не повинен впливати на резолвінг джерел backup (BRAVO_ROOT/MODEL/BLOG/BRAVOEXCH/BAZA_APP мають лишатись визначеними так само, як і для Running)"
        }

        # Дзеркальна перевірка для BRAVO Web/Apache (BAZA_WWW) — УСІ ТРИ
        # стани (не лише Disabled): це саме той шлях, де до фіксу
        # StartMode=Disabled повністю блокував BAZA_WWW backup
        # (Find-BRAVOServiceByCandidates відкидав службу як "не
        # встановлену"), хоча DocumentRoot на диску лишався доступним.
        # BRAVO фіксований Running, варіюємо лише Apache; усі три стани
        # мають резолвити BAZA_WWW з ОДНОГО Й ТОГО САМОГО httpd.conf.
        foreach ($apacheServiceStateCase in @(
            @{ Name = 'Running'; State = 'Running'; StartMode = 'Auto' },
            @{ Name = 'Stopped'; State = 'Stopped'; StartMode = 'Manual' },
            @{ Name = 'Disabled'; State = 'Stopped'; StartMode = 'Disabled' }
        )) {
            $servicesForApacheStateCase = @(
                [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeBravoExePath) },
                [pscustomobject]@{ Name = "Apache2.4"; DisplayName = "Apache2.4"; State = $apacheServiceStateCase.State; StartMode = $apacheServiceStateCase.StartMode; PathName = ('"{0}"' -f $fakeHttpdPath) }
            )
            $discoveryForApacheStateCase = Resolve-BRAVOInstallationDiscovery `
                -LimsRoot $discoveryTestRoot `
                -BravoServiceName "BRAVO" `
                -WebServiceCandidates @("Apache2.4") `
                -Services $servicesForApacheStateCase `
                -SystemRoot $fixtureSystemRoot `
                -Is64BitOperatingSystem $true
            $expectApacheDisabledNote = ($apacheServiceStateCase.StartMode -ieq 'Disabled')
            Test-BRAVOCondition `
                -Condition (
                    $discoveryForApacheStateCase.BAZA_WWW -eq (Join-Path $fakeDocumentRoot "BAZA") -and
                    $discoveryForApacheStateCase.HttpdConfPath -eq $fakeHttpdConfPath -and
                    -not $discoveryForApacheStateCase.Reasons.WebRoot.Contains("не знайдено") -and
                    ($discoveryForApacheStateCase.Reasons.WebRoot.Contains("Disabled") -eq $expectApacheDisabledNote)
                ) `
                -Name "Discovery/BazaWWWResolvesWhenApache$($apacheServiceStateCase.Name)" `
                -Failure "BAZA_WWW має резолвитись з того самого httpd.conf DocumentRoot незалежно від стану служби Apache/BravoWeb ($($apacheServiceStateCase.Name)); діагностичне [УВАГА: Disabled] має з'являтись лише коли служба справді Disabled"
        }

        # Service-absent (не Disabled — служби взагалі немає в WMI) — ДВІ
        # явно різні поведінки:
        #  1) явний override discoverySettings.Sources.BAZA_WWW заданий ->
        #     BAZA_WWW доступний, backup дозволений, override діє
        #     незалежно від того, що служби немає;
        #  2) override відсутній -> керована discovery-помилка з причиною
        #     "службу не знайдено" — навмисно НЕ сформульована як "backup
        #     заборонено через зупинену/вимкнену службу" (це відрізняється
        #     семантично: "невідомо, де шукати" != "заборонено політикою").
        $servicesWithoutApache = @(
            [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeBravoExePath) }
        )
        $bazaWwwOverridePath = Join-Path $discoveryTestRoot "ExplicitBazaWWW"
        # Explicit override тепер валідується (absolute + directory
        # existence) перед прийняттям як Presence=Present — без реального
        # каталогу override давав би Presence=Error, не Present.
        [void][IO.Directory]::CreateDirectory($bazaWwwOverridePath)
        $discoveryApacheAbsentWithOverride = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO" `
            -WebServiceCandidates @("Apache2.4") `
            -Services $servicesWithoutApache `
            -SystemRoot $fixtureSystemRoot `
            -Is64BitOperatingSystem $true `
            -DiscoverySettings @{ Sources = @{ BAZA_WWW = $bazaWwwOverridePath } }
        Test-BRAVOCondition `
            -Condition (
                $discoveryApacheAbsentWithOverride.BAZA_WWW -eq $bazaWwwOverridePath -and
                [bool]$discoveryApacheAbsentWithOverride.Overrides["BAZA_WWW"] -and
                $discoveryApacheAbsentWithOverride.Reasons.BAZA_WWW.Contains("override")
            ) `
            -Name "Discovery/BazaWWWResolvesFromExplicitOverrideWhenApacheAbsent" `
            -Failure "коли служби Apache/BravoWeb взагалі немає (не Disabled — відсутня), явний discoverySettings.Sources.BAZA_WWW має все одно робити BAZA_WWW доступним для backup"
        $discoveryApacheAbsentNoOverride = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO" `
            -WebServiceCandidates @("Apache2.4") `
            -Services $servicesWithoutApache `
            -SystemRoot $fixtureSystemRoot `
            -Is64BitOperatingSystem $true
        Test-BRAVOCondition `
            -Condition (
                [string]::IsNullOrWhiteSpace([string]$discoveryApacheAbsentNoOverride.BAZA_WWW) -and
                $discoveryApacheAbsentNoOverride.Reasons.WebRoot.Contains("не знайдено") -and
                $discoveryApacheAbsentNoOverride.Reasons.BAZA_WWW.Contains("не знайдено") -and
                $discoveryApacheAbsentNoOverride.Reasons.BAZA_WWW -notmatch '(?i)stopped|running|disabled|заборонен' -and
                $discoveryApacheAbsentNoOverride.Reasons.WebRoot -notmatch '(?i)заборонен'
            ) `
            -Name "Discovery/BazaWWWAbsentApacheIsControlledFailureNotServiceDenial" `
            -Failure "коли служби Apache/BravoWeb немає і override не задано, причина має бути 'службу не знайдено' (джерело невідоме), а НЕ формулюванням на кшталт 'backup заборонено через stopped/disabled службу' — це різна семантика"

        # =====================================================================
        # BAZA_WWW Presence-контракт (Present/Absent/Ambiguous/Error) —
        # regression matrix scenarios 01-07, 11-15, 17-18 (частково; SFTP-
        # enabled dispatch у BRAVO.Archive.Runtime.ps1 уже покрито окремим
        # Archive/BazaWWW* блоком нижче за файлом).
        # =====================================================================

        # 01-03: Apache Running/Stopped/Disabled + валідний DocumentRoot з
        # реальним <DocumentRoot>\BAZA -> Present, той самий шлях у всіх
        # трьох (fixture вище — $fakeDocumentRoot/BAZA уже створено з файлом).
        Test-BRAVOCondition `
            -Condition ($discoveryWithHttpdConf.BAZA_WWW_Presence -eq 'Present' -and $discoveryWithHttpdConf.BAZA_WWW_Source -eq 'ApacheConfig') `
            -Name "Discovery/BazaWWWPresenceContractPresentFromApacheConfig" `
            -Failure "коли Apache-служба однозначна і <DocumentRoot>\BAZA реально існує/непорожній, BAZA_WWW_Presence має бути 'Present', Source='ApacheConfig'"

        # 04/11: Apache відсутній (немає служби) і немає override -> Absent
        # (не generic error), stale-директорія на диску тут відсутня.
        Test-BRAVOCondition `
            -Condition ($discoveryApacheAbsentNoOverride.BAZA_WWW_Presence -eq 'Absent') `
            -Name "Discovery/BazaWWWPresenceContractAbsentWhenApacheMissing" `
            -Failure "коли Apache-службу не знайдено і override не задано, BAZA_WWW_Presence має бути 'Absent', а не 'Error'/'Ambiguous'"

        # 05: explicit валідний override + Apache відсутній -> Present,
        # Source=ExplicitOverride (fixture вище тепер створює каталог override).
        Test-BRAVOCondition `
            -Condition ($discoveryApacheAbsentWithOverride.BAZA_WWW_Presence -eq 'Present' -and $discoveryApacheAbsentWithOverride.BAZA_WWW_Source -eq 'ExplicitOverride') `
            -Name "Discovery/BazaWWWPresenceContractExplicitOverrideIsPresent" `
            -Failure "явний, валідний (absolute + existing) discoverySettings.Sources.BAZA_WWW має давати Presence='Present', Source='ExplicitOverride' навіть без Apache-служби"

        # 07: explicit override заданий, але каталог на диску не існує ->
        # Error, БЕЗ silent fallback на auto-discovery (навіть коли Apache
        # ТАКОЖ присутній і валідний — override має пріоритет; тут Apache
        # взагалі відсутній, що додатково підтверджує відсутність fallback).
        $invalidBazaWwwOverridePath = Join-Path $discoveryTestRoot "NoSuchExplicitBazaWWW"
        $discoveryInvalidOverride = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO" `
            -WebServiceCandidates @("Apache2.4") `
            -Services $servicesWithoutApache `
            -SystemRoot $fixtureSystemRoot `
            -Is64BitOperatingSystem $true `
            -DiscoverySettings @{ Sources = @{ BAZA_WWW = $invalidBazaWwwOverridePath } }
        Test-BRAVOCondition `
            -Condition (
                $discoveryInvalidOverride.BAZA_WWW_Presence -eq 'Error' -and
                [string]::IsNullOrWhiteSpace([string]$discoveryInvalidOverride.BAZA_WWW) -and
                $discoveryInvalidOverride.BAZA_WWW_Source -eq 'ExplicitOverride' -and
                $discoveryInvalidOverride.Reasons.BAZA_WWW -match '(?i)не існує'
            ) `
            -Name "Discovery/BazaWWWPresenceContractInvalidOverrideFailsClosedNoFallback" `
            -Failure "невалідний (неіснуючий каталог) explicit override BAZA_WWW має давати Presence='Error' і Value=`$null — БЕЗ автоматичного fallback на Apache-виявлення"

        # 12: кілька Apache-подібних служб із РІЗНИМИ виконуваними файлами ->
        # Ambiguous, БЕЗ мовчазного вибору першої (реґрес до фіксу: раніше
        # BAZA_WWW тихо брав шлях першого кандидата, лише додаючи текстове
        # [УВАГА] у Reasons.WebRoot).
        $ambiguousApacheServices = @(
            [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeBravoExePath) },
            [pscustomobject]@{ Name = "Apache2.4"; DisplayName = "Apache2.4"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeHttpdPath) },
            [pscustomobject]@{ Name = "Apache2.4-Second"; DisplayName = "Apache2.4 (другий)"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f (Join-Path $discoveryTestRoot "second-apache\bin\httpd.exe")) }
        )
        $discoveryAmbiguousApache = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO" `
            -WebServiceCandidates @("Apache2.4", "Apache2.4-Second") `
            -Services $ambiguousApacheServices `
            -SystemRoot $fixtureSystemRoot `
            -Is64BitOperatingSystem $true
        Test-BRAVOCondition `
            -Condition (
                $discoveryAmbiguousApache.BAZA_WWW_Presence -eq 'Ambiguous' -and
                [string]::IsNullOrWhiteSpace([string]$discoveryAmbiguousApache.BAZA_WWW) -and
                $discoveryAmbiguousApache.Ambiguous.WebRoot -eq $true
            ) `
            -Name "Discovery/BazaWWWPresenceContractAmbiguousDoesNotPickFirst" `
            -Failure "кілька Apache-подібних служб з різними виконуваними файлами мають давати Presence='Ambiguous' і BAZA_WWW=`$null — НЕ мовчки перший знайдений кандидат"

        # 18: Apache однозначний, DocumentRoot реально резолвиться, але
        # <DocumentRoot>\BAZA або не існує, або порожній -> НЕ Present
        # (структурна перевірка Test-BRAVOBazaWwwInstallation). Окремий
        # httpd.conf/DocumentRoot без файлів у BAZA-підкаталозі.
        $notBazaApacheConfDir = Join-Path $discoveryTestRoot "not-baza-apache\conf"
        [void][IO.Directory]::CreateDirectory($notBazaApacheConfDir)
        $notBazaHttpdConfPath = Join-Path $notBazaApacheConfDir "httpd.conf"
        $notBazaDocumentRoot = Join-Path $discoveryTestRoot "not-baza-web-root"
        [void][IO.Directory]::CreateDirectory($notBazaDocumentRoot)
        [IO.File]::WriteAllLines($notBazaHttpdConfPath, @(
            'ServerRoot "c:/not-baza/apache"',
            ("DocumentRoot ""{0}""" -f $notBazaDocumentRoot.Replace('\', '/'))
        ))
        $notBazaServices = @(
            [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeBravoExePath) },
            [pscustomobject]@{ Name = "NotBazaApache"; DisplayName = "NotBazaApache"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f (Join-Path $discoveryTestRoot "not-baza-apache\bin\httpd.exe")) }
        )
        $discoveryNotBaza = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO" `
            -WebServiceCandidates @("NotBazaApache") `
            -Services $notBazaServices `
            -SystemRoot $fixtureSystemRoot `
            -Is64BitOperatingSystem $true
        Test-BRAVOCondition `
            -Condition (
                $discoveryNotBaza.BAZA_WWW_Presence -eq 'Absent' -and
                [string]::IsNullOrWhiteSpace([string]$discoveryNotBaza.BAZA_WWW) -and
                -not [string]::IsNullOrWhiteSpace([string]$discoveryNotBaza.HttpdConfPath)
            ) `
            -Name "Discovery/BazaWWWPresenceContractApachePresentButNotBazaStaysAbsent" `
            -Failure "Apache-служба однозначна і DocumentRoot реально резолвиться, але <DocumentRoot>\BAZA не проходить структурну перевірку (не існує/порожній) — Presence має лишатись 'Absent', а НЕ 'Present' з хибним шляхом"

        # Test-BRAVOBazaWwwInstallation напряму: 0/1/N елементів усередині
        # кандидата, reparse point.
        $structuralMissingDir = Join-Path $discoveryTestRoot "structural-missing"
        $structuralEmptyDir = Join-Path $discoveryTestRoot "structural-empty"
        [void][IO.Directory]::CreateDirectory($structuralEmptyDir)
        $structuralPopulatedDir = Join-Path $discoveryTestRoot "structural-populated"
        [void][IO.Directory]::CreateDirectory($structuralPopulatedDir)
        [IO.File]::WriteAllText((Join-Path $structuralPopulatedDir 'a.txt'), 'x', (New-Object Text.UTF8Encoding($false)))
        Test-BRAVOCondition `
            -Condition (
                -not (Test-BRAVOBazaWwwInstallation -Path $structuralMissingDir).Valid -and
                -not (Test-BRAVOBazaWwwInstallation -Path $structuralEmptyDir).Valid -and
                (Test-BRAVOBazaWwwInstallation -Path $structuralPopulatedDir).Valid
            ) `
            -Name "Discovery/TestBRAVOBazaWwwInstallationZeroOneManyEntries" `
            -Failure "Test-BRAVOBazaWwwInstallation має відхиляти відсутній і порожній каталог, приймати непорожній реальний каталог"

        # === #158 (етап 2): presence-контракт для ВСІХ компонентів ===
        # Власний ізольований root і власний try/finally: матриця має бути
        # незалежною від фікстур BAZA_WWW вище (спільний $discoveryTestRoot
        # навмисно НЕ створює каталоги MODEL/BLOG/BEXCH на диску, і саме це
        # робить його непридатним для перевірки Present).
        & {
            $presenceRoot = Join-Path `
                -Path ([IO.Path]::GetTempPath()) `
                -ChildPath ("BRAVO_PRESENCE_SELF_TEST_{0}" -f [guid]::NewGuid().ToString("N"))
            try {
                [void][IO.Directory]::CreateDirectory($presenceRoot)
                $presenceInstallRoot = Join-Path $presenceRoot "install"
                [void][IO.Directory]::CreateDirectory($presenceInstallRoot)

                function New-BRAVOPresenceFixtureDirectory {
                    param([string]$Path, [switch]$Empty)
                    [void][IO.Directory]::CreateDirectory($Path)
                    if (-not $Empty) {
                        [IO.File]::WriteAllText((Join-Path $Path 'fixture.txt'), 'x', (New-Object Text.UTF8Encoding($false)))
                    }
                    return $Path
                }

                # Present-кандидати: реальні НЕПОРОЖНІ каталоги.
                $presenceModelDir = New-BRAVOPresenceFixtureDirectory -Path (Join-Path $presenceInstallRoot "Model")
                $presenceBlogDir = New-BRAVOPresenceFixtureDirectory -Path (Join-Path $presenceInstallRoot "BLOG")
                [void](New-BRAVOPresenceFixtureDirectory -Path (Join-Path $presenceInstallRoot "BAZA"))
                # Stale-кандидат: каталог існує, але порожній — сам факт
                # наявності каталогу з правильною назвою НЕ робить Present.
                $presenceStaleExchDir = New-BRAVOPresenceFixtureDirectory -Path (Join-Path $presenceInstallRoot "bravoexch") -Empty
                $presenceBravoExePath = Join-Path $presenceInstallRoot "bravo.exe"
                [IO.File]::WriteAllText($presenceBravoExePath, "stub")

                $presenceSystemRoot = Join-Path $presenceRoot "FixtureWindows"
                $presenceIniPath = Join-Path $presenceSystemRoot "SysWOW64\bravo.ini"
                [void][IO.Directory]::CreateDirectory((Split-Path -Path $presenceIniPath -Parent))
                [IO.File]::WriteAllLines($presenceIniPath, @(
                    '[model]',
                    ("MODEL={0}" -f (Join-Path $presenceModelDir "lims")),
                    ("BLOG={0}\" -f $presenceBlogDir),
                    ("BEXCH={0}" -f $presenceStaleExchDir)
                ))

                $presenceServices = @(
                    [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $presenceBravoExePath) }
                )

                $presenceHappy = Resolve-BRAVOInstallationDiscovery `
                    -LimsRoot $presenceInstallRoot `
                    -BravoServiceName "BRAVO" `
                    -WebServiceCandidates @("Apache2.4") `
                    -Services $presenceServices `
                    -SystemRoot $presenceSystemRoot `
                    -Is64BitOperatingSystem $true

                # Спільна структура результату — однакова для всіх
                # компонентів, а не окрема модель на кожен.
                $presenceExpectedComponents = @('BRAVO_ROOT', 'MODEL', 'BLOG', 'BRAVOEXCH', 'BAZA_APP', 'WEB_ROOT', 'BAZA_WWW')
                Test-BRAVOCondition `
                    -Condition (
                        $presenceHappy.PSObject.Properties['Components'] -and
                        $presenceHappy.Components -is [System.Collections.IDictionary] -and
                        @($presenceExpectedComponents | Where-Object { -not $presenceHappy.Components.Contains($_) }).Count -eq 0 -and
                        @(@($presenceHappy.Components.Keys) | Where-Object {
                            $entry = $presenceHappy.Components[$_]
                            -not ($entry.PSObject.Properties['Component'] -and
                                $entry.PSObject.Properties['Presence'] -and
                                $entry.PSObject.Properties['Source'] -and
                                $entry.PSObject.Properties['Path'] -and
                                $entry.PSObject.Properties['Reason'])
                        }).Count -eq 0
                    ) `
                    -Name "Discovery/PresenceContractSharedShapeForAllComponents" `
                    -Failure "Resolve-BRAVOInstallationDiscovery має повертати Components з однаковою структурою {Component;Presence;Source;Path;Reason} для кожного з: $($presenceExpectedComponents -join ', ')"

                # Present -> Present (і Path заповнений лише тут).
                Test-BRAVOCondition `
                    -Condition (
                        $presenceHappy.Components['MODEL'].Presence -eq 'Present' -and
                        $presenceHappy.Components['MODEL'].Source -eq 'BravoIni' -and
                        $presenceHappy.Components['MODEL'].Path -eq $presenceModelDir -and
                        $presenceHappy.Components['BLOG'].Presence -eq 'Present' -and
                        $presenceHappy.Components['BLOG'].Path -eq $presenceBlogDir -and
                        $presenceHappy.Components['BAZA_APP'].Presence -eq 'Present' -and
                        $presenceHappy.Components['BAZA_APP'].Path -eq (Join-Path $presenceInstallRoot "BAZA") -and
                        $presenceHappy.Components['BRAVO_ROOT'].Presence -eq 'Present' -and
                        $presenceHappy.Components['BRAVO_ROOT'].Source -eq 'ServiceDiscovery'
                    ) `
                    -Name "Discovery/PresenceContractConfirmedSourcesArePresent" `
                    -Failure "підтверджені однозначні джерела (bravo.ini + реальні непорожні каталоги, однозначна служба BRAVO) мають давати Presence='Present' з непорожнім Path"

                # stale directory alone does not imply Present: BEXCH
                # оголошений у bravo.ini, каталог існує, але порожній.
                Test-BRAVOCondition `
                    -Condition (
                        $presenceHappy.Components['BRAVOEXCH'].Presence -eq 'Absent' -and
                        $null -eq $presenceHappy.Components['BRAVOEXCH'].Path -and
                        (Test-Path -LiteralPath $presenceStaleExchDir -PathType Container)
                    ) `
                    -Name "Discovery/PresenceContractStaleDirectoryIsNotPresent" `
                    -Failure "порожній каталог із правильною назвою (stale directory) НЕ має давати Presence='Present' — лише 'Absent' з порожнім Path"

                # confirmed absence -> Absent: bravo.ini читається, ключа
                # BEXCH у ньому немає взагалі.
                $presenceNoKeySystemRoot = Join-Path $presenceRoot "FixtureWindowsNoBexch"
                $presenceNoKeyIniPath = Join-Path $presenceNoKeySystemRoot "SysWOW64\bravo.ini"
                [void][IO.Directory]::CreateDirectory((Split-Path -Path $presenceNoKeyIniPath -Parent))
                [IO.File]::WriteAllLines($presenceNoKeyIniPath, @(
                    '[model]',
                    ("MODEL={0}" -f (Join-Path $presenceModelDir "lims"))
                ))
                $presenceNoKey = Resolve-BRAVOInstallationDiscovery `
                    -LimsRoot $presenceInstallRoot `
                    -BravoServiceName "BRAVO" `
                    -WebServiceCandidates @("Apache2.4") `
                    -Services $presenceServices `
                    -SystemRoot $presenceNoKeySystemRoot `
                    -Is64BitOperatingSystem $true
                Test-BRAVOCondition `
                    -Condition (
                        $presenceNoKey.Components['BRAVOEXCH'].Presence -eq 'Absent' -and
                        $presenceNoKey.Components['BRAVOEXCH'].Source -eq 'None' -and
                        $null -eq $presenceNoKey.Components['BRAVOEXCH'].Path -and
                        $presenceNoKey.Components['MODEL'].Presence -eq 'Present'
                    ) `
                    -Name "Discovery/PresenceContractMissingIniKeyIsAbsentNotError" `
                    -Failure "доступний canonical bravo.ini без ключа компонента — це достовірна відсутність (Presence='Absent', Source='None'), а не помилка провайдера"

                # multiple candidates -> Ambiguous (і НЕ 'перший знайдений'),
                # provider failure -> Error: bravo.ini недоступний, тому
                # єдиним джерелом лишається служба, а служб дві з різними
                # виконуваними файлами.
                $presenceSecondBravoExe = Join-Path (New-BRAVOPresenceFixtureDirectory -Path (Join-Path $presenceRoot "second-install")) "bravo.exe"
                [IO.File]::WriteAllText($presenceSecondBravoExe, "stub")
                $presenceAmbiguousServices = @(
                    [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $presenceBravoExePath) },
                    [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Server"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $presenceSecondBravoExe) }
                )
                $presenceAmbiguous = Resolve-BRAVOInstallationDiscovery `
                    -LimsRoot $presenceInstallRoot `
                    -BravoServiceName "BRAVO" `
                    -WebServiceCandidates @("Apache2.4") `
                    -Services $presenceAmbiguousServices `
                    -SystemRoot (Join-Path $presenceRoot "NoSuchSystemRoot") `
                    -Is64BitOperatingSystem $true
                Test-BRAVOCondition `
                    -Condition (
                        $presenceAmbiguous.Components['BRAVO_ROOT'].Presence -eq 'Ambiguous' -and
                        $null -eq $presenceAmbiguous.Components['BRAVO_ROOT'].Path -and
                        $presenceAmbiguous.Components['BAZA_APP'].Presence -eq 'Ambiguous' -and
                        $null -eq $presenceAmbiguous.Components['BAZA_APP'].Path -and
                        -not [string]::IsNullOrWhiteSpace([string]$presenceAmbiguous.BRAVO_ROOT)
                    ) `
                    -Name "Discovery/PresenceContractMultipleCandidatesAreAmbiguousNotFirst" `
                    -Failure "кілька служб BRAVO з різними виконуваними файлами мають давати Presence='Ambiguous' з порожнім Path для BRAVO_ROOT і BAZA_APP — навіть попри те, що сире поле BRAVO_ROOT для діагностики і далі показує перший варіант"

                Test-BRAVOCondition `
                    -Condition (
                        $presenceAmbiguous.Components['MODEL'].Presence -eq 'Error' -and
                        $presenceAmbiguous.Components['BLOG'].Presence -eq 'Error' -and
                        $presenceAmbiguous.Components['BRAVOEXCH'].Presence -eq 'Error' -and
                        $null -eq $presenceAmbiguous.Components['MODEL'].Path
                    ) `
                    -Name "Discovery/PresenceContractProviderFailureIsErrorNotAbsent" `
                    -Failure "недоступний canonical bravo.ini — це відмова провайдера discovery: MODEL/BLOG/BRAVOEXCH мають отримати Presence='Error', а НЕ 'Absent'"

                # Явний override з невалідним шляхом — fail-closed Error без
                # мовчазного fallback на робоче значення з bravo.ini.
                $presenceInvalidOverride = Resolve-BRAVOInstallationDiscovery `
                    -LimsRoot $presenceInstallRoot `
                    -BravoServiceName "BRAVO" `
                    -WebServiceCandidates @("Apache2.4") `
                    -Services $presenceServices `
                    -SystemRoot $presenceSystemRoot `
                    -Is64BitOperatingSystem $true `
                    -DiscoverySettings @{ Sources = @{ MODEL = (Join-Path $presenceRoot "NoSuchOverrideModel") } }
                Test-BRAVOCondition `
                    -Condition (
                        $presenceInvalidOverride.Components['MODEL'].Presence -eq 'Error' -and
                        $presenceInvalidOverride.Components['MODEL'].Source -eq 'ExplicitOverride' -and
                        $null -eq $presenceInvalidOverride.Components['MODEL'].Path
                    ) `
                    -Name "Discovery/PresenceContractInvalidExplicitOverrideIsErrorNotFallback" `
                    -Failure "явний discoverySettings.Sources.MODEL на неіснуючий каталог має давати Presence='Error' — без мовчазного fallback на значення з bravo.ini"

                # Інваріант, який має триматись у КОЖНОМУ сценарії:
                # непорожній Path існує виключно у стані Present.
                $presenceAllResults = @($presenceHappy, $presenceNoKey, $presenceAmbiguous, $presenceInvalidOverride)
                $presencePathLeaks = @($presenceAllResults | ForEach-Object {
                    $currentResult = $_
                    @($currentResult.Components.Keys) | Where-Object {
                        $entry = $currentResult.Components[$_]
                        ($entry.Presence -ne 'Present') -and (-not [string]::IsNullOrWhiteSpace([string]$entry.Path))
                    }
                })
                Test-BRAVOCondition `
                    -Condition ($presencePathLeaks.Count -eq 0) `
                    -Name "Discovery/PresenceContractPathOnlyForPresent" `
                    -Failure "Ambiguous/Error/Absent не мають права нести непорожній Path (інваріанти 'Ambiguous != Present' і 'Error != Absent' мають бути механічними, а не текстовими): $($presencePathLeaks -join ', ')"

                # BAZA_WWW не отримує другої, несумісної моделі presence:
                # Components лише віддзеркалює вже перевірений ланцюг.
                Test-BRAVOCondition `
                    -Condition (
                        @($presenceAllResults | Where-Object {
                            [string]$_.Components['BAZA_WWW'].Presence -ne [string]$_.BAZA_WWW_Presence -or
                            [string]$_.Components['BAZA_WWW'].Source -ne [string]$_.BAZA_WWW_Source
                        }).Count -eq 0
                    ) `
                    -Name "Discovery/PresenceContractBazaWwwMirrorsLegacyFields" `
                    -Failure "Components['BAZA_WWW'] має точно віддзеркалювати BAZA_WWW_Presence/BAZA_WWW_Source, а не обчислювати другу, окрему модель presence"
            } finally {
                Remove-Item -LiteralPath $presenceRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Discovery.ResolvesFromServiceAndIniWithoutOverride' } }
        if (Enter-BRAVOSelfTestSection -Name 'Root/Discovery.PresenceContractShownBySetupValidateOnly' -DependsOn 'Root/Discovery.ResolvesFromServiceAndIniWithoutOverride') { try {

        # Оператор мусить бачити presence-стан у BRAVO_SETUP.ps1
        # -Action Test -ValidateOnly, інакше Ambiguous/Error виглядають
        # як звичайна відсутність компонента.
        $setupTextForPresence = Get-Content -LiteralPath (Join-Path $root "BRAVO_SETUP.ps1") -Raw -Encoding UTF8
        Test-BRAVOCondition `
            -Condition ($setupTextForPresence.Contains('Write-BRAVODiscoveryPresenceReport')) `
            -Name "Discovery/PresenceContractShownBySetupValidateOnly" `
            -Failure "BRAVO_SETUP.ps1 має виводити presence-стан компонентів через Write-BRAVODiscoveryPresenceReport"

        # === #158 (етап 3): дрейф складу джерел відносно baseline ===
        # Перевіряємо саме рішення (Test-BRAVODiscoveryComponentDrift) на
        # РЕАЛЬНИХ результатах discovery, а не на синтетичних об'єктах:
        # інакше тест зафіксував би власну копію presence-контракту замість
        # фактичної поведінки пари "presence + baseline".
        & {
            $driftRoot = Join-Path `
                -Path ([IO.Path]::GetTempPath()) `
                -ChildPath ("BRAVO_DRIFT_SELF_TEST_{0}" -f [guid]::NewGuid().ToString("N"))
            try {
                [void][IO.Directory]::CreateDirectory($driftRoot)
                $driftInstallRoot = Join-Path $driftRoot "install"
                [void][IO.Directory]::CreateDirectory($driftInstallRoot)
                foreach ($driftDirName in @("Model", "BLOG", "BAZA")) {
                    $driftDirPath = Join-Path $driftInstallRoot $driftDirName
                    [void][IO.Directory]::CreateDirectory($driftDirPath)
                    [IO.File]::WriteAllText((Join-Path $driftDirPath 'fixture.txt'), 'x', (New-Object Text.UTF8Encoding($false)))
                }
                $driftBravoExePath = Join-Path $driftInstallRoot "bravo.exe"
                [IO.File]::WriteAllText($driftBravoExePath, "stub")

                $driftSystemRoot = Join-Path $driftRoot "FixtureWindows"
                $driftIniPath = Join-Path $driftSystemRoot "SysWOW64\bravo.ini"
                [void][IO.Directory]::CreateDirectory((Split-Path -Path $driftIniPath -Parent))
                # BEXCH у bravo.ini свідомо НЕМАЄ: це і є "компонент
                # достовірно відсутній" для матриці нижче.
                [IO.File]::WriteAllLines($driftIniPath, @(
                    '[model]',
                    ("MODEL={0}" -f (Join-Path (Join-Path $driftInstallRoot "Model") "lims")),
                    ("BLOG={0}\" -f (Join-Path $driftInstallRoot "BLOG"))
                ))
                $driftServices = @(
                    [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $driftBravoExePath) }
                )
                $driftDiscovery = Resolve-BRAVOInstallationDiscovery `
                    -LimsRoot $driftInstallRoot `
                    -BravoServiceName "BRAVO" `
                    -WebServiceCandidates @("Apache2.4") `
                    -Services $driftServices `
                    -SystemRoot $driftSystemRoot `
                    -Is64BitOperatingSystem $true

                $driftAllEnabled = @{
                    MODEL = $true; BLOG = $true; BRAVOEXCH = $true
                    BAZA_APP = $true; BAZA_WWW = $true
                }
                $driftAllDisabled = @{
                    MODEL = $false; BLOG = $false; BRAVOEXCH = $false
                    BAZA_APP = $false; BAZA_WWW = $false
                }
                function Get-BRAVODriftErrorComponents {
                    param([object[]]$Findings)
                    return @(@($Findings) | Where-Object { [string]$_.Severity -eq 'Error' } |
                        ForEach-Object { [string]$_.Component })
                }

                # --- Presence/AbsentWithoutBaselineIsInformational ---
                # BRAVOEXCH увімкнений, джерело достовірно відсутнє
                # (bravo.ini читається, ключа BEXCH немає), у baseline його
                # ніколи не було -> Info, прогін не зупиняється.
                $driftNoBaseline = @(Test-BRAVODiscoveryComponentDrift `
                    -DiscoveryResult $driftDiscovery `
                    -Baseline $null `
                    -BaselineSourceKind 'None' `
                    -EnabledComponents $driftAllEnabled)
                $driftNoBaselineErrors = @(Get-BRAVODriftErrorComponents -Findings $driftNoBaseline)
                Test-BRAVOCondition `
                    -Condition (
                        $driftNoBaselineErrors.Count -eq 0 -and
                        @($driftNoBaseline | Where-Object {
                            [string]$_.Component -eq 'BRAVOEXCH' -and [string]$_.Severity -eq 'Info'
                        }).Count -eq 1
                    ) `
                    -Name "Presence/AbsentWithoutBaselineIsInformational" `
                    -Failure "компонент, достовірно відсутній і НЕ підтверджений раніше в baseline, має давати лише Info — прогін через нього зупинятись не повинен"

                # --- Presence/FirstRunWithoutBaselineDoesNotTreatEverythingAsDisappeared ---
                # Той самий результат, але дивимось на ВЕСЬ набір: перший
                # запуск не має перетворити кожен компонент на "зниклий".
                Test-BRAVOCondition `
                    -Condition (
                        $driftNoBaselineErrors.Count -eq 0 -and
                        @($driftNoBaseline | Where-Object { [string]$_.Severity -eq 'Info' }).Count -ge 2
                    ) `
                    -Name "Presence/FirstRunWithoutBaselineDoesNotTreatEverythingAsDisappeared" `
                    -Failure "перший запуск (baseline ще немає) не має давати жодної помилки дрейфу — порожній baseline не містить підтверджень, отже зникнути не могло нічого"

                # --- Presence/AbsentKnownComponentFailsClosed ---
                # Той самий Absent, але компонент БУВ підтверджений у
                # baseline -> fail-closed. Це і є головний інваріант Issue:
                # "не знайшли" != "значить не треба backup".
                $driftStaleBaselinePath = Join-Path $driftRoot "stale-state"
                [void][IO.Directory]::CreateDirectory($driftStaleBaselinePath)
                $driftConfirmedExchSource = Join-Path $driftInstallRoot "bravoexch"
                [IO.File]::WriteAllText(
                    (Join-Path $driftStaleBaselinePath 'DISCOVERY_BASELINE.json'),
                    ([pscustomobject]@{
                        SavedAt = (Get-Date).ToString("o")
                        MODEL_SOURCE = (Join-Path $driftInstallRoot "Model")
                        BLOG_SOURCE = (Join-Path $driftInstallRoot "BLOG")
                        BRAVOEXCH_SOURCE = $driftConfirmedExchSource
                        BAZA_APP = (Join-Path $driftInstallRoot "BAZA")
                    } | ConvertTo-Json),
                    (New-Object Text.UTF8Encoding($false)))
                $driftStaleImport = Import-BRAVODiscoveryBaseline `
                    -StateRoot $driftStaleBaselinePath `
                    -RuntimeRoot $driftRoot
                $driftWithBaseline = @(Test-BRAVODiscoveryComponentDrift `
                    -DiscoveryResult $driftDiscovery `
                    -Baseline $driftStaleImport.Baseline `
                    -BaselineSourceKind ([string]$driftStaleImport.Source) `
                    -EnabledComponents $driftAllEnabled)
                $driftWithBaselineExch = @($driftWithBaseline | Where-Object { [string]$_.Component -eq 'BRAVOEXCH' })
                Test-BRAVOCondition `
                    -Condition (
                        $driftWithBaselineExch.Count -eq 1 -and
                        [string]$driftWithBaselineExch[0].Severity -eq 'Error' -and
                        [string]$driftWithBaselineExch[0].Presence -eq 'Absent' -and
                        [string]$driftWithBaselineExch[0].BaselineSource -eq $driftConfirmedExchSource -and
                        [string]$driftWithBaselineExch[0].Message -match '(?i)BRAVOEXCH' -and
                        [string]$driftWithBaselineExch[0].Message -match 'ConfirmDiscoveryBaseline'
                    ) `
                    -Name "Presence/AbsentKnownComponentFailsClosed" `
                    -Failure "компонент, раніше підтверджений у baseline, а тепер Absent, має давати Error із назвою компонента, попереднім джерелом і canonical командою підтвердження"

                # --- Presence/AmbiguousFailsClosed і Presence/ErrorFailsClosed ---
                # bravo.ini недоступний (MODEL/BLOG/BRAVOEXCH -> Error) і
                # дві служби BRAVO з різними exe (BAZA_APP -> Ambiguous).
                $driftSecondInstall = Join-Path $driftRoot "second-install"
                [void][IO.Directory]::CreateDirectory($driftSecondInstall)
                $driftSecondExe = Join-Path $driftSecondInstall "bravo.exe"
                [IO.File]::WriteAllText($driftSecondExe, "stub")
                $driftAmbiguousServices = @(
                    [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $driftBravoExePath) },
                    [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Server"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $driftSecondExe) }
                )
                $driftUnknownDiscovery = Resolve-BRAVOInstallationDiscovery `
                    -LimsRoot $driftInstallRoot `
                    -BravoServiceName "BRAVO" `
                    -WebServiceCandidates @("Apache2.4") `
                    -Services $driftAmbiguousServices `
                    -SystemRoot (Join-Path $driftRoot "NoSuchSystemRoot") `
                    -Is64BitOperatingSystem $true
                $driftUnknownFindings = @(Test-BRAVODiscoveryComponentDrift `
                    -DiscoveryResult $driftUnknownDiscovery `
                    -Baseline $null `
                    -BaselineSourceKind 'None' `
                    -EnabledComponents $driftAllEnabled)
                $driftUnknownBazaApp = @($driftUnknownFindings | Where-Object { [string]$_.Component -eq 'BAZA_APP' })
                Test-BRAVOCondition `
                    -Condition (
                        $driftUnknownBazaApp.Count -eq 1 -and
                        [string]$driftUnknownBazaApp[0].Severity -eq 'Error' -and
                        [string]$driftUnknownBazaApp[0].Presence -eq 'Ambiguous'
                    ) `
                    -Name "Presence/AmbiguousFailsClosed" `
                    -Failure "неоднозначне джерело увімкненого компонента має зупиняти прогін (Error) навіть без baseline — обирати кандидата автоматично заборонено"

                $driftUnknownModel = @($driftUnknownFindings | Where-Object { [string]$_.Component -eq 'MODEL' })
                Test-BRAVOCondition `
                    -Condition (
                        $driftUnknownModel.Count -eq 1 -and
                        [string]$driftUnknownModel[0].Severity -eq 'Error' -and
                        [string]$driftUnknownModel[0].Presence -eq 'Error'
                    ) `
                    -Name "Presence/ErrorFailsClosed" `
                    -Failure "presence='Error' (відмова провайдера discovery) увімкненого компонента має зупиняти прогін і НЕ трактуватись як 'Absent'"

                # --- Presence/ExplicitDisabledOverridesPresenceWithoutDriftError ---
                # Той самий "поганий" результат, але всі компоненти вимкнені
                # оператором: це свідома політика, а не дрейф.
                $driftDisabledFindings = @(Test-BRAVODiscoveryComponentDrift `
                    -DiscoveryResult $driftUnknownDiscovery `
                    -Baseline $driftStaleImport.Baseline `
                    -BaselineSourceKind ([string]$driftStaleImport.Source) `
                    -EnabledComponents $driftAllDisabled)
                Test-BRAVOCondition `
                    -Condition (
                        @(Get-BRAVODriftErrorComponents -Findings $driftDisabledFindings).Count -eq 0 -and
                        @($driftDisabledFindings | Where-Object {
                            [string]$_.Presence -eq 'Disabled' -and
                            [string]$_.Message -match '(?i)вимкнено явною конфігурацією'
                        }).Count -ge 1
                    ) `
                    -Name "Presence/ExplicitDisabledOverridesPresenceWithoutDriftError" `
                    -Failure "явно вимкнений оператором компонент не має породжувати помилку дрейфу навіть при Ambiguous/Error чи наявному baseline — у журналі має бути сказано, що його пропущено через конфігурацію"

                # --- Presence/ConfirmBaselineAcceptsLegitimateChange ---
                # Оператор підтвердив новий склад через canonical
                # -ConfirmDiscoveryBaseline: той самий прогін, який щойно
                # падав, більше не має помилок дрейфу.
                $driftConfirmedStateRoot = Join-Path $driftRoot "confirmed-state"
                [void][IO.Directory]::CreateDirectory($driftConfirmedStateRoot)
                Save-BRAVODiscoveryBaseline `
                    -DiscoveryResult $driftDiscovery `
                    -BaselinePath (Get-BRAVODiscoveryBaselinePath -StateRoot $driftConfirmedStateRoot)
                $driftConfirmedImport = Import-BRAVODiscoveryBaseline `
                    -StateRoot $driftConfirmedStateRoot `
                    -RuntimeRoot $driftRoot
                $driftAfterConfirm = @(Test-BRAVODiscoveryComponentDrift `
                    -DiscoveryResult $driftDiscovery `
                    -Baseline $driftConfirmedImport.Baseline `
                    -BaselineSourceKind ([string]$driftConfirmedImport.Source) `
                    -EnabledComponents $driftAllEnabled)
                Test-BRAVOCondition `
                    -Condition (
                        @(Get-BRAVODriftErrorComponents -Findings $driftWithBaseline).Count -gt 0 -and
                        @(Get-BRAVODriftErrorComponents -Findings $driftAfterConfirm).Count -eq 0 -and
                        [string]$driftConfirmedImport.Source -eq 'Canonical'
                    ) `
                    -Name "Presence/ConfirmBaselineAcceptsLegitimateChange" `
                    -Failure "після підтвердження нового baseline через Save-BRAVODiscoveryBaseline той самий discovery-результат не має давати помилок дрейфу (інакше легітимну зміну складу неможливо прийняти)"

                # Пошкоджений baseline != 'baseline немає': відкат на
                # 'перший запуск' знецінив би захист саме тоді, коли він
                # потрібен.
                $driftBrokenStateRoot = Join-Path $driftRoot "broken-state"
                [void][IO.Directory]::CreateDirectory($driftBrokenStateRoot)
                [IO.File]::WriteAllText(
                    (Join-Path $driftBrokenStateRoot 'DISCOVERY_BASELINE.json'),
                    '{ це не JSON',
                    (New-Object Text.UTF8Encoding($false)))
                $driftBrokenImport = Import-BRAVODiscoveryBaseline `
                    -StateRoot $driftBrokenStateRoot `
                    -RuntimeRoot $driftRoot
                $driftBrokenFindings = @(Test-BRAVODiscoveryComponentDrift `
                    -DiscoveryResult $driftDiscovery `
                    -Baseline $driftBrokenImport.Baseline `
                    -BaselineSourceKind ([string]$driftBrokenImport.Source) `
                    -EnabledComponents $driftAllEnabled)
                Test-BRAVOCondition `
                    -Condition (
                        [string]$driftBrokenImport.Source -eq 'Unreadable' -and
                        @($driftBrokenFindings | Where-Object {
                            [string]$_.Component -eq 'BASELINE' -and [string]$_.Severity -eq 'Error'
                        }).Count -eq 1
                    ) `
                    -Name "Presence/UnreadableBaselineFailsClosed" `
                    -Failure "непридатний до читання baseline має давати помилку (стан складу джерел невідомий), а не мовчазний відкат на 'перший запуск'"
            } finally {
                Remove-Item -LiteralPath $driftRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        # Структурні guard-и: рішення про дрейф має бути під'єднане і до
        # операторської перевірки, і до production-прогону. Без другого
        # захист діяв би лише тоді, коли оператор дивиться на екран.
        $setupTextForDrift = Get-Content -LiteralPath (Join-Path $root "BRAVO_SETUP.ps1") -Raw -Encoding UTF8
        $archiveRuntimeTextForDrift = Get-Content -LiteralPath (Join-Path $root "modules\BRAVO.Archive\BRAVO.Archive.Runtime.ps1") -Raw -Encoding UTF8
        $derivationTextForDrift = Get-Content -LiteralPath (Join-Path $root "modules\BRAVO.Configuration\BRAVO.Configuration.Derivation.psm1") -Raw -Encoding UTF8
        Test-BRAVOCondition `
            -Condition (
                $setupTextForDrift.Contains('Resolve-BRAVOBackupComponentScope') -and
                $archiveRuntimeTextForDrift.Contains('Resolve-BRAVOBackupComponentScope') -and
                $archiveRuntimeTextForDrift.Contains('-not $discoveryBaselineValid') -and
                $derivationTextForDrift.Contains('$global:discoveryEnabledComponents') -and
                $setupTextForDrift.Contains('$global:discoveryEnabledComponents') -and
                $archiveRuntimeTextForDrift.Contains('-EnabledComponents $discoveryEnabledComponents')
            ) `
            -Name "Presence/DriftGateIsWiredIntoArchiveRuntimeAndSetup" `
            -Failure "Рішення про дрейф (Test-BRAVODiscoveryComponentDrift через канонічний Resolve-BRAVOBackupComponentScope) має викликатись і в BRAVO_SETUP.ps1, і в Archive runtime (де `$discoveryBaselineValid впливає на exit-код), а перелік увімкнених компонентів має братись з канонічного `$global:discoveryEnabledComponents (у самому runtime Archive — без `$global:-префікса, цього вимагає guard RuntimeScope/Archive), а не будуватись inline двічі"

        # 06: explicit override має АБСОЛЮТНИЙ пріоритет над Apache
        # discovery, навіть коли Apache-служба ОДНОЗНАЧНА і її DocumentRoot
        # структурно валідний (реальний, непорожній <DocumentRoot>\BAZA) —
        # обидва кандидати (Path A через override, Path B через Apache)
        # structurally valid одночасно; Path B не повинен використовуватись
        # ні напряму, ні як fallback. Ізольований temp root + власний
        # try/finally (не покладається на спільний $discoveryTestRoot
        # cleanup наприкінці блоку).
        $scenario06Root = Join-Path `
            -Path ([IO.Path]::GetTempPath()) `
            -ChildPath ("BRAVO_BAZAWWW_S06_SELF_TEST_{0}" -f [guid]::NewGuid().ToString("N"))
        try {
            [void][IO.Directory]::CreateDirectory($scenario06Root)

            # Path A — explicit override, structurally valid.
            $scenario06PathA = Join-Path $scenario06Root "PathA-Explicit"
            [void][IO.Directory]::CreateDirectory($scenario06PathA)
            [IO.File]::WriteAllText((Join-Path $scenario06PathA 'explicit-a.txt'), 'path-a', (New-Object Text.UTF8Encoding($false)))

            # Path B — окремий, ТАКОЖ structurally valid Apache DocumentRoot\BAZA.
            $scenario06ApacheConfDir = Join-Path $scenario06Root "apache\conf"
            [void][IO.Directory]::CreateDirectory($scenario06ApacheConfDir)
            $scenario06HttpdConfPath = Join-Path $scenario06ApacheConfDir "httpd.conf"
            $scenario06DocumentRoot = Join-Path $scenario06Root "PathB-Apache-DocRoot"
            [void][IO.Directory]::CreateDirectory($scenario06DocumentRoot)
            [IO.File]::WriteAllLines($scenario06HttpdConfPath, @(
                'ServerRoot "c:/scenario06/apache"',
                ("DocumentRoot ""{0}""" -f $scenario06DocumentRoot.Replace('\', '/'))
            ))
            $scenario06PathB = Join-Path $scenario06DocumentRoot "BAZA"
            [void][IO.Directory]::CreateDirectory($scenario06PathB)
            [IO.File]::WriteAllText((Join-Path $scenario06PathB 'apache-b.txt'), 'path-b', (New-Object Text.UTF8Encoding($false)))

            $scenario06Services = @(
                [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeBravoExePath) },
                [pscustomobject]@{ Name = "Scenario06Apache"; DisplayName = "Scenario06Apache"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f (Join-Path $scenario06Root "apache\bin\httpd.exe")) }
            )
            $scenario06Discovery = Resolve-BRAVOInstallationDiscovery `
                -LimsRoot $scenario06Root `
                -BravoServiceName "BRAVO" `
                -WebServiceCandidates @("Scenario06Apache") `
                -Services $scenario06Services `
                -SystemRoot $fixtureSystemRoot `
                -Is64BitOperatingSystem $true `
                -DiscoverySettings @{ Sources = @{ BAZA_WWW = $scenario06PathA } }
            Test-BRAVOCondition `
                -Condition (
                    $scenario06Discovery.BAZA_WWW_Presence -eq 'Present' -and
                    $scenario06Discovery.BAZA_WWW_Source -eq 'ExplicitOverride' -and
                    $scenario06Discovery.BAZA_WWW -eq $scenario06PathA -and
                    $scenario06Discovery.BAZA_WWW -ne $scenario06PathB -and
                    -not [string]::IsNullOrWhiteSpace([string]$scenario06Discovery.HttpdConfPath)
                ) `
                -Name "Discovery/BazaWWWPresenceContractExplicitOverrideWinsOverApache" `
                -Failure "коли явний override (Path A) і однозначна, structurally valid Apache-служба (Path B) присутні ОДНОЧАСНО, Presence має бути 'Present', Source='ExplicitOverride', BAZA_WWW=Path A — Path B (Apache DocumentRoot\BAZA) не повинен використовуватись ні напряму, ні як fallback, і результат не повинен ставати Ambiguous"
        } finally {
            if (Test-Path -LiteralPath $scenario06Root) {
                Remove-Item -LiteralPath $scenario06Root -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        # 11: stale/legacy каталог, що ВИГЛЯДАЄ як старий BAZA_WWW layout
        # (populated, canonical-looking ім'я), не повинен активувати
        # компонент, коли Apache-служба відсутня і explicit override не
        # заданий — discovery не сканує диск заради BAZA_WWW: коли Apache
        # відсутній, єдине джерело — override, якого тут немає. Ізольований
        # temp root + власний try/finally.
        $scenario11Root = Join-Path `
            -Path ([IO.Path]::GetTempPath()) `
            -ChildPath ("BRAVO_BAZAWWW_S11_SELF_TEST_{0}" -f [guid]::NewGuid().ToString("N"))
        try {
            [void][IO.Directory]::CreateDirectory($scenario11Root)

            # "Правдоподібний" legacy BAZA_WWW layout — саме такий шлях і
            # такі файли реальний BAZA_WWW міг би мати, якби Apache-служба
            # реально стояла тут колись і згодом була видалена/перенесена.
            $scenario11StaleDocumentRoot = Join-Path $scenario11Root "old-apache\htdocs"
            $scenario11StaleBazaDir = Join-Path $scenario11StaleDocumentRoot "BAZA"
            [void][IO.Directory]::CreateDirectory($scenario11StaleBazaDir)
            [IO.File]::WriteAllText((Join-Path $scenario11StaleBazaDir 'legacy-data.txt'), 'stale-baza-www-leftover', (New-Object Text.UTF8Encoding($false)))
            [void][IO.Directory]::CreateDirectory((Join-Path $scenario11StaleBazaDir 'subfolder'))

            $scenario11Services = @(
                [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = "Running"; StartMode = "Auto"; PathName = ('"{0}"' -f $fakeBravoExePath) }
            )
            $scenario11Discovery = Resolve-BRAVOInstallationDiscovery `
                -LimsRoot $scenario11Root `
                -BravoServiceName "BRAVO" `
                -WebServiceCandidates @("Apache2.4") `
                -Services $scenario11Services `
                -SystemRoot $fixtureSystemRoot `
                -Is64BitOperatingSystem $true
            Test-BRAVOCondition `
                -Condition (
                    $scenario11Discovery.BAZA_WWW_Presence -eq 'Absent' -and
                    [string]::IsNullOrWhiteSpace([string]$scenario11Discovery.BAZA_WWW) -and
                    $scenario11Discovery.BAZA_WWW_Source -eq 'None'
                ) `
                -Name "Discovery/BazaWWWPresenceContractStaleDirectoryDoesNotActivateComponent" `
                -Failure "populated, canonical-looking legacy BAZA_WWW каталог на диску (без Apache-служби і без explicit override) НЕ повинен активувати компонент — Presence має лишатись 'Absent', BAZA_WWW=`$null, Source='None'; discovery не сканує диск заради BAZA_WWW"
        } finally {
            if (Test-Path -LiteralPath $scenario11Root) {
                Remove-Item -LiteralPath $scenario11Root -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        # Аналогічно для BRAVO: коли служба взагалі не встановлена,
        # MODEL/BLOG/BRAVOEXCH мають лишатись доступними через незалежне
        # authoritative джерело (canonical bravo.ini) — BRAVO_ROOT сам по
        # собі при цьому лишається невизначеним (немає служби -> немає
        # каталогу інсталяції), але це НЕ блокує backup MODEL/BLOG/BRAVOEXCH.
        $discoveryBravoAbsent = Resolve-BRAVOInstallationDiscovery `
            -LimsRoot $discoveryTestRoot `
            -BravoServiceName "BRAVO_NOT_INSTALLED" `
            -Services @() `
            -SystemRoot $fixtureSystemRoot `
            -Is64BitOperatingSystem $true
        Test-BRAVOCondition `
            -Condition (
                [string]::IsNullOrWhiteSpace([string]$discoveryBravoAbsent.BRAVO_ROOT) -and
                $discoveryBravoAbsent.MODEL_SOURCE -eq (Join-Path $discoveryTestRoot "Model") -and
                $discoveryBravoAbsent.BLOG_SOURCE -eq (Join-Path $discoveryTestRoot "BLOG") -and
                $discoveryBravoAbsent.BRAVOEXCH_SOURCE -eq (Join-Path $discoveryTestRoot "bravoexch") -and
                $discoveryBravoAbsent.Reasons.MODEL.StartsWith("bravo.ini")
            ) `
            -Name "Discovery/BravoServiceAbsentModelBlogBravoexchResolveFromIni" `
            -Failure "коли службу BRAVO не встановлено, MODEL/BLOG/BRAVOEXCH мають резолвитись з canonical bravo.ini (незалежне authoritative джерело) — відсутність служби не повинна блокувати ці backup-джерела, лише BRAVO_ROOT (похідне від служби значення)"

        # =====================================================================
        # PRODUCTION CONFIG LOADER: service-not-installed acceptance tests
        # =====================================================================
        # Усі тести Discovery/* вище викликають Resolve-BRAVOInstallationDiscovery
        # НАПРЯМУ — доводять коректність самого helper'а, але НЕ доводять, що
        # РЕАЛЬНИЙ виробничий шлях завантаження конфігурації взагалі ДІЙДЕ до
        # цього коду. BRAVO.config СПОЧАТКУ (до Discovery) викликає
        # Resolve-BRAVOEffectiveLimsRoot; за замовчуванням
        # pathSettings.LIMSRoot="", і коли служби BRAVO немає, це РАНІШЕ
        # завершувалось `throw` ще ДО виклику Discovery — helper-тести цього
        # взагалі не бачили, бо викликали Discovery в обхід BRAVO.config.
        #
        # Тести нижче йдуть через РЕАЛЬНИЙ Import-BravoConfiguration з
        # РЕАЛЬНИМ текстом BRAVO.config: targeted-регекс підміна КОНКРЕТНИХ
        # значень конфігурації (той самий прийом, що Version/AuthoritativeLoader
        # вище вже застосовує для LIMSRoot), і РЕАЛЬНИМ Get-CimInstance/
        # Get-WmiObject, перевизначеними в global scope — єдиний надійний
        # спосіб контролювати "яких служб не існує" для коду всередині
        # ІМПОРТОВАНОГО модуля BRAVO.Discovery: shadow інших BRAVO-функцій між
        # модулями НЕ працює (кожен модуль має власний session state — див.
        # коментар на початку BRAVO.Discovery.psm1), але Get-CimInstance —
        # чужий cmdlet, не BRAVO-функція, тому глобальний shadow дійсно
        # перехоплює виклик з середини чужого модуля.
        #
        # Регресія, знайдена САМЕ цим підходом (а не helper-тестами): коли
        # LIMSRoot дійсно порожній, BRAVO.config передає порожній рядок у
        # Resolve-BRAVOInstallationDiscovery -LimsRoot, чий параметр був
        # Mandatory — PowerShell відхиляє Mandatory [string] з порожнім
        # значенням окремою помилкою біндингу, іншою за симптомом, ніж
        # оригінальний LIMSRoot-throw. Виправлено (LimsRoot прибрано з
        # Mandatory — параметр і так ніде не використовується в тілі функції).
        function New-BRAVOProductionConfigFixtureResult {
            param(
                [Parameter(Mandatory = $true)][string]$Root,
                [Parameter(Mandatory = $true)][string]$SourceConfigPath,
                [Parameter(Mandatory = $true)][string]$ConfigLoaderPath,
                [Parameter(Mandatory = $true)][string]$RuntimeRoot,
                [object[]]$Services = @(),
                [hashtable]$PathSettingsOverrides = @{},
                [hashtable]$DiscoverySettingsOverrides = @{},
                # Булеві componentSettings.Synchronization.* флаги (напр.
                # BAZA_WWW_LOCAL/BAZA_WWW_SFTP, обидва $false за замовчуванням)
                # — без хоча б одного $true бекап-детекція BAZA_WWW взагалі не
                # виконується ("синхронізацію вимкнено"), незалежно від служби.
                [hashtable]$ComponentSyncFlagOverrides = @{}
            )

            # Ізольований module scope для fixture-стану: усередині функцій,
            # визначених через New-Module -ScriptBlock, $script: лексично
            # прив'язується до SCOPE САМОГО МОДУЛЯ (перевірено емпірично) —
            # НЕ до $script: скрипта, що ВИКЛИКАЄ функцію під час виконання,
            # на відміну від "голих" function global:-визначень поза
            # модулем, де $script: усередині динамічно резолвиться відносно
            # ПОТОЧНОГО виклик-стека. Це прибирає цілий клас crossscript
            # contamination: навіть якщо cleanup нижче колись знову дасть
            # збій, fixture-дані лишаються прив'язані до СВОГО модуля, а не
            # плутають $script:-простір production-скрипта, що працює далі
            # в тому самому powershell.exe process.
            if ($DiscoverySettingsOverrides.Count -gt 0) {
                # Complete-BRAVOConfigurationLoad (BRAVO_CONFIG_LOADER.ps1)
                # пропускає повторний Import-Module лише коли модуль УЖЕ
                # завантажений (perf-guard) — тому Derivation-модуль МАЄ
                # бути імпортований ДО визначення shadow-функції нижче.
                # КРИТИЧНО: цей Import-Module має виконуватись ТУТ, У
                # ЗВИЧАЙНОМУ (не-модульному) scope виклику, а НЕ всередині
                # New-Module -ScriptBlock нижче — перевірено емпірично, що
                # Import-Module, викликаний ЗСЕРЕДИНИ dynamic-module
                # scriptblock-а, реєструє реальний модуль як NESTED MODULE
                # цього dynamic-модуля: подальше "function global:X" з тим
                # самим іменем усередині ТОГО САМОГО scriptblock-а після
                # цього формально стає активним command (Get-Command
                # показує dynamic-модуль джерелом), але РЕАЛЬНИЙ виклик
                # усе одно диспетчеризується в оригінальну nested-модульну
                # реалізацію (мовчки повертає canonical, НЕ shadow) —
                # класичний PowerShell-дефект command-resolution для
                # nested-module re-export. Import-Module ЗВІДСИ (звичайний
                # caller scope) не створює цього вкладеного зв'язку —
                # подальший global:-shadow усередині scriptblock-а коректно
                # перекриває виклик.
                Import-Module -Name (Join-Path $RuntimeRoot `
                    'modules\BRAVO.Configuration\BRAVO.Configuration.Derivation.psd1') -ErrorAction Stop
            }
            $prodLoaderFixtureModule = New-Module -ScriptBlock {
                param([object[]]$Services, [hashtable]$DiscoveryOverrides)
                $script:prodLoaderFixtureServices = @($Services)
                function global:Get-CimInstance {
                    param([string]$ClassName, [string]$Namespace, [string]$Filter, [string]$ErrorAction)
                    if ($ClassName -eq 'Win32_Service') { return @($script:prodLoaderFixtureServices) }
                    Microsoft.Management.Infrastructure.CimCmdlets\Get-CimInstance @PSBoundParameters
                }
                function global:Get-WmiObject {
                    param([string]$Class, [string]$Namespace, [string]$Filter, [string]$ErrorAction)
                    if ($Class -eq 'Win32_Service') { return @($script:prodLoaderFixtureServices) }
                    Microsoft.PowerShell.Management\Get-WmiObject @PSBoundParameters
                }
                # P0 Configuration Foundation (PR C, Секція 3): discoverySettings
                # більше НЕ інлайн-літерал у BRAVO.config-тексті (той anchor
                # видалено — обчислення повністю перенесено в
                # BRAVO_CONFIG_LOADER.ps1/Complete-BRAVOConfigurationLoad,
                # спільне для legacy й synthetic шляхів). Той самий
                # function-shadowing прийом, що для Get-CimInstance/
                # Get-WmiObject вище (а не текстовий патч BRAVO.config) —
                # підміняє canonical baseline-функцію лише для цього
                # ізольованого дочірнього прогону self-test.
                if ($DiscoveryOverrides.Count -gt 0) {
                    # Реальний модуль уже імпортовано ЗОВНІ (перед
                    # New-Module -ScriptBlock, див. коментар вище) — тут
                    # лише перекриваємо ім'я function global: у звичайний
                    # спосіб, без вкладеного Import-Module.
                    $script:prodLoaderDiscoveryOverrides = $DiscoveryOverrides
                    function global:Get-BRAVOCanonicalDiscoverySettings {
                        $baseline = @{
                            BravoIniPath = $null
                            BravoRoot = $null
                            WebRoot = $null
                            Sources = @{
                                MODEL = $null; BLOG = $null; BRAVOEXCH = $null
                                BAZA_APP = $null; BAZA_WWW = $null; BACKUP_ROOT = $null
                            }
                        }
                        foreach ($overrideKey in @($script:prodLoaderDiscoveryOverrides.Keys)) {
                            $segments = @(([string]$overrideKey) -split '\.')
                            $node = $baseline
                            for ($i = 0; $i -lt ($segments.Count - 1); $i++) {
                                $node = $node[$segments[$i]]
                            }
                            $node[$segments[$segments.Count - 1]] = $script:prodLoaderDiscoveryOverrides[$overrideKey]
                        }
                        return $baseline
                    }
                }
            } -ArgumentList (, @($Services)), $DiscoverySettingsOverrides

            try {
                $configText = [IO.File]::ReadAllText($SourceConfigPath, [Text.Encoding]::UTF8)
                foreach ($key in $PathSettingsOverrides.Keys) {
                    $escapedValue = ([string]$PathSettingsOverrides[$key]).Replace("'", "''")
                    $pattern = '(?m)^(\s*' + [regex]::Escape($key) + '\s*=\s*)""\s*$'
                    $evaluator = [Text.RegularExpressions.MatchEvaluator] {
                        param($match) $match.Groups[1].Value + "'$escapedValue'"
                    }
                    $replacedText = [regex]::Replace($configText, $pattern, $evaluator, 1)
                    if ($replacedText -eq $configText) {
                        throw "pathSettings.$key substitution matched nothing (fixture BRAVO.config may have drifted)"
                    }
                    $configText = $replacedText
                }
                # discoverySettings override — тепер через function-shadowing
                # Get-BRAVOCanonicalDiscoverySettings у fixture-модулі вище
                # (не текстовий патч: anchor більше не існує в BRAVO.config).
                foreach ($key in $ComponentSyncFlagOverrides.Keys) {
                    $boolValue = if ([bool]$ComponentSyncFlagOverrides[$key]) { '$true' } else { '$false' }
                    $pattern = '(?m)^(\s*' + [regex]::Escape($key) + '\s*=\s*)\$(true|false)\s*$'
                    $evaluator = [Text.RegularExpressions.MatchEvaluator] {
                        param($match) $match.Groups[1].Value + $boolValue
                    }
                    $replacedText = [regex]::Replace($configText, $pattern, $evaluator, 1)
                    if ($replacedText -eq $configText) {
                        throw "componentSettings.Synchronization.$key substitution matched nothing (fixture BRAVO.config may have drifted)"
                    }
                    $configText = $replacedText
                }

                $fixtureConfigPath = Join-Path $Root 'BRAVO.config'
                [IO.File]::WriteAllText($fixtureConfigPath, $configText, (New-Object Text.UTF8Encoding($false)))

                . $ConfigLoaderPath

                $result = [pscustomobject]@{
                    Threw = $false
                    ExceptionMessage = $null
                    EffectiveLimsRoot = $null
                    LimsRootSource = $null
                    BackupRootPath = $null
                    ArchiveDefinitions = $null
                    BazaWWWDetection = $null
                    BravoDiscoveryResult = $null
                }
                try {
                    Import-BravoConfiguration `
                        -ConfigRoot $Root `
                        -ConfigPath $fixtureConfigPath `
                        -RuntimeRoot $RuntimeRoot `
                        -ErrorAction Stop
                    $result.EffectiveLimsRoot = [string]$global:effectiveLimsRoot
                    $result.LimsRootSource = [string]$global:limsRootResult.Source
                    $result.BackupRootPath = [string]$global:backupRootPath
                    $result.ArchiveDefinitions = $global:archiveDefinitions
                    $result.BazaWWWDetection = $global:bazaWWWDetection
                    $result.BravoDiscoveryResult = $global:bravoDiscoveryResult
                } catch {
                    $result.Threw = $true
                    $result.ExceptionMessage = $_.Exception.Message
                }
                return $result
            } finally {
                # КОРІНЬ production-інциденту (2026-08, LIMS acceptance):
                # `Remove-Item -Path function:global:Get-CimInstance` (з
                # явним префіксом "global:" У РЯДКУ шляху function:-
                # провайдера) НІЧОГО не видаляє — провайдер мовчки резолвить
                # 0 елементів і НЕ кидає помилку (перевірено емпірично на
                # Windows PowerShell 5.1.26100: Get-Item з тим самим шляхом
                # читає елемент нормально, але Remove-Item з ним — ні), тож
                # -ErrorAction SilentlyContinue раніше маскував це як
                # "успіх" — override переживав завершення self-test і в
                # ТОМУ САМОМУ powershell.exe отруював наступний production
                # entrypoint (BRAVO_ARCHIV.ps1 -> embedded Health ->
                # Get-BRAVOWmiInstance -> цей leftover Get-CimInstance),
                # даючи саме "$script:prodLoaderFixtureServices cannot be
                # retrieved because it has not been set" — бо $script:
                # усередині "голої" function global:-функції динамічно
                # резолвиться відносно СКРИПТА, що її ВИКЛИКАВ, а не того,
                # що її визначив (теж перевірено емпірично).
                #
                # Правильний шлях провайдера — БЕЗ "global:" у самому
                # рядку: тоді провайдер коректно знаходить і видаляє
                # визначення в глобальній таблиці функцій незалежно від
                # того, з якого вкладеного scope викликається Remove-Item
                # (перевірено емпірично). -ErrorAction Stop + явна перевірка
                # нижче — щоб БУДЬ-ЯКЕ повторне регресування цього класу
                # дефекту провалювало сам self-test голосно (fail-closed),
                # а не мовчки залишало production-runtime отруєним у тому
                # самому процесі.
                Remove-Item -Path function:Get-CimInstance -Force -ErrorAction Stop
                Remove-Item -Path function:Get-WmiObject -Force -ErrorAction Stop
                if (Test-Path -LiteralPath function:global:Get-CimInstance) {
                    throw "New-BRAVOProductionConfigFixtureResult: не вдалося видалити fixture-override function:global:Get-CimInstance — production runtime у цьому процесі залишиться отруєним"
                }
                if (Test-Path -LiteralPath function:global:Get-WmiObject) {
                    throw "New-BRAVOProductionConfigFixtureResult: не вдалося видалити fixture-override function:global:Get-WmiObject — production runtime у цьому процесі залишиться отруєним"
