                    [pscustomobject]@{ Name = "BRAVO"; DisplayName = "BRAVO Service"; State = $backupStateCase.State; StartMode = $backupStateCase.StartMode; PathName = ('"{0}"' -f $serviceStateFakeBravoExePath) }
