    Microsoft.PowerShell.Management\Set-Item -Path ('function:script:' + $suiteIsolationCaseCommand) -Value { 'STUB' } -Force
} {
    & $suiteIsolationCheckFunction $suiteIsolationScriptTable $suiteIsolationCaseCommand $suiteIsolationOriginalBlock 'Private'
    if ($suiteIsolationScriptTable -eq 'Script') { & $suiteIsolationHiddenFromChild ('function:' + $suiteIsolationCaseCommand) }
}
. $suiteIsolationCaseRun 'PrivateScriptFunctionRemoved' @('Move-Item') $suiteIsolationArrangeScriptFunction {
    Microsoft.PowerShell.Management\Remove-Item -LiteralPath ('function:' + $suiteIsolationCaseCommand) -Force
} {
    & $suiteIsolationCheckFunction $suiteIsolationScriptTable $suiteIsolationCaseCommand $suiteIsolationOriginalBlock 'Private'
}
. $suiteIsolationCaseRun 'PrivateScriptAliasOverwritten' @('Wait-Process') $suiteIsolationArrangeScriptAlias {
    Microsoft.PowerShell.Utility\Set-Alias -Name $suiteIsolationCaseCommand -Value 'Out-Null' -Scope Script -Option Private -Force
} {
    & $suiteIsolationCheckAlias $suiteIsolationScriptTable $suiteIsolationCaseCommand 'Private'
    if ($suiteIsolationScriptTable -eq 'Script') { & $suiteIsolationHiddenFromChild ('alias:' + $suiteIsolationCaseCommand) }
}
. $suiteIsolationCaseRun 'PrivateScriptAliasRemoved' @('Invoke-RestMethod') $suiteIsolationArrangeScriptAlias {
    Microsoft.PowerShell.Management\Remove-Item -LiteralPath ('alias:' + $suiteIsolationCaseCommand) -Force
} {
    & $suiteIsolationCheckAlias $suiteIsolationScriptTable $suiteIsolationCaseCommand 'Private'
}
. $suiteIsolationCaseRun 'PrivateGlobalFunctionAndAliasRestored' @('Resolve-Path', 'Get-ItemProperty') {
    . $suiteIsolationArrangeGlobalFunction
    (Get-BRAVOSelfTestScopedCommandItem -Access (Get-BRAVOSelfTestSessionScopeAccess) -Scope Global -Kind Function `
        -Name $suiteIsolationCaseCommand).Options = [Management.Automation.ScopedItemOptions]::Private
    Microsoft.PowerShell.Utility\Set-Alias -Name 'Get-ItemProperty' -Value 'Microsoft.PowerShell.Utility\Write-Output' -Scope Global `
        -Option Private -Description 'probe-350' -Force
} {
    Microsoft.PowerShell.Management\Set-Item -Path ('function:global:' + $suiteIsolationCaseCommand) -Value { 'STUB' } -Force
    Microsoft.PowerShell.Utility\Set-Alias -Name 'Get-ItemProperty' -Value 'Out-Null' -Scope Global -Option Private -Force
} {
    & $suiteIsolationCheckFunction 'Global' $suiteIsolationCaseCommand $suiteIsolationOriginalBlock 'Private'
    & $suiteIsolationCheckAlias 'Global' 'Get-ItemProperty' 'Private'
}

# --- Матриця функцій і аліасів -------------------------------------------
. $suiteIsolationCaseRun 'ExistingFunctionOverwritten' @('Get-ItemProperty') $suiteIsolationArrangeGlobalFunction {
    Microsoft.PowerShell.Management\Set-Item -Path ('function:global:' + $suiteIsolationCaseCommand) -Value { 'STUB' } -Force
} {
    & $suiteIsolationCheckFunction 'Global' $suiteIsolationCaseCommand $suiteIsolationOriginalBlock 'None'
}
. $suiteIsolationCaseRun 'ExistingFunctionRemoved' @('Set-ItemProperty') $suiteIsolationArrangeGlobalFunction {
    Invoke-BRAVOSelfTestGlobalScopeItem -Operation Remove -Path ('function:' + $suiteIsolationCaseCommand)
} {
    & $suiteIsolationCheckFunction 'Global' $suiteIsolationCaseCommand $suiteIsolationOriginalBlock 'None'
}
. $suiteIsolationCaseRun 'NewFunctionRemoved' @('Test-Connection', 'Move-Item') { } {
    Microsoft.PowerShell.Management\Set-Item -Path 'function:global:Test-Connection' -Value { 'STUB' } -Force
    Microsoft.PowerShell.Management\Set-Item -Path 'function:script:Move-Item' -Value { 'STUB' } -Force
} $suiteIsolationAbsent
. $suiteIsolationCaseRun 'ExistingAliasModified' @('Move-Item') $suiteIsolationArrangeGlobalAlias {
    Microsoft.PowerShell.Utility\Set-Alias -Name $suiteIsolationCaseCommand -Value 'Out-Null' -Scope Global -Force
} {
    & $suiteIsolationCheckAlias 'Global' $suiteIsolationCaseCommand 'None'
}
. $suiteIsolationCaseRun 'ExistingAliasRemoved' @('Wait-Process') $suiteIsolationArrangeGlobalAlias {
    Invoke-BRAVOSelfTestGlobalScopeItem -Operation Remove -Path ('alias:' + $suiteIsolationCaseCommand)
} {
    & $suiteIsolationCheckAlias 'Global' $suiteIsolationCaseCommand 'None'
}
. $suiteIsolationCaseRun 'NewAliasRemoved' @('Invoke-RestMethod', 'Resolve-Path') { } {
    Microsoft.PowerShell.Utility\Set-Alias -Name 'Invoke-RestMethod' -Value 'Out-Null' -Scope Global -Force
    Microsoft.PowerShell.Utility\Set-Alias -Name 'Resolve-Path' -Value 'Out-Null' -Scope Script -Option Private -Force
} $suiteIsolationAbsent

# --- Динамічні модулі та dot-source suite-фрагмента ----------------------
. $suiteIsolationCaseRun 'BareNewModuleOverExistingFunction' @('Restart-Service') $suiteIsolationArrangeGlobalFunction {
    [void](Microsoft.PowerShell.Core\New-Module -ScriptBlock { function Restart-Service { 'STUB' } })
} {
    & $suiteIsolationCheckFunction 'Global' $suiteIsolationCaseCommand $suiteIsolationOriginalBlock 'None'
}
. $suiteIsolationCaseRun 'DotSourcedSuiteFragmentRemoved' @('Send-MailMessage', 'Set-ItemProperty') { } {
    . ([scriptblock]::Create("function Send-MailMessage { 'STUB' }`nSet-Alias -Name Set-ItemProperty -Value Out-Null -Option Private"))
} $suiteIsolationAbsent
. $suiteIsolationCaseRun 'RuntimeModuleOverPrivateScriptFunction' @('Move-Item') $suiteIsolationArrangeScriptFunction {
    [void](New-BRAVOSelfTestRuntimeModule -SourceText "function Move-Item { 'STUB' }" -FunctionNames @('Move-Item'))
} {
    & $suiteIsolationCheckFunction $suiteIsolationScriptTable $suiteIsolationCaseCommand $suiteIsolationOriginalBlock 'Private'
    if ($suiteIsolationScriptTable -eq 'Script' -and $null -ne (Get-BRAVOSelfTestScopedCommandItem -Access (Get-BRAVOSelfTestSessionScopeAccess) `
                -Scope Global -Kind Function -Name $suiteIsolationCaseCommand)) { 'global-заглушка runtime-модуля лишилась' }
}

# --- Виняток у suite: відновлення все одно відбувається (finally) ---------
. $suiteIsolationCaseRun 'CleanupAfterSuiteException' @('Test-Connection', 'Restart-Service') $suiteIsolationArrangeScriptFunction {
    Microsoft.PowerShell.Management\Set-Item -Path ('function:script:' + $suiteIsolationCaseCommand) -Value { 'STUB' } -Force
    [void](Microsoft.PowerShell.Core\New-Module -ScriptBlock { function Restart-Service { 'STUB' } })
    throw (Microsoft.PowerShell.Utility\New-Object System.IO.InvalidDataException 'probe-350-suite-fault')
} {
    & $suiteIsolationCheckFunction $suiteIsolationScriptTable $suiteIsolationCaseCommand $suiteIsolationOriginalBlock 'Private'
    if ((Get-BRAVOSelfTestBuiltinCommandState -Name 'Restart-Service').Key -ne '<none>') { 'заглушка Restart-Service лишилась' }
} $true

# --- Незмінний знімок функцій (дефект 2) ---------------------------------
# Перевизначення наявної функції змінює той самий FunctionInfo на місці;
# знімок із живими FunctionInfo віддав би при відновленні вже 'STUB'. Options
# = Private: з ReadOnly Set-Item -Force створює новий об'єкт, а не змінює
# наявний, і проба не відтворювала б дефект.
. $suiteIsolationCaseRun 'FunctionSnapshotNotLiveFunctionInfo' @('Test-BRAVOSelfTestIsolation350Original') {
    . $suiteIsolationArrangeGlobalFunction
    $suiteIsolationLiveInfo = Get-BRAVOSelfTestScopedCommandItem -Access (Get-BRAVOSelfTestSessionScopeAccess) `
        -Scope Global -Kind Function -Name $suiteIsolationCaseCommand
    $suiteIsolationLiveInfo.Options = [Management.Automation.ScopedItemOptions]::Private
} {
    Microsoft.PowerShell.Management\Set-Item -Path ('function:global:' + $suiteIsolationCaseCommand) -Value { 'STUB' } -Force
    # Suite прибирає перевизначену функцію, і runtime-модуль ставить власну
    # заглушку: без цього в Windows PowerShell 5.1 експорт модуля не
    # витісняє наявну Private-функцію, і відновлення через модуль не
    # запускалося б.
    Remove-BRAVOSelfTestScopedCommandItem -Access (Get-BRAVOSelfTestSessionScopeAccess) -Scope Global -Kind Function -Name $suiteIsolationCaseCommand
    [void](New-BRAVOSelfTestRuntimeModule -SourceText "function Test-BRAVOSelfTestIsolation350Original { 'STUB' }" `
            -FunctionNames @('Test-BRAVOSelfTestIsolation350Original'))
} {
    # Непорожність: живий FunctionInfo справді змінився на місці.
    if ((& $suiteIsolationLiveInfo.ScriptBlock) -ne 'STUB') { 'живий FunctionInfo не змінився — проба нічого не доводить' }
    & $suiteIsolationCheckFunction 'Global' $suiteIsolationCaseCommand $suiteIsolationOriginalBlock 'Private'
}

# --- Поведінковий guard вбудованих команд проти Private-заглушок ----------
# Резолюція (CommandType + Source) кожного імені після suite така сама, як до.
$suiteIsolationBuiltinNames = @(
    'Get-Service', 'Start-Service', 'Stop-Service', 'Get-Process', 'Stop-Process',
    'Start-Sleep', 'Invoke-WebRequest', 'Get-CimInstance', 'Get-WmiObject', 'Start-Process'
)
$suiteIsolationResolution = {
    @(foreach ($suiteIsolationResolvedName in $suiteIsolationBuiltinNames) {
            $suiteIsolationResolved = Microsoft.PowerShell.Core\Get-Command -Name $suiteIsolationResolvedName -ErrorAction SilentlyContinue |
                Microsoft.PowerShell.Utility\Select-Object -First 1
            if ($null -eq $suiteIsolationResolved) { $suiteIsolationResolvedName + '=<none>' } else {
                '{0}={1}|{2}' -f $suiteIsolationResolvedName, $suiteIsolationResolved.CommandType, $suiteIsolationResolved.Source }
        })
}
$suiteIsolationResolutionBefore = [string]::Join(', ', [string[]](. $suiteIsolationResolution))
. $suiteIsolationCaseRun 'PrivateBuiltinStubsDoNotLeak' $suiteIsolationBuiltinNames { } {
    foreach ($suiteIsolationStubName in $suiteIsolationBuiltinNames) {
        Microsoft.PowerShell.Management\Set-Item -Path ('function:script:' + $suiteIsolationStubName) -Value { 'leaked-stub' } -Force
        (Microsoft.PowerShell.Management\Get-Item -LiteralPath ('function:' + $suiteIsolationStubName)).Options = [Management.Automation.ScopedItemOptions]::Private
    }
    $suiteIsolationStubsActive = @($suiteIsolationBuiltinNames | Where-Object {
            $null -ne (Microsoft.PowerShell.Core\Get-Command -Name $_ -CommandType Function -ErrorAction SilentlyContinue) }).Count
} {
    if ($suiteIsolationStubsActive -ne $suiteIsolationBuiltinNames.Count) {
        "заглушки мали діяти всередині suite: активних $suiteIsolationStubsActive з $($suiteIsolationBuiltinNames.Count)"
    }
    $suiteIsolationResolutionAfter = [string]::Join(', ', [string[]](. $suiteIsolationResolution))
    if ($suiteIsolationResolutionAfter -ne $suiteIsolationResolutionBefore) { "резолюція до: $suiteIsolationResolutionBefore; після: $suiteIsolationResolutionAfter" }
}
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Framework.SuiteIsolationPrivateAndImmutableSnapshot' } }
if (Enter-BRAVOSelfTestSection -Name 'Tail/Framework.VariableScopeHeadroom') { try {

# #163: перевірка запасу змінних області. Стеля $MaximumVariableCount
# піднята на початку файлу; тут — доказ, що запас реальний. Без цієї
# перевірки наступне вичерпання знову спливло б випадковою помилкою в
# непов'язаному тесті, а не чесною діагностикою.
#
# Get-Variable -Scope 0 на ВЕРХНЬОМУ рівні файлу — це саме та область,
# у яку dot-source'яться всі фрагменти, тобто та сама, що переповнювалась.
# Запас рахується від Get-Variable -Scope 0 БЕЗ жодних відрахувань —
# це саме те число, яке впирається в ліміт. Два прогони CI це показали:
#   34795718300: Scope 0 = 4096 — рівно стеля, на якій PR #160 і впав;
#   34796475880: Scope 0 = 4096, Scope Global = 148 (ІНШІ змінні).
# Спроба відняти global (перша редакція цієї перевірки) занижувала
# використання на ті 148 і робила запас оптимістичнішим за реальний.
# Global друкується лише як контекст.
$script:selfTestScopeVariableCount = @(Get-Variable -Scope 0 -ErrorAction SilentlyContinue).Count
$script:selfTestGlobalVariableCount = @(Get-Variable -Scope Global -ErrorAction SilentlyContinue).Count
$script:selfTestScopeVariableHeadroom = $script:selfTestVariableCountLimit - $script:selfTestScopeVariableCount
Write-Host ("Змінних в області self-test: {0} з {1} (запас {2}); у global окремо: {3}" -f `
    $script:selfTestScopeVariableCount, $script:selfTestVariableCountLimit, `
    $script:selfTestScopeVariableHeadroom, $script:selfTestGlobalVariableCount)
Test-BRAVOCondition `
    -Condition ($script:selfTestScopeVariableHeadroom -ge 256) `
    -Name "Framework/VariableScopeHeadroom" `
    -Failure ("запас змінних області self-test вичерпується: використано " +
        "$($script:selfTestScopeVariableCount) з $($script:selfTestVariableCountLimit), лишилось " +
        "$($script:selfTestScopeVariableHeadroom) (потрібно щонайменше 256). Нові блоки фрагментів " +
        "виконуйте в дочірній області (& { ... }) або підніміть " +
        "`$script:selfTestVariableCountLimit — інакше наступне переповнення знову спливе " +
        "помилкою SessionStateOverflowException у непов'язаному тесті (#163)")

# ============================================================
# #188: класифікація обмежень хоста замість [FAIL].
#
# На жорстко налаштованому сервері (GPO-транскрипція PowerShell,
# Constrained Language Mode через AppLocker/WDAC) дочірні проби не можуть
# стартувати, і оператор бачив [FAIL], не відрізнимий від дефекту
# комплекту. Один [FAIL], що нічого не означає, знецінює наступний, що
# означає реальний дефект.
#
# Контракт перевіряється на ЧИСТІЙ функції рішення, а не справжнім
# викликом assert-а: фікстурні [FAIL]/[НЕДОСТУПНО] у чистому прогоні самі
# були б тим шумом, проти якого ця задача.
# ============================================================

& {
    Test-BRAVOCondition `
        -Condition ((Get-BRAVOSelfTestAssertionResult -Condition $true -Restriction '') -eq 'PASS') `
        -Name "Framework/AssertionResultPassUnchanged" `
        -Failure "умова, що виконалась, мусить лишатись PASS — контракт PASS/FAIL не має змінюватись від появи -EnvironmentLimitation"

    Test-BRAVOCondition `
        -Condition ((Get-BRAVOSelfTestAssertionResult -Condition $false -Restriction '') -eq 'FAIL') `
        -Name "Framework/AssertionResultFailWithoutProvenRestriction" `
        -Failure "перевірка, що не пройшла без доведеної причини з боку хоста, мусить лишатись FAIL"

    # Ключовий fail-closed інваріант: порожня або пробільна причина НЕ
    # перетворює провал на «недоступно». Інакше достатньо було б передати
    # порожній рядок, щоб заглушити будь-який дефект.
    Test-BRAVOCondition `
        -Condition (
            (Get-BRAVOSelfTestAssertionResult -Condition $false -Restriction '   ') -eq 'FAIL'
        ) `
        -Name "Framework/BlankRestrictionNeverSilencesFailure" `
        -Failure "порожня причина не може перетворювати [FAIL] на [НЕДОСТУПНО] — інакше класифікація стала б глушником дефектів"

    Test-BRAVOCondition `
        -Condition (
            (Get-BRAVOSelfTestAssertionResult -Condition $false `
                -Restriction 'LanguageMode = ConstrainedLanguage') -eq 'UNAVAILABLE'
        ) `
        -Name "Framework/ProvenRestrictionClassifiesAsUnavailable" `
        -Failure "провал із названою доведеною причиною з боку хоста мусить класифікуватись як UNAVAILABLE, а не як помилка комплекту"

    # Дзеркальний інваріант: класифікація не може «врятувати» перевірку,
    # яка насправді пройшла б інакше — причина розглядається ЛИШЕ для
    # умови, що не виконалась.
    Test-BRAVOCondition `
        -Condition (
            (Get-BRAVOSelfTestAssertionResult -Condition $true `
                -Restriction 'LanguageMode = ConstrainedLanguage') -eq 'PASS'
        ) `
        -Name "Framework/RestrictionDoesNotOverrideSatisfiedCondition" `
        -Failure "названа причина не повинна впливати на умову, що виконалась"

    # UNAVAILABLE не потрапляє в $script:failures, тому НЕ впливає на код
    # завершення — саме тому воно мусить бути видимим окремо. На чистому
    # раннері CI цей список порожній, і це теж частина контракту: детектор
    # не має вигадувати обмежень там, де їх немає.
    Test-BRAVOCondition `
        -Condition (
            $null -ne $script:environmentLimitations -and
            -not [object]::ReferenceEquals($script:environmentLimitations, $script:failures)
        ) `
        -Name "Framework/EnvironmentLimitationsAreTracked" `
        -Failure "перелік недоступних перевірок мусить існувати ОКРЕМО від переліку помилок — інакше класифікація змінювала б код завершення"

    $selfTestHostRestrictionOnThisHost = Get-BRAVOSelfTestHostRestriction
    Test-BRAVOCondition `
        -Condition ([string]::IsNullOrWhiteSpace($selfTestHostRestrictionOnThisHost)) `
        -Name "Framework/HostRestrictionAbsentOnUnrestrictedHost" `
        -Failure ("на хості без обмежень детектор мусить повертати порожню причину, інакше кожен звичайний " +
            "провал класифікувався б як обмеження середовища; фактично: $selfTestHostRestrictionOnThisHost")

    # Структурний guard: причина мусить братися з детектора, а не з
    # літерала в місці виклику. Літеральна причина означала б, що автор
    # тесту може оголосити будь-який провал «обмеженням хоста».
    $selfTestOwnSourceForRestriction = Get-BRAVOSelfTestOwnSourceText
    $selfTestLiteralRestrictionUses = @(
        [regex]::Matches($selfTestOwnSourceForRestriction, "-EnvironmentLimitation\s+'[^']") |
            ForEach-Object { $_.Value })
    Test-BRAVOCondition `
        -Condition (@($selfTestLiteralRestrictionUses).Count -eq 0) `
        -Name "Framework/RestrictionReasonComesFromDetectorNotLiteral" `
        -Failure ("-EnvironmentLimitation мусить отримувати причину від Get-BRAVOSelfTestHostRestriction, " +
            "а не рядковий літерал у місці виклику; знайдено: " +
            [string]::Join(', ', @($selfTestLiteralRestrictionUses)))

    # Проба transcript мусить звітувати СВОЮ помилку в stdout: доти вона
    # йшла у stderr батьківського процесу, і причина відмови зникала —
    # батько бачив лише «проба не повернула JSON».
    Test-BRAVOCondition `
        -Condition (
            $selfTestOwnSourceForRestriction.Contains('ProbeError') -and
            $selfTestOwnSourceForRestriction.Contains('$suspensionProbeExitCode = $LASTEXITCODE')
        ) `
        -Name "Framework/SuspensionProbeReportsItsOwnFailure" `
        -Failure "дочірня проба transcript мусить повертати власну помилку й код виходу — інакше на жорсткому хості причина відмови не фіксується ніде"

    # КОРІНЬ ЧЕРВОНОГО CI ЦЬОГО Ж PR, закритий механічно. Дві Framework-
    # фікстури (fatal-catch і timing-probe) AST-екстрагують СПРАВЖНІ функції
    # цього файлу в ізольований модуль за списком імен. Щойно
    # Test-BRAVOCondition почала делегувати категорію результату
    # Get-BRAVOSelfTestAssertionResult, обидві фікстури впали з
    # "The term ... is not recognized" — бо помічника в списку не було.
    #
    # Наступний, хто додасть виклик усередину Test-BRAVOCondition, має
    # впертися в цю перевірку, а не в CI.
    $assertionFunctionStart = $selfTestOwnSourceForRestriction.IndexOf("function Test-BRAVOCondition {")
    $assertionFunctionEnd = if ($assertionFunctionStart -ge 0) {
        $selfTestOwnSourceForRestriction.IndexOf("`n}", $assertionFunctionStart)
    } else { -1 }
    $assertionFunctionBody = if ($assertionFunctionEnd -gt $assertionFunctionStart) {
        $selfTestOwnSourceForRestriction.Substring(
            $assertionFunctionStart, $assertionFunctionEnd - $assertionFunctionStart)
    } else { '' }
    $assertionHelperNames = @(
        [regex]::Matches($assertionFunctionBody, '\bGet-BRAVOSelfTest[A-Za-z]+\b') |
            ForEach-Object { $_.Value } | Sort-Object -Unique)
    # Списки імен кожної фікстури, яка екстрагує саме Test-BRAVOCondition.
    $assertionFixtureLists = @(
        [regex]::Matches($selfTestOwnSourceForRestriction,
            "-FunctionNames @\(([^)]*'Test-BRAVOCondition'[^)]*)\)") |
            ForEach-Object { $_.Groups[1].Value })
    $assertionMissingHelpers = New-Object System.Collections.Generic.List[string]
    foreach ($assertionFixtureList in $assertionFixtureLists) {
        foreach ($assertionHelperName in $assertionHelperNames) {
            if (-not $assertionFixtureList.Contains("'" + $assertionHelperName + "'")) {
                [void]$assertionMissingHelpers.Add($assertionHelperName)
            }
        }
    }
    Test-BRAVOCondition `
        -Condition (
            $assertionFunctionBody.Length -gt 0 -and
            @($assertionFixtureLists).Count -ge 2 -and
            @($assertionHelperNames).Count -gt 0 -and
            $assertionMissingHelpers.Count -eq 0
        ) `
        -Name "Framework/AssertionFixturesExtractEveryHelperItCalls" `
        -Failure ("кожна Framework-фікстура, що екстрагує Test-BRAVOCondition, мусить екстрагувати й " +
            "помічників, яких та викликає — інакше фікстура падає з 'is not recognized'. Знайдено " +
            "фікстур: $(@($assertionFixtureLists).Count); помічників: " +
            "$([string]::Join(', ', @($assertionHelperNames))); бракує: " +
            "$([string]::Join(', ', @($assertionMissingHelpers.ToArray())))")
}

# ============================================================
# #187 (фаза 2): вибірковий прогін suite-фрагментів.
#
# Найнебезпечніший спосіб зламати цю фічу — не помилка в предикаті, а те,
# що вибірковий прогін колись почне виглядати як повний. Тому перевірки
# нижче стережуть насамперед МЕЖУ режимів, а вже потім саму логіку.
# ============================================================

& {
    $suiteOwnSource = Get-BRAVOSelfTestOwnSourceText

    # Чи був запитаний НЕпорожній -Suite: незалежний факт із параметра скрипта, а не зі
    # стану вибору. Фільтр порожніх і пробільних елементів дослівно той самий, що в
    # нормалізації -Suite на початку файлу (порожній -Suite = повний прогін). Gate на
    # самому $script:BRAVOSelfTestSelectedSuite зробив би перевірки стану повного прогону
    # тавтологією і пропускав би їх саме тоді, коли вибір виставлено без -Suite.
    $suiteRequested = (
        $null -ne $Suite -and @($Suite).Count -gt 0 -and
        @(@($Suite) |
            ForEach-Object { [string]$_ } |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) }).Count -gt 0)

    # Каталог — єдине джерело істини для -Suite. Якщо він розійдеться з
    # фактичними сайтами підключення, -Suite почне мовчки не робити нічого
    # для реального фрагмента або приймати ім'я, якого не існує.
    $suiteGatedNames = @(
        [regex]::Matches($suiteOwnSource, "(?m)^\s*if \(Test-BRAVOSelfTestSuiteEnabled -Name '([^']+)'\) \{") |
            ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique)
    $suiteCatalogSorted = @($script:BRAVOSelfTestSuiteCatalog | Sort-Object -Unique)
    Test-BRAVOCondition `
        -Condition (
            @($suiteGatedNames).Count -gt 0 -and
            @($suiteGatedNames).Count -eq @($suiteCatalogSorted).Count -and
            @(Compare-Object -ReferenceObject $suiteCatalogSorted -DifferenceObject $suiteGatedNames).Count -eq 0
        ) `
        -Name "Framework/SuiteCatalogMatchesGatedFragments" `
        -Failure ("каталог -Suite мусить точно збігатися з переліком фрагментів, узятих під " +
            "Test-BRAVOSelfTestSuiteEnabled; у каталозі $(@($suiteCatalogSorted).Count), " +
            "під гейтом $(@($suiteGatedNames).Count)")

    # Фрагмент, підключений повз гейт, ігнорував би -Suite — і прогін мовчки
    # робив би більше, ніж просили. #219 (частина B): гейт, suite, секція
    # Suite/<Ім'я> і підключення мусять називати ОДИН і той самий фрагмент, а
    # секція — охоплювати рівно це підключення: фрагмент поза своєю секцією
    # при винятку зупинив би основне тіло замість однієї секції.
    $suiteFragmentDotSources = @(
        [regex]::Matches($suiteOwnSource, "(?m)^\s*\. \(Join-Path \`$root 'selftest\\BRAVO_SELF_TEST\.([A-Za-z]+)\.ps1'\)") |
            ForEach-Object { $_.Value })
    $suiteGuardedDotSources = @(
        [regex]::Matches($suiteOwnSource,
            ("(?m)^\s*if \(Test-BRAVOSelfTestSuiteEnabled -Name '([^']+)'\) \{\r?\n\s*Enter-BRAVOSelfTestSuite -Name '\1'\r?\n" +
                "\s*if \(Enter-BRAVOSelfTestSection -Name 'Suite/\1'(?: -DependsOn '[^']+'(?:, '[^']+')*)?\) \{ try \{\r?\n" +
                "\s*\. \(Join-Path \`$root 'selftest\\BRAVO_SELF_TEST\.\1\.ps1'\)\r?\n" +
                "\s*\} catch \{ Register-BRAVOSelfTestSectionFault -ErrorRecord \`$_ \} finally \{ Complete-BRAVOSelfTestSection -Name 'Suite/\1' \} \}")) |
            ForEach-Object { $_.Value })
    Test-BRAVOCondition `
        -Condition (
            @($suiteFragmentDotSources).Count -gt 0 -and
            @($suiteFragmentDotSources).Count -eq @($suiteGuardedDotSources).Count
        ) `
        -Name "Framework/EverySuiteFragmentIsGated" `
        -Failure ("кожне підключення suite-фрагмента мусить стояти під Test-BRAVOSelfTestSuiteEnabled і всередині " +
            "власної секції Suite/<Ім'я>; підключень $(@($suiteFragmentDotSources).Count), під гейтом і в секції " +
            "$(@($suiteGuardedDotSources).Count)")

    # Повний прогін — режим за замовчуванням. Саме цей прогін його і доводить:
    # якби -Suite якось активувався без параметра, тут був би не $null.
    #
    # Це стан САМЕ повного прогону (без запитаного -Suite, див. $suiteRequested вище), тому
    # в -Suite він хибний за визначенням. Gate — НЕ на самому вибору: інакше умова
    # $null -eq вибір стала б тавтологією всередині такого gate.
    # Без gate кожен реальний -Suite X завершувався б SELF-TEST FAILED (exit 1),
    # і успішний вибірковий прогін (exit 0 + SELF-TEST PARTIAL) був би недосяжним.
    # Gate не послаблює повний прогін: у ньому всі три перевірки виконуються як і раніше.
    # Стереже Framework/SuiteSelectionContract.FullOnlyAssertionsAreGatedOnFullRun.
    if (-not $suiteRequested) {
        Test-BRAVOCondition `
            -Condition ($null -eq $script:BRAVOSelfTestSelectedSuite) `
            -Name "Framework/FullCanonicalRunIsDefault" `
            -Failure "без -Suite вибір фрагментів мусить лишатися невстановленим — інакше повний прогін перестав бути дефолтом"
    }

    $suiteAlwaysEnabled = @(
        $script:BRAVOSelfTestSuiteCatalog |
            Where-Object { -not (Test-BRAVOSelfTestSuiteEnabled -Name $_) })
    if (-not $suiteRequested) {
        Test-BRAVOCondition `
            -Condition (@($suiteAlwaysEnabled).Count -eq 0) `
            -Name "Framework/FullRunEnablesEverySuite" `
            -Failure ("у повному прогоні кожен фрагмент каталогу мусить бути увімкнений; вимкнені: " +
                [string]::Join(', ', @($suiteAlwaysEnabled)))
    }

    # КЛЮЧОВА властивість fail-closed: маркер релізу недосяжний з
    # вибіркового прогону. RELEASE_CHECKLIST.md вимагає дослівний
    # "SELF-TEST PASSED" як доказ повного прогону.
    $suitePartialIndex = $suiteOwnSource.IndexOf('"SELF-TEST PARTIAL: "')
    $suitePassedIndex = $suiteOwnSource.IndexOf('Write-Host "SELF-TEST PASSED" -ForegroundColor Green')
    $suitePartialGuardIndex = $suiteOwnSource.IndexOf(
        '} elseif ($null -ne $script:BRAVOSelfTestSelectedSuite) {')
    Test-BRAVOCondition `
        -Condition (
            $suitePartialIndex -ge 0 -and $suitePassedIndex -ge 0 -and
            $suitePartialGuardIndex -ge 0 -and
            $suitePartialGuardIndex -lt $suitePartialIndex -and
            $suitePartialIndex -lt $suitePassedIndex
        ) `
        -Name "Framework/SelectiveRunNeverPrintsReleaseMarker" `
        -Failure ("вибірковий прогін мусить друкувати SELF-TEST PARTIAL у гілці, що стоїть ПЕРЕД " +
            "гілкою SELF-TEST PASSED — інакше вибірковий прогін можна зарахувати як доказ релізу")

    # CI не має права звужувати прогін: required check мусить лишатися повним.
    $suiteCiWorkflowText = [IO.File]::ReadAllText(
        (Join-Path $root '.github\workflows\ci.yml'), [Text.Encoding]::UTF8)
    Test-BRAVOCondition `
        -Condition (-not [regex]::IsMatch($suiteCiWorkflowText, 'BRAVO_SELF_TEST\.ps1[^\r\n]*-Suite')) `
        -Name "Framework/CiWorkflowNeverNarrowsSelfTest" `
        -Failure "ci.yml не повинен передавати -Suite у BRAVO_SELF_TEST.ps1 — required check мусить лишатися повним канонічним прогоном"

    # Невідоме ім'я зупиняє прогін і називає доступні: мовчки виконати не те,
    # що просили, гірше, ніж не виконати нічого.
    Test-BRAVOCondition `
        -Condition (
            $suiteOwnSource.Contains('throw ("Невідомий suite: "') -and
            $suiteOwnSource.Contains('Доступні: ')
        ) `
        -Name "Framework/UnknownSuiteFailsClosed" `
        -Failure "невідоме ім'я -Suite мусить зупиняти прогін з переліком доступних, а не мовчки нічого не виконувати"

    # --- Предикат у вибірковому режимі ---------------------------------
    # Стан відновлюється у finally: підсумок нижче читає ту саму змінну, і
    # залишений вибір перетворив би повний прогін на "вибірковий" у звіті.
    $suiteSelectionBefore = $script:BRAVOSelfTestSelectedSuite
    try {
        $script:BRAVOSelfTestSelectedSuite = @('Archive', 'Paths')
        Test-BRAVOCondition `
            -Condition (
                (Test-BRAVOSelfTestSuiteEnabled -Name 'Archive') -and
                (Test-BRAVOSelfTestSuiteEnabled -Name 'Paths') -and
                -not (Test-BRAVOSelfTestSuiteEnabled -Name 'DataRestore')
            ) `
            -Name "Framework/SelectedSuitesRunAndOthersDoNot" `
            -Failure "у вибірковому режимі мусять виконуватись рівно обрані фрагменти"
    } finally {
        $script:BRAVOSelfTestSelectedSuite = $suiteSelectionBefore
    }
    # Ця перевірка БЕЗУМОВНА і порівнює з тим, що було ДО проби ($suiteSelectionBefore):
    # у повному прогоні це $null/$null, у -Suite — той самий масив. Обгортка
    # if ($null -eq ...) зробила б її тавтологією: зламане відновлення залишило б вибір
    # непорожнім, gate пропустив би перевірку, і нічого б не впало.
    Test-BRAVOCondition `
        -Condition ([object]::ReferenceEquals($script:BRAVOSelfTestSelectedSuite, $suiteSelectionBefore)) `
        -Name "Framework/SuiteSelectionProbeRestoresState" `
        -Failure "проба предиката мусить відновити той вибір фрагментів, що був до проби — інакше підсумок повного прогону назве себе вибірковим"

    # --- Підказка "змінений файл -> suite" -----------------------------
    Test-BRAVOCondition `
        -Condition (
            @(Get-BRAVOSelfTestSuiteForChangedPath -Path 'selftest\BRAVO_SELF_TEST.BazaSync.ps1') -contains 'BazaSync' -and
            @(Get-BRAVOSelfTestSuiteForChangedPath -Path 'selftest/BRAVO_SELF_TEST.BazaSync.ps1') -contains 'BazaSync'
        ) `
        -Name "Framework/ChangedFragmentMapsToItsOwnSuite" `
        -Failure "змінений фрагмент мусить відображатися на однойменний suite, незалежно від роздільника шляху"

    Test-BRAVOCondition `
        -Condition (@(Get-BRAVOSelfTestSuiteForChangedPath -Path 'modules\BRAVO.DiskSpace\BRAVO.DiskSpace.psm1') -contains 'DiskSpace') `
        -Name "Framework/ChangedModuleMapsToSuiteOfSameDomain" `
        -Failure "доменний модуль мусить відображатися на suite з тим самим іменем домену, коли такий існує"

    # Найважливіша властивість підказки: вона НЕ вгадує. Незнайомий шлях дає
    # порожній результат, тобто "виконуй повний прогін", а не довільний suite.
    $suiteHintUnknown = @(
        @('BRAVO_ARCHIV.ps1', 'modules\BRAVO.Console\BRAVO.Console.psm1', 'README.md', '') |
            ForEach-Object { @(Get-BRAVOSelfTestSuiteForChangedPath -Path $_) } |
            Where-Object { $null -ne $_ })
    Test-BRAVOCondition `
        -Condition (@($suiteHintUnknown).Count -eq 0) `
        -Name "Framework/ChangedPathHintNeverGuesses" `
        -Failure ("для шляху без точної відповідності підказка мусить повертати порожньо (= повний прогін), " +
            "а не вгадувати suite; повернуто: " + [string]::Join(', ', @($suiteHintUnknown)))
}
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Framework.VariableScopeHeadroom' } }
if (Enter-BRAVOSelfTestSection -Name 'Tail/Framework.SelectiveSuitesHaveNoCrossSuiteDependency') { try {

# ============================================================
# #219: вибірковий прогін без прихованих міжsuite-залежностей.
#
# Кореневе тіло виконується завжди, а gated-фрагмент — лише коли його
# обрано. Тому змінна чи функція, яку визначає ЛИШЕ фрагмент, не може
# читатися ні коренем, ні іншим фрагментом: у повному прогоні читання
# працює (фрагмент уже виконався), а в -Suite без цього фрагмента падає під
# Set-StrictMode ще до обраного suite. Так було з п'ятьма залежностями
# #219, і жодна перевірка цього не бачила, бо CI вибірковий режим не
# запускає (Framework/CiWorkflowNeverNarrowsSelfTest).
#
# Guard статичний (AST), без Windows і без запуску фрагментів:
#   - визначення фрагмента: присвоєння змінних і функції у scope файлу
#     (усередині try/if теж), а також $script:/$global:-присвоєння;
#   - споживачі: корінь (включно з хвостом) та інші фрагменти;
#   - читання не є залежністю, якщо ім'я визначає сам споживач, корінь
#     РАНІШЕ за місце читання (для фрагмента — раніше за його гейт), або
#     воно локальне в дочірньому scriptblock/функції;
#   - scriptblock, виконаний у scope динамічного модуля (& $module { }),
#     змінних self-test не бачить, тож не аналізується.
# ============================================================
& {
    function Get-BRAVOSelfTestCrossSuiteDependency {
        param(
            [Parameter(Mandatory = $true)]$RootAst,
            [Parameter(Mandatory = $true)][hashtable]$FragmentAst
        )

        $automaticNames = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
        foreach ($automaticName in @(
                'null', 'true', 'false', '_', 'PSItem', 'this', 'args', 'input', 'Matches',
                'LASTEXITCODE', 'Error', 'PSScriptRoot', 'PSCommandPath', 'MyInvocation',
                'PSBoundParameters', 'PSCmdlet', 'ExecutionContext', 'Host', 'PID', 'HOME', 'PWD',
                'PSVersionTable', 'PSEdition', 'PSHOME', 'ShellId', 'StackTrace', 'OFS',
                'ErrorActionPreference', 'WarningPreference', 'VerbosePreference',
                'DebugPreference', 'InformationPreference', 'ProgressPreference',
                'ConfirmPreference', 'WhatIfPreference', 'MaximumVariableCount',
                'PSDefaultParameterValues', 'OutputEncoding', 'foreach', 'switch', 'sender',
                'EventArgs', 'Event', '?', '^', '$')) {
            [void]$automaticNames.Add($automaticName)
        }
        $sameScopeCommands = @('ForEach-Object', '%', 'foreach', 'Where-Object', '?', 'where', 'Measure-Command')
        $problems = New-Object System.Collections.ArrayList

        # --- 1. Одиниці: корінь і gated-фрагменти (з вкладеними) ----------
        # Підключення фрагмента має єдину форму . (Join-Path $root
        # 'selftest\BRAVO_SELF_TEST.<Ім'я>.ps1') — її ж вимагає
        # Framework/EverySuiteFragmentIsGated; вкладене підключення
        # (ManualLaunchers у LogRotation) належить тому самому suite.
        $getDotSourcedFragments = {
            param($Ast)
            return @([regex]::Matches([string]$Ast.Extent.Text,
                    "(?m)^\s*\.\s*\(\s*Join-Path\s+\`$root\s+'selftest[\\/]BRAVO_SELF_TEST\.([A-Za-z0-9]+)\.ps1'\s*\)") |
                    ForEach-Object { $_.Groups[1].Value })
        }

        $units = New-Object System.Collections.ArrayList
        [void]$units.Add([pscustomobject]@{ Suite = $null; Fragment = 'BRAVO_SELF_TEST'; Ast = $RootAst; GateOffset = [int]::MaxValue })
        $gateStatements = @(
            @($RootAst.FindAll((Get-BRAVOSelfTestAstTypePredicate -Type @([Management.Automation.Language.IfStatementAst])), $true)) |
                Where-Object {
                    $_.Clauses.Count -ge 1 -and
                    $_.Clauses[0].Item1.Extent.Text -match "^\s*Test-BRAVOSelfTestSuiteEnabled\s+-Name\s+'[^']+'\s*$"
                })
        $gatedSuites = New-Object System.Collections.ArrayList
        foreach ($gate in $gateStatements) {
            $suiteName = [regex]::Match($gate.Clauses[0].Item1.Extent.Text, "'([^']+)'").Groups[1].Value
            [void]$gatedSuites.Add($suiteName)
            $pending = New-Object System.Collections.Queue
            foreach ($fragmentName in (& $getDotSourcedFragments $gate.Clauses[0].Item2)) { $pending.Enqueue($fragmentName) }
            $seenFragments = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
            while ($pending.Count -gt 0) {
                $fragmentName = [string]$pending.Dequeue()
                if (-not $seenFragments.Add($fragmentName)) { continue }
                if (-not $FragmentAst.ContainsKey($fragmentName)) {
                    [void]$problems.Add("фрагмент $fragmentName (suite $suiteName) не розібрано")
                    continue
                }
                $fragmentUnitAst = $FragmentAst[$fragmentName]
                [void]$units.Add([pscustomobject]@{ Suite = $suiteName; Fragment = $fragmentName; Ast = $fragmentUnitAst; GateOffset = $gate.Extent.StartOffset })
                foreach ($nestedName in (& $getDotSourcedFragments $fragmentUnitAst)) { $pending.Enqueue($nestedName) }
            }
            if ($seenFragments.Count -eq 0) { [void]$problems.Add("гейт suite $suiteName не підключає жодного фрагмента") }
        }

        # --- 2. Визначення і використання в кожній одиниці ---------------
        $scopeKindOf = {
            param($Block)
            if ($Block -is [Management.Automation.Language.FunctionDefinitionAst]) { return 'Function' }
            $command = $Block.Parent
            if ($command -is [Management.Automation.Language.CommandAst]) {
                $commandName = $command.GetCommandName()
                $isFirst = [object]::ReferenceEquals($command.CommandElements[0], $Block)
                if ($command.InvocationOperator -eq [Management.Automation.Language.TokenKind]::Dot -and $isFirst) { return 'Same' }
                if ($null -ne $commandName -and $sameScopeCommands -contains $commandName) { return 'Same' }
                if ($commandName -eq 'New-Module') { return 'Foreign' }
                if (-not $isFirst -and (
                        $command.InvocationOperator -eq [Management.Automation.Language.TokenKind]::Ampersand -or
                        $command.InvocationOperator -eq [Management.Automation.Language.TokenKind]::Dot)) {
                    return 'Foreign'
                }
            }
            return 'Child'
        }
        # Контекст вузла: ланцюг дочірніх scope (найглибший перший) і чи він
        # усередині функції; $null — вузол у scope динамічного модуля.
        # Контекст кожного scope-блока обчислюється раз і кешується: вузли
        # одного блока мають спільний ланцюг предків.
        $fileScopeContext = [pscustomobject]@{ Scopes = @(); InFunction = $false }
        $blockContextCache = @{}
        $getContext = {
            param($Node, $UnitAst)
            $parent = $Node.Parent
            while ($null -ne $parent -and -not [object]::ReferenceEquals($parent, $UnitAst) -and
                -not ($parent -is [Management.Automation.Language.FunctionDefinitionAst] -or
                    $parent -is [Management.Automation.Language.ScriptBlockExpressionAst])) {
                $parent = $parent.Parent
            }
            if ($null -eq $parent -or [object]::ReferenceEquals($parent, $UnitAst)) { return $fileScopeContext }
            if ($blockContextCache.ContainsKey($parent)) { return $blockContextCache[$parent] }
            $outerContext = & $getContext $parent $UnitAst
            $kind = & $scopeKindOf $parent
            $blockContext = $null
            if ($null -ne $outerContext -and $kind -ne 'Foreign') {
                $blockScopes = New-Object System.Collections.ArrayList
                if ($kind -ne 'Same') { [void]$blockScopes.Add($parent) }
                foreach ($outerScope in $outerContext.Scopes) { [void]$blockScopes.Add($outerScope) }
                $blockContext = [pscustomobject]@{
                    Scopes     = $blockScopes
                    InFunction = ($outerContext.InFunction -or $kind -eq 'Function')
                }
            }
            $blockContextCache[$parent] = $blockContext
            return $blockContext
        }

        # Спершу дешево класифікуємо кожен вузол (визначення чи читання).
        # Дорогий підйом до меж scope — лише для визначень і для тих читань,
        # чиє ім'я взагалі визначає якийсь фрагмент.
        $unitFacts = @()
        $unitNodePredicate = Get-BRAVOSelfTestAstTypePredicate -Type @(
            [Management.Automation.Language.VariableExpressionAst],
            [Management.Automation.Language.FunctionDefinitionAst],
            [Management.Automation.Language.CommandAst])
        foreach ($unit in $units) {
            $definitionNodes = New-Object System.Collections.ArrayList
            $useKeys = New-Object System.Collections.ArrayList
            $useNodes = New-Object System.Collections.ArrayList
            foreach ($node in @($unit.Ast.FindAll($unitNodePredicate, $true))) {
                if ($node -is [Management.Automation.Language.FunctionDefinitionAst]) {
                    [void]$definitionNodes.Add([pscustomobject]@{ Key = 'function:' + $node.Name; Node = $node; Qualified = $false })
                    continue
                }
                if ($node -is [Management.Automation.Language.CommandAst]) {
                    $commandName = $node.GetCommandName()
                    if ([string]::IsNullOrEmpty($commandName) -or
                        $node.InvocationOperator -eq [Management.Automation.Language.TokenKind]::Dot) { continue }
                    [void]$useKeys.Add('function:' + $commandName)
                    [void]$useNodes.Add($node)
                    continue
                }
                $variablePath = $node.VariablePath
                # Кваліфікатор scope ($script:, $global:, ...) не змінює ім'я;
                # провайдерні диски ($env:, $function:, ...) — не змінні self-test.
                $variableName = $variablePath.UserPath
                $qualifierEnd = $variableName.IndexOf(':')
                if ($qualifierEnd -ge 0) {
                    if (@('script', 'global', 'local', 'private', 'variable', 'using') -notcontains $variableName.Substring(0, $qualifierEnd)) { continue }
                    $variableName = $variableName.Substring($qualifierEnd + 1)
                }
                if ($automaticNames.Contains($variableName)) { continue }
                $key = 'variable:' + $variableName
                $parentNode = $node.Parent
                $isDefinition = $false
                $isAlsoRead = $false
                if ($parentNode -is [Management.Automation.Language.AssignmentStatementAst] -and [object]::ReferenceEquals($parentNode.Left, $node)) {
                    $isDefinition = $true
                    $isAlsoRead = $parentNode.Operator -ne [Management.Automation.Language.TokenKind]::Equals
                } elseif (($parentNode -is [Management.Automation.Language.ConvertExpressionAst] -or
                        $parentNode -is [Management.Automation.Language.ArrayLiteralAst]) -and
                    $parentNode.Parent -is [Management.Automation.Language.AssignmentStatementAst] -and
                    [object]::ReferenceEquals($parentNode.Parent.Left, $parentNode)) {
                    $isDefinition = $true
                } elseif ($parentNode -is [Management.Automation.Language.ForEachStatementAst] -and
                    [object]::ReferenceEquals($parentNode.Variable, $node)) {
                    $isDefinition = $true
                } elseif ($parentNode -is [Management.Automation.Language.ParameterAst]) {
                    $isDefinition = $true
                }
                if ($isDefinition) {
                    [void]$definitionNodes.Add([pscustomobject]@{ Key = $key; Node = $node; Qualified = ($variablePath.IsScript -or $variablePath.IsGlobal) })
                }
                if (-not $isDefinition -or $isAlsoRead) {
                    [void]$useKeys.Add($key)
                    [void]$useNodes.Add($node)
                }
            }
            $unitFacts += , ([pscustomobject]@{
                    Unit            = $unit
                    DefinitionNodes = $definitionNodes
                    Definitions     = New-Object System.Collections.ArrayList
                    UseKeys         = $useKeys
                    UseNodes        = $useNodes
                    LocalNames      = @{}
                })
        }

        # Визначення: у scope файлу (разом із $script:/$global:) чи локальне
        # в дочірньому scriptblock/функції. Спершу фрагменти; для кореня
        # потрібні лише імена, які визначає хоч один фрагмент.
        $fragmentDefinedKeys = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
        foreach ($pass in @('Fragments', 'Root')) {
            foreach ($facts in $unitFacts) {
                $isRootUnit = $null -eq $facts.Unit.Suite
                if (($pass -eq 'Root') -ne $isRootUnit) { continue }
                foreach ($definitionNode in $facts.DefinitionNodes) {
                    if ($isRootUnit -and -not $fragmentDefinedKeys.Contains($definitionNode.Key)) { continue }
                    $context = & $getContext $definitionNode.Node $facts.Unit.Ast
                    if ($null -eq $context) { continue }
                    if ($context.Scopes.Count -eq 0 -or $definitionNode.Qualified) {
                        [void]$facts.Definitions.Add([pscustomobject]@{
                                Key        = $definitionNode.Key
                                Offset     = $definitionNode.Node.Extent.StartOffset
                                InFunction = $context.InFunction
                            })
                        if (-not $isRootUnit) { [void]$fragmentDefinedKeys.Add($definitionNode.Key) }
                    } else {
                        $innermost = $context.Scopes[0]
                        if (-not $facts.LocalNames.ContainsKey($innermost)) {
                            $facts.LocalNames[$innermost] = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
                        }
                        [void]$facts.LocalNames[$innermost].Add($definitionNode.Key)
                    }
                }
            }
        }

        # --- 3. Хто що визначає ------------------------------------------
        # Порядок виконання повного прогону = порядок у кореневому файлі, а
        # фрагмент виконується в точці свого гейта. Для кореня досить
        # найранішого визначення у scope файлу; визначення всередині функції
        # може виконатися будь-коли, тож вважається задовільним.
        $rootEarliest = @{}
        $rootInFunction = @{}
        $fragmentOwners = @{}
        $suiteDefinitions = @{}
        foreach ($facts in $unitFacts) {
            foreach ($definition in $facts.Definitions) {
                if ($null -eq $facts.Unit.Suite) {
                    if ($definition.InFunction) {
                        $rootInFunction[$definition.Key] = $true
                    } elseif (-not $rootEarliest.ContainsKey($definition.Key) -or $definition.Offset -lt $rootEarliest[$definition.Key]) {
                        $rootEarliest[$definition.Key] = $definition.Offset
                    }
                } else {
                    if (-not $fragmentOwners.ContainsKey($definition.Key)) { $fragmentOwners[$definition.Key] = @{} }
                    $fragmentOwners[$definition.Key][$facts.Unit.Suite] = $facts.Unit.GateOffset
                    $suiteDefinitions[$facts.Unit.Suite + '|' + $definition.Key] = $true
                }
            }
        }

        # --- 4. Читання чужого визначення ---------------------------------
        # Залежність є лише тоді, коли у повному прогоні значення справді
        # приходить із чужого фрагмента: фрагмент-власник виконується РАНІШЕ
        # за місце читання (для читання всередині функції — будь-коли), а
        # корінь до того моменту не визначив це ім'я сам. Читання, що в
        # повному прогоні відбувається до будь-якого визначення, тут не
        # предмет: воно або зовнішнє (наприклад, глобальна змінна з
        # Import-BravoConfiguration), або вже ламає й повний прогін.
        $findings = New-Object 'System.Collections.Generic.List[string]'
        $seenFindings = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
        foreach ($facts in $unitFacts) {
            $consumerSuite = $facts.Unit.Suite
            for ($useIndex = 0; $useIndex -lt $facts.UseKeys.Count; $useIndex++) {
                if (-not $fragmentOwners.ContainsKey($facts.UseKeys[$useIndex])) { continue }
                $use = [pscustomobject]@{ Key = [string]$facts.UseKeys[$useIndex]; Node = $facts.UseNodes[$useIndex] }
                if ($rootInFunction.ContainsKey($use.Key)) { continue }
                if ($null -ne $consumerSuite -and $suiteDefinitions.ContainsKey($consumerSuite + '|' + $use.Key)) { continue }
                $readOffset = if ($null -eq $consumerSuite) { $use.Node.Extent.StartOffset } else { $facts.Unit.GateOffset }
                if ($rootEarliest.ContainsKey($use.Key) -and $rootEarliest[$use.Key] -lt $readOffset) { continue }
                $context = & $getContext $use.Node $facts.Unit.Ast
                if ($null -eq $context) { continue }
                if ($context.InFunction -and $rootEarliest.ContainsKey($use.Key)) { continue }
                $owners = New-Object System.Collections.ArrayList
                foreach ($ownerEntry in $fragmentOwners[$use.Key].GetEnumerator()) {
                    if ($ownerEntry.Key -eq $consumerSuite) { continue }
                    if ($context.InFunction -or $ownerEntry.Value -lt $readOffset) { [void]$owners.Add([string]$ownerEntry.Key) }
                }
                if ($owners.Count -eq 0) { continue }
                $isLocal = $false
                foreach ($scope in $context.Scopes) {
                    if ($facts.LocalNames.ContainsKey($scope) -and $facts.LocalNames[$scope].Contains($use.Key)) { $isLocal = $true; break }
                }
                if ($isLocal) { continue }
                $consumerLabel = if ($null -eq $consumerSuite) { 'корінь' } else { "suite $consumerSuite" }
                if (-not $seenFindings.Add($use.Key + '|' + $consumerLabel)) { continue }
                $findings.Add(("{0} визначає лише suite {1}, а читає {2} ({3}:{4})" -f
                        $use.Key, ([string]::Join('/', @($owners | Sort-Object))), $consumerLabel,
                        $facts.Unit.Fragment, $use.Node.Extent.StartLineNumber))
            }
        }

        return [pscustomobject]@{
            GatedSuites = @($gatedSuites | Sort-Object -Unique)
            Problems    = @($problems)
            Findings    = @($findings)
        }
    }

    # --- Реальне джерело ---------------------------------------------------
    $crossSuiteResult = $null
    $crossSuiteError = $null
    try {
        $crossSuiteFragmentAst = @{}
        foreach ($crossSuiteFile in @(Get-ChildItem -LiteralPath (Join-Path $root 'selftest') -Filter 'BRAVO_SELF_TEST.*.ps1' -File)) {
            $crossSuiteParsedFile = Get-BRAVOSelfTestParsedFile -Path $crossSuiteFile.FullName
            $crossSuiteParsed = $crossSuiteParsedFile.Ast
            if (@($crossSuiteParsedFile.Errors).Count -gt 0) { throw "синтаксичні помилки у $($crossSuiteFile.Name)" }
            $crossSuiteName = $crossSuiteFile.Name -replace '^BRAVO_SELF_TEST\.', '' -replace '\.ps1$', ''
            $crossSuiteFragmentAst[$crossSuiteName] = $crossSuiteParsed
        }
        $crossSuiteResult = Get-BRAVOSelfTestCrossSuiteDependency `
            -RootAst (Get-BRAVOSelfTestOwnSourceAst) -FragmentAst $crossSuiteFragmentAst
    } catch {
        $crossSuiteError = $_.Exception.Message
    }
    $crossSuiteCatalogSorted = @($script:BRAVOSelfTestSuiteCatalog | Sort-Object -Unique)
    Test-BRAVOCondition `
        -Condition (
            $null -eq $crossSuiteError -and
            $null -ne $crossSuiteResult -and
            @($crossSuiteResult.Problems).Count -eq 0 -and
            @($crossSuiteResult.GatedSuites).Count -eq @($crossSuiteCatalogSorted).Count -and
            @(Compare-Object -ReferenceObject $crossSuiteCatalogSorted -DifferenceObject @($crossSuiteResult.GatedSuites)).Count -eq 0 -and
            @($crossSuiteResult.Findings).Count -eq 0
        ) `
        -Name "Framework/SelectiveSuitesHaveNoCrossSuiteDependency" `
        -Failure ("корінь та інші фрагменти не повинні читати змінні чи викликати функції, які визначає лише " +
            "gated-фрагмент: -Suite без нього падає під Set-StrictMode. Спільне визначайте в bootstrap-і " +
            "кореня або в самому споживачі. Помилка аналізу: [$crossSuiteError]; " +
            $(if ($null -ne $crossSuiteResult) {
                    "проблеми: [$([string]::Join('; ', @($crossSuiteResult.Problems)))]; " +
                    "suite під гейтом: $(@($crossSuiteResult.GatedSuites).Count) з $(@($crossSuiteCatalogSorted).Count); " +
                    "залежності: [$([string]::Join('; ', @($crossSuiteResult.Findings)))]"
                } else { 'результату немає' }))

    # --- Негативний контроль: guard бачить синтетичну залежність ----------
    # Та сама форма підключення, що й у корені. Фрагмент Alpha визначає
    # змінну й функцію; корінь читає змінну, фрагмент Beta викликає функцію.
    # Чистий варіант тих самих джерел (корінь визначає своє, функція — у
    # bootstrap-і) мусить дати нуль знахідок: guard не має спрацьовувати на
    # будь-що.
    $crossSuiteFixtureError = $null
    $crossSuiteDirty = $null
    $crossSuiteClean = $null
    try {
        $crossSuiteParse = {
            param([string]$Text)
            $fixtureTokens = $null
            $fixtureErrors = $null
            $fixtureAst = [Management.Automation.Language.Parser]::ParseInput($Text, [ref]$fixtureTokens, [ref]$fixtureErrors)
            if (@($fixtureErrors).Count -gt 0) { throw 'синтаксична помилка у фікстурі guard-а' }
            return $fixtureAst
        }
        # Рядки гейта складаються з формату, а не лежать у here-string
        # дослівно: інакше regex-guard-и #187 (SuiteCatalogMatchesGatedFragments,
        # EverySuiteFragmentIsGated), що читають сирий текст цього файлу,
        # побачили б синтетичні suite Alpha/Beta як справжні.
        $crossSuiteGateText = [string]::Join("`n", @(
                @('Alpha', 'Beta') | ForEach-Object {
                    ("    if (Test-BRAVOSelfTestSuiteEnabled -Name '{0}') {{" -f $_)
                    ("        Enter-BRAVOSelfTestSuite -Name '{0}'" -f $_)
                    ("        . (Join-Path `$root 'selftest\BRAVO_SELF_TEST.{0}.ps1')" -f $_)
                    '    }'
                }))
        $crossSuiteAlphaText = @'
$alphaOwnedText = 'alpha'
try {
    function New-AlphaOwnedFixture { return 1 }
} finally { }
& { param($alphaLocalOnly) $null = $alphaLocalOnly }
'@
        $crossSuiteBetaText = @'
$null = New-AlphaOwnedFixture
& { $alphaLocalOnly = 2; $null = $alphaLocalOnly }
'@
        $crossSuiteDirtyRoot = "try {`n" + $crossSuiteGateText + "`n    `$null = `$alphaOwnedText.Length`n} catch { }"
        $crossSuiteCleanRoot = "function New-AlphaOwnedFixture { return 1 }`n`$alphaOwnedText = 'root'`ntry {`n" +
            $crossSuiteGateText + "`n    `$null = `$alphaOwnedText.Length`n} catch { }"
        $crossSuiteFixtureFragments = @{
            Alpha = & $crossSuiteParse $crossSuiteAlphaText
            Beta  = & $crossSuiteParse $crossSuiteBetaText
        }
        $crossSuiteDirty = Get-BRAVOSelfTestCrossSuiteDependency `
            -RootAst (& $crossSuiteParse $crossSuiteDirtyRoot) -FragmentAst $crossSuiteFixtureFragments
        $crossSuiteClean = Get-BRAVOSelfTestCrossSuiteDependency `
            -RootAst (& $crossSuiteParse $crossSuiteCleanRoot) -FragmentAst $crossSuiteFixtureFragments
    } catch {
        $crossSuiteFixtureError = $_.Exception.Message
    }
    $crossSuiteDirtyText = if ($null -ne $crossSuiteDirty) { [string]::Join('; ', @($crossSuiteDirty.Findings)) } else { '' }
    Test-BRAVOCondition `
        -Condition (
            $null -eq $crossSuiteFixtureError -and
            $null -ne $crossSuiteDirty -and $null -ne $crossSuiteClean -and
            @($crossSuiteDirty.Findings).Count -eq 2 -and
            $crossSuiteDirtyText.Contains('variable:alphaOwnedText визначає лише suite Alpha, а читає корінь') -and
            $crossSuiteDirtyText.Contains('function:New-AlphaOwnedFixture визначає лише suite Alpha, а читає suite Beta') -and
            @($crossSuiteClean.Findings).Count -eq 0 -and
            @($crossSuiteDirty.Problems).Count -eq 0 -and
            @($crossSuiteDirty.GatedSuites).Count -eq 2
        ) `
        -Name "Framework/SelectiveSuitesHaveNoCrossSuiteDependencyIsMeaningful" `
        -Failure ("guard міжsuite-залежностей мусить знаходити рівно дві синтетичні залежності (змінну, " +
            "прочитану коренем, і функцію, викликану іншим фрагментом) і нуль у чистому варіанті. " +
            "Помилка: [$crossSuiteFixtureError]; знайдено: [$crossSuiteDirtyText]; у чистому варіанті: " +
            $(if ($null -ne $crossSuiteClean) { [string]::Join('; ', @($crossSuiteClean.Findings)) } else { 'н/д' }))
}

# ============================================================
# #157 (фаза 1): guard-и вартості прогону.
#
# Оптимізація, яку легко «покращити» видаленням перевірки, гірша за
# повільний self-test. Тому тут не просто перевіряється memo, а й
# механічно доводиться, що ЄДИНИЙ прохід по файлах комплекту й далі
# живить УСІ чотири аналізи, які він замінив.
# ============================================================
& {
    $perfOwnAstFirst = Get-BRAVOSelfTestOwnSourceAst
    $perfOwnAstSecond = Get-BRAVOSelfTestOwnSourceAst
    $perfOwnTextFirst = Get-BRAVOSelfTestOwnSourceText
    $perfOwnTextSecond = Get-BRAVOSelfTestOwnSourceText
    Test-BRAVOCondition `
        -Condition (
            $null -ne $perfOwnAstFirst -and
            [object]::ReferenceEquals($perfOwnAstFirst, $perfOwnAstSecond) -and
            [object]::ReferenceEquals($perfOwnTextFirst, $perfOwnTextSecond)
        ) `
        -Name "Perf/OwnSourceMemoReturnsSameInstance" `
        -Failure "повторний виклик Get-BRAVOSelfTestOwnSourceAst/Text має повертати ТОЙ САМИЙ екземпляр — інакше memo не діє і найбільший файл комплекту розбирається заново"

    # Чергування Text/Ast не повинно інвалідувати сусіда: саме на цьому
    # спотикається наївне memo, де кожен getter скидає інший.
    $perfOwnAstAfterText = Get-BRAVOSelfTestOwnSourceAst
    Test-BRAVOCondition `
        -Condition ([object]::ReferenceEquals($perfOwnAstFirst, $perfOwnAstAfterText)) `
        -Name "Perf/OwnSourceMemoSurvivesAlternatingAccess" `
        -Failure "виклик Get-BRAVOSelfTestOwnSourceText не має скидати вже розібраний AST (і навпаки)"

    # Ключ memo мусить враховувати фактичний стан файлу, а не лише шлях:
    # застарілий AST був би гіршим за повторний парсинг.
    $perfOwnItem = Get-Item -LiteralPath $PSCommandPath
    $perfOwnStamp = Get-BRAVOSelfTestOwnSourceStamp
    Test-BRAVOCondition `
        -Condition (
            $perfOwnStamp -like "*$($perfOwnItem.LastWriteTimeUtc.Ticks)*" -and
            $perfOwnStamp -like "*$($perfOwnItem.Length)*"
        ) `
        -Name "Perf/OwnSourceMemoKeyTracksFileState" `
        -Failure "ключ memo має містити час модифікації й розмір файлу, інакше зміна файлу під час прогону віддала б застарілий розбір; фактично: '$perfOwnStamp'"

    # Пришвидшення 2026-10-02: кеш розбору файлів на прогін. Той самий
    # екземпляр для незміненого файлу; новий розбір, щойно файл змінився;
    # синтаксичні помилки кешуються разом із розбором.
    $perfCacheProbeRoot = Join-Path ([IO.Path]::GetTempPath()) ("BRAVO_AST_CACHE_SELF_TEST_{0}" -f [guid]::NewGuid().ToString('N'))
    $perfCacheSameInstance = $false
    $perfCacheTracksChange = $false
    $perfCacheKeepsErrors = $false
    try {
        [void][IO.Directory]::CreateDirectory($perfCacheProbeRoot)
        $perfCacheProbeFile = Join-Path $perfCacheProbeRoot 'probe.ps1'
        [IO.File]::WriteAllText($perfCacheProbeFile, "function Get-ProbeA { 1 }`r`n", (New-Object Text.UTF8Encoding($false)))
        $perfCacheFirst = Get-BRAVOSelfTestParsedFile -Path $perfCacheProbeFile
        $perfCacheSecond = Get-BRAVOSelfTestParsedFile -Path $perfCacheProbeFile
        $perfCacheSameInstance = [object]::ReferenceEquals($perfCacheFirst, $perfCacheSecond) -and
            [object]::ReferenceEquals($perfCacheFirst.Ast, $perfCacheSecond.Ast)
        [IO.File]::WriteAllText($perfCacheProbeFile, "function Get-ProbeChanged { 2 }`r`n", (New-Object Text.UTF8Encoding($false)))
        [IO.File]::SetLastWriteTimeUtc($perfCacheProbeFile, [datetime]::UtcNow.AddMinutes(1))
        $perfCacheChanged = Get-BRAVOSelfTestParsedFile -Path $perfCacheProbeFile
        $perfCacheTracksChange = -not [object]::ReferenceEquals($perfCacheFirst, $perfCacheChanged) -and
            $perfCacheChanged.Ast.Extent.Text.Contains('Get-ProbeChanged')
        $perfCacheBrokenFile = Join-Path $perfCacheProbeRoot 'broken.ps1'
        [IO.File]::WriteAllText($perfCacheBrokenFile, "if (`$true) {`r`n", (New-Object Text.UTF8Encoding($false)))
        $perfCacheBrokenFirst = Get-BRAVOSelfTestParsedFile -Path $perfCacheBrokenFile
        $perfCacheBrokenSecond = Get-BRAVOSelfTestParsedFile -Path $perfCacheBrokenFile
        $perfCacheKeepsErrors = @($perfCacheBrokenFirst.Errors).Count -gt 0 -and
            @($perfCacheBrokenSecond.Errors).Count -eq @($perfCacheBrokenFirst.Errors).Count
    } finally {
        foreach ($perfCacheKey in @($script:BRAVOSelfTestParsedFileCache.Keys)) {
            if ($perfCacheKey.StartsWith($perfCacheProbeRoot, [StringComparison]::OrdinalIgnoreCase)) {
                $script:BRAVOSelfTestParsedFileCache.Remove($perfCacheKey)
            }
        }
        if (Test-Path -LiteralPath $perfCacheProbeRoot) {
            Remove-Item -LiteralPath $perfCacheProbeRoot -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
    Test-BRAVOCondition `
        -Condition ($perfCacheSameInstance -and $perfCacheTracksChange -and $perfCacheKeepsErrors) `
        -Name "Perf/ParsedFileCacheReusesAndTracksFileState" `
        -Failure ("кеш розбору має віддавати той самий розбір для незміненого файлу, розбирати файл " +
            "заново після зміни і зберігати синтаксичні помилки; фактично: same=$perfCacheSameInstance, " +
            "changed=$perfCacheTracksChange, errors=$perfCacheKeepsErrors")

    # Скомпільований предикат типу має знаходити рівно ті самі вузли, що й
    # -is у scriptblock-у, включно з похідними класами
    # (InvokeMemberExpressionAst є MemberExpressionAst).
    $perfPredicateAst = [Management.Automation.Language.Parser]::ParseInput(
        "`$a.B; `$a.C(); [x]::D(); function F { `$e.G() }; if (`$h) { `$i.J }", [ref]$null, [ref]$null)
    $perfPredicateTypes = @(
        [Management.Automation.Language.MemberExpressionAst],
        [Management.Automation.Language.FunctionDefinitionAst])
    $perfCompiledPredicate = Get-BRAVOSelfTestAstTypePredicate -Type $perfPredicateTypes
    $perfCompiledMatches = @($perfPredicateAst.FindAll($perfCompiledPredicate, $true) | ForEach-Object { $_.Extent.StartOffset })
    $perfScriptBlockMatches = @($perfPredicateAst.FindAll({
        param($node)
        $node -is [Management.Automation.Language.MemberExpressionAst] -or
            $node -is [Management.Automation.Language.FunctionDefinitionAst]
    }, $true) | ForEach-Object { $_.Extent.StartOffset })
    Test-BRAVOCondition `
        -Condition (
            $perfCompiledPredicate -is [Func[Management.Automation.Language.Ast, bool]] -and
            [object]::ReferenceEquals($perfCompiledPredicate, (Get-BRAVOSelfTestAstTypePredicate -Type $perfPredicateTypes)) -and
            $perfCompiledMatches.Count -eq 6 -and
            ($perfCompiledMatches -join ',') -eq ($perfScriptBlockMatches -join ',')
        ) `
        -Name "Perf/AstTypePredicateIsCompiledAndMatchesIsOperator" `
        -Failure ("предикат типу має бути скомпільованим делегатом, повторно використовуватись і знаходити " +
            "ті самі вузли, що й -is; фактично: compiled=$($perfCompiledPredicate -is [Func[Management.Automation.Language.Ast, bool]]), " +
            "скомпільований=$($perfCompiledMatches -join ','), scriptblock=$($perfScriptBlockMatches -join ',')")

    # Головний anti-regression guard фази 1: рівно ОДИН АНАЛІТИЧНИЙ
    # AST-прохід по $powerShellFiles, і він годує всі чотири набори
    # знахідок. Цикл синтаксичної перевірки (Parser/<file>) теж розбирає
    # ті самі файли й теж легітимний — його відрізняє саме те, що він не
    # звертається до жодного з наборів знахідок нижче.
    $perfRequiredCollections = @(
        '$silentCatchFindings',
        '$keywordAsCommandFindings',
        '$halfFormattedFindings',
        '$credentialShapedLiterals'
    )
    $perfRepoLoops = @($perfOwnAstFirst.FindAll({
        param($node)
        $node -is [System.Management.Automation.Language.ForEachStatementAst] -and
        $node.Condition.Extent.Text.Contains('powerShellFiles')
    }, $true))
    $perfAnalysisLoops = @($perfRepoLoops | Where-Object {
        $loopText = [string]$_.Extent.Text
        # Розбір іде через кеш прогону (Get-BRAVOSelfTestParsedFile), а не
        # прямим Parser::ParseFile.
        $loopText.Contains('Get-BRAVOSelfTestParsedFile') -and
        @($perfRequiredCollections | Where-Object { $loopText.Contains($_) }).Count -gt 0
    })
    $perfMergedLoopText = if ($perfAnalysisLoops.Count -eq 1) {
        [string]$perfAnalysisLoops[0].Extent.Text
    } else {
        ''
    }
    $perfMissingCollections = @($perfRequiredCollections | Where-Object {
        -not $perfMergedLoopText.Contains($_)
    })
    # Обхід дерева теж має бути один: FindAll викликає scriptblock на
    # КОЖЕН вузол, тож чотири обходи коштують учетверо більше за один —
    # саме це, а не повторний ParseFile, було справжнім вузьким місцем.
    $perfTreeWalkCount = @([regex]::Matches($perfMergedLoopText, '\.FindAll\(')).Count
    Test-BRAVOCondition `
        -Condition (
            $perfAnalysisLoops.Count -eq 1 -and
            $perfMissingCollections.Count -eq 0 -and
            $perfTreeWalkCount -eq 1
        ) `
        -Name "Perf/SingleAstPassOverRepositoryFiles" `
        -Failure ("по файлах комплекту має бути РІВНО ОДИН аналітичний AST-прохід, і він має живити всі " +
            "чотири аналізи (порожній catch, keyword-as-command, half-formatted -f, credential-shaped " +
            "літерали), використавши РІВНО ОДИН обхід дерева (FindAll). Фактично аналітичних " +
            "проходів: $($perfAnalysisLoops.Count); обходів дерева в ньому: $perfTreeWalkCount; " +
            "не живляться з нього: $($perfMissingCollections -join ', ')")
}
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Framework.SelectiveSuitesHaveNoCrossSuiteDependency' } }

if (Enter-BRAVOSelfTestSection -Name 'Tail/Framework.SuiteSelectionContract') { try {

# ============================================================
# Контракт -Suite і підказки "змінений файл -> suite" (VAL-04a / VAL-02a).
#
# Корінь виконується ЗАВЖДИ, у тому числі в -Suite, тому ця секція не читає
# $script:BRAVOSelfTestSelectedSuite як "має бути $null": уся динаміка йде
# через код, витягнутий з реального файлу, у дочірніх процесах (розбір -Suite)
# або через статичний AST. Нові змінні тут не виходять за межі своїх & { }.
# ============================================================
& {
    # G1. Перевірки стану ПОВНОГО прогону (вибір не встановлено) в -Suite
    # хибні за визначенням. Якщо вони не обгорнуті умовою "-Suite не запитано",
    # кожен реальний -Suite X завершується SELF-TEST FAILED, і успішний
    # вибірковий прогін (exit 0 + SELF-TEST PARTIAL) недосяжний.
    # Виняток — SuiteSelectionProbeRestoresState: вона порівнює з $suiteSelectionBefore і
    # ВІРНА в обох режимах, тому gate на ній заборонений (він робить її тавтологією).
    $suiteContractG1Ast = Get-BRAVOSelfTestOwnSourceAst
    $suiteContractG1Names = @(
        'Framework/FullCanonicalRunIsDefault',
        'Framework/FullRunEnablesEverySuite',
        'Framework/SuiteSelectionProbeRestoresState')
    $suiteContractG1Calls = @($suiteContractG1Ast.FindAll({
                param($node)
                $node -is [Management.Automation.Language.CommandAst] -and
                $node.GetCommandName() -eq 'Test-BRAVOCondition'
            }, $true))
    $suiteContractG1Found = @{}
    $suiteContractG1RestoreName = 'Framework/SuiteSelectionProbeRestoresState'
    $suiteContractG1RestoreOk = $false
    # Прапорець gate мусить бути присвоєний рівно один раз, із параметра $Suite, і не з
    # самого вибору $script:BRAVOSelfTestSelectedSuite.
    $suiteContractG1FlagAssignments = @($suiteContractG1Ast.FindAll({
                param($node)
                $node -is [Management.Automation.Language.AssignmentStatementAst] -and
                $node.Left.Extent.Text -ceq '$suiteRequested'
            }, $true))
    $suiteContractG1FlagOk = (
        $suiteContractG1FlagAssignments.Count -eq 1 -and
        $suiteContractG1FlagAssignments[0].Right.Extent.Text.Contains('$Suite') -and
        -not $suiteContractG1FlagAssignments[0].Right.Extent.Text.Contains('BRAVOSelfTestSelectedSuite'))
    $suiteContractG1Ungated = New-Object System.Collections.Generic.List[string]
    foreach ($suiteContractG1Call in $suiteContractG1Calls) {
        $suiteContractG1CallName = ''
        $suiteContractG1Elements = @($suiteContractG1Call.CommandElements)
        for ($suiteContractG1Index = 0; $suiteContractG1Index -lt ($suiteContractG1Elements.Count - 1); $suiteContractG1Index++) {
            $suiteContractG1Element = $suiteContractG1Elements[$suiteContractG1Index]
            if ($suiteContractG1Element -is [Management.Automation.Language.CommandParameterAst] -and
                $suiteContractG1Element.ParameterName -eq 'Name' -and
                $suiteContractG1Elements[$suiteContractG1Index + 1] -is [Management.Automation.Language.StringConstantExpressionAst]) {
                $suiteContractG1CallName = $suiteContractG1Elements[$suiteContractG1Index + 1].Value
            }
        }
        if ($suiteContractG1Names -cnotcontains $suiteContractG1CallName) { continue }
        if (-not $suiteContractG1Found.ContainsKey($suiteContractG1CallName)) {
            $suiteContractG1Found[$suiteContractG1CallName] = 0
        }
        $suiteContractG1Found[$suiteContractG1CallName] = $suiteContractG1Found[$suiteContractG1CallName] + 1
        # Умова gate стоїть у ТІЛІ if (Item2), а не в самій умові чи else.
        # Для RestoresState вимога протилежна: gate там робить перевірку тавтологією,
        # тож вона мусить бути БЕЗ gate і порівнювати з $suiteSelectionBefore.
        $suiteContractG1Gated = $false
        $suiteContractG1Parent = $suiteContractG1Call.Parent
        while ($null -ne $suiteContractG1Parent) {
            if ($suiteContractG1Parent -is [Management.Automation.Language.IfStatementAst]) {
                foreach ($suiteContractG1Clause in $suiteContractG1Parent.Clauses) {
                    if ($suiteContractG1Clause.Item1.Extent.Text.Trim() -ceq '-not $suiteRequested' -and
                        $suiteContractG1Clause.Item2.Extent.StartOffset -le $suiteContractG1Call.Extent.StartOffset -and
                        $suiteContractG1Call.Extent.EndOffset -le $suiteContractG1Clause.Item2.Extent.EndOffset) {
                        $suiteContractG1Gated = $true
                    }
                }
            }
            $suiteContractG1Parent = $suiteContractG1Parent.Parent
        }
        if ($suiteContractG1CallName -ceq $suiteContractG1RestoreName) {
            $suiteContractG1RestoreOk = (-not $suiteContractG1Gated) -and
                $suiteContractG1Call.Extent.Text.Contains('$suiteSelectionBefore')
            if (-not $suiteContractG1RestoreOk) { [void]$suiteContractG1Ungated.Add($suiteContractG1CallName) }
        } elseif (-not $suiteContractG1Gated) {
            [void]$suiteContractG1Ungated.Add($suiteContractG1CallName)
        }
    }
    # Спершу доводиться, що всі три виклики знайдено рівно по одному разу:
    # інакше "нічого не порушено" означало б лише "нічого не знайдено".
    $suiteContractG1AllFound = $true
    foreach ($suiteContractG1Name in $suiteContractG1Names) {
        if (-not $suiteContractG1Found.ContainsKey($suiteContractG1Name) -or $suiteContractG1Found[$suiteContractG1Name] -ne 1) {
            $suiteContractG1AllFound = $false
        }
    }
    Test-BRAVOCondition `
        -Condition ($suiteContractG1AllFound -and $suiteContractG1FlagOk -and $suiteContractG1Ungated.Count -eq 0) `
        -Name "Framework/SuiteSelectionContract.FullOnlyAssertionsAreGatedOnFullRun" `
        -Failure ("FullCanonicalRunIsDefault і FullRunEnablesEverySuite мусять стояти в тілі if (-not `$suiteRequested), де прапорець обчислено з параметра `$Suite (а не з вибору), " +
            "інакше кожен -Suite завершується SELF-TEST FAILED; SuiteSelectionProbeRestoresState мусить бути без такого gate " +
            "і порівнювати з `$suiteSelectionBefore. Усі три знайдено по одному разу: $suiteContractG1AllFound; прапорець коректний: $suiteContractG1FlagOk; " +
            "порушують: [" + [string]::Join(', ', @($suiteContractG1Ungated.ToArray())) + "]")
}
& {
    # S1, S2, S3, S11, R2, R3, R4: статичний контракт -Suite. Усе читається з
    # AST власного файлу (Get-BRAVOSelfTestOwnSourceAst), без жодного запуску.
    $suiteContractAst = Get-BRAVOSelfTestOwnSourceAst
    $suiteContractTop = @($suiteContractAst.EndBlock.Statements)

    # S1. Оголошення параметрів: порядок, тип, відсутність прив'язочних обмежень.
    $suiteContractParams = @($suiteContractAst.ParamBlock.Parameters)
    $suiteContractParamNames = @($suiteContractParams | ForEach-Object { $_.Name.VariablePath.UserPath })
    $suiteContractSuiteParam = @($suiteContractParams | Where-Object { $_.Name.VariablePath.UserPath -ceq 'Suite' })
    $suiteContractNoPauseParam = @($suiteContractParams | Where-Object { $_.Name.VariablePath.UserPath -ceq 'NoPause' })
    $suiteContractCmdletBinding = @($suiteContractAst.ParamBlock.Attributes |
            Where-Object { $_.TypeName.Name -eq 'CmdletBinding' })
    $suiteContractParamsOk = (
        [string]::Join(',', $suiteContractParamNames) -ceq 'ConfigPath,Suite,NoPause' -and
        $suiteContractSuiteParam.Count -eq 1 -and
        $suiteContractNoPauseParam.Count -eq 1 -and
        $suiteContractCmdletBinding.Count -eq 1
    )
    if ($suiteContractParamsOk) {
        $suiteContractParamsOk = (
            $suiteContractSuiteParam[0].StaticType -eq [string[]] -and
            @($suiteContractSuiteParam[0].Attributes | Where-Object { $_ -is [Management.Automation.Language.AttributeAst] }).Count -eq 0 -and
            $null -eq $suiteContractSuiteParam[0].DefaultValue -and
            $suiteContractNoPauseParam[0].StaticType -eq [switch] -and
            @($suiteContractCmdletBinding[0].NamedArguments | Where-Object { $_.ArgumentName -eq 'PositionalBinding' }).Count -eq 0
        )
    }
    Test-BRAVOCondition `
        -Condition $suiteContractParamsOk `
        -Name "Framework/SuiteSelectionContract.ParamDeclaration" `
        -Failure ("param() кореня мусить мати порядок ConfigPath, Suite, NoPause; Suite — [string[]] без атрибутів " +
            "прив'язки (Mandatory/Position/ValidateSet/Alias) і без значення за замовчуванням; NoPause — [switch] останнім; " +
            "CmdletBinding без PositionalBinding (тоді Suite — позиція 1). Фактичний порядок: " +
            [string]::Join(', ', $suiteContractParamNames))

    # S2. Каталог: унікальний (без урахування регістру — -notcontains нечутливий),
    # лише літери, відсортований ordinal-порядком.
    $suiteContractCatalog = @($script:BRAVOSelfTestSuiteCatalog)
    $suiteContractCatalogSet = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach ($suiteContractCatalogName in $suiteContractCatalog) { [void]$suiteContractCatalogSet.Add([string]$suiteContractCatalogName) }
    $suiteContractCatalogSorted = [string[]]@($suiteContractCatalog)
    [Array]::Sort($suiteContractCatalogSorted, [StringComparer]::Ordinal)
    $suiteContractCatalogNonLetters = @($suiteContractCatalog | Where-Object { $_ -cnotmatch '^[A-Za-z]+$' })
    Test-BRAVOCondition `
        -Condition (
            $suiteContractCatalog.Count -gt 0 -and
            $suiteContractCatalogSet.Count -eq $suiteContractCatalog.Count -and
            $suiteContractCatalogNonLetters.Count -eq 0 -and
            [string]::Join(',', $suiteContractCatalogSorted) -ceq [string]::Join(',', $suiteContractCatalog)
        ) `
        -Name "Framework/SuiteSelectionContract.CatalogShapeIsDeterministic" `
        -Failure ("каталог -Suite мусить бути непорожнім, без дублів (без урахування регістру), лише з літер A-Z " +
            "(від цього залежить мапа шляхів) і відсортованим ordinal-порядком; імена не з літер: [" +
            [string]::Join(', ', $suiteContractCatalogNonLetters) + "]")

    # S3. Кожен елемент каталогу має файл фрагмента; фрагменти поза каталогом —
    # рівно два відомі винятки. Новий standalone-фрагмент вимагає свідомого рішення.
    $suiteContractFragmentNames = @(
        [IO.Directory]::GetFiles((Join-Path $root 'selftest'), 'BRAVO_SELF_TEST.*.ps1') |
            ForEach-Object { [IO.Path]::GetFileName($_) } |
            Where-Object { $_.EndsWith('.ps1', [StringComparison]::OrdinalIgnoreCase) } |
            ForEach-Object { $_.Substring('BRAVO_SELF_TEST.'.Length, $_.Length - 'BRAVO_SELF_TEST.'.Length - '.ps1'.Length) })
    $suiteContractNoFile = @($suiteContractCatalog | Where-Object { $suiteContractFragmentNames -cnotcontains $_ })
    $suiteContractNotInCatalog = [string[]]@($suiteContractFragmentNames | Where-Object { $suiteContractCatalog -cnotcontains $_ })
    [Array]::Sort($suiteContractNotInCatalog, [StringComparer]::Ordinal)
    Test-BRAVOCondition `
        -Condition (
            $suiteContractFragmentNames.Count -gt 0 -and
            $suiteContractNoFile.Count -eq 0 -and
            [string]::Join(',', $suiteContractNotInCatalog) -ceq 'ConfigV2PilotArtifact,ManualLaunchers'
        ) `
        -Name "Framework/SuiteSelectionContract.CatalogEntriesHaveFragmentFiles" `
        -Failure ("кожен suite каталогу мусить мати selftest\BRAVO_SELF_TEST.<Ім'я>.ps1, а фрагменти поза каталогом " +
            "мусять бути рівно ConfigV2PilotArtifact (окремий скрипт) і ManualLaunchers (вкладений у LogRotation) — " +
            "новий фрагмент потребує свідомого рішення. Без файлу: [" + [string]::Join(', ', $suiteContractNoFile) +
            "]; поза каталогом: [" + [string]::Join(', ', $suiteContractNotInCatalog) + "]")

    # Спільний обхід: усі CommandAst (один FindAll на секцію).
    $suiteContractCommands = @($suiteContractAst.FindAll({
                param($node) $node -is [Management.Automation.Language.CommandAst]
            }, $true))

    # S11. throw на невідомий suite — на верхньому рівні, поза try/trap/функцією,
    # після Import-Module HelperLogging і до першої секції.
    $suiteContractThrows = @($suiteContractAst.FindAll({
                param($node)
                $node -is [Management.Automation.Language.ThrowStatementAst] -and
                $node.Extent.Text.Contains('Невідомий suite')
            }, $true))
    $suiteContractTraps = @($suiteContractAst.FindAll({
                param($node) $node -is [Management.Automation.Language.TrapStatementAst]
            }, $true))
    $suiteContractThrowWrapped = $true
    $suiteContractThrowOrdered = $false
    if ($suiteContractThrows.Count -eq 1) {
        $suiteContractThrowWrapped = $false
        $suiteContractThrowParent = $suiteContractThrows[0].Parent
        while ($null -ne $suiteContractThrowParent) {
            if ($suiteContractThrowParent -is [Management.Automation.Language.TryStatementAst] -or
                $suiteContractThrowParent -is [Management.Automation.Language.CatchClauseAst] -or
                $suiteContractThrowParent -is [Management.Automation.Language.TrapStatementAst] -or
                $suiteContractThrowParent -is [Management.Automation.Language.FunctionDefinitionAst]) {
                $suiteContractThrowWrapped = $true
            }
            $suiteContractThrowParent = $suiteContractThrowParent.Parent
        }
        $suiteContractHelperImports = @($suiteContractCommands | Where-Object {
                $_.GetCommandName() -eq 'Import-Module' -and $_.Extent.Text.Contains('$helperLoggingPath') })
        $suiteContractSectionEnters = @($suiteContractCommands | Where-Object {
                $_.GetCommandName() -eq 'Enter-BRAVOSelfTestSection' })
        if ($suiteContractHelperImports.Count -ge 1 -and $suiteContractSectionEnters.Count -ge 1) {
            $suiteContractFirstEnter = ($suiteContractSectionEnters | ForEach-Object { $_.Extent.StartOffset } | Measure-Object -Minimum).Minimum
            $suiteContractThrowOrdered = (
                $suiteContractThrows[0].Extent.StartOffset -gt $suiteContractHelperImports[0].Extent.StartOffset -and
                $suiteContractThrows[0].Extent.StartOffset -lt $suiteContractFirstEnter)
        }
    }
    Test-BRAVOCondition `
        -Condition (
            $suiteContractThrows.Count -eq 1 -and
            -not $suiteContractThrowWrapped -and
            $suiteContractTraps.Count -eq 0 -and
            $suiteContractThrowOrdered
        ) `
        -Name "Framework/SuiteSelectionContract.UnknownThrowIsUncaughtTopLevel" `
        -Failure ("throw на невідомий suite мусить бути один, на верхньому рівні скрипта (поза try/catch/trap/функцією; " +
            "trap у файлі: $($suiteContractTraps.Count)), після Import-Module HelperLogging і до першої секції — тоді " +
            "-File завершується необробленою помилкою (код 1). throw: $($suiteContractThrows.Count); обгорнутий: " +
            "$suiteContractThrowWrapped; порядок: $suiteContractThrowOrdered")

    $suiteContractReportFns = @($suiteContractAst.FindAll({
                param($node)
                $node -is [Management.Automation.Language.FunctionDefinitionAst] -and
                $node.Name -ceq 'Complete-BRAVOSelfTestReport'
            }, $true))
    $suiteContractReportText = ''
    if ($suiteContractReportFns.Count -eq 1) { $suiteContractReportText = $suiteContractReportFns[0].Extent.Text }

    # R2. Текст selective-підсумку зафіксовано (читається з тіла функції звіту,
    # а не з усього файлу, тому цей тест не задовольняє сам себе).
    Test-BRAVOCondition `
        -Condition (
            $suiteContractReportFns.Count -eq 1 -and
            $suiteContractReportText.Contains("'вибірковий: '") -and
            $suiteContractReportText.Contains('Виявлених помилок немає, але виконано ВИБІРКОВИЙ прогін.') -and
            $suiteContractReportText.Contains('Для мержу й релізу потрібен повний канонічний прогін без -Suite.') -and
            [regex]::IsMatch($suiteContractReportText,
                'SELF-TEST PARTIAL: "\s*\+\s*\[string\]::Join\('','', \$script:BRAVOSelfTestSelectedSuite\)')
        ) `
        -Name "Framework/SuiteSelectionContract.SelectiveSummaryTextIsPinned" `
        -Failure ("Complete-BRAVOSelfTestReport мусить друкувати поле 'вибірковий: ', три рядки попередження про " +
            "вибірковий прогін і маркер SELF-TEST PARTIAL: <імена через кому>; зміна тексту — свідоме рішення")

    # R3. Код завершення не залежить від режиму вибору.
    $suiteContractExitAssignments = @()
    if ($suiteContractReportFns.Count -eq 1) {
        $suiteContractExitAssignments = @($suiteContractReportFns[0].FindAll({
                    param($node)
                    $node -is [Management.Automation.Language.AssignmentStatementAst] -and
                    $node.Left.Extent.Text -ceq '$script:selfTestExitCode'
                }, $true))
    }
    $suiteContractSelectedRefs = @()
    if ($suiteContractReportFns.Count -eq 1) {
        $suiteContractSelectedRefs = @($suiteContractReportFns[0].FindAll({
                    param($node)
                    $node -is [Management.Automation.Language.VariableExpressionAst] -and
                    $node.VariablePath.UserPath -ceq 'script:BRAVOSelfTestSelectedSuite'
                }, $true))
    }
    $suiteContractRefsMisplaced = New-Object System.Collections.Generic.List[string]
    foreach ($suiteContractRef in $suiteContractSelectedRefs) {
        $suiteContractRefOk = $false
        $suiteContractRefParent = $suiteContractRef.Parent
        while ($null -ne $suiteContractRefParent) {
            if ($suiteContractRefParent -is [Management.Automation.Language.IfStatementAst]) {
                foreach ($suiteContractRefClause in $suiteContractRefParent.Clauses) {
                    if ($suiteContractRefClause.Item1.Extent.StartOffset -le $suiteContractRef.Extent.StartOffset -and
                        $suiteContractRef.Extent.EndOffset -le $suiteContractRefClause.Item1.Extent.EndOffset) {
                        $suiteContractRefOk = $true
                    }
                }
            }
            if ($suiteContractRefParent -is [Management.Automation.Language.CommandAst] -and
                [string]$suiteContractRefParent.GetCommandName() -like 'Write-*') {
                $suiteContractRefOk = $true
            }
            $suiteContractRefParent = $suiteContractRefParent.Parent
        }
        if (-not $suiteContractRefOk) { [void]$suiteContractRefsMisplaced.Add($suiteContractRef.Extent.Text) }
    }
    Test-BRAVOCondition `
        -Condition (
            $suiteContractExitAssignments.Count -eq 1 -and
            $suiteContractExitAssignments[0].Right.Extent.Text -ceq 'if ($script:failures.Count -gt 0) { 1 } else { 0 }' -and
            -not $suiteContractExitAssignments[0].Extent.Text.Contains('BRAVOSelfTestSelectedSuite') -and
            $suiteContractSelectedRefs.Count -gt 0 -and
            $suiteContractRefsMisplaced.Count -eq 0
        ) `
        -Name "Framework/SuiteSelectionContract.ExitCodeIndependentOfSelectionMode" `
        -Failure ("код завершення мусить обчислюватись лише з кількості збоїв (1, якщо збої є, інакше 0): рівно одне " +
            "присвоєння змінної коду завершення, без згадки вибору suite; " +
            "вибір у звіті може стояти лише в умовах if або в Write-*. Присвоєнь: $($suiteContractExitAssignments.Count); " +
            "згадок поза умовою/Write-*: $($suiteContractRefsMisplaced.Count)")

    # R4. Корінь і Phase0 ніколи не під suite-gate; число gate-if = розмір каталогу.
    $suiteContractGateIfs = New-Object System.Collections.Generic.List[object]
    foreach ($suiteContractIf in @($suiteContractAst.FindAll({
                    param($node) $node -is [Management.Automation.Language.IfStatementAst]
                }, $true))) {
        foreach ($suiteContractIfClause in $suiteContractIf.Clauses) {
            if ($suiteContractIfClause.Item1.Extent.Text -match '^Test-BRAVOSelfTestSuiteEnabled -Name ') {
                [void]$suiteContractGateIfs.Add([pscustomobject]@{ Clause = $suiteContractIfClause })
            }
        }
    }
    $suiteContractGuardProblems = New-Object System.Collections.Generic.List[string]
    foreach ($suiteContractGuardName in @('Bootstrap/RuntimeGuard', 'Phase0')) {
        # Ім'я секції — значення параметра -Name (а не будь-який рядок виклику: 'Phase0' є ще й у -DependsOn).
        $suiteContractGuardEnters = New-Object System.Collections.Generic.List[object]
        foreach ($suiteContractEnter in @($suiteContractCommands | Where-Object { $_.GetCommandName() -eq 'Enter-BRAVOSelfTestSection' })) {
            $suiteContractEnterElements = @($suiteContractEnter.CommandElements)
            for ($suiteContractEnterIndex = 0; $suiteContractEnterIndex -lt ($suiteContractEnterElements.Count - 1); $suiteContractEnterIndex++) {
                if ($suiteContractEnterElements[$suiteContractEnterIndex] -is [Management.Automation.Language.CommandParameterAst] -and
                    $suiteContractEnterElements[$suiteContractEnterIndex].ParameterName -eq 'Name' -and
                    $suiteContractEnterElements[$suiteContractEnterIndex + 1] -is [Management.Automation.Language.StringConstantExpressionAst] -and
                    $suiteContractEnterElements[$suiteContractEnterIndex + 1].Value -ceq $suiteContractGuardName) {
                    [void]$suiteContractGuardEnters.Add($suiteContractEnter)
                }
            }
        }
        if ($suiteContractGuardEnters.Count -ne 1) {
            [void]$suiteContractGuardProblems.Add("${suiteContractGuardName}: входів $($suiteContractGuardEnters.Count)")
            continue
        }
        foreach ($suiteContractGate in $suiteContractGateIfs) {
            $suiteContractGuardBody = $suiteContractGate.Clause.Item2.Extent
            if ($suiteContractGuardBody.StartOffset -le $suiteContractGuardEnters[0].Extent.StartOffset -and
                $suiteContractGuardEnters[0].Extent.EndOffset -le $suiteContractGuardBody.EndOffset) {
                [void]$suiteContractGuardProblems.Add("$suiteContractGuardName стоїть під suite-gate")
            }
        }
    }
    Test-BRAVOCondition `
        -Condition (
            $suiteContractGuardProblems.Count -eq 0 -and
            $suiteContractGateIfs.Count -gt 0 -and
            $suiteContractGateIfs.Count -eq $suiteContractCatalog.Count
        ) `
        -Name "Framework/SuiteSelectionContract.RootGuardsAreNeverSuiteGated" `
        -Failure ("Bootstrap/RuntimeGuard і Phase0 мусять виконуватись у кожному режимі, а число if (Test-BRAVOSelfTestSuiteEnabled ...) " +
            "мусить дорівнювати розміру каталогу ($($suiteContractCatalog.Count)); gate-if: $($suiteContractGateIfs.Count); " +
            "проблеми: [" + [string]::Join('; ', @($suiteContractGuardProblems.ToArray())) + "]")
}
& {
    # S4-S10, S12, S13: дочірні процеси. P1 — один процес на багато входів
    # (розбір -Suite з реального коду кореня); P2 — два запуски через -File
    # (код завершення невідомого suite і форма виклику з комою).
    # Патерн той самий, що в Tail/Framework.SectionIsolation: хост = поточний
    # процес, скрипт проби з BOM, без 2>&1 (stderr нативного процесу під
    # ErrorActionPreference = Stop став би термінальною помилкою батька),
    # кирилиця з дочірнього процесу — лише через base64.
    # Корінь проби резолвиться ВСЕРЕДИНІ try (конвенція Framework/FixtureTempRootSetupIsControlled):
    # збій визначення тимчасового шляху стає помилкою проби, а не обриває секцію.
    $suiteProbeRoot = $null
    $suiteProbeCases = @{}
    $suiteProbeRuns = @{}
    $suiteProbeError = $null
    # Id, текст аргументів виклику Invoke-SuiteSelectionCase. Єдине джерело
    # випадків: і драйвер дочірнього процесу, і очікування батька беруть id звідси.
    $suiteProbeCaseTable = @(
        @('absent', ''),
        @('null', '-Suite $null'),
        @('empty-array', '-Suite @()'),
        @('empty-string', "-Suite ''"),
        @('space', "-Suite ' '"),
        @('empty-and-space', "-Suite @('', ' ')"),
        @('single', "-Suite 'Paths'"),
        @('single-padded', "-Suite ' Paths '"),
        @('multi-paths-archive', "-Suite @('Paths', 'Archive')"),
        @('multi-archive-paths', "-Suite @('Archive', 'Paths')"),
        @('dup-same', "-Suite @('Paths', 'Paths')"),
        @('dup-case', "-Suite @('paths', 'PATHS', 'Paths')"),
        @('lower', "-Suite 'archive'"),
        @('upper-long', "-Suite 'ARCHIVEDISKSPACE'"),
        @('unknown', "-Suite 'NoSuch'"),
        @('unknown-mixed', "-Suite @('Paths', 'Bogus', 'Nope')"),
        @('unknown-dup', "-Suite @('Bogus', 'Bogus')"),
        @('nonsel-phase0', "-Suite 'Phase0'"),
        @('nonsel-root-inline', "-Suite 'Root (inline)'"),
        @('nonsel-manuallaunchers', "-Suite 'ManualLaunchers'"),
        @('nonsel-configv2pilot', "-Suite 'ConfigV2PilotArtifact'"),
        @('nonsel-prefix', "-Suite 'Arch'"),
        @('nonsel-comma-one-element', "-Suite 'Paths,Archive'")
    )
    try {
        $suiteProbeRoot = Join-Path ([IO.Path]::GetTempPath()) ('BRAVO_SUITE_CONTRACT_' + [guid]::NewGuid().ToString('N'))
        [void][IO.Directory]::CreateDirectory($suiteProbeRoot)
        $suiteProbeAst = Get-BRAVOSelfTestOwnSourceAst
        $suiteProbeTop = @($suiteProbeAst.EndBlock.Statements)
        # Каталог живе у файлі мапи (selftest\BRAVOSelfTestSuiteMap.ps1), а корінь його dot-source-ить;
        # присвоєння береться з AST саме цього файлу, а корінь мусить підключати його рівно один раз.
        $suiteProbeMapParsed = Get-BRAVOSelfTestParsedFile -Path (Join-Path $root 'selftest\BRAVOSelfTestSuiteMap.ps1')
        if (@($suiteProbeMapParsed.Errors).Count -gt 0) { throw 'синтаксичні помилки у selftest\BRAVOSelfTestSuiteMap.ps1' }
        $suiteProbeMapTop = @($suiteProbeMapParsed.Ast.EndBlock.Statements)
        $suiteProbeCatalogAssign = @($suiteProbeMapTop | Where-Object {
                $_ -is [Management.Automation.Language.AssignmentStatementAst] -and
                $_.Left.Extent.Text -ceq '$script:BRAVOSelfTestSuiteCatalog' })
        $suiteProbeMapDotSource = @($suiteProbeTop | Where-Object {
                $_ -is [Management.Automation.Language.PipelineAst] -and
                $_.PipelineElements.Count -eq 1 -and
                $_.PipelineElements[0] -is [Management.Automation.Language.CommandAst] -and
                $_.PipelineElements[0].InvocationOperator -eq [Management.Automation.Language.TokenKind]::Dot -and
                $_.Extent.Text -ceq ". (Join-Path `$root 'selftest\BRAVOSelfTestSuiteMap.ps1')" })
        $suiteProbeResetAssign = @($suiteProbeTop | Where-Object {
                $_ -is [Management.Automation.Language.AssignmentStatementAst] -and
                $_.Left.Extent.Text -ceq '$script:BRAVOSelfTestSelectedSuite' -and
                $_.Right.Extent.Text -ceq '$null' }) | Select-Object -First 1
        $suiteProbeNormalize = @($suiteProbeTop | Where-Object {
                $_ -is [Management.Automation.Language.IfStatementAst] -and
                $_.Clauses[0].Item1.Extent.Text -match '^\$null -ne \$Suite' })
        $suiteProbeEnabledFn = @($suiteProbeTop | Where-Object {
                $_ -is [Management.Automation.Language.FunctionDefinitionAst] -and
                $_.Name -ceq 'Test-BRAVOSelfTestSuiteEnabled' })
        if ($suiteProbeCatalogAssign.Count -ne 1 -or $suiteProbeMapDotSource.Count -ne 1 -or $null -eq $suiteProbeResetAssign -or
            $suiteProbeNormalize.Count -ne 1 -or $suiteProbeEnabledFn.Count -ne 1) {
            throw 'не знайдено каталог у файлі мапи, його dot-source у корені, скидання вибору, розбір -Suite чи Test-BRAVOSelfTestSuiteEnabled — межі розбору -Suite змінено'
        }

        # P1: функція повторює param() кореня ([string[]]$Suite) і виконує дослівні
        # оператори розбору (без Set-StrictMode, як у корені на цей момент).
        $suiteProbeDriverCases = New-Object System.Text.StringBuilder
        foreach ($suiteProbeRow in $suiteProbeCaseTable) {
            [void]$suiteProbeDriverCases.AppendLine(
                "    @{ Id = '" + $suiteProbeRow[0] + "'; Run = { Invoke-SuiteSelectionCase " + $suiteProbeRow[1] + " } }")
        }
        $suiteProbeP1Head = @'
$ErrorActionPreference = 'Stop'
function Format-SuiteState {
    if ($null -eq $script:BRAVOSelfTestSelectedSuite) { return 'NULL' }
    return [string]::Join(';', @($script:BRAVOSelfTestSelectedSuite))
}
'@
        $suiteProbeP1Driver = @'
foreach ($case in $cases) {
    $sel = ''
    $err = ''
    try {
        $sel = [string](& $case.Run)
    } catch {
        $sel = 'THROW'
        $err = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]$_.Exception.Message))
    }
    Write-Host ('CASE|' + $case.Id + '|SEL=' + $sel + '|POST=' + (Format-SuiteState) + '|ERR=' + $err)
}
'@
        $suiteProbeP1 = $suiteProbeP1Head + "`r`n" + $suiteProbeCatalogAssign[0].Extent.Text + "`r`n" +
            $suiteProbeEnabledFn[0].Extent.Text + "`r`n" +
            "function Invoke-SuiteSelectionCase {`r`n    param([string[]]`$Suite)`r`n    " +
            $suiteProbeResetAssign.Extent.Text + "`r`n    " + $suiteProbeNormalize[0].Extent.Text + "`r`n" +
            "    return (Format-SuiteState)`r`n}`r`n`$cases = @(`r`n" + $suiteProbeDriverCases.ToString() + ")`r`n" +
            $suiteProbeP1Driver + "`r`n"
        # P2: те саме на верхньому рівні скрипта з param() — точна копія контексту throw.
        $suiteProbeP2 = "param([string[]]`$Suite)`r`n`$ErrorActionPreference = 'Stop'`r`n" +
            $suiteProbeCatalogAssign[0].Extent.Text + "`r`n" + $suiteProbeResetAssign.Extent.Text + "`r`n" +
            $suiteProbeNormalize[0].Extent.Text + "`r`n" +
            "Write-Host 'PROBE-REACHED'`r`n" +
            "Write-Host ('PROBE-SEL=' + [string]::Join(';', @(`$script:BRAVOSelfTestSelectedSuite)))`r`n"

        $suiteProbeP1Path = Join-Path $suiteProbeRoot 'probe-p1.ps1'
        $suiteProbeP2Path = Join-Path $suiteProbeRoot 'probe-p2.ps1'
        # BOM обов'язковий: Windows PowerShell 5.1 без нього читає кириличні
        # рядки екстрагованого коду в кодовій сторінці ANSI.
        [IO.File]::WriteAllText($suiteProbeP1Path, $suiteProbeP1, (New-Object Text.UTF8Encoding($true)))
        [IO.File]::WriteAllText($suiteProbeP2Path, $suiteProbeP2, (New-Object Text.UTF8Encoding($true)))
        $suiteProbeHost = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName

        $suiteProbeP1Lines = @(& $suiteProbeHost -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass `
                -File $suiteProbeP1Path | ForEach-Object { [string]$_ })
        foreach ($suiteProbeLine in $suiteProbeP1Lines) {
            $suiteProbeMatch = [regex]::Match($suiteProbeLine.TrimEnd("`r"), '^CASE\|([^|]+)\|SEL=([^|]*)\|POST=([^|]*)\|ERR=(.*)$')
            if (-not $suiteProbeMatch.Success) { continue }
            $suiteProbeErrText = ''
            if ($suiteProbeMatch.Groups[4].Value.Length -gt 0) {
                $suiteProbeErrText = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($suiteProbeMatch.Groups[4].Value))
            }
            $suiteProbeCases[$suiteProbeMatch.Groups[1].Value] = [pscustomobject]@{
                Sel  = $suiteProbeMatch.Groups[2].Value
                Post = $suiteProbeMatch.Groups[3].Value
                Err  = $suiteProbeErrText
            }
        }

        # Без 2>&1: повідомлення про помилку йде в stderr і тут не перевіряється.
        $suiteProbeRunA = @(& $suiteProbeHost -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass `
                -File $suiteProbeP2Path -Suite NoSuchSuite | ForEach-Object { [string]$_ })
        $suiteProbeRuns['unknown'] = [pscustomobject]@{ ExitCode = $LASTEXITCODE; Lines = @($suiteProbeRunA | ForEach-Object { $_.TrimEnd("`r") }) }
        $suiteProbeRunB = @(& $suiteProbeHost -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass `
                -File $suiteProbeP2Path -Suite 'Paths,Archive' | ForEach-Object { [string]$_ })
        $suiteProbeRuns['comma'] = [pscustomobject]@{ ExitCode = $LASTEXITCODE; Lines = @($suiteProbeRunB | ForEach-Object { $_.TrimEnd("`r") }) }
    } catch {
        $suiteProbeError = $_.Exception.Message
    } finally {
        # Remove-BRAVOSelfTestFixtureDirectory тут не застосовано: його визначено всередині
        # секції Tail/Isolation (з -DependsOn), тож виклик з цієї секції створив би прихований
        # зв'язок між секціями і при перерваній Tail/Isolation кидав би CommandNotFound у finally.
        # Секція SectionIsolation прибирає свій корінь так само напряму.
        if (-not [string]::IsNullOrEmpty($suiteProbeRoot) -and [IO.Directory]::Exists($suiteProbeRoot)) {
            [IO.Directory]::Delete($suiteProbeRoot, $true)
        }
    }

    # [НЕДОСТУПНО] лише коли дочірній процес не дав ЖОДНОГО випадку і хост
    # доведено обмежений; проба, що відпрацювала неправильно, — [FAIL].
    $suiteProbeRestriction = ''
    if ($suiteProbeCases.Count -eq 0) {
        $suiteProbeRestriction = [string](Get-BRAVOSelfTestHostRestriction)
    }
    $suiteProbeCase = {
        param([string]$Id)
        if ($suiteProbeCases.ContainsKey($Id)) { return $suiteProbeCases[$Id] }
        return $null
    }
    $suiteProbeDescribe = {
        param([string[]]$Ids)
        $described = New-Object System.Collections.Generic.List[string]
        foreach ($describedId in $Ids) {
            $describedCase = & $suiteProbeCase $describedId
            if ($null -eq $describedCase) { [void]$described.Add("${describedId}: випадку немає"); continue }
            [void]$described.Add("${describedId}: SEL=$($describedCase.Sel) POST=$($describedCase.Post) ERR=[$($describedCase.Err)]")
        }
        return [string]::Join('; ', @($described.ToArray()))
    }
    # Очікування "вибір = $Selected, без помилки" (NULL = повний прогін).
    $suiteProbeExpectSelection = {
        param([string[]]$Ids, [string[]]$Selected)
        for ($expectIndex = 0; $expectIndex -lt $Ids.Count; $expectIndex++) {
            $expectCase = & $suiteProbeCase $Ids[$expectIndex]
            if ($null -eq $expectCase) { return $false }
            if ($expectCase.Sel -cne $Selected[$expectIndex] -or $expectCase.Post -cne $Selected[$expectIndex] -or
                $expectCase.Err.Length -ne 0) { return $false }
        }
        return $true
    }
    $suiteProbeExpectedError = {
        param([string]$Unknown)
        return ('Невідомий suite: ' + $Unknown + '. Доступні: ' + [string]::Join(', ', $script:BRAVOSelfTestSuiteCatalog) +
            '. Без -Suite виконується повний канонічний прогін.')
    }
    # Очікування "виняток з точним повідомленням, вибір не встановлено".
    $suiteProbeExpectThrow = {
        param([string[]]$Ids, [string[]]$Unknown)
        for ($expectIndex = 0; $expectIndex -lt $Ids.Count; $expectIndex++) {
            $expectCase = & $suiteProbeCase $Ids[$expectIndex]
            if ($null -eq $expectCase) { return $false }
            if ($expectCase.Sel -cne 'THROW' -or $expectCase.Post -cne 'NULL' -or
                $expectCase.Err -cne (& $suiteProbeExpectedError $Unknown[$expectIndex])) { return $false }
        }
        return $true
    }

    if ($null -ne $suiteProbeError) {
        Test-BRAVOCondition `
            -Condition $false `
            -Name 'Framework/SuiteSelectionContract.ProbeExecution' `
            -EnvironmentLimitation $suiteProbeRestriction `
            -Failure "проби розбору -Suite не вдалося підготувати чи запустити: $suiteProbeError"
    } else {
        $suiteProbeFull = @('absent', 'null', 'empty-array', 'empty-string', 'space', 'empty-and-space')
        Test-BRAVOCondition `
            -Condition (& $suiteProbeExpectSelection $suiteProbeFull @('NULL', 'NULL', 'NULL', 'NULL', 'NULL', 'NULL')) `
            -Name "Framework/SuiteSelectionContract.AbsentOrEmptyMeansFull" `
            -EnvironmentLimitation $suiteProbeRestriction `
            -Failure ("відсутній, `$null, порожній масив, порожній і пробільний рядок -Suite мусять давати повний прогін " +
                "(вибір `$null) без помилки: " + (& $suiteProbeDescribe $suiteProbeFull))

        $suiteProbeSingle = @('single', 'single-padded')
        Test-BRAVOCondition `
            -Condition (& $suiteProbeExpectSelection $suiteProbeSingle @('Paths', 'Paths')) `
            -Name "Framework/SuiteSelectionContract.SingleSuiteSelected" `
            -EnvironmentLimitation $suiteProbeRestriction `
            -Failure ("один suite (також з пробілами по краях) мусить дати вибір з одного імені: " + (& $suiteProbeDescribe $suiteProbeSingle))

        $suiteProbeMulti = @('multi-paths-archive', 'multi-archive-paths')
        Test-BRAVOCondition `
            -Condition (& $suiteProbeExpectSelection $suiteProbeMulti @('Paths;Archive', 'Archive;Paths')) `
            -Name "Framework/SuiteSelectionContract.MultiSuiteKeepsRequestOrder" `
            -EnvironmentLimitation $suiteProbeRestriction `
            -Failure ("кілька suite мусять зберігати порядок запиту, а не порядок каталогу: " + (& $suiteProbeDescribe $suiteProbeMulti))

        $suiteProbeDup = @('dup-same', 'dup-case', 'lower', 'upper-long')
        Test-BRAVOCondition `
            -Condition (& $suiteProbeExpectSelection $suiteProbeDup @('Paths', 'Paths', 'Archive', 'ArchiveDiskSpace')) `
            -Name "Framework/SuiteSelectionContract.DuplicatesAndCaseCollapse" `
            -EnvironmentLimitation $suiteProbeRestriction `
            -Failure ("дублі й варіанти регістру мусять згортатись до одного імені в написанні каталогу: " + (& $suiteProbeDescribe $suiteProbeDup))

        Test-BRAVOCondition `
            -Condition (& $suiteProbeExpectThrow @('unknown') @('NoSuch')) `
            -Name "Framework/SuiteSelectionContract.UnknownSuiteThrowsExactMessage" `
            -EnvironmentLimitation $suiteProbeRestriction `
            -Failure ("невідомий suite мусить кидати точне повідомлення з повним переліком каталогу, а вибір лишатись `$null: " +
                (& $suiteProbeDescribe @('unknown')))

        $suiteProbeMixed = @('unknown-mixed', 'unknown-dup')
        Test-BRAVOCondition `
            -Condition (& $suiteProbeExpectThrow $suiteProbeMixed @('Bogus, Nope', 'Bogus, Bogus')) `
            -Name "Framework/SuiteSelectionContract.UnknownSuiteListsOnlyUnknownAndNeverPartiallySelects" `
            -EnvironmentLimitation $suiteProbeRestriction `
            -Failure ("повідомлення має називати лише невідомі імена (дублі невідомих не згортаються), а відомі імена з того " +
                "самого запиту не мають потрапляти у вибір: " + (& $suiteProbeDescribe $suiteProbeMixed))

        $suiteProbeNonSelectable = @('nonsel-phase0', 'nonsel-root-inline', 'nonsel-manuallaunchers',
            'nonsel-configv2pilot', 'nonsel-prefix', 'nonsel-comma-one-element')
        Test-BRAVOCondition `
            -Condition (& $suiteProbeExpectThrow $suiteProbeNonSelectable @('Phase0', 'Root (inline)', 'ManualLaunchers',
                    'ConfigV2PilotArtifact', 'Arch', 'Paths,Archive')) `
            -Name "Framework/SuiteSelectionContract.NonSelectableNamesAreUnknown" `
            -EnvironmentLimitation $suiteProbeRestriction `
            -Failure ("імена поза каталогом (Phase0, Root (inline), фрагменти поза каталогом, префікс імені, два імені в одному " +
                "рядку) мусять бути невідомими: " + (& $suiteProbeDescribe $suiteProbeNonSelectable))
    }

    # S12 / S13: -File. Обидва запуски мають сенс лише коли дочірній процес працює взагалі.
    $suiteProbeUnknownRun = $null
    if ($suiteProbeRuns.ContainsKey('unknown')) { $suiteProbeUnknownRun = $suiteProbeRuns['unknown'] }
    $suiteProbeCommaRun = $null
    if ($suiteProbeRuns.ContainsKey('comma')) { $suiteProbeCommaRun = $suiteProbeRuns['comma'] }
    $suiteProbeUnknownOk = (
        $null -ne $suiteProbeUnknownRun -and
        $suiteProbeUnknownRun.ExitCode -eq 1 -and
        @($suiteProbeUnknownRun.Lines | Where-Object { $_.Contains('PROBE-REACHED') -or $_.Contains('SELF-TEST PASSED') }).Count -eq 0)
    $suiteProbeUnknownExit = 'прогін не виконано'
    if ($null -ne $suiteProbeUnknownRun) { $suiteProbeUnknownExit = [string]$suiteProbeUnknownRun.ExitCode }
    Test-BRAVOCondition `
        -Condition $suiteProbeUnknownOk `
        -Name "Framework/SuiteSelectionContract.UnknownSuiteExitsNonZeroUnderFile" `
        -EnvironmentLimitation $suiteProbeRestriction `
        -Failure ("powershell -File ... -Suite NoSuchSuite мусить завершуватись кодом 1 без виконання подальшого коду; " +
            "код: $suiteProbeUnknownExit")

    # Межа -File: у Windows PowerShell 5.1 аргумент 'Paths,Archive' після -File
    # не обов'язково розбирається як масив. Допустимі рівно два результати, і
    # жоден не вибирає тихо не те, що просили: (1) масив з двох елементів —
    # код 0 і вибір Paths;Archive, або (2) один рядок 'Paths,Archive' — він
    # невідомий, код 1 і код далі не виконується.
    # Після першого прогону на Windows CI записати тут, який саме варіант
    # обрав Windows PowerShell 5.1.
    $suiteProbeCommaSelected = (
        $null -ne $suiteProbeCommaRun -and
        $suiteProbeCommaRun.ExitCode -eq 0 -and
        $suiteProbeCommaRun.Lines -ccontains 'PROBE-REACHED' -and
        $suiteProbeCommaRun.Lines -ccontains 'PROBE-SEL=Paths;Archive')
    $suiteProbeCommaRejected = (
        $null -ne $suiteProbeCommaRun -and
        $suiteProbeCommaRun.ExitCode -eq 1 -and
        $suiteProbeCommaRun.Lines -cnotcontains 'PROBE-REACHED')
    $suiteProbeCommaExit = 'прогін не виконано'
    if ($null -ne $suiteProbeCommaRun) { $suiteProbeCommaExit = [string]$suiteProbeCommaRun.ExitCode }
    Test-BRAVOCondition `
        -Condition ($suiteProbeCommaSelected -or $suiteProbeCommaRejected) `
        -Name "Framework/SuiteSelectionContract.FileInvocationCommaFormNeverSilentlyMisselects" `
        -EnvironmentLimitation $suiteProbeRestriction `
        -Failure ("-File ... -Suite 'Paths,Archive' мусить дати або вибір Paths;Archive з кодом 0, або відмову з кодом 1 " +
            "без виконання подальшого коду; код: $suiteProbeCommaExit")
}
& {
    # M1-M9: мапа "змінений файл -> suite" (Get-BRAVOSelfTestSuiteForChangedPath),
    # in-process. Порівняння точне (-ceq) за приєднаним через '|' результатом, а не
    # -contains: -contains не помічає зайвих елементів у результаті. Група фіксує
    # ПОТОЧНУ поведінку мапи; її розширення (Affected) оновлює ці тести свідомо.
    $suiteMapCatalog = @($script:BRAVOSelfTestSuiteCatalog)
    $suiteMapped = {
        param([string]$Path)
        return [string]::Join('|', @(Get-BRAVOSelfTestSuiteForChangedPath -Path $Path))
    }
    # Пари @(шлях, очікуваний результат); повертає опис розбіжностей.
    $suiteMapMismatch = {
        param([object[]]$Pairs)
        $mismatches = New-Object System.Collections.Generic.List[string]
        foreach ($pair in $Pairs) {
            $actual = & $suiteMapped ([string]$pair[0])
            if ($actual -cne [string]$pair[1]) {
                [void]$mismatches.Add("'" + [string]$pair[0] + "' -> '" + $actual + "' (очікувалось '" + [string]$pair[1] + "')")
            }
        }
        return @($mismatches.ToArray())
    }

    # M1. Кожен фрагмент каталогу відображається рівно на себе у відносних формах шляху
    # ('\', '/', '.\', './', верхній регістр). Абсолютні шляхи й шляхи з пробілами по
    # краях НЕ відображаються (VAL-05, ревізія 2.1): вхід не обрізається, а абсолютний
    # шлях не є точним шляхом від кореня репозиторію - підказка порожня, план дає V3.
    $suiteMapFragmentPairs = New-Object System.Collections.Generic.List[object]
    foreach ($suiteMapName in $suiteMapCatalog) {
        $suiteMapRel = 'selftest\BRAVO_SELF_TEST.' + $suiteMapName + '.ps1'
        foreach ($suiteMapForm in @(
                $suiteMapRel,
                $suiteMapRel.Replace('\', '/'),
                ('.\' + $suiteMapRel),
                ('./' + $suiteMapRel.Replace('\', '/')),
                $suiteMapRel.ToUpperInvariant())) {
            [void]$suiteMapFragmentPairs.Add(@($suiteMapForm, $suiteMapName))
        }
        foreach ($suiteMapForm in @(
                ('C:\work\repo\' + $suiteMapRel),
                ('/home/u/repo/' + $suiteMapRel.Replace('\', '/')),
                ('\\host-a\share\' + $suiteMapRel),
                ('  ' + $suiteMapRel + '  '),
                (' ' + $suiteMapRel),
                ($suiteMapRel + ' '))) {
            [void]$suiteMapFragmentPairs.Add(@($suiteMapForm, ''))
        }
    }
    $suiteMapProblems = @(& $suiteMapMismatch $suiteMapFragmentPairs.ToArray())
    Test-BRAVOCondition `
        -Condition ($suiteMapCatalog.Count -gt 0 -and $suiteMapProblems.Count -eq 0) `
        -Name "Framework/ChangedPathMap.FragmentsMapExactlyAndOnlyToThemselves" `
        -Failure ("фрагмент каталогу мусить відображатись рівно на однойменний suite (без зайвих елементів) у формах " +
            "'\', '/', '.\', './', верхній регістр; абсолютний шлях і пробіли по краях дають порожній результат: " +
            [string]::Join('; ', @($suiteMapProblems | Select-Object -First 5)))

    # M2. Фрагменти й файли поза каталогом не відображаються ні на що.
    $suiteMapProblems = @(& $suiteMapMismatch @(
            @('selftest\BRAVO_SELF_TEST.ManualLaunchers.ps1', ''),
            @('selftest\BRAVO_SELF_TEST.ConfigV2PilotArtifact.ps1', ''),
            @('selftest\BRAVO_SELF_TEST.NoSuch.ps1', ''),
            @('selftest\BRAVO_SELF_TEST.Paths.ps1.bak', ''),
            @('selftest\fixtures\BravoConfigLegacyFrozen.config', '')))
    Test-BRAVOCondition `
        -Condition ($suiteMapProblems.Count -eq 0) `
        -Name "Framework/ChangedPathMap.FragmentsOutsideCatalogMapToNothing" `
        -Failure ("фрагмент поза каталогом, суфікс після .ps1 і фікстури selftest мусять давати порожній результат: " +
            [string]::Join('; ', $suiteMapProblems))

    # M3. Таблиця модулів закріплена: ПОВНИЙ перелік каталогів modules\BRAVO.* і
    # відповідний suite для кожного. Новий модуль ламає тест і вимагає свідомого
    # рішення про мапу (станом на базу гілки: 23 модулі, 10 з suite).
    $suiteMapModuleSuites = @{
        'Archive'                = 'Archive'
        'BazaSync'               = 'BazaSync'
        'Configuration'          = 'Configuration'
        'Configurator'           = 'Configurator'
        'DataRestore'            = 'DataRestore'
        'DataRestore.MatrixTest' = 'DataRestore'
        'DiskSpace'              = 'DiskSpace'
        'Operations'             = 'Operations'
        'RestoreVerify'          = 'RestoreVerify'
        'Status'                 = 'Status'
    }
    $suiteMapModulesWithoutSuite = @('ArchiveHelpers', 'ArchiveRuntime', 'Compatibility', 'Console', 'Credentials',
        'Discovery', 'ExitCodes', 'Health', 'HelperLogging', 'Logging', 'Maintenance', 'Notifications', 'System')
    $suiteMapActualModules = [string[]]@(
        [IO.Directory]::GetDirectories((Join-Path $root 'modules')) |
            ForEach-Object { [IO.Path]::GetFileName($_) } |
            Where-Object { $_.StartsWith('BRAVO.', [StringComparison]::Ordinal) } |
            ForEach-Object { $_.Substring('BRAVO.'.Length) })
    [Array]::Sort($suiteMapActualModules, [StringComparer]::Ordinal)
    $suiteMapExpectedModules = [string[]]@(@($suiteMapModuleSuites.Keys) + $suiteMapModulesWithoutSuite)
    [Array]::Sort($suiteMapExpectedModules, [StringComparer]::Ordinal)
    $suiteMapModulePairs = New-Object System.Collections.Generic.List[object]
    foreach ($suiteMapModule in $suiteMapActualModules) {
        $suiteMapExpected = ''
        if ($suiteMapModuleSuites.ContainsKey($suiteMapModule)) { $suiteMapExpected = $suiteMapModuleSuites[$suiteMapModule] }
        [void]$suiteMapModulePairs.Add(@(('modules\BRAVO.' + $suiteMapModule + '\x.psm1'), $suiteMapExpected))
    }
    # Двійники імені модуля (повний сегмент каталогу, а не префікс) не відображаються.
    foreach ($suiteMapLookalike in @('modules\BRAVO.Archive.Legacy\x.psm1', 'modules\BRAVO.DiskSpace.Legacy\x.psm1',
            'modules\BRAVO.DataRestore.Legacy\x.psm1', 'modules\BRAVO.Status2\x.psm1')) {
        [void]$suiteMapModulePairs.Add(@($suiteMapLookalike, ''))
    }
    $suiteMapProblems = @(& $suiteMapMismatch $suiteMapModulePairs.ToArray())
    Test-BRAVOCondition `
        -Condition (
            $suiteMapActualModules.Count -gt 0 -and
            [string]::Join(',', $suiteMapActualModules) -ceq [string]::Join(',', $suiteMapExpectedModules) -and
            $suiteMapProblems.Count -eq 0
        ) `
        -Name "Framework/ChangedPathMap.ModuleTableIsPinned" `
        -Failure ("перелік модулів і мапа 'модуль -> suite' закріплені: новий або перейменований модуль потребує свідомого " +
            "рішення про мапу. Фактично: [" + [string]::Join(',', $suiteMapActualModules) + "]; розбіжності: [" +
            [string]::Join('; ', $suiteMapProblems) + "]")

    # M4. Модуль-префікс іншого імені не просочується; суміжні suite не підміняються.
    $suiteMapProblems = @(& $suiteMapMismatch @(
            @('modules\BRAVO.ArchiveHelpers\x.psm1', ''),
            @('modules\BRAVO.ArchiveRuntime\x.psm1', ''),
            @('modules\BRAVO.DiskSpace', ''),
            @('modules\BRAVO.DiskSpace\', ''),
            @('modules\BRAVO.DiskSpace\BRAVO.DiskSpace.psm1', 'DiskSpace'),
            @('modules\BRAVO.Archive\BRAVO.Archive.psm1', 'Archive')))
    Test-BRAVOCondition `
        -Condition ($suiteMapProblems.Count -eq 0) `
        -Name "Framework/ChangedPathMap.ModulePrefixDoesNotLeak" `
        -Failure ("ім'я модуля береться повним сегментом: ArchiveHelpers/ArchiveRuntime не відображаються на Archive, DiskSpace — " +
            "лише на DiskSpace, без залежних suite, а голий каталог модуля без кінцевого роздільника не відображається: " +
            [string]::Join('; ', $suiteMapProblems))

    # M5. Не-код і інфраструктура — порожній результат (= повний прогін). Це
    # поточний консервативний стан; правила для цих класів додає Affected.
    $suiteMapUnmapped = @('BRAVO_ARCHIV.ps1', 'BRAVO_HEALTH.ps1', 'BRAVO_SELF_TEST.ps1', 'README.md', 'CHANGELOG.md',
        'docs\design\BRAVO_VALIDATION_ARCHITECTURE.md', '.github\workflows\ci.yml', 'ci\Update-BRAVORuntimeManifest.ps1',
        'deploy\Install-BRAVOServer.ps1', 'Tools\TOOLS_MANIFEST.json', 'RUNTIME_MANIFEST.json', 'VERSION.json',
        'BRAVO.local.config.example', 'PSScriptAnalyzerSettings.psd1')
    $suiteMapProblems = @(& $suiteMapMismatch @($suiteMapUnmapped | ForEach-Object { , @($_, '') }))
    Test-BRAVOCondition `
        -Condition ($suiteMapProblems.Count -eq 0) `
        -Name "Framework/ChangedPathMap.NonCodeAndInfraPathsMapToNothing" `
        -Failure ("точки входу, документи, workflow, ci/deploy/Tools, маніфести й конфігурація мусять давати порожній " +
            "результат: " + [string]::Join('; ', $suiteMapProblems))

    # M6. Порожній вхід не повертає suite. Для $null допустимі рівно два
    # результати (Mandatory + AllowEmptyString + коерція [string], точна поведінка
    # залежить від runtime): виняток прив'язки або порожній результат.
    $suiteMapProblems = @(& $suiteMapMismatch @(@('', ''), @('   ', '')))
    $suiteMapNullThrew = $false
    $suiteMapNullResult = @()
    try {
        $suiteMapNullResult = @(Get-BRAVOSelfTestSuiteForChangedPath -Path $null)
    } catch {
        $suiteMapNullThrew = $true
    }
    Test-BRAVOCondition `
        -Condition ($suiteMapProblems.Count -eq 0 -and ($suiteMapNullThrew -or $suiteMapNullResult.Count -eq 0)) `
        -Name "Framework/ChangedPathMap.EmptyAndNullInputNeverReturnsSuite" `
        -Failure ("порожній і пробільний шлях мусять давати порожній результат, а `$null — виняток прив'язки або порожній " +
            "результат, але не suite. Розбіжності: [" + [string]::Join('; ', $suiteMapProblems) + "]; `$null повернув: " +
            [string]::Join(',', @($suiteMapNullResult)))

    # M7. Форма результату: без @(...) порожній результат — $null, а один збіг —
    # скалярний [string]. Майбутній union мусить обгортати виклик у @(...).
    $suiteMapShapeEmpty = Get-BRAVOSelfTestSuiteForChangedPath -Path 'README.md'
    $suiteMapShapeKnown = Get-BRAVOSelfTestSuiteForChangedPath -Path 'selftest\BRAVO_SELF_TEST.Paths.ps1'
    Test-BRAVOCondition `
        -Condition (
            $null -eq $suiteMapShapeEmpty -and
            $suiteMapShapeKnown -is [string] -and
            $suiteMapShapeKnown -isnot [array] -and
            @($suiteMapShapeEmpty).Count -eq 0 -and
            @($suiteMapShapeKnown).Count -eq 1
        ) `
        -Name "Framework/ChangedPathMap.ResultShapeNeedsArrayWrapping" `
        -Failure ("результат мапи розгортається конвеєром: нуль збігів -> `$null, один збіг -> скаляр [string]; викликач мусить " +
            "обгортати його в @(...). Порожній: " + $(if ($null -eq $suiteMapShapeEmpty) { '$null' } else { $suiteMapShapeEmpty.GetType().Name }) +
            "; один збіг: " + $(if ($null -eq $suiteMapShapeKnown) { '$null' } else { $suiteMapShapeKnown.GetType().Name }))

    # M8. Для кожного реального файлу під modules\ і selftest\: не більше одного
    # suite, і це ім'я з каталогу.
    $suiteMapRootFull = [IO.Path]::GetFullPath($root).TrimEnd('\', '/')
    $suiteMapFiles = New-Object System.Collections.Generic.List[string]
    foreach ($suiteMapDirName in @('modules', 'selftest')) {
        $suiteMapDirFull = [IO.Path]::GetFullPath((Join-Path $root $suiteMapDirName))
        foreach ($suiteMapFile in [IO.Directory]::GetFiles($suiteMapDirFull, '*', [IO.SearchOption]::AllDirectories)) {
            [void]$suiteMapFiles.Add($suiteMapFile.Substring($suiteMapRootFull.Length).TrimStart('\', '/').Replace('/', '\'))
        }
    }
    $suiteMapShapeProblems = New-Object System.Collections.Generic.List[string]
    foreach ($suiteMapRelFile in $suiteMapFiles) {
        $suiteMapResult = @(Get-BRAVOSelfTestSuiteForChangedPath -Path $suiteMapRelFile)
        if ($suiteMapResult.Count -gt 1) {
            [void]$suiteMapShapeProblems.Add("$suiteMapRelFile -> [" + [string]::Join(',', $suiteMapResult) + "]")
        }
        foreach ($suiteMapResultItem in $suiteMapResult) {
            if ($suiteMapCatalog -cnotcontains [string]$suiteMapResultItem) {
                [void]$suiteMapShapeProblems.Add("$suiteMapRelFile -> '$suiteMapResultItem' не з каталогу")
            }
        }
    }
    Test-BRAVOCondition `
        -Condition ($suiteMapFiles.Count -gt 0 -and $suiteMapShapeProblems.Count -eq 0) `
        -Name "Framework/ChangedPathMap.NeverReturnsMoreThanOneSuiteOrUnknownName" `
        -Failure ("мапа мусить повертати для файлу не більше одного suite і лише ім'я з каталогу; перевірено файлів: " +
            "$($suiteMapFiles.Count); проблеми: [" + [string]::Join('; ', @($suiteMapShapeProblems | Select-Object -First 5)) + "]")

    # M9. Обидва правила (фрагмент і модуль) прив'язані до початку шляху: двійники префікса
    # (xselftest\..., docs\selftest\...) і абсолютні шляхи дають порожньо. Провідний './'
    # зрізається однаково для обох правил (тому ./modules/BRAVO.Archive/x дає Archive).
    $suiteMapProblems = @(& $suiteMapMismatch @(
            @('xselftest\BRAVO_SELF_TEST.Paths.ps1', ''),
            @('docs\selftest\BRAVO_SELF_TEST.Paths.ps1', ''),
            @('xmodules\BRAVO.Archive\x', ''),
            @('docs\modules\BRAVO.Archive\x', ''),
            @('./modules/BRAVO.Archive/x', 'Archive'),
            @('C:\repo\modules\BRAVO.Archive\x', '')))
    Test-BRAVOCondition `
        -Condition ($suiteMapProblems.Count -eq 0) `
        -Name "Framework/ChangedPathMap.RulesAreAnchoredAtPathStart" `
        -Failure ("правила фрагмента й модуля мусять бути прив'язані до початку шляху (двійники префікса й абсолютні шляхи дають " +
            "порожньо; провідний './' зрізається): " + [string]::Join('; ', $suiteMapProblems))

    # M10. Некоректні форми шляху не відображаються ні на що, навіть якщо після обрізання чи
    # нормалізації збіглися б з фрагментом або модулем (обхід каталогів, порожні й '.'-сегменти,
    # пробіли та керувальні символи, UNC, кінцевий роздільник у фрагменті).
    $suiteMapProblems = @(& $suiteMapMismatch @(
            @('selftest\..\selftest\BRAVO_SELF_TEST.Paths.ps1', ''),
            @('docs/../selftest/BRAVO_SELF_TEST.Paths.ps1', ''),
            @('selftest\.\BRAVO_SELF_TEST.Paths.ps1', ''),
            @('selftest\\BRAVO_SELF_TEST.Paths.ps1', ''),
            @('selftest\BRAVO_SELF_TEST.Paths.ps1\', ''),
            @('modules\..\modules\BRAVO.Archive\x', ''),
            @('modules\BRAVO.Archive\..\BRAVO.Archive\x', ''),
            @("selftest\BRAVO_SELF_TEST.Paths.ps1`n", ''),
            @("`tselftest\BRAVO_SELF_TEST.Paths.ps1", ''),
            @(('selftest\BRAVO_SELF_TEST.Paths' + [string][char]1 + '.ps1'), ''),
            @('\selftest\BRAVO_SELF_TEST.Paths.ps1', ''),
            @('..\selftest\BRAVO_SELF_TEST.Paths.ps1', '')))
    Test-BRAVOCondition `
        -Condition ($suiteMapProblems.Count -eq 0) `
        -Name "Framework/ChangedPathMap.InvalidPathFormsMapToNothing" `
        -Failure ("шлях з '..', порожнім чи '.'-сегментом, пробілами або керувальними символами по краях/всередині, абсолютний чи " +
            "UNC мусить давати порожній результат: " + [string]::Join('; ', $suiteMapProblems))
}
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Framework.SuiteSelectionContract' } }

if (Enter-BRAVOSelfTestSection -Name 'Tail/Framework.AffectedPlan') { try {

# ============================================================
# VAL-05 (Affected), PR1: мапа шляхів і консервативний класифікатор.
#
# Канонічний власник - selftest\BRAVOSelfTestSuiteMap.ps1 (каталог -Suite,
# підказка "шлях -> suite", план Affected). Секція перевіряє ЧИСТІ функції
# in-process, без git і без дочірніх процесів. Інваріанти:
#   * клас лише V1/V2/V3, V0 не видається ніколи (рішення P1-B);
#   * невідомий або змішаний вхід -> V3 і Suite = @() (запускати лише відомі
#     suite небезпечно);
#   * RUNTIME_MANIFEST.json - похідний супутник, а не підстава для V3, але
#     лише за доведеної дельти (мінімум V2 завжди);
#   * leaf-модулі V2 стереже статичний guard вхідних ребер.
# Змінні лишаються в межах & { }: нічого нового не читається коренем.
# ============================================================
& {
    $affMapPath = Join-Path $root 'selftest\BRAVOSelfTestSuiteMap.ps1'
    $affCatalog = @($script:BRAVOSelfTestSuiteCatalog)
    $affMismatch = New-Object System.Collections.Generic.List[string]
    $affSeenClass = New-Object System.Collections.Generic.List[string]

    # --- Допоміжні конструкції -------------------------------------------
    $affManifestText = {
        param([System.Collections.IDictionary]$Files, [string]$Description = 'desc', [bool]$Compress = $false)
        $manifestDocument = [ordered]@{
            schemaVersion   = 1
            description     = $Description
            updateProcedure = 'proc'
            files           = $Files
        }
        return (ConvertTo-Json -InputObject $manifestDocument -Depth 4 -Compress:$Compress)
    }
    $affBaseFiles = [ordered]@{
        'BRAVO_ARCHIV.ps1'                         = 'A1'
        'BRAVO_HEALTH.ps1'                         = 'A2'
        'selftest\BRAVO_SELF_TEST.Archive.ps1'     = 'A3'
        'selftest\BRAVO_SELF_TEST.Governance.ps1'  = 'A4'
        'selftest\BRAVO_SELF_TEST.Paths.ps1'       = 'A5'
    }
    # План із супутнім маніфестом: Delta - зміни записів files ($null = запис видалено).
    $affPlanWithManifest = {
        param([string[]]$Paths, [hashtable]$Delta, [string[]]$Deleted = @(), [string]$Description = 'desc')
        $baseText = & $affManifestText $affBaseFiles 'desc'
        $currentFiles = [ordered]@{}
        foreach ($baseKey in @($affBaseFiles.Keys)) { $currentFiles[$baseKey] = $affBaseFiles[$baseKey] }
        foreach ($deltaKey in @($Delta.Keys)) {
            if ($null -eq $Delta[$deltaKey]) { $currentFiles.Remove($deltaKey) } else { $currentFiles[$deltaKey] = $Delta[$deltaKey] }
        }
        $currentText = & $affManifestText $currentFiles $Description
        $changed = @($Paths) + @('RUNTIME_MANIFEST.json')
        $companion = Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $baseText -CurrentText $currentText -ChangedPath $changed
        return (Get-BRAVOSelfTestAffectedPlan -ChangedPath $changed -DeletedPath $Deleted -RuntimeManifestCompanion $companion)
    }
    $affPlanPlain = {
        param([string[]]$Paths, [string[]]$Deleted = @())
        return (Get-BRAVOSelfTestAffectedPlan -ChangedPath $Paths -DeletedPath $Deleted)
    }
    $affSignature = {
        param($Plan)
        return ([string]$Plan.Class + '|' + [string]::Join(',', @($Plan.Suite)))
    }
    $affExpect = {
        param([string]$Id, $Plan, [string]$Expected)
        [void]$affSeenClass.Add([string]$Plan.Class)
        $actual = & $affSignature $Plan
        if ($actual -cne $Expected) { [void]$affMismatch.Add($Id + ": '" + $actual + "' (очікувалось '" + $Expected + "')") }
    }
    $affExpectGate = {
        param([string]$Id, $Plan, [string]$Expected)
        $actual = [string]::Join(',', @($Plan.RequiredGate))
        if ($actual -cne $Expected) { [void]$affMismatch.Add($Id + ": gate '" + $actual + "' (очікувалось '" + $Expected + "')") }
    }
    $affTakeMismatch = {
        $taken = [string]::Join('; ', @($affMismatch.ToArray() | Select-Object -First 6))
        $affMismatch.Clear()
        return $taken
    }

    $affPaths = 'selftest\BRAVO_SELF_TEST.Paths.ps1'
    $affArchive = 'selftest\BRAVO_SELF_TEST.Archive.ps1'
    $affGovernance = 'selftest\BRAVO_SELF_TEST.Governance.ps1'

    # --- B1-B4, B29-B31: відомі фрагменти + супутній маніфест -> V2 ------
    & $affExpect 'B1 KnownSingle' (& $affPlanWithManifest @($affPaths) @{ $affPaths = 'N1' }) 'V2|Governance,Paths'
    & $affExpect 'B2 KnownMultipleSameSuite' (& $affPlanWithManifest @($affGovernance, 'SECURITY.md') @{ $affGovernance = 'N1' }) 'V2|Governance'
    & $affExpect 'B3 KnownMultipleSuites' (& $affPlanWithManifest @($affPaths, $affArchive) @{ $affPaths = 'N1'; $affArchive = 'N2' }) 'V2|Archive,Governance,Paths'
    & $affExpect 'B4 DuplicatePaths' (& $affPlanWithManifest @('selftest/BRAVO_SELF_TEST.Paths.ps1', $affPaths, 'selftest/BRAVO_SELF_TEST.Paths.ps1') @{ $affPaths = 'N1' }) 'V2|Governance,Paths'
    & $affExpect 'B29 CaseVariant' (& $affPlanWithManifest @('SELFTEST/bravo_self_test.PATHS.ps1') @{ $affPaths = 'N1' }) 'V2|Governance,Paths'
    & $affExpect 'B30 SlashVsBackslash' (& $affPlanWithManifest @('selftest/BRAVO_SELF_TEST.Archive.ps1') @{ $affArchive = 'N1' }) 'V2|Archive,Governance'
    & $affExpect 'B31 DotPrefix' (& $affPlanWithManifest @('./selftest/BRAVO_SELF_TEST.Paths.ps1', '.\selftest\BRAVO_SELF_TEST.Archive.ps1') @{ $affPaths = 'N1'; $affArchive = 'N2' }) 'V2|Archive,Governance,Paths'
    & $affExpect 'B3a RealisticCodePR' (& $affPlanWithManifest @($affPaths, 'CHANGELOG.md') @{ $affPaths = 'N1' }) 'V2|Governance,Paths'
    & $affExpectGate 'B3a gate' (& $affPlanWithManifest @($affPaths, 'CHANGELOG.md') @{ $affPaths = 'N1' }) 'Integrity manifests are current,Release policy'
    & $affExpect 'B47 MixedDocAndFragment' (& $affPlanWithManifest @('README.md', $affPaths) @{ $affPaths = 'N1' }) 'V2|Governance,Paths'
    & $affExpectGate 'B47 gate' (& $affPlanWithManifest @('README.md', $affPaths) @{ $affPaths = 'N1' }) 'Integrity manifests are current,Release policy'
    & $affExpect 'FragmentWithoutManifestIsStillV2' (& $affPlanPlain @($affPaths)) 'V2|Governance,Paths'
    $affProblem = & $affTakeMismatch
    Test-BRAVOCondition `
        -Condition ($affProblem.Length -eq 0) `
        -Name "Framework/AffectedPlan.KnownFragmentsPlanV2WithGovernance" `
        -Failure ("фрагменти каталогу з супутнім маніфестом (з CHANGELOG.md чи документом таблиці також) мусять давати V2 з union за порядком каталогу, Governance і gate-підказками: " + $affProblem)

    # --- B3a, B47 і мінімум V2 для маніфеста (ревізія 2.1) ---------------
    $affReformatBase = & $affManifestText $affBaseFiles 'desc' $false
    $affReformatCurrent = & $affManifestText ([ordered]@{
            'selftest\BRAVO_SELF_TEST.Paths.ps1'      = 'A5'
            'selftest\BRAVO_SELF_TEST.Governance.ps1' = 'A4'
            'selftest\BRAVO_SELF_TEST.Archive.ps1'    = 'A3'
            'BRAVO_HEALTH.ps1'                        = 'A2'
            'BRAVO_ARCHIV.ps1'                        = 'A1'
        }) 'desc' $true
    $affReformatCompanion = Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affReformatBase -CurrentText $affReformatCurrent `
        -ChangedPath @('README.md', 'RUNTIME_MANIFEST.json')
    $affReformatPlan = Get-BRAVOSelfTestAffectedPlan -ChangedPath @('README.md', 'RUNTIME_MANIFEST.json') -RuntimeManifestCompanion $affReformatCompanion
    & $affExpect '2.1 README+ReformattedManifest' $affReformatPlan 'V2|Governance'
    Test-BRAVOCondition `
        -Condition ($affMismatch.Count -eq 0 -and $affReformatCompanion.IsCompanion -and @($affReformatCompanion.OutsideEntry).Count -eq 0) `
        -Name "Framework/AffectedPlan.ManifestCompanionGivesAtLeastV2" `
        -Failure ("супутній маніфест (навіть переформатований, з порожньою дельтою) дає щонайменше V2, а документ із таблиці " +
            "разом із ним не лишається V1: " + [string]::Join('; ', @($affMismatch.ToArray())) + "; супутник: " + $affReformatCompanion.Reason)
    $affMismatch.Clear()

    # --- B3b-B3e: маніфест, що НЕ є супутником -> V3 ---------------------
    & $affExpect 'B3b ManifestExtraEntry' (& $affPlanWithManifest @($affPaths) @{ $affPaths = 'N1'; 'BRAVO_ARCHIV.ps1' = 'N9' }) 'V3|'
    & $affExpect 'B3b ManifestRemovedEntry' (& $affPlanWithManifest @($affPaths) @{ $affPaths = 'N1'; 'BRAVO_HEALTH.ps1' = $null }) 'V3|'
    & $affExpect 'B3b ManifestAddedEntry' (& $affPlanWithManifest @($affPaths) @{ $affPaths = 'N1'; 'ci\Extra.ps1' = 'N9' }) 'V3|'
    & $affExpect 'B3c ManifestNonHashField' (& $affPlanWithManifest @($affPaths) @{ $affPaths = 'N1' } @() 'changed description') 'V3|'
    & $affExpect 'B3d ManifestOnly' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @('RUNTIME_MANIFEST.json') -RuntimeManifestCompanion (
            Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affReformatBase -CurrentText $affReformatCurrent -ChangedPath @('RUNTIME_MANIFEST.json'))) 'V3|'
    & $affExpect 'B3e ManifestBaseMissing' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affPaths, 'RUNTIME_MANIFEST.json') -RuntimeManifestCompanion (
            Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $null -CurrentText $affReformatCurrent -ChangedPath @($affPaths, 'RUNTIME_MANIFEST.json'))) 'V3|'
    & $affExpect 'B3e ManifestUnparsable' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affPaths, 'RUNTIME_MANIFEST.json') -RuntimeManifestCompanion (
            Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affReformatBase -CurrentText '{ not json' -ChangedPath @($affPaths, 'RUNTIME_MANIFEST.json'))) 'V3|'
    & $affExpect 'B3e NoCompanionObject' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affPaths, 'RUNTIME_MANIFEST.json')) 'V3|'
    & $affExpect 'ManifestDeleted' (& $affPlanWithManifest @($affPaths) @{ $affPaths = 'N1' } @('RUNTIME_MANIFEST.json')) 'V3|'
    $affProblem = & $affTakeMismatch
    Test-BRAVOCondition `
        -Condition ($affProblem.Length -eq 0) `
        -Name "Framework/AffectedPlan.ManifestWithoutProvenCompanionEscalatesToV3" `
        -Failure ("маніфест із записом поза ChangedPath, зміненим не-хеш полем, без змісту, без бази, з некоректним JSON, без об'єкта супутника чи видалений мусить давати V3 і Suite = @(): " + $affProblem)

    # --- Функція супутника маніфесту: пряма перевірка ---------------------
    $affCompanionCases = New-Object System.Collections.Generic.List[string]
    $affBaseJson = & $affManifestText $affBaseFiles 'desc' $false
    $affChangedOne = @('selftest/bravo_self_test.paths.ps1', 'RUNTIME_MANIFEST.json')
    $affOneDelta = [ordered]@{}
    foreach ($affKey in @($affBaseFiles.Keys)) { $affOneDelta[$affKey] = $affBaseFiles[$affKey] }
    $affOneDelta['selftest\BRAVO_SELF_TEST.Paths.ps1'] = 'N1'
    $affOneDeltaJson = & $affManifestText $affOneDelta 'desc' $false
    $affResult = Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affBaseJson -CurrentText $affOneDeltaJson -ChangedPath $affChangedOne
    if (-not $affResult.IsCompanion) { [void]$affCompanionCases.Add('регістр і роздільник ключів мусять нормалізуватись: ' + $affResult.Reason) }
    $affResult = Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affBaseJson -CurrentText $affOneDeltaJson -ChangedPath @('RUNTIME_MANIFEST.json')
    if ($affResult.IsCompanion -or [string]::Join(',', @($affResult.OutsideEntry)) -cne 'selftest/BRAVO_SELF_TEST.Paths.ps1') {
        [void]$affCompanionCases.Add('запис поза ChangedPath мусить бути названий у OutsideEntry: ' + [string]::Join(',', @($affResult.OutsideEntry)))
    }
    $affRemovedFiles = [ordered]@{}
    foreach ($affKey in @($affBaseFiles.Keys)) { if ($affKey -cne 'BRAVO_HEALTH.ps1') { $affRemovedFiles[$affKey] = $affBaseFiles[$affKey] } }
    $affRemovedJson = & $affManifestText $affRemovedFiles 'desc' $false
    $affResult = Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affBaseJson -CurrentText $affRemovedJson -ChangedPath @('BRAVO_HEALTH.ps1')
    if (-not $affResult.IsCompanion) { [void]$affCompanionCases.Add('видалений запис, названий у ChangedPath, мусить бути супутником: ' + $affResult.Reason) }
    $affResult = Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affBaseJson -CurrentText $affRemovedJson -ChangedPath @('BRAVO_ARCHIV.ps1')
    if ($affResult.IsCompanion) { [void]$affCompanionCases.Add('видалений запис поза ChangedPath не може бути супутником') }
    $affFilesJson = ConvertTo-Json -InputObject $affBaseFiles -Compress
    $affSchemaJson = '{"schemaVersion":2,"description":"desc","updateProcedure":"proc","files":' + $affFilesJson + '}'
    $affProcedureJson = '{"schemaVersion":1,"description":"desc","updateProcedure":"other","files":' + $affFilesJson + '}'
    $affExtraFieldJson = '{"schemaVersion":1,"description":"desc","updateProcedure":"proc","files":' + $affFilesJson + ',"extra":1}'
    foreach ($affVariant in @(
            @('schemaVersion', $affSchemaJson), @('updateProcedure', $affProcedureJson), @('додаткове поле верхнього рівня', $affExtraFieldJson),
            @('порожній текст', ''), @('пробіли', '   '), @('масив у корені', '[1,2]'), @('files не об''єкт', '{"schemaVersion":1,"description":"desc","updateProcedure":"proc","files":[1]}'))) {
        $affResult = Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affBaseJson -CurrentText $affVariant[1] -ChangedPath @($affPaths, 'RUNTIME_MANIFEST.json')
        if ($affResult.IsCompanion) { [void]$affCompanionCases.Add('варіант не може бути супутником: ' + $affVariant[0]) }
    }
    $affResult = Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affBaseJson -CurrentText $affBaseJson -ChangedPath @('RUNTIME_MANIFEST.json')
    if (-not $affResult.IsCompanion -or @($affResult.OutsideEntry).Count -ne 0) { [void]$affCompanionCases.Add('ідентичні тексти (порожня дельта) мусять бути супутником') }
    Test-BRAVOCondition `
        -Condition ($affCompanionCases.Count -eq 0) `
        -Name "Framework/AffectedPlan.ManifestCompanionFunctionIsStrict" `
        -Failure ("Test-BRAVOSelfTestRuntimeManifestCompanion: " + [string]::Join('; ', @($affCompanionCases.ToArray())))

    # --- B5, B6, B19-B26: невідомі й змішані шляхи -> V3 ------------------
    $affManifestOnlyArchive = @{ 'BRAVO_ARCHIV.ps1' = 'N1' }
    & $affExpect 'B5 UnknownSingle' (& $affPlanWithManifest @('BRAVO_ARCHIV.ps1') $affManifestOnlyArchive) 'V3|'
    & $affExpect 'B6 KnownPlusUnknown' (& $affPlanWithManifest @($affPaths, 'ci/Update-BRAVORuntimeManifest.ps1') @{ $affPaths = 'N1'; 'ci\Update-BRAVORuntimeManifest.ps1' = 'N2' }) 'V3|'
    & $affExpect 'B19 RootEntrypoint' (& $affPlanWithManifest @('BRAVO_HEALTH.ps1') @{ 'BRAVO_HEALTH.ps1' = 'N1' }) 'V3|'
    & $affExpect 'B19 RuntimeGuard' (& $affPlanWithManifest @('BRAVO_RUNTIME_GUARD.ps1') @{ 'BRAVO_RUNTIME_GUARD.ps1' = 'N1' }) 'V3|'
    & $affExpect 'B20 ModuleNoSuite' (& $affPlanWithManifest @('modules/BRAVO.Console/BRAVO.Console.psm1') @{ 'modules\BRAVO.Console\BRAVO.Console.psm1' = 'N1' }) 'V3|'
    & $affExpect 'B20a ConfigurationModule' (& $affPlanWithManifest @('modules/BRAVO.Configuration/BRAVO.Configuration.psm1') @{ 'modules\BRAVO.Configuration\BRAVO.Configuration.psm1' = 'N1' }) 'V3|'
    & $affExpect 'B20b DiskSpaceModule' (& $affPlanWithManifest @('modules/BRAVO.DiskSpace/BRAVO.DiskSpace.psm1') @{ 'modules\BRAVO.DiskSpace\BRAVO.DiskSpace.psm1' = 'N1' }) 'V3|'
    & $affExpect 'B20b ArchiveModule' (& $affPlanWithManifest @('modules/BRAVO.Archive/BRAVO.Archive.psm1') @{ 'modules\BRAVO.Archive\BRAVO.Archive.psm1' = 'N1' }) 'V3|'
    & $affExpect 'B20d MatrixTestModule' (& $affPlanWithManifest @('modules/BRAVO.DataRestore.MatrixTest/x.psm1') @{ 'modules\BRAVO.DataRestore.MatrixTest\x.psm1' = 'N1' }) 'V3|'
    & $affExpect 'B20e ModuleNameLookalike' (& $affPlanPlain @('modules/BRAVO.Archive.Legacy/x')) 'V3|'
    & $affExpect 'B20e ModuleDirWithoutFile' (& $affPlanPlain @('modules/BRAVO.Archive')) 'V3|'
    & $affExpect 'B21 SelfTest' (& $affPlanWithManifest @('BRAVO_SELF_TEST.ps1') @{ 'BRAVO_SELF_TEST.ps1' = 'N1' }) 'V3|'
    & $affExpect 'B21 MapFile' (& $affPlanWithManifest @('selftest/BRAVOSelfTestSuiteMap.ps1') @{ 'selftest\BRAVOSelfTestSuiteMap.ps1' = 'N1' }) 'V3|'
    & $affExpect 'B21 ManualLaunchers' (& $affPlanWithManifest @('selftest/BRAVO_SELF_TEST.ManualLaunchers.ps1') @{ 'selftest\BRAVO_SELF_TEST.ManualLaunchers.ps1' = 'N1' }) 'V3|'
    & $affExpect 'B21 ConfigV2PilotArtifact' (& $affPlanPlain @('selftest/BRAVO_SELF_TEST.ConfigV2PilotArtifact.ps1')) 'V3|'
    & $affExpect 'B21 Fixture' (& $affPlanPlain @('selftest/fixtures/BravoConfigLegacyFrozen.config')) 'V3|'
    & $affExpect 'B22 Config' (& $affPlanPlain @('BRAVO.local.config.example')) 'V3|'
    & $affExpect 'B23 Schema' (& $affPlanWithManifest @('modules/BRAVO.Configuration/BRAVO.Configuration.Schema.psm1') @{ 'modules\BRAVO.Configuration\BRAVO.Configuration.Schema.psm1' = 'N1' }) 'V3|'
    & $affExpect 'B24 Workflow' (& $affPlanPlain @('.github/workflows/ci.yml')) 'V3|'
    & $affExpect 'B25 ToolsManifest' (& $affPlanPlain @('Tools/TOOLS_MANIFEST.json')) 'V3|'
    & $affExpect 'B26 VERSION' (& $affPlanPlain @('VERSION.json')) 'V3|'
    & $affExpect 'ToolsDirectory' (& $affPlanPlain @('Tools/WinSCP/WinSCP.com')) 'V3|'
    & $affExpect 'ClaudeDirectory' (& $affPlanPlain @('.claude/rules/05-architecture.md')) 'V3|'
    & $affExpect 'DeployScript' (& $affPlanPlain @('deploy/Install-BRAVOServer.ps1')) 'V3|'
    & $affExpect 'FragmentBackupFile' (& $affPlanPlain @('selftest/BRAVO_SELF_TEST.Paths.ps1.bak')) 'V3|'
    & $affExpect 'UnknownFragmentName' (& $affPlanPlain @('selftest/BRAVO_SELF_TEST.NoSuch.ps1')) 'V3|'
    $affProblem = & $affTakeMismatch
    Test-BRAVOCondition `
        -Condition ($affProblem.Length -eq 0) `
        -Name "Framework/AffectedPlan.UnknownAndInfrastructurePathsEscalateToV3" `
        -Failure ("entrypoint-и, модулі без leaf-статусу (зокрема Configuration, DiskSpace, Archive, MatrixTest, двійник імені), harness, " +
            "фікстури, конфіг, workflow, Tools, VERSION та змішані набори мусять давати V3 і Suite = @(): " + $affProblem)

    # Змішаний набір: Paths не повертається, невідомий шлях названо.
    $affMixed = & $affPlanWithManifest @($affPaths, 'ci/Update-BRAVORuntimeManifest.ps1') @{ $affPaths = 'N1'; 'ci\Update-BRAVORuntimeManifest.ps1' = 'N2' }
    Test-BRAVOCondition `
        -Condition (
            $affMixed.Class -ceq 'V3' -and @($affMixed.Suite).Count -eq 0 -and
            [string]::Join(',', @($affMixed.UnknownPath)) -ceq 'ci/Update-BRAVORuntimeManifest.ps1' -and
            $affMixed.RequiresIndependentReview -eq $true
        ) `
        -Name "Framework/AffectedPlan.MixedKnownAndUnknownNeverNarrows" `
        -Failure ("відомий + невідомий шлях: V3, порожній Suite, невідомий шлях названо, потрібне незалежне рев'ю. Фактично: " +
            $affMixed.Class + "|" + [string]::Join(',', @($affMixed.Suite)) + "|" + [string]::Join(',', @($affMixed.UnknownPath)))

    # --- B9a: видалення -------------------------------------------------
    & $affExpect 'B9a DeletedFragment' (& $affPlanWithManifest @($affPaths) @{ $affPaths = $null } @($affPaths)) 'V3|'
    & $affExpect 'B9a DeletedFragmentOnly' (& $affPlanPlain @($affPaths) @($affPaths)) 'V3|'
    & $affExpect 'B9a DeletedOtherFragmentAlongsideChange' (& $affPlanWithManifest @($affPaths, $affArchive) @{ $affPaths = 'N1'; $affArchive = $null } @($affArchive)) 'V3|'
    & $affExpect 'B9a DeletedConsumedDoc' (& $affPlanPlain @('README.md') @('README.md')) 'V3|'
    & $affExpect 'B9a DeletedOnlyEntryNotInChanged' (& $affPlanPlain @('README.md') @($affPaths)) 'V3|'
    $affProblem = & $affTakeMismatch
    Test-BRAVOCondition `
        -Condition ($affProblem.Length -eq 0) `
        -Name "Framework/AffectedPlan.DeletedKnownPathEscalatesToV3" `
        -Failure ("видалений фрагмент каталогу (і видалений документ із таблиці) мусить давати V3: " + $affProblem)

    # --- B11, B12: документи ---------------------------------------------
    & $affExpect 'B11 README' (& $affPlanPlain @('README.md')) 'V1|Governance'
    & $affExpect 'B11 OPERATIONS' (& $affPlanPlain @('OPERATIONS.md')) 'V1|DataRestore,Governance'
    & $affExpect 'B11 BRAVO_SETUP' (& $affPlanPlain @('BRAVO_SETUP.md')) 'V1|ConfigLoader,Governance'
    & $affExpect 'B11 CHANGELOG' (& $affPlanPlain @('CHANGELOG.md')) 'V1|Governance'
    & $affExpect 'B11 deploy README' (& $affPlanPlain @('deploy/README.md')) 'V1|Governance'
    & $affExpect 'B11 all documents' (& $affPlanPlain @('README.md', 'OPERATIONS.md', 'BRAVO_SETUP.md', 'CHANGELOG.md', 'SECURITY.md', 'RELEASE_CHECKLIST.md', 'RELEASE_POLICY.md', 'THREAT_MODEL.md', 'PROJECT.md')) 'V1|ConfigLoader,DataRestore,Governance'
    & $affExpectGate 'B11 README gate' (& $affPlanPlain @('README.md')) 'Release policy'
    & $affExpectGate 'B11 OPERATIONS gate' (& $affPlanPlain @('OPERATIONS.md')) ''
    & $affExpectGate 'B11 BRAVO_SETUP gate' (& $affPlanPlain @('BRAVO_SETUP.md')) 'Release policy'
    & $affExpectGate 'B11 CHANGELOG gate' (& $affPlanPlain @('CHANGELOG.md')) 'Release policy'
    & $affExpect 'B12 docs outside table 1' (& $affPlanPlain @('docs/BRAVO_HEALTH_FUTURE_MONITORING_DESIGN.md')) 'V3|'
    & $affExpect 'B12 docs outside table 2' (& $affPlanPlain @('docs/design/BRAVO_VALIDATION_ARCHITECTURE.md')) 'V3|'
    & $affExpect 'B12 docs outside table 3' (& $affPlanPlain @('ROADMAP.md')) 'V3|'
    & $affExpect 'B12 docs outside table 4' (& $affPlanPlain @('docs/../README.md')) 'V3|'
    & $affExpect 'B12 doc plus table doc' (& $affPlanPlain @('README.md', 'docs/x.md')) 'V3|'
    $affProblem = & $affTakeMismatch
    Test-BRAVOCondition `
        -Condition ($affProblem.Length -eq 0) `
        -Name "Framework/AffectedPlan.ConsumedDocumentsAreV1AndOthersV3" `
        -Failure ("документи з таблиці споживаних мають клас V1 із своїми споживачами й gate, будь-який інший *.md (зокрема docs\**) - V3: " + $affProblem)

    # --- B20c: leaf-модуль - лише синтетично -----------------------------
    $affLeafTable = @{ 'Leaf' = @{ Owner = 'Paths'; Dependents = @('Status') } }
    $affLeafPath = 'modules/BRAVO.Leaf/BRAVO.Leaf.psm1'
    $affLeafCompanion = Test-BRAVOSelfTestRuntimeManifestCompanion `
        -BaseText (& $affManifestText ([ordered]@{ 'modules\BRAVO.Leaf\BRAVO.Leaf.psm1' = 'L1' }) 'desc' $false) `
        -CurrentText (& $affManifestText ([ordered]@{ 'modules\BRAVO.Leaf\BRAVO.Leaf.psm1' = 'L2' }) 'desc' $false) `
        -ChangedPath @($affLeafPath, 'RUNTIME_MANIFEST.json')
    & $affExpect 'B20c LeafModuleSynthetic' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affLeafPath, 'RUNTIME_MANIFEST.json') `
            -RuntimeManifestCompanion $affLeafCompanion -LeafModuleTable $affLeafTable) 'V2|Governance,Paths,Status'
    & $affExpect 'B20c LeafWithoutTable' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affLeafPath)) 'V3|'
    & $affExpect 'B20c LeafPlusUnknown' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affLeafPath, 'BRAVO_ARCHIV.ps1') -LeafModuleTable $affLeafTable) 'V3|'
    & $affExpect 'B20c LeafLookalike' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @('modules/BRAVO.Leaf.Legacy/x.psm1') -LeafModuleTable $affLeafTable) 'V3|'
    & $affExpect 'B20c LeafDeleted' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affLeafPath) -DeletedPath @($affLeafPath) -LeafModuleTable $affLeafTable) 'V3|'
    & $affExpect 'B20c LeafOwnerNotInCatalog' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affLeafPath) `
            -LeafModuleTable @{ 'Leaf' = @{ Owner = 'NoSuch'; Dependents = @() } }) 'V3|'
    & $affExpect 'B20c LeafDependentNotInCatalog' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affLeafPath) `
            -LeafModuleTable @{ 'Leaf' = @{ Owner = 'Paths'; Dependents = @('NoSuch') } }) 'V3|'
    & $affExpect 'B20c LeafWithoutOwner' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affLeafPath) `
            -LeafModuleTable @{ 'Leaf' = @{ Dependents = @('Status') } }) 'V3|'
    & $affExpect 'B20c LeafOwnerOnly' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @($affLeafPath) `
            -LeafModuleTable @{ 'Leaf' = @{ Owner = 'Paths' } }) 'V2|Governance,Paths'
    & $affExpect 'B20c SubstitutedDocumentTable' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @('X.md') `
            -ConsumedDocumentTable @{ 'X.md' = @{ Suite = @('Status'); Gate = @() } }) 'V1|Governance,Status'
    & $affExpect 'B20c DocumentTableBadSuite' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @('X.md') `
            -ConsumedDocumentTable @{ 'X.md' = @{ Suite = @('NoSuch'); Gate = @() } }) 'V3|'
    $affProblem = & $affTakeMismatch
    Test-BRAVOCondition `
        -Condition ($affProblem.Length -eq 0) `
        -Name "Framework/AffectedPlan.LeafModuleTableGivesV2OnlyForValidEntries" `
        -Failure ("підмінена таблиця leaf-модуля дає V2 {owner + dependents + Governance}; відсутній запис, двійник імені, видалення, " +
            "невідомий suite чи запис без Owner дають V3: " + $affProblem)

    # --- Gate-підказки ---------------------------------------------------
    & $affExpectGate 'no Config parity (module)' (& $affPlanPlain @('modules/BRAVO.Configuration/BRAVO.Configuration.psm1')) ''
    & $affExpectGate 'no Config parity (example)' (& $affPlanPlain @('BRAVO.local.config.example')) ''
    & $affExpectGate 'gate Matrix' (& $affPlanPlain @('modules/BRAVO.DataRestore.MatrixTest/x.psm1')) 'DataRestore matrix test'
    & $affExpectGate 'gate VERSION' (& $affPlanPlain @('VERSION.json')) 'Release policy'
    & $affExpectGate 'gate TOOLS_MANIFEST' (& $affPlanPlain @('Tools/TOOLS_MANIFEST.json')) 'Integrity manifests are current'
    & $affExpectGate 'gate none' (& $affPlanPlain @('BRAVO_ARCHIV.ps1')) ''
    & $affExpectGate 'gate order' (& $affPlanPlain @('VERSION.json', 'BRAVO.local.config.example', 'Tools/TOOLS_MANIFEST.json')) 'Integrity manifests are current,Release policy'
    $affProblem = & $affTakeMismatch
    Test-BRAVOCondition `
        -Condition ($affProblem.Length -eq 0) `
        -Name "Framework/AffectedPlan.RequiredGateHintsAreDeterministic" `
        -Failure ("метадані gate: Integrity для маніфестів, Release policy для VERSION/документів, матричний gate для DataRestore.MatrixTest; " +
            "gate Config parity план не обчислює (це робить runner через канонічний ci-перелік); порядок фіксований: " + $affProblem)

    # Рішення Config parity належить ci\Test-BRAVOConfigParityRelevantPath.ps1; мапа не має копії його шаблонів.
    $affMapTextAll = [IO.File]::ReadAllText((Join-Path $root 'selftest\BRAVOSelfTestSuiteMap.ps1'), [Text.Encoding]::UTF8)
    $affMapParityTokens = @((Get-BRAVOSelfTestParsedFile -Path (Join-Path $root 'selftest\BRAVOSelfTestSuiteMap.ps1')).Tokens |
            Where-Object { @('StringLiteral', 'StringExpandable', 'HereStringLiteral', 'HereStringExpandable', 'Generic') -contains [string]$_.Kind } |
            Where-Object { [string]$_.Text -match '(?i)config_loader|config-parity|configparity|config\.example|BRAVO\.Configurat|Config parity' })
    Test-BRAVOCondition `
        -Condition ($affMapTextAll.Length -gt 0 -and $affMapParityTokens.Count -eq 0) `
        -Name "Framework/AffectedPlan.MapHasNoCopyOfConfigParityPatterns" `
        -Failure ("файл мапи не мусить містити рядкових літералів зі шаблонами config-parity (BRAVO_CONFIG_LOADER, config-parity, BRAVO.local.config.example, " +
            "модулі Configuration/Configurator, назва gate): рішення належить ci\Test-BRAVOConfigParityRelevantPath.ps1. Знайдено: " + $affMapParityTokens.Count)

    # --- Суворість: тип IsCompanion, регістр Unicode, тип полів маніфесту ----
    $affStrictChanged = @($affPaths, 'RUNTIME_MANIFEST.json')
    $affKelvin = [string][char]0x212A
    $affLongS = [string][char]0x017F
    $affCyrillicA = [string][char]0x0410
    & $affExpect 'strict IsCompanion string' (Get-BRAVOSelfTestAffectedPlan -ChangedPath $affStrictChanged -RuntimeManifestCompanion ([pscustomobject]@{ IsCompanion = 'False'; Reason = 'x' })) 'V3|'
    & $affExpect 'strict IsCompanion int' (Get-BRAVOSelfTestAffectedPlan -ChangedPath $affStrictChanged -RuntimeManifestCompanion ([pscustomobject]@{ IsCompanion = 1; Reason = 'x' })) 'V3|'
    & $affExpect 'strict IsCompanion true' (Get-BRAVOSelfTestAffectedPlan -ChangedPath $affStrictChanged -RuntimeManifestCompanion ([pscustomobject]@{ IsCompanion = $true; Reason = 'x' })) 'V2|Governance,Paths'
    & $affExpect 'Kelvin module' (& $affPlanPlain @('modules/BRAVO.Dis' + $affKelvin + 'Space/x.psm1')) 'V3|'
    & $affExpect 'Kelvin fragment' (& $affPlanPlain @('selftest/BRAVO_SELF_TEST.Dis' + $affKelvin + 'Space.ps1')) 'V3|'
    & $affExpect 'Kelvin leaf module' (Get-BRAVOSelfTestAffectedPlan -ChangedPath @('modules/BRAVO.Lea' + $affKelvin + '/x.psm1') -LeafModuleTable @{ 'Leak' = @{ Owner = 'Paths' } }) 'V3|'
    & $affExpect 'long s directory' (& $affPlanPlain @($affLongS + 'elftest/BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'Cyrillic fragment name' (& $affPlanPlain @('selftest/BRAVO_SELF_TEST.' + $affCyrillicA + 'rchive.ps1')) 'V3|'
    & $affExpect 'Cyrillic document' (& $affPlanPlain @($affCyrillicA + '.md')) 'V3|'
    & $affExpect 'Cyrillic README lookalike' (& $affPlanPlain @('REA' + [string][char]0x0414 + 'ME.md')) 'V3|'
    $affStrictFiles = & $affManifestText $affBaseFiles 'desc' $true
    $affStringSchema = $affStrictFiles.Replace('"schemaVersion":1', '"schemaVersion":"1"')
    $affTypeCompanion = Test-BRAVOSelfTestRuntimeManifestCompanion -BaseText $affStrictFiles -CurrentText $affStringSchema -ChangedPath $affStrictChanged
    & $affExpect 'strict schemaVersion 1 vs "1"' (Get-BRAVOSelfTestAffectedPlan -ChangedPath $affStrictChanged -RuntimeManifestCompanion $affTypeCompanion) 'V3|'
    $affProblem = & $affTakeMismatch
    Test-BRAVOCondition `
        -Condition ($affProblem.Length -eq 0 -and $affStringSchema -cne $affStrictFiles -and -not $affTypeCompanion.IsCompanion) `
        -Name "Framework/AffectedPlan.StrictTypesAndAsciiOnlyNames" `
        -Failure ("IsCompanion лише булевий true; Kelvin sign, довге s та кириличні двійники не відображаються на suite/модуль/документ; " +
            'schemaVersion 1 -> "1" не є супутником: ' + $affProblem)

    # --- B32-B36: некоректні шляхи -> V3 ----------------------------------
    & $affExpect 'B32 AbsoluteWindows' (& $affPlanPlain @('C:\repo\selftest\BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'B32 AbsolutePosix' (& $affPlanPlain @('/home/user/repo/selftest/BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'B32 AbsoluteUnc' (& $affPlanPlain @('\\host-a\share\selftest\BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'B32 LeadingBackslash' (& $affPlanPlain @('\selftest\BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'B33 Traversal 1' (& $affPlanPlain @('selftest/../BRAVO_ARCHIV.ps1')) 'V3|'
    & $affExpect 'B33 Traversal 2' (& $affPlanPlain @('docs/../X.md')) 'V3|'
    & $affExpect 'B33 Traversal into fragment' (& $affPlanPlain @('docs/../selftest/BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'B33 DotSegment' (& $affPlanPlain @('selftest/./BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'B33 EmptySegment' (& $affPlanPlain @('selftest//BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'B33 TrailingSeparator' (& $affPlanPlain @('selftest/')) 'V3|'
    & $affExpect 'B34 PrefixLookalike 1' (& $affPlanPlain @('xselftest/BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'B34 PrefixLookalike 2' (& $affPlanPlain @('docs/selftest/BRAVO_SELF_TEST.Paths.ps1')) 'V3|'
    & $affExpect 'B35 LeadingSpace' (& $affPlanPlain @(' README.md')) 'V3|'
    & $affExpect 'B35 TrailingSpace' (& $affPlanPlain @('README.md ')) 'V3|'
    & $affExpect 'B35 OnlySpace' (& $affPlanPlain @(' ')) 'V3|'
    & $affExpect 'B35 EmptyEntry' (& $affPlanPlain @('')) 'V3|'
    & $affExpect 'B35 TrailingNewline' (& $affPlanPlain @("README.md`n")) 'V3|'
    & $affExpect 'B35 PaddedFragment' (& $affPlanPlain @('  selftest\BRAVO_SELF_TEST.Paths.ps1  ')) 'V3|'
    & $affExpect 'B35 ValidPlusWhitespace' (& $affPlanPlain @('README.md', ' ')) 'V3|'
    & $affExpect 'ControlCharacter' (& $affPlanPlain @(('selftest\BRAVO_SELF_TEST.Paths' + [string][char]1 + '.ps1'))) 'V3|'
    $affProblem = & $affTakeMismatch
    Test-BRAVOCondition `
        -Condition ($affProblem.Length -eq 0) `
        -Name "Framework/AffectedPlan.InvalidPathFormsEscalateToV3" `
        -Failure ("абсолютні шляхи, обхід каталогів, порожні сегменти, двійники префікса й пробіли по краях (без Trim) мусять давати V3: " + $affProblem)

    # --- B36: порожній вхід -----------------------------------------------
    $affEmpty = Get-BRAVOSelfTestAffectedPlan -ChangedPath @()
    Test-BRAVOCondition `
        -Condition (
            $affEmpty.Status -ceq 'EmptyInput' -and @($affEmpty.Suite).Count -eq 0 -and
            $affEmpty.Class -ceq 'V3' -and $affEmpty.IsAcceptanceEvidence -eq $false
        ) `
        -Name "Framework/AffectedPlan.EmptyInputIsNotAPlan" `
        -Failure ("порожній набір шляхів - це Status EmptyInput (не порожній прогін); навіть якщо викликач проігнорує Status, клас V3 " +
            "і Suite = @(). Фактично: " + [string]$affEmpty.Status + "/" + [string]$affEmpty.Class)

    # --- Форма й контракт плану -------------------------------------------
    $affShapeProblems = New-Object System.Collections.Generic.List[string]
    $affShapePlans = @(
        (& $affPlanPlain @('README.md')),
        (& $affPlanPlain @('BRAVO_ARCHIV.ps1')),
        (& $affPlanPlain @($affPaths)),
        (& $affPlanPlain @($affPaths, $affArchive)),
        (Get-BRAVOSelfTestAffectedPlan -ChangedPath @()))
    foreach ($affShapePlan in $affShapePlans) {
        $affShapeNames = [string]::Join(',', @($affShapePlan.PSObject.Properties | ForEach-Object { $_.Name }))
        if ($affShapeNames -cne 'Status,Class,ClassLabel,Suite,RequiredGate,RequiresIndependentReview,UnknownPath,Decision,IsAcceptanceEvidence') {
            [void]$affShapeProblems.Add('поля плану: ' + $affShapeNames)
        }
        if ($affShapePlan.ClassLabel -cne 'мінімальний клас за картою шляхів') { [void]$affShapeProblems.Add('ClassLabel: ' + $affShapePlan.ClassLabel) }
        if ($affShapePlan.IsAcceptanceEvidence -ne $false) { [void]$affShapeProblems.Add('IsAcceptanceEvidence не $false') }
        if (@('V1', 'V2', 'V3') -cnotcontains $affShapePlan.Class) { [void]$affShapeProblems.Add('клас поза V1-V3: ' + $affShapePlan.Class) }
        foreach ($affShapeProperty in @('Suite', 'RequiredGate', 'UnknownPath', 'Decision')) {
            if ($affShapePlan.$affShapeProperty -isnot [array]) { [void]$affShapeProblems.Add($affShapeProperty + ' не масив') }
        }
        if (@($affShapePlan.Suite | Where-Object { $affCatalog -cnotcontains $_ }).Count -ne 0) { [void]$affShapeProblems.Add('suite поза каталогом') }
        if ($affShapePlan.Class -cne 'V3' -and @($affShapePlan.Suite) -cnotcontains 'Governance') { [void]$affShapeProblems.Add('Governance відсутній нижче V3') }
        if ($affShapePlan.Class -ceq 'V3' -and @($affShapePlan.Suite).Count -ne 0) { [void]$affShapeProblems.Add('V3 з непорожнім Suite') }
        if ($affShapePlan.Class -ceq 'V3' -and $affShapePlan.RequiresIndependentReview -ne $true) { [void]$affShapeProblems.Add('V3 без незалежного рев''ю') }
    }
    $affDecision = (& $affPlanPlain @($affPaths, 'README.md')).Decision
    if (@($affDecision).Count -ne 2) { [void]$affShapeProblems.Add('Decision мусить мати запис на кожен шлях') }
    Test-BRAVOCondition `
        -Condition (
            $affShapeProblems.Count -eq 0 -and
            @($affSeenClass.ToArray() | Where-Object { @('V1', 'V2', 'V3') -cnotcontains $_ }).Count -eq 0 -and
            $affSeenClass.Count -gt 50
        ) `
        -Name "Framework/AffectedPlan.PlanContractShapeAndNeverV0" `
        -Failure ("план: фіксований набір полів, ClassLabel, IsAcceptanceEvidence = `$false, масиви під StrictMode для 0/1/N елементів, " +
            "Governance нижче V3, порожній Suite у V3; жоден з " + $affSeenClass.Count + " прогнаних планів не має класу поза V1-V3: " +
            [string]::Join('; ', @($affShapeProblems.ToArray() | Select-Object -First 6)))

    # --- B45: чистота ------------------------------------------------------
    $affSelectionBefore = $script:BRAVOSelfTestSelectedSuite
    $affCatalogBefore = [string]::Join(',', @($script:BRAVOSelfTestSuiteCatalog))
    $affTableBefore = Get-BRAVOSelfTestConsumedDocumentTable
    [void]$affTableBefore.Remove('README.md')
    $affTableAfter = Get-BRAVOSelfTestConsumedDocumentTable
    $affLeafBefore = Get-BRAVOSelfTestLeafModuleTable
    $affLeafBefore['Injected'] = @{ Owner = 'Paths' }
    $affPurityPlan = & $affPlanPlain @('README.md')
    Test-BRAVOCondition `
        -Condition (
            [object]::ReferenceEquals($script:BRAVOSelfTestSelectedSuite, $affSelectionBefore) -and
            [string]::Join(',', @($script:BRAVOSelfTestSuiteCatalog)) -ceq $affCatalogBefore -and
            $affTableAfter.ContainsKey('README.md') -and
            -not (Get-BRAVOSelfTestLeafModuleTable).ContainsKey('Injected') -and
            $affPurityPlan.Class -ceq 'V1'
        ) `
        -Name "Framework/AffectedPlan.PlanIsPureAndTablesAreFresh" `
        -Failure "план не змінює вибір suite й каталог, а таблиці повертаються свіжими копіями: зміна повернутої таблиці не впливає на наступні виклики"

    # --- B46: детермінізм --------------------------------------------------
    $affOrderInput = @($affPaths, $affArchive, 'README.md', 'CHANGELOG.md', $affGovernance)
    $affOrderReference = & $affPlanPlain $affOrderInput
    $affOrderProblems = New-Object System.Collections.Generic.List[string]
    $affReversed = $affOrderInput.Clone()
    [Array]::Reverse($affReversed)
    $affRotated = @($affOrderInput[2..4] + $affOrderInput[0..1])
    foreach ($affPermutation in @($affReversed, $affRotated, @($affOrderInput + $affOrderInput))) {
        $affOrderPlan = & $affPlanPlain $affPermutation
        if ((& $affSignature $affOrderPlan) -cne (& $affSignature $affOrderReference) -or
            [string]::Join(',', @($affOrderPlan.RequiredGate)) -cne [string]::Join(',', @($affOrderReference.RequiredGate))) {
            [void]$affOrderProblems.Add((& $affSignature $affOrderPlan))
        }
    }
    $affOrderCatalogIndex = @($affOrderReference.Suite | ForEach-Object { [array]::IndexOf($affCatalog, $_) })
    $affOrderSorted = @($affOrderCatalogIndex | Sort-Object)
    Test-BRAVOCondition `
        -Condition (
            $affOrderProblems.Count -eq 0 -and
            [string]::Join(',', $affOrderCatalogIndex) -ceq [string]::Join(',', $affOrderSorted) -and
            (& $affSignature $affOrderReference) -ceq 'V2|Archive,Governance,Paths'
        ) `
        -Name "Framework/AffectedPlan.UnionIsDeterministicInCatalogOrder" `
        -Failure ("перестановка, ротація й дублікати входу мусять давати той самий union у порядку каталогу; розбіжності: [" +
            [string]::Join('; ', @($affOrderProblems.ToArray())) + "]; еталон: " + (& $affSignature $affOrderReference))

    # --- Статичні guard-и файлу мапи --------------------------------------
    $affMapParsed = Get-BRAVOSelfTestParsedFile -Path $affMapPath
    $affMapAst = $affMapParsed.Ast
    $affMapBytes = [IO.File]::ReadAllBytes($affMapPath)
    $affMapFunctions = @($affMapAst.FindAll({ param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst] }, $true))
    $affMapFunctionNames = [string]::Join(',', @($affMapFunctions | ForEach-Object { $_.Name } | Sort-Object))
    $affMapAssignments = @($affMapAst.FindAll({ param($node) $node -is [Management.Automation.Language.AssignmentStatementAst] }, $true))
    $affMapScopedAssignments = @($affMapAssignments | Where-Object {
            $_.Left -is [Management.Automation.Language.VariableExpressionAst] -and
            -not $_.Left.VariablePath.IsUnqualified })
    $affMapScopedNames = [string]::Join(',', @($affMapScopedAssignments | ForEach-Object { $_.Left.VariablePath.UserPath }))
    $affMapTopLevelCatalog = @($affMapAst.EndBlock.Statements | Where-Object {
            $_ -is [Management.Automation.Language.AssignmentStatementAst] -and
            $_.Left.Extent.Text -ceq '$script:BRAVOSelfTestSuiteCatalog' })
    $affMapForbiddenCommands = @($affMapAst.FindAll({ param($node) $node -is [Management.Automation.Language.CommandAst] }, $true) |
            Where-Object {
                @('set-variable', 'new-variable', 'remove-variable', 'set-item', 'set-content', 'add-content', 'out-file', 'get-content',
                    'get-item', 'get-childitem', 'test-path', 'set-location', 'push-location', 'remove-item', 'invoke-expression',
                    'start-process', 'import-module', 'git', 'write-host') -contains ([string]$_.GetCommandName()).ToLowerInvariant()
            })
    $affMapForbiddenTypes = @($affMapAst.FindAll({ param($node) $node -is [Management.Automation.Language.TypeExpressionAst] }, $true) |
            Where-Object { $_.TypeName.FullName -match '(?i)^(System\.)?(IO\.|Environment|Diagnostics\.|Net\.|Reflection\.)' })
    Test-BRAVOCondition `
        -Condition (
            @($affMapParsed.Errors).Count -eq 0 -and
            $affMapFunctionNames -ceq 'ConvertTo-BRAVOSelfTestNormalizedChangedPath,Get-BRAVOSelfTestAffectedPlan,Get-BRAVOSelfTestConsumedDocumentTable,Get-BRAVOSelfTestLeafModuleTable,Get-BRAVOSelfTestSuiteForChangedPath,Test-BRAVOSelfTestRuntimeManifestCompanion' -and
            $affMapTopLevelCatalog.Count -eq 1 -and
            $affMapScopedNames -ceq 'script:BRAVOSelfTestSuiteCatalog' -and
            $affMapForbiddenCommands.Count -eq 0 -and
            $affMapForbiddenTypes.Count -eq 0
        ) `
        -Name "Framework/AffectedPlan.MapFileIsPureAndOwnsOnlyTheCatalog" `
        -Failure ("selftest\BRAVOSelfTestSuiteMap.ps1 мусить розбиратись без помилок, мати рівно відомі функції, один стан `$script: (каталог) " +
            "і жодного вводу-виводу, git, середовища чи виводу в консоль. Помилок розбору: $(@($affMapParsed.Errors).Count); функції: [$affMapFunctionNames]; " +
            "присвоєння поза локальним scope: [$affMapScopedNames]; заборонені команди: $($affMapForbiddenCommands.Count); типи: $($affMapForbiddenTypes.Count)")

    $affMapHasBareLf = $false
    for ($affByteIndex = 0; $affByteIndex -lt $affMapBytes.Length; $affByteIndex++) {
        if ($affMapBytes[$affByteIndex] -eq 10 -and ($affByteIndex -eq 0 -or $affMapBytes[$affByteIndex - 1] -ne 13)) { $affMapHasBareLf = $true; break }
    }
    Test-BRAVOCondition `
        -Condition (
            $affMapBytes.Length -gt 3 -and $affMapBytes[0] -eq 0xEF -and $affMapBytes[1] -eq 0xBB -and $affMapBytes[2] -eq 0xBF -and
            -not $affMapHasBareLf -and
            -not [regex]::IsMatch([IO.Path]::GetFileName($affMapPath), '^BRAVO_SELF_TEST\..+\.ps1$')
        ) `
        -Name "Framework/AffectedPlan.MapFileHasBomCrlfAndIsNotAFragment" `
        -Failure "файл мапи: UTF-8 з BOM, CRLF (як у сусідніх файлів) і ім'я, що не збігається з BRAVO_SELF_TEST.<Ім'я>.ps1 (інакше його вважали б фрагментом suite)"

    $affMapStringTokens = @($affMapParsed.Tokens | Where-Object { @('StringLiteral', 'StringExpandable', 'HereStringLiteral', 'HereStringExpandable') -contains [string]$_.Kind })
    $affMapV0Tokens = @($affMapStringTokens | Where-Object { [string]$_.Value -match '(?i)\bV0\b' })
    Test-BRAVOCondition `
        -Condition ($affMapStringTokens.Count -gt 0 -and $affMapV0Tokens.Count -eq 0) `
        -Name "Framework/AffectedPlan.MapNeverEmitsV0" `
        -Failure "жоден рядковий літерал мапи не містить V0: клас V0 (лише документація) визначає класифікація PR, а не автоматичний план; запускача, що друкує 'Full не потрібен', немає"

    $affRootAst = Get-BRAVOSelfTestOwnSourceAst
    $affRootTop = @($affRootAst.EndBlock.Statements)
    $affDotSources = @($affRootTop | Where-Object {
            $_ -is [Management.Automation.Language.PipelineAst] -and $_.PipelineElements.Count -eq 1 -and
            $_.PipelineElements[0] -is [Management.Automation.Language.CommandAst] -and
            $_.PipelineElements[0].InvocationOperator -eq [Management.Automation.Language.TokenKind]::Dot -and
            $_.Extent.Text -ceq ". (Join-Path `$root 'selftest\BRAVOSelfTestSuiteMap.ps1')" })
    $affIntegrityGate = @($affRootTop | Where-Object {
            $_ -is [Management.Automation.Language.IfStatementAst] -and
            $_.Clauses[0].Item1.Extent.Text.Contains('$script:selfTestBootstrapRuntimeManifest.IsValid') })
    $affNormalize = @($affRootTop | Where-Object {
            $_ -is [Management.Automation.Language.IfStatementAst] -and
            $_.Clauses[0].Item1.Extent.Text -match '^\$null -ne \$Suite' })
    $affRootCatalogAssign = @($affRootTop | Where-Object {
            $_ -is [Management.Automation.Language.AssignmentStatementAst] -and
            $_.Left.Extent.Text -ceq '$script:BRAVOSelfTestSuiteCatalog' })
    $affRootMapperDefinition = @($affRootAst.FindAll({ param($node)
                $node -is [Management.Automation.Language.FunctionDefinitionAst] -and
                @('Get-BRAVOSelfTestSuiteForChangedPath', 'Get-BRAVOSelfTestAffectedPlan') -contains $node.Name }, $true))
    Test-BRAVOCondition `
        -Condition (
            $affDotSources.Count -eq 1 -and $affIntegrityGate.Count -eq 1 -and $affNormalize.Count -eq 1 -and
            $affRootCatalogAssign.Count -eq 0 -and $affRootMapperDefinition.Count -eq 0 -and
            $affDotSources[0].Extent.StartOffset -gt $affIntegrityGate[0].Extent.EndOffset -and
            $affDotSources[0].Extent.EndOffset -lt $affNormalize[0].Extent.StartOffset
        ) `
        -Name "Framework/AffectedPlan.MapIsDotSourcedAfterIntegrityBeforeSuiteNormalization" `
        -Failure ("корінь мусить dot-source-ити файл мапи один раз на верхньому рівні ПІСЛЯ перевірки цілісності маніфеста (інакше непідтверджений код виконається) " +
            "і ДО розбору -Suite, а каталог і мапера в корені не дублюються. dot-source: $($affDotSources.Count); перевірка цілісності: $($affIntegrityGate.Count); " +
            "розбір -Suite: $($affNormalize.Count); присвоєнь каталогу в корені: $($affRootCatalogAssign.Count); визначень мапера в корені: $($affRootMapperDefinition.Count)")

    # --- Guard-и leaf-модулів: сканер вхідних ребер -------------------------
    # Ребро до модуля M з файлу F є, якщо F не лежить під modules\BRAVO.<M>\ і РЯДКОВИЙ або
    # generic-токен F (не коментар) містить сегмент modules\BRAVO.<M>\, дорівнює BRAVO.<M> або
    # закінчується на BRAVO.<M>.psd1|.psm1. Динамічне складання імені ("BRAVO.$x", 'BRAVO.' + $x,
    # 'BRAVO.{0}') ребра не показує, тому воно фіксується окремо й для непорожньої таблиці
    # leaf-модулів є відмовою (fail closed).
    $affEdgeScan = {
        param([object[]]$Unit, [string[]]$ModuleName)
        $stringKinds = @('StringLiteral', 'StringExpandable', 'HereStringLiteral', 'HereStringExpandable', 'Generic')
        $edges = @{}
        $dynamic = New-Object System.Collections.Generic.List[string]
        $moduleAlternation = ''
        if (@($ModuleName).Count -gt 0) {
            $moduleAlternation = [string]::Join('|', @($ModuleName | Sort-Object { $_.Length } -Descending | ForEach-Object { [regex]::Escape($_) }))
        }
        $candidatePattern = '(?i)BRAVO\.(?:\$|\{\d+\}|[''"])'
        if ($moduleAlternation.Length -gt 0) {
            $candidatePattern = '(?i)BRAVO\.(?:(?<module>' + $moduleAlternation + ')(?![A-Za-z0-9_])|\$|\{\d+\}|[''"])'
        }
        foreach ($affUnit in @($Unit)) {
            $unitTokens = @($affUnit.Tokens)
            $unitText = [string]$affUnit.Text
            $checkedOffsets = @{}
            foreach ($candidate in [regex]::Matches($unitText, $candidatePattern)) {
                $low = 0
                $high = $unitTokens.Count - 1
                $found = $null
                while ($low -le $high) {
                    $middle = [int][Math]::Floor(($low + $high) / 2)
                    $probe = $unitTokens[$middle]
                    if ($candidate.Index -lt $probe.Extent.StartOffset) { $high = $middle - 1 }
                    elseif ($candidate.Index -ge $probe.Extent.EndOffset) { $low = $middle + 1 }
                    else { $found = $probe; break }
                }
                if ($null -eq $found -or $stringKinds -cnotcontains [string]$found.Kind) { continue }
                $tokenValue = [string]$found.Text
                if ($found -is [Management.Automation.Language.StringToken]) { $tokenValue = [string]$found.Value }
                if ($candidate.Groups['module'].Success) {
                    $moduleHit = [regex]::Escape($candidate.Groups['module'].Value)
                    $edgeKey = [string]$found.Extent.StartOffset + '|' + $candidate.Groups['module'].Value.ToLowerInvariant()
                    if ($checkedOffsets.ContainsKey($edgeKey)) { continue }
                    $checkedOffsets[$edgeKey] = $true
                    $isEdge = (
                        [regex]::IsMatch($tokenValue, '(?i)modules[\\/]BRAVO\.' + $moduleHit + '[\\/]') -or
                        [regex]::IsMatch($tokenValue, '(?i)^BRAVO\.' + $moduleHit + '$') -or
                        [regex]::IsMatch($tokenValue, '(?i)BRAVO\.' + $moduleHit + '\.(psd1|psm1)$'))
                    if (-not $isEdge) { continue }
                    $ownDirectory = 'modules\bravo.' + $candidate.Groups['module'].Value.ToLowerInvariant() + '\'
                    if (([string]$affUnit.Rel).ToLowerInvariant().StartsWith($ownDirectory, [StringComparison]::Ordinal)) { continue }
                    $moduleKey = $candidate.Groups['module'].Value
                    $matchedName = @($ModuleName | Where-Object { $_ -eq $moduleKey }) | Select-Object -First 1
                    if ($null -eq $matchedName) { $matchedName = $moduleKey }
                    if (-not $edges.ContainsKey([string]$matchedName)) { $edges[[string]$matchedName] = New-Object System.Collections.Generic.List[string] }
                    if (-not $edges[[string]$matchedName].Contains([string]$affUnit.Rel)) { [void]$edges[[string]$matchedName].Add([string]$affUnit.Rel) }
                } else {
                    $dynamicKey = [string]$found.Extent.StartOffset + '|dynamic'
                    if ($checkedOffsets.ContainsKey($dynamicKey)) { continue }
                    $checkedOffsets[$dynamicKey] = $true
                    if ([regex]::IsMatch($tokenValue, '(?i)BRAVO\.(\$|\{\d+\}|$)')) {
                        [void]$dynamic.Add([string]$affUnit.Rel + ':' + [string]$found.Extent.StartLineNumber)
                    }
                }
            }
        }
        return [pscustomobject]@{ Edge = $edges; Dynamic = [string[]]@($dynamic.ToArray()) }
    }
    $affMakeUnit = {
        param([string]$Rel, [string]$Text)
        $unitTokens = $null
        $unitErrors = $null
        [void][Management.Automation.Language.Parser]::ParseInput($Text, [ref]$unitTokens, [ref]$unitErrors)
        return [pscustomobject]@{ Rel = $Rel; Text = $Text; Tokens = $unitTokens }
    }
    $affLeafCoverage = {
        param([object[]]$FragmentUnit, [hashtable]$Table)
        $coverageProblems = New-Object System.Collections.Generic.List[string]
        if (@($Table.Keys).Count -eq 0) { return , @() }
        $coverageScan = & $affEdgeScan $FragmentUnit @($Table.Keys | ForEach-Object { [string]$_ })
        foreach ($coverageModule in @($coverageScan.Edge.Keys)) {
            $coverageEntry = $Table[$coverageModule]
            $coverageAllowed = @('Governance')
            if ($coverageEntry -is [System.Collections.IDictionary]) {
                if ($coverageEntry.Contains('Owner')) { $coverageAllowed += @([string]$coverageEntry['Owner']) }
                if ($coverageEntry.Contains('Dependents')) { $coverageAllowed += @($coverageEntry['Dependents'] | ForEach-Object { [string]$_ }) }
            }
            foreach ($coverageFile in @($coverageScan.Edge[$coverageModule])) {
                $coverageSuite = [regex]::Match($coverageFile, '(?i)^selftest\\BRAVO_SELF_TEST\.([A-Za-z]+)\.ps1$').Groups[1].Value
                if ($coverageAllowed -cnotcontains $coverageSuite) {
                    [void]$coverageProblems.Add($coverageModule + ' <- ' + $coverageFile)
                }
            }
        }
        return , @($coverageProblems.ToArray())
    }

    $affModuleNames = [string[]]@(
        [IO.Directory]::GetDirectories((Join-Path $root 'modules')) |
            ForEach-Object { [IO.Path]::GetFileName($_) } |
            Where-Object { $_.StartsWith('BRAVO.', [StringComparison]::Ordinal) } |
            ForEach-Object { $_.Substring('BRAVO.'.Length) })
    $affScanFiles = New-Object System.Collections.Generic.List[string]
    foreach ($affModuleFile in [IO.Directory]::GetFiles((Join-Path $root 'modules'), '*', [IO.SearchOption]::AllDirectories)) {
        if (@('.ps1', '.psm1', '.psd1') -contains [IO.Path]::GetExtension($affModuleFile).ToLowerInvariant()) { [void]$affScanFiles.Add($affModuleFile) }
    }
    foreach ($affRootFile in [IO.Directory]::GetFiles($root, 'BRAVO_*.ps1')) {
        if ([IO.Path]::GetFileName($affRootFile) -cne 'BRAVO_SELF_TEST.ps1') { [void]$affScanFiles.Add($affRootFile) }
    }
    foreach ($affFolderName in @('deploy', 'ci')) {
        $affFolderPath = Join-Path $root $affFolderName
        if ([IO.Directory]::Exists($affFolderPath)) {
            foreach ($affFolderFile in [IO.Directory]::GetFiles($affFolderPath, '*.ps1')) { [void]$affScanFiles.Add($affFolderFile) }
        }
    }
    $affRootFull = [IO.Path]::GetFullPath($root).TrimEnd('\', '/')
    $affUnits = New-Object System.Collections.Generic.List[object]
    foreach ($affScanFile in $affScanFiles) {
        $affScanParsed = Get-BRAVOSelfTestParsedFile -Path $affScanFile
        [void]$affUnits.Add([pscustomobject]@{
                Rel    = ([IO.Path]::GetFullPath($affScanFile).Substring($affRootFull.Length).TrimStart('\', '/').Replace('/', '\'))
                Text   = [IO.File]::ReadAllText($affScanFile, [Text.Encoding]::UTF8)
                Tokens = $affScanParsed.Tokens
            })
    }
    $affRealScan = & $affEdgeScan @($affUnits.ToArray()) $affModuleNames
    $affLeafActual = Get-BRAVOSelfTestLeafModuleTable
    $affLeafViolations = New-Object System.Collections.Generic.List[string]
    foreach ($affLeafName in @($affLeafActual.Keys)) {
        if ($affModuleNames -cnotcontains [string]$affLeafName) {
            [void]$affLeafViolations.Add([string]$affLeafName + ': каталогу модуля немає')
            continue
        }
        if ($affRealScan.Edge.ContainsKey([string]$affLeafName)) {
            [void]$affLeafViolations.Add([string]$affLeafName + ' <- ' + [string]::Join(', ', @($affRealScan.Edge[[string]$affLeafName])))
        }
    }
    if (@($affLeafActual.Keys).Count -gt 0 -and @($affRealScan.Dynamic).Count -gt 0) {
        [void]$affLeafViolations.Add('динамічне складання імені модуля, ребра не визначити: ' + [string]::Join(', ', @($affRealScan.Dynamic)))
    }
    Test-BRAVOCondition `
        -Condition ($affLeafViolations.Count -eq 0) `
        -Name "Framework/AffectedPlan.LeafModulesHaveNoNonFragmentInboundEdge" `
        -Failure ("leaf-модуль не має вхідних ребер від модулів, BRAVO_CONFIG_LOADER.ps1, кореневих BRAVO_*.ps1, deploy\*.ps1 і ci\*.ps1; а за динамічного " +
            "складання імені модуля таблиця leaf-модулів мусить лишатись порожньою. Порушення: " + [string]::Join('; ', @($affLeafViolations.ToArray())))

    $affEdgeModuleCount = @($affRealScan.Edge.Keys).Count
    $affSyntheticLeaf = @('Leaf')
    $affSyntheticEdge = & $affEdgeScan @(
        (& $affMakeUnit 'BRAVO_X.ps1' "Import-Module (Join-Path `$root 'modules\BRAVO.Leaf\BRAVO.Leaf.psd1')`r`n")) $affSyntheticLeaf
    $affSyntheticGeneric = & $affEdgeScan @((& $affMakeUnit 'BRAVO_Z.ps1' "Import-Module BRAVO.Leaf`r`n")) $affSyntheticLeaf
    $affSyntheticCommentOnly = & $affEdgeScan @((& $affMakeUnit 'BRAVO_Y.ps1' "# modules\BRAVO.Leaf\x.psm1`r`nWrite-Output 'x'`r`n")) $affSyntheticLeaf
    $affSyntheticOwn = & $affEdgeScan @((& $affMakeUnit 'modules\BRAVO.Leaf\BRAVO.Leaf.psm1' "Import-Module (Join-Path `$PSScriptRoot 'modules\BRAVO.Leaf\x.psm1')`r`n")) $affSyntheticLeaf
    $affSyntheticLookalike = & $affEdgeScan @((& $affMakeUnit 'BRAVO_W.ps1' "Import-Module 'modules\BRAVO.Leaf.Legacy\x.psm1'`r`n")) $affSyntheticLeaf
    $affSyntheticDynamic = & $affEdgeScan @(
        (& $affMakeUnit 'BRAVO_D1.ps1' "`$n = 'Leaf'`r`nImport-Module `"modules\BRAVO.`$n\BRAVO.`$n.psd1`"`r`n"),
        (& $affMakeUnit 'BRAVO_D2.ps1' "`$n = 'Leaf'`r`nImport-Module (Join-Path `$root ('modules\BRAVO.' + `$n))`r`n"),
        (& $affMakeUnit 'ci\x.ps1' "`$n = 'Leaf'`r`nImport-Module ('modules\BRAVO.{0}' -f `$n)`r`n")) $affSyntheticLeaf
    Test-BRAVOCondition `
        -Condition (
            $affSyntheticEdge.Edge.ContainsKey('Leaf') -and [string]::Join(',', @($affSyntheticEdge.Edge['Leaf'])) -ceq 'BRAVO_X.ps1' -and
            $affSyntheticGeneric.Edge.ContainsKey('Leaf') -and
            @($affSyntheticCommentOnly.Edge.Keys).Count -eq 0 -and
            @($affSyntheticOwn.Edge.Keys).Count -eq 0 -and
            @($affSyntheticLookalike.Edge.Keys).Count -eq 0 -and
            @($affSyntheticDynamic.Dynamic).Count -eq 3 -and
            $affEdgeModuleCount -ge 5
        ) `
        -Name "Framework/AffectedPlan.LeafModulesHaveNoNonFragmentInboundEdgeIsMeaningful" `
        -Failure ("сканер ребер мусить бачити ребро з синтетичного BRAVO_X.ps1 (рядковий і generic токен), ігнорувати коментар, власний каталог " +
            "і двійник імені, фіксувати динамічне складання (3 варіанти) і знаходити ребра реальних модулів (модулів з ребрами: $affEdgeModuleCount, потрібно >= 5)")

    $affCoverageTable = @{ 'Leaf' = @{ Owner = 'Paths'; Dependents = @('Status') } }
    $affCoverageGood = & $affLeafCoverage @(
        (& $affMakeUnit 'selftest\BRAVO_SELF_TEST.Paths.ps1' "Import-Module 'modules\BRAVO.Leaf\BRAVO.Leaf.psd1'`r`n"),
        (& $affMakeUnit 'selftest\BRAVO_SELF_TEST.Status.ps1' "Import-Module 'modules\BRAVO.Leaf\BRAVO.Leaf.psd1'`r`n"),
        (& $affMakeUnit 'selftest\BRAVO_SELF_TEST.Governance.ps1' "Import-Module 'modules\BRAVO.Leaf\BRAVO.Leaf.psd1'`r`n")) $affCoverageTable
    $affCoverageBad = & $affLeafCoverage @(
        (& $affMakeUnit 'selftest\BRAVO_SELF_TEST.Archive.ps1' "Import-Module 'modules\BRAVO.Leaf\BRAVO.Leaf.psd1'`r`n")) $affCoverageTable
    $affCoverageActual = @()
    if (@($affLeafActual.Keys).Count -gt 0) {
        $affCoverageReal = New-Object System.Collections.Generic.List[object]
        foreach ($affCoverageSuite in $affCatalog) {
            $affCoverageFile = Join-Path $root ('selftest\BRAVO_SELF_TEST.' + $affCoverageSuite + '.ps1')
            $affCoverageParsed = Get-BRAVOSelfTestParsedFile -Path $affCoverageFile
            [void]$affCoverageReal.Add([pscustomobject]@{
                    Rel    = 'selftest\BRAVO_SELF_TEST.' + $affCoverageSuite + '.ps1'
                    Text   = [IO.File]::ReadAllText($affCoverageFile, [Text.Encoding]::UTF8)
                    Tokens = $affCoverageParsed.Tokens
                })
        }
        $affCoverageActual = & $affLeafCoverage @($affCoverageReal.ToArray()) $affLeafActual
    }
    Test-BRAVOCondition `
        -Condition (@($affCoverageActual).Count -eq 0) `
        -Name "Framework/AffectedPlan.LeafDependentsCoverDirectConsumers" `
        -Failure ("кожен фрагмент, що посилається на leaf-модуль, мусить входити до owner + dependents (+ Governance): " + [string]::Join('; ', @($affCoverageActual)))
    Test-BRAVOCondition `
        -Condition (@($affCoverageGood).Count -eq 0 -and @($affCoverageBad).Count -eq 1 -and @($affCoverageBad)[0] -ceq 'Leaf <- selftest\BRAVO_SELF_TEST.Archive.ps1') `
        -Name "Framework/AffectedPlan.LeafDependentsCoverDirectConsumersIsMeaningful" `
        -Failure "перевірка покриття споживачів мусить пропустити owner, dependents і Governance та назвати фрагмент поза ними (синтетичний Archive)"

    # --- Таблиці посилаються лише на каталог і наявні документи -------------
    $affTableProblems = New-Object System.Collections.Generic.List[string]
    foreach ($affLeafKey in @($affLeafActual.Keys)) {
        $affLeafEntry = $affLeafActual[$affLeafKey]
        $affLeafNames = @()
        if ($affLeafEntry -is [System.Collections.IDictionary]) {
            if ($affLeafEntry.Contains('Owner')) { $affLeafNames += @([string]$affLeafEntry['Owner']) } else { [void]$affTableProblems.Add("$affLeafKey без Owner") }
            if ($affLeafEntry.Contains('Dependents')) { $affLeafNames += @($affLeafEntry['Dependents'] | ForEach-Object { [string]$_ }) }
        } else {
            [void]$affTableProblems.Add("$affLeafKey не є таблицею")
        }
        foreach ($affLeafSuiteName in $affLeafNames) {
            if ($affCatalog -cnotcontains $affLeafSuiteName) { [void]$affTableProblems.Add("$affLeafKey -> $affLeafSuiteName поза каталогом") }
        }
    }
    $affDocumentTable = Get-BRAVOSelfTestConsumedDocumentTable
    foreach ($affDocumentKey in @($affDocumentTable.Keys)) {
        foreach ($affDocumentSuite in @($affDocumentTable[$affDocumentKey].Suite)) {
            if ($affCatalog -cnotcontains [string]$affDocumentSuite) { [void]$affTableProblems.Add("$affDocumentKey -> $affDocumentSuite поза каталогом") }
        }
        if (@($affDocumentTable[$affDocumentKey].Suite) -cnotcontains 'Governance') { [void]$affTableProblems.Add("$affDocumentKey без Governance") }
    }
    Test-BRAVOCondition `
        -Condition ($affTableProblems.Count -eq 0 -and @($affDocumentTable.Keys).Count -gt 0) `
        -Name "Framework/AffectedPlan.DependentsAreCatalogSuites" `
        -Failure ("owner і dependents leaf-модулів та споживачі документів мусять бути suite з каталогу, а кожен документ - споживатись Governance: " +
            [string]::Join('; ', @($affTableProblems.ToArray())))

    $affMissingDocuments = @($affDocumentTable.Keys | Where-Object {
            -not [IO.File]::Exists((Join-Path $root ([string]$_)))
        } | Sort-Object)
    Test-BRAVOCondition `
        -Condition ($affMissingDocuments.Count -eq 0) `
        -Name "Framework/AffectedPlan.ConsumedDocumentsExist" `
        -Failure ("кожен документ таблиці споживаних мусить існувати в дереві (застарілий запис давав би V1 для неіснуючого файлу): " + [string]::Join(', ', $affMissingDocuments))
}
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Framework.AffectedPlan' } }

if (Enter-BRAVOSelfTestSection -Name 'Tail/Framework.AffectedChangedPath') { try {

# ============================================================
# VAL-05 (Affected), PR2: git-збирач змінених шляхів.
#
# Канонічний власник - ci\BRAVOChangedPath.ps1 (Invoke-BRAVOGitCommand,
# Get-BRAVOChangedPathSet). Секція перевіряє контракт бази порівняння
# (merge-base -> робоче дерево, untracked включно, rename дає обидва
# шляхи, видалення окремо) і головний інваріант: збій git НІКОЛИ не
# стає порожнім набором шляхів (fail closed).
#
# Позначення: [I] - ін'єкція -GitInvoker (git не потрібен); [T] -
# тимчасовий репозиторій під TEMP з вигаданою ідентичністю; [R] -
# статичний guard файлу. [T]-перевірки виконуються лише в git-робочій копії
# (є .git і git): розгорнутий пакет на сервері не має .git, і [НЕДОСТУПНО]
# там інвалідувало б acceptance. Покриття на CI не може зникнути мовчки:
# RealScenariosRunOnCi падає, якщо на GitHub Actions сценарії не виконуються.
# Змінні лишаються в межах & { }: нічого нового не читається коренем.
# ============================================================
& {
    $cpPath = Join-Path $root 'ci\BRAVOChangedPath.ps1'
    $cpText = ''
    if ([IO.File]::Exists($cpPath)) {
        . $cpPath
        $cpText = [IO.File]::ReadAllText($cpPath, [Text.Encoding]::UTF8)
    }
    $cpReady = (
        $null -ne (Get-Command -Name 'Invoke-BRAVOGitCommand' -CommandType Function -ErrorAction SilentlyContinue) -and
        $null -ne (Get-Command -Name 'Get-BRAVOChangedPathSet' -CommandType Function -ErrorAction SilentlyContinue))
    Test-BRAVOCondition `
        -Condition $cpReady `
        -Name "Framework/AffectedChangedPath.FunctionsExist" `
        -Failure "ci\BRAVOChangedPath.ps1 мусить існувати й визначати Invoke-BRAVOGitCommand та Get-BRAVOChangedPathSet (канонічний git-збирач Affected); файл знайдено: $([IO.File]::Exists($cpPath))"

    if ($cpReady) {
        $cpNul = [string][char]0
        $cpSha1 = 'a' * 40
        $cpSha2 = 'b' * 40
        $cpMismatch = New-Object System.Collections.Generic.List[string]
        $cpCheck = {
            param([string]$Id, [bool]$Condition)
            if (-not $Condition) { [void]$cpMismatch.Add($Id) }
        }
        $cpTake = {
            $taken = [string]::Join('; ', @($cpMismatch.ToArray() | Select-Object -First 8))
            $cpMismatch.Clear()
            return $taken
        }
        $cpHas = {
            param($Set, [string]$Value)
            foreach ($member in @($Set)) {
                if ([string]::Equals([string]$member, $Value, [StringComparison]::Ordinal)) { return $true }
            }
            return $false
        }

        # --- [I]: fake-git за ін'єкцією -GitInvoker ----------------------------
        $cpFakeRoot = Join-Path ([IO.Path]::GetTempPath()) ('BRAVO_CHANGEDPATH_FAKE_' + [guid]::NewGuid().ToString('N'))
        $cpEmptyRoot = Join-Path ([IO.Path]::GetTempPath()) ('BRAVO_CHANGEDPATH_EMPTY_' + [guid]::NewGuid().ToString('N'))
        $cpManifestCurrent = '{"current":true}'
        $cpFakeCalls = New-Object System.Collections.Generic.List[string]
        $cpFakeResponses = @{}
        $cpFakeKind = {
            param([string[]]$Argument)
            if ($Argument -contains 'diff') { return 'diff' }
            if ($Argument -contains 'ls-files') { return 'untracked' }
            if ($Argument -contains 'status') { return 'status' }
            if ($Argument -contains 'merge-base') { return 'mergebase' }
            if ($Argument -contains 'show') { return 'show' }
            if ($Argument -contains '--show-toplevel') { return 'toplevel' }
            if ($Argument -contains '--is-shallow-repository') { return 'shallow' }
            if ($Argument -contains 'HEAD^{commit}') { return 'head' }
            return 'base'
        }
        $cpFakeDefaults = {
            return @{
                toplevel  = @{ ExitCode = 0; StdOut = ($cpFakeRoot + "`n"); StdErr = '' }
                shallow   = @{ ExitCode = 0; StdOut = "false`n"; StdErr = '' }
                base      = @{ ExitCode = 0; StdOut = ($cpSha1 + "`n"); StdErr = '' }
                head      = @{ ExitCode = 0; StdOut = ($cpSha2 + "`n"); StdErr = '' }
                mergebase = @{ ExitCode = 0; StdOut = ($cpSha1 + "`n"); StdErr = '' }
                diff      = @{ ExitCode = 0; StdOut = ('M' + $cpNul + 'docs/a.md' + $cpNul); StdErr = '' }
                untracked = @{ ExitCode = 0; StdOut = ('docs/b.md' + $cpNul); StdErr = '' }
                show      = @{ ExitCode = 0; StdOut = '{"base":true}'; StdErr = '' }
                status    = @{ ExitCode = 0; StdOut = (' M docs/a.md' + $cpNul); StdErr = '' }
            }
        }
        # Відповідь-рядок означає виняток запуску (симуляція Process.Start).
        $cpFakeInvoker = {
            param([string[]]$Argument)
            [void]$cpFakeCalls.Add([string]::Join(' ', $Argument))
            $fakeKind = & $cpFakeKind $Argument
            $fakeResponse = $cpFakeResponses[$fakeKind]
            if ($fakeResponse -is [string]) { throw $fakeResponse }
            return $fakeResponse
        }
        $cpRun = {
            param([hashtable]$Override = @{}, [string]$BaseRef = 'main', [string]$Root = $cpFakeRoot)
            $cpFakeCalls.Clear()
            $cpFakeResponses = & $cpFakeDefaults
            foreach ($overrideKey in @($Override.Keys)) { $cpFakeResponses[$overrideKey] = $Override[$overrideKey] }
            return (Get-BRAVOChangedPathSet -RepositoryRoot $Root -BaseRef $BaseRef -GitInvoker $cpFakeInvoker)
        }
        $cpReply = {
            param([int]$Code, [string]$Out = '', [string]$Err = '')
            return @{ ExitCode = $Code; StdOut = $Out; StdErr = $Err }
        }

        try {
            [void][IO.Directory]::CreateDirectory($cpFakeRoot)
            [void][IO.Directory]::CreateDirectory($cpEmptyRoot)
            [IO.File]::WriteAllText((Join-Path $cpFakeRoot 'RUNTIME_MANIFEST.json'), $cpManifestCurrent, (New-Object System.Text.UTF8Encoding -ArgumentList $false))

            # C6: порожня база - жодного виклику git.
            foreach ($cpMissing in @('', '  ', [string]$null, "`t", "`r`n")) {
                $cpResult = & $cpRun @{} $cpMissing
                & $cpCheck ('missing[' + $cpMissing.Length + ']') ($cpResult.Status -ceq 'BASE-MISSING' -and $cpFakeCalls.Count -eq 0)
            }
            $cpProblem = & $cpTake
            Test-BRAVOCondition `
                -Condition ($cpProblem.Length -eq 0) `
                -Name "Framework/AffectedChangedPath.MissingBaseNeverCallsGit" `
                -Failure ("порожній BaseRef (порожній рядок, пробіли, `$null) мусить давати BASE-MISSING без жодного виклику git: " + $cpProblem)

            # C5 [I]: форма BaseRef поза allowlist - BASE-INVALID до будь-якого виклику git.
            foreach ($cpInvalid in @('-x', '--help', '--output=x', 'a b', 'a;b', ' main', 'main ', "main`n", 'a|b', 'a$b', 'a"b', "a`0b", 'a\b', 'a`b', 'a&b', 'a*b', 'a:b')) {
                $cpResult = & $cpRun @{} $cpInvalid
                & $cpCheck ('invalid[' + $cpInvalid.Replace("`n", '\n').Replace("`0", '\0') + ']') ($cpResult.Status -ceq 'BASE-INVALID' -and $cpFakeCalls.Count -eq 0)
            }
            foreach ($cpValid in @('main', 'origin/main', 'HEAD~1', 'HEAD^', 'v1.2.3', '@{u}', 'feature/x-y_z.1', 'a1b2c3d')) {
                $cpResult = & $cpRun @{} $cpValid
                & $cpCheck ('valid[' + $cpValid + ']') ($cpResult.Status -ceq 'Ok')
            }
            $cpResult = & $cpRun @{ base = (& $cpReply 1) } 'no-such-ref'
            & $cpCheck 'base exit 1' ($cpResult.Status -ceq 'BASE-INVALID')
            $cpProblem = & $cpTake
            Test-BRAVOCondition `
                -Condition ($cpProblem.Length -eq 0) `
                -Name "Framework/AffectedChangedPath.InvalidBaseRefNeverReachesGit" `
                -Failure ("BaseRef поза allowlist (початок з '-', пробіли, метасимволи, `\`) мусить давати BASE-INVALID без виклику git, допустимі форми проходять, а код 1 від rev-parse --verify означає BASE-INVALID: " + $cpProblem)

            # Фіксований контракт викликів: порядок, прапорці, відсутність 2>&1 тощо.
            $cpResult = & $cpRun @{} 'main'
            $cpExpectedCalls = @(
                'rev-parse --show-toplevel',
                'rev-parse --is-shallow-repository',
                'rev-parse --verify --quiet main^{commit}',
                'rev-parse --verify --quiet HEAD^{commit}',
                ('merge-base ' + $cpSha1 + ' ' + $cpSha2),
                ('-c core.quotepath=off diff --no-renames --name-status -z --no-ext-diff ' + $cpSha1 + ' --'),
                'ls-files --others --exclude-standard -z',
                'status --porcelain=v1 -z --untracked-files=all')
            $cpActualCalls = [string]::Join("`n", $cpFakeCalls.ToArray())
            Test-BRAVOCondition `
                -Condition (
                    $cpResult.Status -ceq 'Ok' -and
                    $cpActualCalls -ceq [string]::Join("`n", $cpExpectedCalls) -and
                    $cpResult.BaseSha -ceq $cpSha1 -and $cpResult.HeadSha -ceq $cpSha2 -and $cpResult.MergeBaseSha -ceq $cpSha1 -and
                    $cpResult.Dirty -eq $true
                ) `
                -Name "Framework/AffectedChangedPath.GitCallContractIsPinned" `
                -Failure ("послідовність і аргументи викликів git мусять збігатися з A5 (show-toplevel, is-shallow, verify base, verify HEAD, merge-base, diff --no-renames --name-status -z --no-ext-diff <mb> --, ls-files --others --exclude-standard -z, status --porcelain=v1 -z --untracked-files=all). Фактично: " +
                    $cpActualCalls.Replace("`n", ' / ') + "; статус: $($cpResult.Status)")

            # C7: будь-який збій git - GIT-FAILED, ніколи не порожній diff.
            $cpFailCases = @(
                @{ Id = 'diff 128'; Key = 'diff'; Response = (& $cpReply 128 '' 'fatal: x') },
                @{ Id = 'diff odd tokens (1)'; Key = 'diff'; Response = (& $cpReply 0 ('M' + $cpNul)) },
                @{ Id = 'diff odd tokens (3)'; Key = 'diff'; Response = (& $cpReply 0 ('M' + $cpNul + 'a.md' + $cpNul + 'D' + $cpNul)) },
                @{ Id = 'diff bad status'; Key = 'diff'; Response = (& $cpReply 0 ('Z' + $cpNul + 'a.md' + $cpNul)) },
                @{ Id = 'diff rename status'; Key = 'diff'; Response = (& $cpReply 0 ('R100' + $cpNul + 'a.md' + $cpNul)) },
                @{ Id = 'merge-base 128'; Key = 'mergebase'; Response = (& $cpReply 128 '' 'fatal: y') },
                @{ Id = 'merge-base not sha'; Key = 'mergebase'; Response = (& $cpReply 0 'zzz') },
                @{ Id = 'merge-base 1 with output'; Key = 'mergebase'; Response = (& $cpReply 1 $cpSha1) },
                @{ Id = 'ls-files 128'; Key = 'untracked'; Response = (& $cpReply 128 '' 'fatal: z') },
                @{ Id = 'status 128'; Key = 'status'; Response = (& $cpReply 128 '' 'fatal: s') },
                @{ Id = 'shallow 128'; Key = 'shallow'; Response = (& $cpReply 128) },
                @{ Id = 'shallow garbage'; Key = 'shallow'; Response = (& $cpReply 0 'maybe') },
                @{ Id = 'shallow empty'; Key = 'shallow'; Response = (& $cpReply 0 '') },
                @{ Id = 'base 2'; Key = 'base'; Response = (& $cpReply 2) },
                @{ Id = 'base not sha'; Key = 'base'; Response = (& $cpReply 0 'xyz') },
                @{ Id = 'base empty'; Key = 'base'; Response = (& $cpReply 0 '') },
                @{ Id = 'head 128'; Key = 'head'; Response = (& $cpReply 128) },
                @{ Id = 'head not sha'; Key = 'head'; Response = (& $cpReply 0 'xyz') },
                @{ Id = 'toplevel empty output'; Key = 'toplevel'; Response = (& $cpReply 0 '') },
                @{ Id = 'toplevel invalid path'; Key = 'toplevel'; Response = (& $cpReply 0 "a`0b") })
            foreach ($cpCase in $cpFailCases) {
                $cpResult = & $cpRun @{ ($cpCase.Key) = $cpCase.Response }
                & $cpCheck $cpCase.Id (
                    $cpResult.Status -ceq 'GIT-FAILED' -and $cpResult.Status -cne 'EMPTY-DIFF' -and
                    -not [string]::IsNullOrEmpty([string]$cpResult.FailedCommand) -and @($cpResult.ChangedPath).Count -eq 0)
            }
            $cpProblem = & $cpTake
            Test-BRAVOCondition `
                -Condition ($cpProblem.Length -eq 0) `
                -Name "Framework/AffectedChangedPath.GitFailureNeverBecomesEmptyDiff" `
                -Failure ("ненульовий код git, непарна кількість NUL-токенів, невірна форма виводу мусять давати GIT-FAILED із заповненим FailedCommand і порожнім ChangedPath, а не EMPTY-DIFF: " + $cpProblem)

            # C8: виняток запуску (Process.Start) - теж GIT-FAILED.
            foreach ($cpThrowKey in @('toplevel', 'shallow', 'base', 'head', 'mergebase', 'diff', 'untracked', 'status')) {
                $cpResult = & $cpRun @{ $cpThrowKey = 'simulated start failure' }
                & $cpCheck ('throw ' + $cpThrowKey) (
                    $cpResult.Status -ceq 'GIT-FAILED' -and -not [string]::IsNullOrEmpty([string]$cpResult.FailedCommand) -and @($cpResult.ChangedPath).Count -eq 0)
            }
            $cpManifestDiff = (& $cpReply 0 ('M' + $cpNul + 'RUNTIME_MANIFEST.json' + $cpNul + 'M' + $cpNul + 'docs/a.md' + $cpNul))
            $cpResult = & $cpRun @{ diff = $cpManifestDiff; show = 'simulated start failure' }
            & $cpCheck 'throw show' ($cpResult.Status -ceq 'GIT-FAILED' -and @($cpResult.ChangedPath).Count -eq 0)
            $cpProblem = & $cpTake
            Test-BRAVOCondition `
                -Condition ($cpProblem.Length -eq 0) `
                -Name "Framework/AffectedChangedPath.ProcessStartFailureIsGitFailed" `
                -Failure ("виняток запуску git на будь-якому кроці мусить давати GIT-FAILED (invoker, що кидає виняток, симулює Process.Start): " + $cpProblem)

            # C9: stderr з кодом 0 не робить виклик невдалим.
            $cpWarn = 'warning: in the working copy of x, LF will be replaced by CRLF'
            $cpResult = & $cpRun @{
                diff      = (& $cpReply 0 ('M' + $cpNul + 'docs/a.md' + $cpNul) $cpWarn)
                untracked = (& $cpReply 0 ('docs/b.md' + $cpNul) $cpWarn)
                status    = (& $cpReply 0 (' M docs/a.md' + $cpNul) $cpWarn)
                toplevel  = (& $cpReply 0 ($cpFakeRoot + "`n") $cpWarn)
            }
            Test-BRAVOCondition `
                -Condition (
                    $cpResult.Status -ceq 'Ok' -and
                    (& $cpHas $cpResult.ChangedPath 'docs/a.md') -and (& $cpHas $cpResult.ChangedPath 'docs/b.md')
                ) `
                -Name "Framework/AffectedChangedPath.StderrWarningWithExitZeroIsNotAFailure" `
                -Failure "код 0 зі stderr 'warning: ...' - успіх: шляхи беруться зі stdout, stderr не розбирається і не змішується зі stdout; статус: $($cpResult.Status)"

            # C10: git не знайдено.
            $cpBogusGit = 'bravo-no-such-git-' + [guid]::NewGuid().ToString('N')
            $cpResult = Get-BRAVOChangedPathSet -RepositoryRoot $cpFakeRoot -BaseRef 'main' -GitCommandName $cpBogusGit
            $cpRunner = Invoke-BRAVOGitCommand -RepositoryRoot $cpFakeRoot -Argument @('--version') -GitCommandName $cpBogusGit
            $cpUnavailable = Get-BRAVOChangedPathSet -RepositoryRoot $cpFakeRoot -BaseRef 'main' -GitInvoker { param([string[]]$Argument) return @{ Available = $false; ExitCode = $null; StdOut = ''; StdErr = '' } }
            Test-BRAVOCondition `
                -Condition (
                    $cpResult.Status -ceq 'GIT-MISSING' -and @($cpResult.ChangedPath).Count -eq 0 -and
                    $cpRunner.Available -eq $false -and $null -eq $cpRunner.ExitCode -and
                    $cpUnavailable.Status -ceq 'GIT-MISSING'
                ) `
                -Name "Framework/AffectedChangedPath.MissingGitIsReported" `
                -Failure "неіснуюча команда git (і invoker з Available=`$false) мусить давати GIT-MISSING, а Invoke-BRAVOGitCommand - Available=`$false без винятку; статус: $($cpResult.Status)/$($cpUnavailable.Status)"

            # C15, C16: shallow і невідповідність кореня.
            $cpResult = & $cpRun @{ shallow = (& $cpReply 0 "true`n") }
            & $cpCheck 'shallow true' ($cpResult.Status -ceq 'SHALLOW-REPOSITORY')
            $cpResult = & $cpRun @{ toplevel = (& $cpReply 0 "C:/other`n") }
            & $cpCheck 'root mismatch' ($cpResult.Status -ceq 'ROOT-MISMATCH')
            foreach ($cpRootForm in @(
                    ($cpFakeRoot + "`r`n"),
                    ($cpFakeRoot + '/' + "`n"),
                    ($cpFakeRoot.ToUpperInvariant() + "`n"),
                    ($cpFakeRoot.Replace('\', '/') + "`n"))) {
                $cpResult = & $cpRun @{ toplevel = (& $cpReply 0 $cpRootForm) }
                & $cpCheck ('root form ' + $cpRootForm.Replace("`r", '\r').Replace("`n", '\n')) ($cpResult.Status -ceq 'Ok')
            }
            $cpProblem = & $cpTake
            Test-BRAVOCondition `
                -Condition ($cpProblem.Length -eq 0) `
                -Name "Framework/AffectedChangedPath.ShallowAndRootMismatchFailClosed" `
                -Failure ("is-shallow=true дає SHALLOW-REPOSITORY, корінь, що не збігається після GetFullPath (без урахування регістру), дає ROOT-MISMATCH, а косі риски, завершальний роздільник, CRLF і регістр кореня не є розбіжністю: " + $cpProblem)

            # C17 [I]: NO-MERGE-BASE і NotARepository (+ підказка safe.directory).
            $cpResult = & $cpRun @{ mergebase = (& $cpReply 1) }
            & $cpCheck 'no merge-base' ($cpResult.Status -ceq 'NO-MERGE-BASE' -and @($cpResult.ChangedPath).Count -eq 0)
            $cpResult = & $cpRun @{ mergebase = (& $cpReply 128 '' 'fatal: q') }
            & $cpCheck 'merge-base 128' ($cpResult.Status -ceq 'GIT-FAILED')
            $cpResult = & $cpRun @{ toplevel = (& $cpReply 128 '' 'fatal: not a git repository (or any of the parent directories): .git') }
            & $cpCheck 'not a repository' ($cpResult.Status -ceq 'NOT-A-REPOSITORY' -and ([string]$cpResult.Message).IndexOf('safe.directory', [StringComparison]::Ordinal) -lt 0)
            $cpDubious = "fatal: detected dubious ownership in repository at 'X'`nTo add an exception for this directory, call:`n`n`tgit config --global --add safe.directory X"
            $cpResult = & $cpRun @{ toplevel = (& $cpReply 128 '' $cpDubious) }
            & $cpCheck 'dubious ownership' (
                $cpResult.Status -ceq 'NOT-A-REPOSITORY' -and @($cpResult.ChangedPath).Count -eq 0 -and
                ([string]$cpResult.Message).IndexOf('safe.directory', [StringComparison]::Ordinal) -ge 0)
            $cpProblem = & $cpTake
            Test-BRAVOCondition `
                -Condition ($cpProblem.Length -eq 0) `
                -Name "Framework/AffectedChangedPath.NoMergeBaseAndNotARepositoryStatuses" `
                -Failure ("merge-base з кодом 1 і порожнім виводом дає NO-MERGE-BASE (код 128 - GIT-FAILED); show-toplevel з кодом != 0 дає NOT-A-REPOSITORY, а за dubious ownership статус лишається тим самим, але Message містить підказку safe.directory: " + $cpProblem)

            # C22, C23 [I]: дедуплікація Ordinal, детермінований порядок, без обрізання.
            $cpOrderA = & $cpRun @{
                diff      = (& $cpReply 0 ('M' + $cpNul + 'docs/z.md' + $cpNul + 'M' + $cpNul + 'docs/a.md' + $cpNul))
                untracked = (& $cpReply 0 ('docs/a.md' + $cpNul + 'Docs/A.md' + $cpNul + 'docs/b.md' + $cpNul))
            }
            $cpOrderB = & $cpRun @{
                diff      = (& $cpReply 0 ('M' + $cpNul + 'docs/a.md' + $cpNul + 'M' + $cpNul + 'docs/z.md' + $cpNul))
                untracked = (& $cpReply 0 ('docs/b.md' + $cpNul + 'docs/a.md' + $cpNul + 'Docs/A.md' + $cpNul))
            }
            $cpExpectedOrder = 'Docs/A.md|docs/a.md|docs/b.md|docs/z.md'
            $cpSpaces = & $cpRun @{
                diff      = (& $cpReply 0 ('M' + $cpNul + ' a.txt' + $cpNul))
                untracked = (& $cpReply 0 ('b.txt ' + $cpNul + ' c d ' + $cpNul))
            }
            Test-BRAVOCondition `
                -Condition (
                    $cpOrderA.Status -ceq 'Ok' -and
                    [string]::Join('|', @($cpOrderA.ChangedPath)) -ceq $cpExpectedOrder -and
                    [string]::Join('|', @($cpOrderB.ChangedPath)) -ceq $cpExpectedOrder -and
                    $cpSpaces.Status -ceq 'Ok' -and
                    [string]::Join('|', @($cpSpaces.ChangedPath)) -ceq ' a.txt| c d |b.txt '
                ) `
                -Name "Framework/AffectedChangedPath.DuplicatesDedupedOrdinalAndNeverTrimmed" `
                -Failure ("дубль із tracked і untracked джерел - рівно один раз, порядок Ordinal не залежить від порядку входу, шляхи з пробілами по краях повертаються дослівно. Фактично: '" +
                    [string]::Join('|', @($cpOrderA.ChangedPath)) + "' / '" + [string]::Join('|', @($cpOrderB.ChangedPath)) + "' / '" + [string]::Join('|', @($cpSpaces.ChangedPath)) + "'")

            # D потрапляє і в ChangedPath, і в DeletedPath.
            $cpDeleted = & $cpRun @{
                diff = (& $cpReply 0 ('D' + $cpNul + 'docs/gone.md' + $cpNul + 'M' + $cpNul + 'docs/a.md' + $cpNul + 'D' + $cpNul + 'docs/gone.md' + $cpNul))
            }
            Test-BRAVOCondition `
                -Condition (
                    $cpDeleted.Status -ceq 'Ok' -and
                    (& $cpHas $cpDeleted.ChangedPath 'docs/gone.md') -and (& $cpHas $cpDeleted.ChangedPath 'docs/a.md') -and
                    [string]::Join('|', @($cpDeleted.DeletedPath)) -ceq 'docs/gone.md' -and
                    @($cpDeleted.ChangedPath).Count -eq 3
                ) `
                -Name "Framework/AffectedChangedPath.DeletedPathIsAlsoChangedPath" `
                -Failure "видалений файл (статус D) мусить бути і в ChangedPath, і в DeletedPath (без дублів), а змінений - лише в ChangedPath; фактично: Changed='$([string]::Join('|', @($cpDeleted.ChangedPath)))' Deleted='$([string]::Join('|', @($cpDeleted.DeletedPath)))'"

            # C21 [I]: тексти супутнього RUNTIME_MANIFEST.json.
            $cpWithManifest = & $cpRun @{ diff = $cpManifestDiff; show = (& $cpReply 0 ('{"base":true}' + "`r`n")) }
            $cpShowCalls = @($cpFakeCalls.ToArray() | Where-Object { $_ -ceq ('show ' + $cpSha1 + ':RUNTIME_MANIFEST.json') })
            $cpShowFailed = & $cpRun @{ diff = $cpManifestDiff; show = (& $cpReply 128 '' 'fatal: path does not exist') }
            $cpShowOne = & $cpRun @{ diff = $cpManifestDiff; show = (& $cpReply 1) }
            $cpNoManifest = & $cpRun @{}
            $cpNoManifestShow = @($cpFakeCalls.ToArray() | Where-Object { $_.StartsWith('show ', [StringComparison]::Ordinal) })
            $cpManifestUntracked = & $cpRun @{ diff = (& $cpReply 0 ''); untracked = (& $cpReply 0 ('RUNTIME_MANIFEST.json' + $cpNul)); show = (& $cpReply 128) }
            $cpManifestDeleted = & $cpRun @{ diff = (& $cpReply 0 ('D' + $cpNul + 'RUNTIME_MANIFEST.json' + $cpNul)); toplevel = (& $cpReply 0 ($cpEmptyRoot + "`n")) } 'main' $cpEmptyRoot
            Test-BRAVOCondition `
                -Condition (
                    $cpWithManifest.Status -ceq 'Ok' -and
                    $cpWithManifest.RuntimeManifestBaseText -ceq ('{"base":true}' + "`r`n") -and
                    $cpWithManifest.RuntimeManifestCurrentText -ceq $cpManifestCurrent -and
                    $cpShowCalls.Count -eq 1 -and
                    $cpShowFailed.Status -ceq 'Ok' -and $null -eq $cpShowFailed.RuntimeManifestBaseText -and $cpShowFailed.RuntimeManifestCurrentText -ceq $cpManifestCurrent -and
                    $cpShowOne.Status -ceq 'Ok' -and $null -eq $cpShowOne.RuntimeManifestBaseText -and
                    $cpNoManifest.Status -ceq 'Ok' -and $null -eq $cpNoManifest.RuntimeManifestBaseText -and $null -eq $cpNoManifest.RuntimeManifestCurrentText -and
                    $cpNoManifestShow.Count -eq 0 -and
                    $cpManifestUntracked.Status -ceq 'Ok' -and $null -eq $cpManifestUntracked.RuntimeManifestBaseText -and $cpManifestUntracked.RuntimeManifestCurrentText -ceq $cpManifestCurrent -and
                    $cpManifestDeleted.Status -ceq 'Ok' -and $null -eq $cpManifestDeleted.RuntimeManifestCurrentText
                ) `
                -Name "Framework/AffectedChangedPath.ManifestCompanionTextsComeFromMergeBaseAndDisk" `
                -Failure "RuntimeManifestBaseText береться з 'git show <merge-base>:RUNTIME_MANIFEST.json' дослівно (код != 0 -> `$null), CurrentText - з диска (немає файлу -> `$null); без маніфесту в наборі обидва `$null і git show не викликається"

            # BASE-EQUALS-HEAD / EMPTY-DIFF / Dirty.
            $cpEmptyAll = @{ diff = (& $cpReply 0 ''); untracked = (& $cpReply 0 ''); status = (& $cpReply 0 '') }
            $cpSame = & $cpRun (@{ head = (& $cpReply 0 ($cpSha1 + "`n")) } + $cpEmptyAll)
            $cpDiffer = & $cpRun $cpEmptyAll
            $cpSameDirty = & $cpRun @{ head = (& $cpReply 0 ($cpSha1 + "`n")); diff = (& $cpReply 0 ''); untracked = (& $cpReply 0 ('x.md' + $cpNul)) }
            Test-BRAVOCondition `
                -Condition (
                    $cpSame.Status -ceq 'BASE-EQUALS-HEAD' -and $cpSame.Dirty -eq $false -and @($cpSame.ChangedPath).Count -eq 0 -and
                    $cpDiffer.Status -ceq 'EMPTY-DIFF' -and $cpDiffer.Dirty -eq $false -and
                    $cpSameDirty.Status -ceq 'Ok' -and $cpSameDirty.Dirty -eq $true
                ) `
                -Name "Framework/AffectedChangedPath.EmptySetIsClassifiedNotAccepted" `
                -Failure "порожній набір: однакові BaseSha і HeadSha - BASE-EQUALS-HEAD, різні - EMPTY-DIFF; за наявності untracked-файлів набір не порожній (Ok, Dirty=`$true); фактично: $($cpSame.Status)/$($cpDiffer.Status)/$($cpSameDirty.Status)"

            # Контракт invoker-а: об'єкт, hashtable, зіпсовані відповіді.
            $cpObjectInvoker = {
                param([string[]]$Argument)
                $plain = & $cpFakeInvoker $Argument
                return [pscustomobject]@{ ExitCode = $plain.ExitCode; StdOut = $plain.StdOut; StdErr = $plain.StdErr }
            }
            $cpFakeCalls.Clear()
            $cpFakeResponses = & $cpFakeDefaults
            $cpViaObject = Get-BRAVOChangedPathSet -RepositoryRoot $cpFakeRoot -BaseRef 'main' -GitInvoker $cpObjectInvoker
            $cpBadInvokers = @(
                @{ Id = 'null'; Invoker = { param([string[]]$Argument) return $null } },
                @{ Id = 'no ExitCode'; Invoker = { param([string[]]$Argument) return @{ StdOut = ''; StdErr = '' } } },
                @{ Id = 'text ExitCode'; Invoker = { param([string[]]$Argument) return @{ ExitCode = 'zero'; StdOut = ''; StdErr = '' } } },
                @{ Id = 'two objects'; Invoker = { param([string[]]$Argument) return @(@{ ExitCode = 0; StdOut = ''; StdErr = '' }, @{ ExitCode = 0; StdOut = ''; StdErr = '' }) } },
                @{ Id = 'throws'; Invoker = { param([string[]]$Argument) throw 'boom' } })
            foreach ($cpBad in $cpBadInvokers) {
                $cpResult = Get-BRAVOChangedPathSet -RepositoryRoot $cpFakeRoot -BaseRef 'main' -GitInvoker $cpBad.Invoker
                & $cpCheck ('bad invoker ' + $cpBad.Id) ($cpResult.Status -ceq 'GIT-FAILED' -and @($cpResult.ChangedPath).Count -eq 0)
            }
            $cpProblem = & $cpTake
            Test-BRAVOCondition `
                -Condition ($cpViaObject.Status -ceq 'Ok' -and $cpProblem.Length -eq 0) `
                -Name "Framework/AffectedChangedPath.InvokerResultShapeIsValidated" `
                -Failure ("invoker повертає {ExitCode; StdOut; StdErr} (об'єкт чи hashtable) або кидає виняток; відсутній чи нечисловий ExitCode, `$null і кілька об'єктів - GIT-FAILED. Об'єкт: $($cpViaObject.Status); " + $cpProblem)

            # Форма результату.
            $cpResult = & $cpRun @{}
            $cpResultNames = @($cpResult.PSObject.Properties | ForEach-Object { $_.Name })
            $cpMissingNames = @('Status', 'BaseSha', 'HeadSha', 'MergeBaseSha', 'Dirty', 'ChangedPath', 'DeletedPath',
                'RuntimeManifestBaseText', 'RuntimeManifestCurrentText', 'FailedCommand', 'ExitCode') | Where-Object { $cpResultNames -cnotcontains $_ }
            $cpFailed = & $cpRun @{ diff = (& $cpReply 128) }
            Test-BRAVOCondition `
                -Condition (
                    @($cpMissingNames).Count -eq 0 -and
                    $cpResult.ChangedPath -is [string[]] -and $cpResult.DeletedPath -is [string[]] -and
                    $cpFailed.ChangedPath -is [string[]] -and $cpFailed.DeletedPath -is [string[]] -and
                    $cpFailed.ExitCode -eq 128 -and $cpFailed.FailedCommand.Contains('diff')
                ) `
                -Name "Framework/AffectedChangedPath.ResultShapeIsStable" `
                -Failure ("результат мусить мати поля Status, BaseSha, HeadSha, MergeBaseSha, Dirty, ChangedPath, DeletedPath, RuntimeManifestBaseText, RuntimeManifestCurrentText, FailedCommand, ExitCode; шляхи - завжди [string[]] (також при збої); бракує: " +
                    [string]::Join(', ', @($cpMissingNames)))
        } finally {
            Remove-Item -LiteralPath $cpFakeRoot -Recurse -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath $cpEmptyRoot -Recurse -Force -ErrorAction SilentlyContinue
        }

        # --- [T]: тимчасові репозиторії -------------------------------------
        $cpT = @{}
        $cpTNote = @{}
        $cpGitCommand = @(Get-Command -Name 'git' -CommandType Application -ErrorAction SilentlyContinue)
        $cpRunReal = ((Test-Path -LiteralPath (Join-Path $root '.git')) -and $cpGitCommand.Count -gt 0)
        $cpTOk = {
            param([string]$Key)
            return ($cpT.ContainsKey($Key) -and $cpT[$Key] -eq $true)
        }
        $cpTWhy = {
            param([string]$Key)
            if ($cpTNote.ContainsKey($Key)) { return [string]$cpTNote[$Key] }
            return 'сценарій не виконано'
        }
        $cpGit = {
            param([string]$Dir, [string[]]$GitArgument)
            $fullArgument = @('-c', 'user.name=Test Author', '-c', 'user.email=test@example.invalid', '-c', 'core.autocrlf=false', '-c', 'core.quotepath=true') + $GitArgument
            return (Invoke-BRAVOGitCommand -RepositoryRoot $Dir -Argument $fullArgument)
        }
        $cpGitOk = {
            param([string]$Dir, [string[]]$GitArgument)
            $gitRun = & $cpGit $Dir $GitArgument
            if (-not ($gitRun.Available -and $null -ne $gitRun.ExitCode -and $gitRun.ExitCode -eq 0)) {
                throw ('git ' + [string]::Join(' ', $GitArgument) + ' завершився з помилкою: ' + [string]$gitRun.StdErr + [string]$gitRun.StartError)
            }
            return ($gitRun.StdOut -replace '[\r\n]+\z', '')
        }
        $cpWrite = {
            param([string]$Dir, [string]$Relative, [string]$Text)
            $target = Join-Path $Dir $Relative
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target))
            [IO.File]::WriteAllText($target, $Text, (New-Object System.Text.UTF8Encoding -ArgumentList $false))
        }
        $cpCommit = {
            param([string]$Dir, [string]$Message)
            $null = & $cpGitOk $Dir @('add', '-A')
            $null = & $cpGitOk $Dir @('commit', '--quiet', '-m', $Message)
        }
        $cpInit = {
            param([string]$Dir)
            $null = & $cpGitOk $Dir @('-c', 'init.defaultBranch=master', 'init', '--quiet')
        }
        $cpWithRepo = {
            param([string]$Key, [scriptblock]$Body)
            $repoDir = Join-Path ([IO.Path]::GetTempPath()) ('BRAVO_CHANGEDPATH_' + [guid]::NewGuid().ToString('N'))
            try {
                [void][IO.Directory]::CreateDirectory($repoDir)
                & $Body $repoDir
            } catch {
                $cpTNote[$Key] = 'виняток сценарію: ' + $_.Exception.Message
            } finally {
                Remove-Item -LiteralPath $repoDir -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        $cpCyr1 = 'документ'
        $cpCyr2 = 'мій новий'

        if ($cpRunReal) {
            # Рядок запуску: потоки розділені, stderr не стає помилкою під Stop, збій запуску - не виняток.
            & $cpWithRepo 'Runner' {
                param([string]$Dir)
                $previousPreference = $ErrorActionPreference
                $ErrorActionPreference = 'Stop'
                try {
                    $versionRun = Invoke-BRAVOGitCommand -RepositoryRoot $Dir -Argument @('--version')
                    $stderrRun = Invoke-BRAVOGitCommand -RepositoryRoot $Dir -Argument @('--bravo-no-such-option')
                    $startRun = Invoke-BRAVOGitCommand -RepositoryRoot (Join-Path $Dir 'no-such-subdirectory') -Argument @('--version')
                } finally {
                    $ErrorActionPreference = $previousPreference
                }
                $cpT['Runner'] = (
                    $versionRun.Available -eq $true -and $versionRun.ExitCode -eq 0 -and $versionRun.StdOut.StartsWith('git version', [StringComparison]::Ordinal) -and
                    $stderrRun.Available -eq $true -and $null -ne $stderrRun.ExitCode -and $stderrRun.ExitCode -ne 0 -and
                    $stderrRun.StdOut.Length -eq 0 -and $stderrRun.StdErr.Length -gt 0 -and
                    $startRun.Available -eq $true -and $null -eq $startRun.ExitCode -and -not [string]::IsNullOrEmpty([string]$startRun.StartError))
                $cpTNote['Runner'] = "version=$($versionRun.ExitCode); stderrRun=$($stderrRun.ExitCode)/out$($stderrRun.StdOut.Length)/err$($stderrRun.StdErr.Length); start=$($startRun.ExitCode)/$($startRun.StartError)"
            }

            # Основний репозиторій: C1-C4, C13, C14, C19, C20, C23.
            & $cpWithRepo 'Main' {
                param([string]$Dir)
                & $cpInit $Dir
                & $cpWrite $Dir 'docs/keep.md' 'keep'
                & $cpWrite $Dir 'docs/mod.md' 'one'
                & $cpWrite $Dir 'docs/del.md' 'del'
                & $cpWrite $Dir 'docs/ren-old.md' 'ren'
                & $cpWrite $Dir 'docs/my doc.md' 'sp1'
                & $cpWrite $Dir ('docs/' + $cpCyr1 + '.md') 'cy1'
                & $cpWrite $Dir '.gitignore' ("ignored/`n")
                & $cpCommit $Dir 'base'
                $baseSha = & $cpGitOk $Dir @('rev-parse', 'HEAD')

                & $cpWrite $Dir 'docs/added.md' 'added'
                $null = & $cpGitOk $Dir @('add', 'docs/added.md')
                & $cpWrite $Dir 'docs/untracked.md' 'u'
                & $cpWrite $Dir 'docs/mod.md' 'two'
                $null = & $cpGitOk $Dir @('add', 'docs/mod.md')
                & $cpWrite $Dir 'docs/mod.md' 'three'
                $null = & $cpGitOk $Dir @('rm', '--quiet', 'docs/del.md')
                $null = & $cpGitOk $Dir @('mv', 'docs/ren-old.md', 'docs/ren-new.md')
                & $cpWrite $Dir 'docs/my doc.md' 'sp2'
                & $cpWrite $Dir ('docs/' + $cpCyr1 + '.md') 'cy2'
                & $cpWrite $Dir ('docs/' + $cpCyr2 + '.md') 'cy3'
                & $cpWrite $Dir ' a.txt' 'lead'
                & $cpWrite $Dir 'ignored/x.md' 'ig'

                $mainResult = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef $baseSha
                $mainChanged = @($mainResult.ChangedPath)
                $mainDeleted = @($mainResult.DeletedPath)
                $cpTNote['Main'] = 'Status=' + $mainResult.Status + '; Message=' + [string]$mainResult.Message + '; Changed=' + [string]::Join('|', $mainChanged) + '; Deleted=' + [string]::Join('|', $mainDeleted)
                $cpT['Main'] = ($mainResult.Status -ceq 'Ok')
                $cpT['Added'] = ((& $cpHas $mainChanged 'docs/added.md') -and (& $cpHas $mainChanged 'docs/untracked.md'))
                $cpT['Modified'] = (@($mainChanged | Where-Object { $_ -ceq 'docs/mod.md' }).Count -eq 1 -and -not (& $cpHas $mainDeleted 'docs/mod.md'))
                $cpT['Deleted'] = ((& $cpHas $mainChanged 'docs/del.md') -and (& $cpHas $mainDeleted 'docs/del.md'))
                $cpT['Renamed'] = (
                    (& $cpHas $mainChanged 'docs/ren-old.md') -and (& $cpHas $mainChanged 'docs/ren-new.md') -and
                    (& $cpHas $mainDeleted 'docs/ren-old.md') -and -not (& $cpHas $mainDeleted 'docs/ren-new.md'))
                $cpT['Spaces'] = ((& $cpHas $mainChanged 'docs/my doc.md') -and @($mainChanged | Where-Object { $_.Contains('"') }).Count -eq 0)
                $cyrExpected = 'docs/' + $cpCyr1 + '.md'
                $cyrUntrackedExpected = 'docs/' + $cpCyr2 + '.md'
                $cyrFound = @($mainChanged | Where-Object { [string]::Equals($_, $cyrExpected, [StringComparison]::Ordinal) })
                $cpT['Cyrillic'] = (
                    $cyrFound.Count -eq 1 -and
                    [BitConverter]::ToString([Text.Encoding]::UTF8.GetBytes($cyrFound[0])) -ceq [BitConverter]::ToString([Text.Encoding]::UTF8.GetBytes($cyrExpected)) -and
                    (& $cpHas $mainChanged $cyrUntrackedExpected) -and
                    @($mainChanged | Where-Object { $_ -match '\\[0-7]{3}' -or $_.StartsWith('"', [StringComparison]::Ordinal) }).Count -eq 0)
                $cpT['NoTrim'] = ((& $cpHas $mainChanged ' a.txt') -and -not (& $cpHas $mainChanged 'a.txt'))
                $cpT['Ignored'] = (@($mainChanged | Where-Object { $_.StartsWith('ignored/', [StringComparison]::Ordinal) }).Count -eq 0 -and -not (& $cpHas $mainChanged '.gitignore'))
                $cpT['Dirty'] = (
                    $mainResult.Dirty -eq $true -and $mainResult.BaseSha -ceq $baseSha -and $mainResult.HeadSha -ceq $baseSha -and $mainResult.MergeBaseSha -ceq $baseSha)
                $expectedList = New-Object System.Collections.Generic.List[string]
                foreach ($expectedPath in @(' a.txt', 'docs/added.md', 'docs/del.md', 'docs/mod.md', 'docs/my doc.md', 'docs/ren-new.md', 'docs/ren-old.md', 'docs/untracked.md', $cyrExpected, $cyrUntrackedExpected)) {
                    [void]$expectedList.Add($expectedPath)
                }
                $expectedList.Sort([StringComparer]::Ordinal)
                $cpT['ExactSet'] = ([string]::Join("`n", $mainChanged) -ceq [string]::Join("`n", $expectedList.ToArray()) -and [string]::Join('|', $mainDeleted) -ceq 'docs/del.md|docs/ren-old.md')
            }

            # Історія: C5 [T], C11, C12, merge-base, C17 [T].
            & $cpWithRepo 'History' {
                param([string]$Dir)
                & $cpInit $Dir
                & $cpWrite $Dir 'a.md' 'one'
                & $cpCommit $Dir 'c1'
                $sha1 = & $cpGitOk $Dir @('rev-parse', 'HEAD')
                $equalsHead = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef 'HEAD'
                $equalsSha = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef $sha1
                $cpT['BaseEqualsHead'] = ($equalsHead.Status -ceq 'BASE-EQUALS-HEAD' -and $equalsSha.Status -ceq 'BASE-EQUALS-HEAD' -and $equalsHead.Dirty -eq $false -and @($equalsHead.ChangedPath).Count -eq 0)
                $cpTNote['BaseEqualsHead'] = "HEAD=$($equalsHead.Status); sha=$($equalsSha.Status); Dirty=$($equalsHead.Dirty)"

                $noRef = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef ('no-such-ref-' + [guid]::NewGuid().ToString('N'))
                $cpT['InvalidBase'] = ($noRef.Status -ceq 'BASE-INVALID' -and @($noRef.ChangedPath).Count -eq 0)
                $cpTNote['InvalidBase'] = "no-such-ref=$($noRef.Status)"

                $null = & $cpGitOk $Dir @('branch', 'side')
                $null = & $cpGitOk $Dir @('checkout', '--quiet', 'side')
                & $cpWrite $Dir 'side.md' 'side'
                & $cpCommit $Dir 'side'
                $sideSha = & $cpGitOk $Dir @('rev-parse', 'HEAD')
                $null = & $cpGitOk $Dir @('checkout', '--quiet', 'master')
                & $cpWrite $Dir 'a.md' 'two'
                & $cpWrite $Dir 'b.md' 'two'
                & $cpCommit $Dir 'c2'
                & $cpWrite $Dir 'a.md' 'one'
                $null = & $cpGitOk $Dir @('rm', '--quiet', 'b.md')
                & $cpCommit $Dir 'c3'
                $emptyDiff = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef $sha1
                $viaSide = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef 'side'
                $cpT['EmptyDiff'] = (
                    $emptyDiff.Status -ceq 'EMPTY-DIFF' -and @($emptyDiff.ChangedPath).Count -eq 0 -and $emptyDiff.Dirty -eq $false -and
                    $viaSide.Status -ceq 'EMPTY-DIFF' -and $viaSide.BaseSha -ceq $sideSha -and $viaSide.MergeBaseSha -ceq $sha1 -and $viaSide.HeadSha -cne $sha1)
                $cpTNote['EmptyDiff'] = "sha=$($emptyDiff.Status); side=$($viaSide.Status) base=$($viaSide.BaseSha) mb=$($viaSide.MergeBaseSha) paths=$([string]::Join('|', @($viaSide.ChangedPath)))"

                $null = & $cpGitOk $Dir @('checkout', '--quiet', '--orphan', 'orphan')
                & $cpWrite $Dir 'o.md' 'orphan'
                & $cpCommit $Dir 'root2'
                $orphan = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef $sha1
                $cpT['NoMergeBase'] = ($orphan.Status -ceq 'NO-MERGE-BASE' -and @($orphan.ChangedPath).Count -eq 0)
                $cpTNote['NoMergeBase'] = "orphan=$($orphan.Status) $($orphan.FailedCommand)"
            }

            # Каталог без git init: C18.
            & $cpWithRepo 'NotARepository' {
                param([string]$Dir)
                $parentProbe = Invoke-BRAVOGitCommand -RepositoryRoot ([IO.Path]::GetDirectoryName($Dir)) -Argument @('rev-parse', '--is-inside-work-tree')
                $parentInsideRepo = ($parentProbe.Available -and $null -ne $parentProbe.ExitCode -and $parentProbe.ExitCode -eq 0 -and $parentProbe.StdOut.StartsWith('true', [StringComparison]::Ordinal))
                $notRepo = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef 'main'
                $cpT['NotARepository'] = ($notRepo.Status -ceq 'NOT-A-REPOSITORY' -and @($notRepo.ChangedPath).Count -eq 0)
                $cpTNote['NotARepository'] = "status=$($notRepo.Status); $($notRepo.Message)"
                if ($parentInsideRepo) {
                    $cpTNote['NotARepository'] += '; ПЕРЕДУМОВА НЕ ВИКОНАНА: батьківський каталог тимчасового каталогу сам лежить усередині git-робочого дерева (TEMP у репозиторії), тому NOT-A-REPOSITORY недосяжний'
                }
            }

            # Супутній маніфест: C21 [T].
            & $cpWithRepo 'Manifest' {
                param([string]$Dir)
                & $cpInit $Dir
                & $cpWrite $Dir 'x.md' 'x'
                & $cpCommit $Dir 'base'
                $baseSha = & $cpGitOk $Dir @('rev-parse', 'HEAD')
                & $cpWrite $Dir 'RUNTIME_MANIFEST.json' '{"v":1}'
                $untrackedManifest = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef $baseSha
                & $cpCommit $Dir 'manifest'
                $manifestSha = & $cpGitOk $Dir @('rev-parse', 'HEAD')
                & $cpWrite $Dir 'RUNTIME_MANIFEST.json' '{"v":2}'
                $changedManifest = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef $manifestSha
                $null = & $cpGitOk $Dir @('checkout', '--quiet', '--', 'RUNTIME_MANIFEST.json')
                & $cpWrite $Dir 'x.md' 'y'
                $withoutManifest = Get-BRAVOChangedPathSet -RepositoryRoot $Dir -BaseRef $manifestSha
                $cpT['Manifest'] = (
                    $untrackedManifest.Status -ceq 'Ok' -and $null -eq $untrackedManifest.RuntimeManifestBaseText -and $untrackedManifest.RuntimeManifestCurrentText -ceq '{"v":1}' -and
                    $changedManifest.Status -ceq 'Ok' -and $changedManifest.RuntimeManifestBaseText -ceq '{"v":1}' -and $changedManifest.RuntimeManifestCurrentText -ceq '{"v":2}' -and
                    $withoutManifest.Status -ceq 'Ok' -and $null -eq $withoutManifest.RuntimeManifestBaseText -and $null -eq $withoutManifest.RuntimeManifestCurrentText)
                $cpTNote['Manifest'] = "untracked=$($untrackedManifest.Status)/$($untrackedManifest.RuntimeManifestBaseText)/$($untrackedManifest.RuntimeManifestCurrentText); changed=$($changedManifest.Status)/$($changedManifest.RuntimeManifestBaseText)/$($changedManifest.RuntimeManifestCurrentText); without=$($withoutManifest.Status)"
            }
        }

        if ($cpRunReal) {
            foreach ($cpCase in @(
                    @{ Key = 'Runner'; Name = 'RealGitRunnerSeparatesStreamsAndReportsStartFailure'; Failure = 'Invoke-BRAVOGitCommand мусить повертати {Available; ExitCode; StdOut; StdErr; StartError}: потоки розділені, stderr не стає помилкою під ErrorActionPreference=Stop, збій запуску - Available=$true, ExitCode=$null, StartError заповнено, без винятку' },
                    @{ Key = 'Main'; Name = 'RealRepositoryCollectsStatusOk'; Failure = 'збирач на реальному репозиторії мусить повернути Ok' },
                    @{ Key = 'Added'; Name = 'RealAddedTrackedAndUntrackedFiles'; Failure = 'новий tracked і новий untracked файли мусять бути в ChangedPath' },
                    @{ Key = 'Modified'; Name = 'RealModifiedStagedAndUnstagedOnce'; Failure = 'файл зі staged і unstaged змінами мусить бути в ChangedPath рівно один раз і не бути в DeletedPath' },
                    @{ Key = 'Deleted'; Name = 'RealDeletedIsChangedAndDeleted'; Failure = 'git rm: шлях мусить бути і в ChangedPath, і в DeletedPath' },
                    @{ Key = 'Renamed'; Name = 'RealRenameReportsBothPaths'; Failure = 'git mv a b: обидва шляхи в ChangedPath (--no-renames), старий у DeletedPath, новий - ні' },
                    @{ Key = 'Spaces'; Name = 'RealPathWithSpacesIsVerbatim'; Failure = 'шлях із пробілом повертається дослівно, без лапок' },
                    @{ Key = 'Cyrillic'; Name = 'RealCyrillicPathIsUtf8WithQuotepathOn'; Failure = 'кириличний шлях (tracked і untracked) за core.quotepath=true повертається побайтово в UTF-8, без восьмеричних екранувань' },
                    @{ Key = 'NoTrim'; Name = 'RealLeadingSpaceIsNotTrimmed'; Failure = 'шлях із пробілом на початку повертається дослівно (без обрізання)' },
                    @{ Key = 'Ignored'; Name = 'RealGitignoredFilesAreExcluded'; Failure = 'файли з .gitignore не входять до ChangedPath' },
                    @{ Key = 'Dirty'; Name = 'RealDirtyTreeIsReported'; Failure = 'база = HEAD зі staged + unstaged + untracked змінами: Dirty=$true, BaseSha=HeadSha=MergeBaseSha' },
                    @{ Key = 'ExactSet'; Name = 'RealChangedPathSetIsExactAndOrdinalSorted'; Failure = 'ChangedPath мусить дорівнювати точному набору в порядку Ordinal, DeletedPath - видаленим і перейменованим старим шляхам' },
                    @{ Key = 'InvalidBase'; Name = 'RealUnknownRefIsBaseInvalid'; Failure = 'неіснуюче ім''я ref мусить давати BASE-INVALID' },
                    @{ Key = 'BaseEqualsHead'; Name = 'RealBaseEqualsHeadOnCleanTree'; Failure = 'BaseRef=HEAD (чи SHA HEAD) на чистому дереві мусить давати BASE-EQUALS-HEAD' },
                    @{ Key = 'EmptyDiff'; Name = 'RealLegitimateEmptyDiffUsesMergeBase'; Failure = 'C1 -> C2 -> C3 (повернення), база C1: EMPTY-DIFF; для бази в іншій гілці порівнюється merge-base, а не кінчик гілки' },
                    @{ Key = 'NoMergeBase'; Name = 'RealOrphanBranchHasNoMergeBase'; Failure = 'orphan-гілка мусить давати NO-MERGE-BASE' },
                    @{ Key = 'NotARepository'; Name = 'RealDirectoryWithoutGitIsNotARepository'; Failure = 'каталог без git init мусить давати NOT-A-REPOSITORY' },
                    @{ Key = 'Manifest'; Name = 'RealManifestCompanionTexts'; Failure = 'RuntimeManifestBaseText - з merge-base ($null, якщо там немає файлу), CurrentText - з диска; без маніфесту в наборі обидва $null' }
                )) {
                Test-BRAVOCondition `
                    -Condition (& $cpTOk $cpCase.Key) `
                    -Name ("Framework/AffectedChangedPath." + $cpCase.Name) `
                    -Failure ($cpCase.Failure + '. Деталі: ' + (& $cpTWhy $cpCase.Key))
            }
        } else {
            Write-Host "  Сценарії AffectedChangedPath на реальному git-репозиторії пропущено: вони виконуються лише в git-робочій копії (потрібні .git і git)."
        }
        Test-BRAVOCondition `
            -Condition (($env:GITHUB_ACTIONS -ne 'true') -or $cpRunReal) `
            -Name "Framework/AffectedChangedPath.RealScenariosRunOnCi" `
            -Failure "на GitHub Actions сценарії AffectedChangedPath на реальному git-репозиторії мусять виконуватись (потрібні .git у корені та git у PATH); їх відсутність мовчки прибрала б покриття. .git: $(Test-Path -LiteralPath (Join-Path $root '.git')); git знайдено: $($cpGitCommand.Count -gt 0)"

        # --- [R]: статичний guard файлу -------------------------------------
        $cpParsed = Get-BRAVOSelfTestParsedFile -Path $cpPath
        $cpBytes = [IO.File]::ReadAllBytes($cpPath)
        $cpBareLf = $false
        for ($cpByteIndex = 0; $cpByteIndex -lt $cpBytes.Length; $cpByteIndex++) {
            if ($cpBytes[$cpByteIndex] -eq 10 -and ($cpByteIndex -eq 0 -or $cpBytes[$cpByteIndex - 1] -ne 13)) { $cpBareLf = $true; break }
        }
        $cpFunctionNames = [string]::Join(',', @($cpParsed.Ast.FindAll({ param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst] }, $true) |
                    ForEach-Object { $_.Name } | Sort-Object { $_ } ))
        $cpForbiddenLiterals = @('2>&1', 'Trim(', '??', '?.', '&&', '||', '-Parallel', '::new', 'Invoke-Expression')
        $cpForbiddenFound = @($cpForbiddenLiterals | Where-Object { $cpText.IndexOf($_, [StringComparison]::Ordinal) -ge 0 })
        $cpForeignPatterns = @([regex]::Matches($cpText, '(?i)BRAVO\.(?:\$|\{\d+\}|[''"])|BRAVOSelfTest|config_loader|config-parity|configparity|config\.example') | ForEach-Object { $_.Value })
        $cpPs7Nodes = @($cpParsed.Ast.FindAll({ param($node)
                    @('TernaryExpressionAst', 'PipelineChainAst', 'NullConditionalMemberAccessAst', 'NullConditionalIndexExpressionAst', 'ChainableAst') -contains $node.GetType().Name }, $true))
        Test-BRAVOCondition `
            -Condition (
                $cpForbiddenFound.Count -eq 0 -and $cpForeignPatterns.Count -eq 0 -and $cpPs7Nodes.Count -eq 0 -and
                $cpFunctionNames -ceq 'Get-BRAVOChangedPathSet,Invoke-BRAVOGitCommand' -and
                @('GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE', 'GIT_OBJECT_DIRECTORY', 'GIT_ALTERNATE_OBJECT_DIRECTORIES', 'GIT_COMMON_DIR' |
                        Where-Object { $cpText.IndexOf("'" + $_ + "'", [StringComparison]::Ordinal) -lt 0 }).Count -eq 0
            ) `
            -Name "Framework/AffectedChangedPath.StaticSourceHasNoForbiddenConstructs" `
            -Failure ("ci\BRAVOChangedPath.ps1: без 2>&1, обрізання (Trim), ??, ?., &&, ||, -Parallel, ::new, динамічного складання імені модуля, копії мапи Affected чи шаблонів config-parity; " +
                "рівно функції Get-BRAVOChangedPathSet та Invoke-BRAVOGitCommand. Знайдено: [" + [string]::Join(', ', $cpForbiddenFound) + "] [" + [string]::Join(', ', $cpForeignPatterns) + "] PS7-вузлів: $($cpPs7Nodes.Count); функції: [$cpFunctionNames]")
        Test-BRAVOCondition `
            -Condition (
                @($cpParsed.Errors).Count -eq 0 -and
                $cpBytes.Length -gt 3 -and $cpBytes[0] -eq 0xEF -and $cpBytes[1] -eq 0xBB -and $cpBytes[2] -eq 0xBF -and -not $cpBareLf
            ) `
            -Name "Framework/AffectedChangedPath.FileParsesAndHasBomCrlf" `
            -Failure "ci\BRAVOChangedPath.ps1 мусить розбиратись без помилок (Windows PowerShell 5.1), мати UTF-8 BOM і CRLF, як сусідні файли ci\. Помилок розбору: $(@($cpParsed.Errors).Count)"
    }
}
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Framework.AffectedChangedPath' } }

if (Enter-BRAVOSelfTestSection -Name 'Tail/Framework.AffectedRunner') { try {

# ============================================================
# VAL-05 (Affected), PR3: runner Affected (бібліотека + тонкий CLI).
#
# Канонічний власник - ci\BRAVOAffectedSelfTest.ps1
# (Invoke-BRAVOAffectedSelfTest) і тонкий CLI
# ci\Invoke-BRAVOAffectedSelfTest.ps1. Ланцюг: збирач шляхів ->
# супутник маніфесту -> план -> (лише V1/V2) дочірній прогін -Suite ->
# розбір маркера -> рядок "AFFECTED RESULT: <CODE>".
#
# Інваріанти, які тут доводяться: V3 НІКОЛИ не запускає дочірній
# процес і не стає Full або вибірковим прогоном; будь-який збій збирача
# проходить без змін і не обчислює план; код 0 лише за повного збігу
# маркера дочірнього прогону; жоден рядок stdout runner-а не починається
# з маркера Self-Test (вивід дочірнього процесу має префікс "child| ");
# план ніколи не є acceptance. Нової таблиці exit-кодів немає: 0 або 1.
#
# Позначення: [I] - ін'єкція -GitInvoker; [C] - ін'єкція
# -SelfTestInvoker (справжній дочірній корінь у Full не запускається);
# [R] - статичний guard файлів; [T] - справжній git-репозиторій. [T]
# виконується лише в git-робочій копії (є .git і git): розгорнутий пакет
# на сервері не має .git, і [НЕДОСТУПНО] там інвалідувало б acceptance.
# Покриття на CI не може зникнути мовчки: RealScenariosRunOnCi.
# Змінні лишаються в межах & { }: нічого нового не читається коренем.
# ============================================================
& {
    $arPath = Join-Path $root 'ci\BRAVOAffectedSelfTest.ps1'
    $arCliPath = Join-Path $root 'ci\Invoke-BRAVOAffectedSelfTest.ps1'
    $arCollectorPath = Join-Path $root 'ci\BRAVOChangedPath.ps1'
    $arParityPath = Join-Path $root 'ci\Test-BRAVOConfigParityRelevantPath.ps1'
    $arText = ''
    $arCliText = ''
    if ([IO.File]::Exists($arCollectorPath)) { . $arCollectorPath }
    if ([IO.File]::Exists($arParityPath)) { . $arParityPath }
    if ([IO.File]::Exists($arPath)) {
        . $arPath
        $arText = [IO.File]::ReadAllText($arPath, [Text.Encoding]::UTF8)
    }
    if ([IO.File]::Exists($arCliPath)) { $arCliText = [IO.File]::ReadAllText($arCliPath, [Text.Encoding]::UTF8) }
    $arReady = $true
    foreach ($arFunctionName in @('Invoke-BRAVOAffectedSelfTest', 'New-BRAVOAffectedChildRequest', 'Invoke-BRAVOAffectedChildProcess', 'ConvertTo-BRAVOAffectedPrintableText', 'Get-BRAVOChangedPathSet', 'Test-BRAVOConfigParityRelevantPath')) {
        if ($null -eq (Get-Command -Name $arFunctionName -CommandType Function -ErrorAction SilentlyContinue)) { $arReady = $false }
    }
    Test-BRAVOCondition `
        -Condition $arReady `
        -Name "Framework/AffectedRunner.FunctionsExist" `
        -Failure "ci\BRAVOAffectedSelfTest.ps1 мусить існувати й визначати Invoke-BRAVOAffectedSelfTest, New-BRAVOAffectedChildRequest, Invoke-BRAVOAffectedChildProcess, ConvertTo-BRAVOAffectedPrintableText (runner Affected), а ci\Invoke-BRAVOAffectedSelfTest.ps1 - тонкий CLI; файли знайдено: $([IO.File]::Exists($arPath)) / $([IO.File]::Exists($arCliPath))"

    if ($arReady) {
        $arNul = [string][char]0
        $arSha1 = 'a' * 40
        $arSha2 = 'b' * 40
        $arMismatch = New-Object System.Collections.Generic.List[string]
        $arCheck = {
            param([string]$Id, [bool]$Condition)
            if (-not $Condition) { [void]$arMismatch.Add($Id) }
        }
        $arTake = {
            $taken = [string]::Join('; ', @($arMismatch.ToArray() | Select-Object -First 8))
            $arMismatch.Clear()
            return $taken
        }
        $arAny = {
            param($Result, [string]$Fragment)
            foreach ($resultLine in @($Result.Line)) {
                if (([string]$resultLine).Contains($Fragment)) { return $true }
            }
            return $false
        }
        $arStarting = {
            param($Result, [string]$Prefix)
            return @(@($Result.Line) | Where-Object { ([string]$_).StartsWith($Prefix, [StringComparison]::Ordinal) })
        }
        $arSelfTestLine = {
            param($Result)
            return @(@($Result.Line) | Where-Object { [regex]::IsMatch([string]$_, '(?i)^\s*SELF-TEST') })
        }

        $arRoot = Join-Path ([IO.Path]::GetTempPath()) ('BRAVO_AFFECTEDRUNNER_' + [guid]::NewGuid().ToString('N'))
        $arOtherRoot = Join-Path ([IO.Path]::GetTempPath()) ('BRAVO_AFFECTEDRUNNER_OTHER_' + [guid]::NewGuid().ToString('N'))
        $arManifestKeys = @(
            'selftest/BRAVO_SELF_TEST.Paths.ps1', 'selftest/BRAVO_SELF_TEST.Archive.ps1', 'BRAVO_ARCHIV.ps1',
            'ci/Update-BRAVORuntimeManifest.ps1', 'modules/BRAVO.Configuration/x.psm1', 'BRAVO_HEALTH.ps1')
        $arManifestText = {
            param([string[]]$DeltaKey)
            $entries = New-Object System.Collections.Generic.List[string]
            foreach ($manifestKey in $arManifestKeys) {
                $hashValue = 'h0'
                if (@($DeltaKey) -contains $manifestKey) { $hashValue = 'h1' }
                [void]$entries.Add('"' + $manifestKey + '":"' + $hashValue + '"')
            }
            return ('{"schemaVersion":1,"description":"d","updateProcedure":"u","files":{' + [string]::Join(',', $entries.ToArray()) + '}}')
        }
        $arReply = {
            param([int]$Code, [string]$Out = '', [string]$Err = '')
            return @{ ExitCode = $Code; StdOut = $Out; StdErr = $Err }
        }
        $arKind = {
            param([string[]]$Argument)
            if ($Argument -contains 'diff') { return 'diff' }
            if ($Argument -contains 'ls-files') { return 'untracked' }
            if ($Argument -contains 'status') { return 'status' }
            if ($Argument -contains 'merge-base') { return 'mergebase' }
            if ($Argument -contains 'show') { return 'show' }
            if ($Argument -contains '--show-toplevel') { return 'toplevel' }
            if ($Argument -contains '--is-shallow-repository') { return 'shallow' }
            if ($Argument -contains 'HEAD^{commit}') { return 'head' }
            return 'base'
        }
        $arChildCalls = New-Object System.Collections.Generic.List[object]
        $arAll = New-Object System.Collections.Generic.List[object]
        $arGitResponses = @{}
        $arChildBehavior = $null
        # Відповідь-рядок означає виняток запуску git (симуляція Process.Start).
        $arGitInvoker = {
            param([string[]]$Argument)
            $fakeResponse = $arGitResponses[(& $arKind $Argument)]
            if ($fakeResponse -is [string]) { throw $fakeResponse }
            return $fakeResponse
        }
        $arChildInvoker = {
            param($Request)
            [void]$arChildCalls.Add($Request)
            return (& $arChildBehavior $Request)
        }
        $arDefaultChild = {
            param($Request)
            return @{ ExitCode = 0; Lines = @('child noise one', 'second line [PASS] ok', ('SELF-TEST PARTIAL: ' + [string]::Join(',', @($Request.Suite)))) }
        }
        # Tracked: 'шлях' (M) або 'D|шлях'. Повертає результат runner-а; Write-Host runner-а приглушено.
        $arRun = {
            param(
                [string[]]$Tracked,
                [string[]]$Untracked = @(),
                [string[]]$DeltaKey = @(),
                [scriptblock]$Behavior = $null,
                [hashtable]$Override = @{},
                [string]$BaseRef = 'main'
            )
            $arChildCalls.Clear()
            [IO.File]::WriteAllText((Join-Path $arRoot 'RUNTIME_MANIFEST.json'), (& $arManifestText $DeltaKey), (New-Object System.Text.UTF8Encoding -ArgumentList $false))
            $diffText = ''
            foreach ($trackedEntry in @($Tracked)) {
                if ($trackedEntry.StartsWith('D|', [StringComparison]::Ordinal)) { $diffText += 'D' + $arNul + $trackedEntry.Substring(2) + $arNul }
                else { $diffText += 'M' + $arNul + $trackedEntry + $arNul }
            }
            $untrackedText = ''
            foreach ($untrackedEntry in @($Untracked)) { $untrackedText += $untrackedEntry + $arNul }
            $arGitResponses = @{
                toplevel  = (& $arReply 0 ($arRoot + "`n"))
                shallow   = (& $arReply 0 "false`n")
                base      = (& $arReply 0 ($arSha1 + "`n"))
                head      = (& $arReply 0 ($arSha2 + "`n"))
                mergebase = (& $arReply 0 ($arSha1 + "`n"))
                diff      = (& $arReply 0 $diffText)
                untracked = (& $arReply 0 $untrackedText)
                show      = (& $arReply 0 (& $arManifestText @()))
                status    = (& $arReply 0 (' M x' + $arNul))
            }
            foreach ($overrideKey in @($Override.Keys)) { $arGitResponses[$overrideKey] = $Override[$overrideKey] }
            $arChildBehavior = $arDefaultChild
            if ($null -ne $Behavior) { $arChildBehavior = $Behavior }
            $runResult = Invoke-BRAVOAffectedSelfTest -RepositoryRoot $arRoot -BaseRef $BaseRef -GitInvoker $arGitInvoker -SelfTestInvoker $arChildInvoker 6>$null
            [void]$arAll.Add($runResult)
            return , $runResult
        }
        $arSuiteText = {
            param($Result)
            return [string]::Join(',', @($Result.Suite))
        }
        $arPaths = 'selftest/BRAVO_SELF_TEST.Paths.ps1'

        try {
            [void][IO.Directory]::CreateDirectory($arRoot)

            # R1 [C+I]: відомий фрагмент + супутній маніфест -> V2, дочірній прогін, код 0.
            $arOne = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths)
            $arOneRequest = $null
            if ($arChildCalls.Count -eq 1) { $arOneRequest = $arChildCalls[0] }
            Test-BRAVOCondition `
                -Condition (
                    @($arOne).Count -eq 1 -and $arOne.ExitCode -eq 0 -and $arOne.ResultCode -ceq 'PARTIAL-OK' -and $arOne.Class -ceq 'V2' -and
                    $arChildCalls.Count -eq 1 -and $null -ne $arOneRequest -and [string]::Join(',', @($arOneRequest.Suite)) -ceq 'Governance,Paths' -and
                    (& $arAny $arOne 'Full Self-Test REQUIRED before acceptance') -and
                    (& $arAny $arOne 'AFFECTED CHILD MARKER: PARTIAL Governance,Paths') -and
                    @(& $arStarting $arOne 'AFFECTED RESULT: PARTIAL-OK').Count -eq 1 -and
                    $arOne.Line[$arOne.Line.Count - 1] -ceq 'AFFECTED RESULT: PARTIAL-OK' -and
                    $arOne.IsAcceptanceEvidence -eq $false
                ) `
                -Name "Framework/AffectedRunner.KnownSingleV2RunsChildAndPasses" `
                -Failure ("R1: фрагмент Paths + супутній маніфест -> клас V2, дочірній прогін із Governance,Paths, код 0, AFFECTED RESULT: PARTIAL-OK останнім рядком і рядок про обов'язковий Full; отримано код=$($arOne.ExitCode) результат=$($arOne.ResultCode) клас=$($arOne.Class) викликів дочірнього=$($arChildCalls.Count)")

            # R20 [I]: лише untracked (фрагмент + маніфест) - теж зміна.
            $arUntracked = & $arRun @() @($arPaths, 'RUNTIME_MANIFEST.json') @($arPaths)
            Test-BRAVOCondition `
                -Condition ($arUntracked.ExitCode -eq 0 -and $arUntracked.Class -ceq 'V2' -and (& $arSuiteText $arUntracked) -ceq 'Governance,Paths' -and $arChildCalls.Count -eq 1) `
                -Name "Framework/AffectedRunner.UntrackedOnlyChangeIsAChange" `
                -Failure "R20: збирач повернув лише untracked фрагмент і маніфест - це зміна класу V2 із Governance,Paths, а не порожній прогін"

            # R2, R3 [C+I]: невідомий шлях -> V3; дочірній процес ніколи не запускається.
            $arUnknown = & $arRun @('BRAVO_ARCHIV.ps1', 'RUNTIME_MANIFEST.json') @() @('BRAVO_ARCHIV.ps1')
            $arUnknownCalls = $arChildCalls.Count
            $arMixed = & $arRun @($arPaths, 'ci/Update-BRAVORuntimeManifest.ps1', 'RUNTIME_MANIFEST.json') @() @($arPaths, 'ci/Update-BRAVORuntimeManifest.ps1')
            $arMixedCalls = $arChildCalls.Count
            Test-BRAVOCondition `
                -Condition (
                    $arUnknown.ExitCode -eq 1 -and $arUnknown.ResultCode -ceq 'ESCALATED-V3' -and $arUnknown.Class -ceq 'V3' -and $arUnknownCalls -eq 0 -and
                    (& $arAny $arUnknown 'AFFECTED RESULT: ESCALATED-V3') -and
                    $arMixed.ExitCode -eq 1 -and $arMixed.ResultCode -ceq 'ESCALATED-V3' -and $arMixedCalls -eq 0 -and
                    @($arMixed.Suite).Count -eq 0 -and (& $arAny $arMixed 'AFFECTED SUITES: (немає)')
                ) `
                -Name "Framework/AffectedRunner.UnknownPathEscalatesV3WithoutChild" `
                -Failure ("R2/R3: невідомий шлях (BRAVO_ARCHIV.ps1) і змішаний набір відомого фрагмента з ci\Update-BRAVORuntimeManifest.ps1 мусять давати клас V3, код 1, ESCALATED-V3, порожній Suite (Paths не запускається окремо) і жодного виклику дочірнього; отримано: [$($arUnknown.ResultCode)/$($arUnknown.ExitCode)/викликів $arUnknownCalls] [$($arMixed.ResultCode)/$($arMixed.ExitCode)/викликів $arMixedCalls/suite $(& $arSuiteText $arMixed)]")

            # R4 [C+I]: споживані документи -> V1, код 0.
            foreach ($arDoc in @(
                    @{ Path = 'README.md'; Suite = 'Governance' },
                    @{ Path = 'OPERATIONS.md'; Suite = 'DataRestore,Governance' },
                    @{ Path = 'BRAVO_SETUP.md'; Suite = 'ConfigLoader,Governance' },
                    @{ Path = 'CHANGELOG.md'; Suite = 'Governance' })) {
                $arDocResult = & $arRun @($arDoc.Path)
                $arDocRequest = $null
                if ($arChildCalls.Count -eq 1) { $arDocRequest = $arChildCalls[0] }
                & $arCheck ('doc ' + $arDoc.Path) (
                    $arDocResult.ExitCode -eq 0 -and $arDocResult.Class -ceq 'V1' -and $arDocResult.ResultCode -ceq 'PARTIAL-OK' -and
                    (& $arSuiteText $arDocResult) -ceq $arDoc.Suite -and $null -ne $arDocRequest -and [string]::Join(',', @($arDocRequest.Suite)) -ceq $arDoc.Suite -and
                    (& $arAny $arDocResult 'Full Self-Test не звільняється'))
            }
            $arProblem = & $arTake
            Test-BRAVOCondition `
                -Condition ($arProblem.Length -eq 0) `
                -Name "Framework/AffectedRunner.ConsumedDocumentsAreV1" `
                -Failure ("R4: README.md, OPERATIONS.md, BRAVO_SETUP.md, CHANGELOG.md -> клас V1, свої suite, код 0 і рядок 'Full Self-Test не звільняється': " + $arProblem)

            # R5 [C+I]: документ поза таблицею -> V3; фрази про непотрібний Full немає.
            foreach ($arOutside in @('docs/design/BRAVO_VALIDATION_ARCHITECTURE.md', 'ROADMAP.md')) {
                $arOutsideResult = & $arRun @($arOutside)
                & $arCheck ('outside ' + $arOutside) (
                    $arOutsideResult.ExitCode -eq 1 -and $arOutsideResult.Class -ceq 'V3' -and $arOutsideResult.ResultCode -ceq 'ESCALATED-V3' -and $arChildCalls.Count -eq 0 -and
                    -not [regex]::IsMatch([string]::Join("`n", @($arOutsideResult.Line)), '(?i)full\s+not\s+required'))
            }
            $arProblem = & $arTake
            Test-BRAVOCondition `
                -Condition ($arProblem.Length -eq 0) `
                -Name "Framework/AffectedRunner.DocOutsideTableIsV3WithoutFullNotRequired" `
                -Failure ("R5: документ поза таблицею споживаних -> V3, код 1, без дочірнього процесу і без фрази 'Full not required': " + $arProblem)

            # R6, R7, R8 [C]: збій дочірнього процесу й невідповідність маркера.
            $arFailed = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths) { param($Request) return @{ ExitCode = 1; Lines = @('boom', 'SELF-TEST FAILED: 2') } }
            $arPassed = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths) { param($Request) return @{ ExitCode = 0; Lines = @('SELF-TEST PASSED') } }
            $arWrongList = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths) { param($Request) return @{ ExitCode = 0; Lines = @('SELF-TEST PARTIAL: Governance') } }
            $arTwoPartial = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths) { param($Request) return @{ ExitCode = 0; Lines = @('SELF-TEST PARTIAL: Governance,Paths', 'SELF-TEST PARTIAL: Governance,Paths') } }
            $arNoMarker = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths) { param($Request) return @{ ExitCode = 0; Lines = @('nothing useful') } }
            $arPartialAndPassed = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths) { param($Request) return @{ ExitCode = 0; Lines = @('SELF-TEST PARTIAL: Governance,Paths', 'SELF-TEST PASSED') } }
            $arFailedWithMarker = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths) { param($Request) return @{ ExitCode = 2; Lines = @('SELF-TEST PARTIAL: Governance,Paths') } }
            Test-BRAVOCondition `
                -Condition (
                    $arFailed.ExitCode -eq 1 -and $arFailed.ResultCode -ceq 'CHILD-FAILED' -and (& $arAny $arFailed 'AFFECTED RESULT: CHILD-FAILED') -and
                    $arFailedWithMarker.ExitCode -eq 1 -and $arFailedWithMarker.ResultCode -ceq 'CHILD-FAILED'
                ) `
                -Name "Framework/AffectedRunner.ChildFailureIsChildFailed" `
                -Failure "R6: ненульовий код дочірнього прогону (навіть із маркером PARTIAL) -> код 1 і AFFECTED RESULT: CHILD-FAILED"
            Test-BRAVOCondition `
                -Condition (
                    $arPassed.ExitCode -eq 1 -and $arPassed.ResultCode -ceq 'MARKER-MISMATCH' -and @(& $arSelfTestLine $arPassed).Count -eq 0 -and
                    (& $arAny $arPassed 'AFFECTED CHILD MARKER: UNEXPECTED (PASSED)') -and
                    $arPartialAndPassed.ExitCode -eq 1 -and $arPartialAndPassed.ResultCode -ceq 'MARKER-MISMATCH' -and @(& $arSelfTestLine $arPartialAndPassed).Count -eq 0
                ) `
                -Name "Framework/AffectedRunner.ChildPassedMarkerIsMismatch" `
                -Failure "R7: код 0, але дочірній прогін надрукував маркер повного прогону (окремо або поряд із PARTIAL) -> код 1 і MARKER-MISMATCH; сирого маркера у stdout runner-а немає"
            Test-BRAVOCondition `
                -Condition (
                    $arWrongList.ExitCode -eq 1 -and $arWrongList.ResultCode -ceq 'MARKER-MISMATCH' -and
                    $arTwoPartial.ExitCode -eq 1 -and $arTwoPartial.ResultCode -ceq 'MARKER-MISMATCH' -and
                    $arNoMarker.ExitCode -eq 1 -and $arNoMarker.ResultCode -ceq 'MARKER-MISMATCH'
                ) `
                -Name "Framework/AffectedRunner.ChildMarkerListMismatch" `
                -Failure "R8: інший перелік у PARTIAL, два рядки PARTIAL або жодного маркера при коді 0 -> код 1 і MARKER-MISMATCH"

            # R9 [C]: шум дочірнього процесу має префікс child| ; маркер розібрано.
            $arNoiseLines = @($arOne.Line | Where-Object { ([string]$_).StartsWith('child| ', [StringComparison]::Ordinal) })
            Test-BRAVOCondition `
                -Condition (
                    $arNoiseLines.Count -eq 2 -and $arNoiseLines[0] -ceq 'child| child noise one' -and $arNoiseLines[1] -ceq 'child| second line [PASS] ok' -and
                    @(& $arSelfTestLine $arOne).Count -eq 0 -and (& $arAny $arOne 'AFFECTED CHILD MARKER: PARTIAL Governance,Paths')
                ) `
                -Name "Framework/AffectedRunner.ChildNoiseIsPrefixed" `
                -Failure "R9: звичайні рядки дочірнього процесу відлунюються як 'child| <рядок>', сирого маркера Self-Test немає, є AFFECTED CHILD MARKER: PARTIAL Governance,Paths"

            # Ін'єкція через шлях і керувальні символи: нові рядки не створюють рядка з маркером.
            $arInjected = & $arRun @("docs/x`nSELF-TEST PASSED.md", "docs/y`r`n  self-test partial.md") @()
            $arInjectedChild = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths) { param($Request) return @{ ExitCode = 0; Lines = @("a`nSELF-TEST PASSED", "b`rSELF-TEST FAILED: 1", 'SELF-TEST PARTIAL: Governance,Paths') } }
            Test-BRAVOCondition `
                -Condition (
                    $arInjected.ExitCode -eq 1 -and @(& $arSelfTestLine $arInjected).Count -eq 0 -and
                    $arInjectedChild.ExitCode -eq 1 -and @(& $arSelfTestLine $arInjectedChild).Count -eq 0
                ) `
                -Name "Framework/AffectedRunner.ControlCharactersCannotForgeMarkerLines" `
                -Failure "шлях з переводом рядка та рядок дочірнього процесу з вбудованим переводом рядка не можуть створити рядок stdout runner-а, що починається з маркера Self-Test (керувальні символи екрануються)"

            # R13 [C+I]: BASE, MERGE-BASE, HEAD, DIRTY - для V1, V2 і V3.
            $arV1 = & $arRun @('README.md')
            $arHeadOk = $true
            foreach ($arClassResult in @($arV1, $arOne, $arUnknown)) {
                $arHeadLine = @(& $arStarting $arClassResult 'AFFECTED HEAD: ')
                $arHeadOk = $arHeadOk -and (& $arAny $arClassResult ('AFFECTED BASE: ' + $arSha1)) -and (& $arAny $arClassResult ('AFFECTED MERGE-BASE: ' + $arSha1)) -and
                    (& $arAny $arClassResult ('AFFECTED HEAD: ' + $arSha2)) -and (& $arAny $arClassResult 'AFFECTED DIRTY: true') -and
                    $arHeadLine.Count -eq 1 -and [regex]::IsMatch([string]$arHeadLine[0], '^AFFECTED HEAD: [0-9a-f]{40}$')
            }
            Test-BRAVOCondition `
                -Condition $arHeadOk `
                -Name "Framework/AffectedRunner.HeadAndDirtyArePrinted" `
                -Failure "R13: для V1, V2 і V3 runner друкує AFFECTED BASE, AFFECTED MERGE-BASE, AFFECTED HEAD (40-hex) і AFFECTED DIRTY"

            # R14 [C]: мітка класу й нагадування про PR-класифікацію; без 'Full not required'.
            $arLabelOk = $true
            foreach ($arClassResult in @($arV1, $arOne, $arUnknown)) {
                $arClassLine = @(& $arStarting $arClassResult 'AFFECTED CLASS: ')
                $arLabelOk = $arLabelOk -and $arClassLine.Count -eq 1 -and ([string]$arClassLine[0]).Contains('(мінімальний клас за картою шляхів)') -and
                    (& $arAny $arClassResult "Класифікація PR на рівні рев'ю все одно обов'язкова") -and
                    -not [regex]::IsMatch([string]::Join("`n", @($arClassResult.Line)), '(?i)full\s+not\s+required')
            }
            $arLabelOk = $arLabelOk -and $arV1.Class -ceq 'V1' -and $arOne.Class -ceq 'V2' -and $arUnknown.Class -ceq 'V3' -and
                (& $arAny $arOne 'Full Self-Test REQUIRED before acceptance: .\BRAVO_SELF_TEST.ps1 -NoPause') -and
                -not (& $arAny $arV1 'Full Self-Test REQUIRED') -and (& $arAny $arV1 'Full Self-Test не звільняється')
            Test-BRAVOCondition `
                -Condition $arLabelOk `
                -Name "Framework/AffectedRunner.ClassLabelAndPrNoticeAreAlwaysPrinted" `
                -Failure "R14: V1, V2, V3 друкують 'мінімальний клас за картою шляхів' і нагадування про класифікацію PR на рівні рев'ю; для V2 - 'Full Self-Test REQUIRED before acceptance', для V1 - 'Full Self-Test не звільняється'; фрази 'Full not required' немає ніколи"

            # R15 [I]: збої збирача проходять без змін; план не обчислюється; дочірній не запускається.
            $arCollectorCases = @(
                @{ Code = 'BASE-MISSING'; Ref = ''; Override = @{} },
                @{ Code = 'BASE-INVALID'; Ref = 'a b'; Override = @{} },
                @{ Code = 'BASE-EQUALS-HEAD'; Ref = 'main'; Override = @{ base = (& $arReply 0 ($arSha2 + "`n")); mergebase = (& $arReply 0 ($arSha2 + "`n")); diff = (& $arReply 0 ''); untracked = (& $arReply 0 '') } },
                @{ Code = 'EMPTY-DIFF'; Ref = 'main'; Override = @{ diff = (& $arReply 0 ''); untracked = (& $arReply 0 '') } },
                @{ Code = 'GIT-MISSING'; Ref = 'main'; Override = @{ toplevel = @{ Available = $false; ExitCode = $null; StdOut = ''; StdErr = '' } } },
                @{ Code = 'GIT-FAILED'; Ref = 'main'; Override = @{ diff = (& $arReply 128 '' 'fatal: x') } },
                @{ Code = 'NOT-A-REPOSITORY'; Ref = 'main'; Override = @{ toplevel = (& $arReply 128 '' 'fatal: not a git repository') } },
                @{ Code = 'ROOT-MISMATCH'; Ref = 'main'; Override = @{ toplevel = (& $arReply 0 ($arOtherRoot + "`n")) } },
                @{ Code = 'SHALLOW-REPOSITORY'; Ref = 'main'; Override = @{ shallow = (& $arReply 0 "true`n") } },
                @{ Code = 'NO-MERGE-BASE'; Ref = 'main'; Override = @{ mergebase = (& $arReply 1) } })
            foreach ($arCase in $arCollectorCases) {
                $arCaseResult = & $arRun @($arPaths) @() @() $null $arCase.Override $arCase.Ref
                & $arCheck $arCase.Code (
                    $arCaseResult.ExitCode -eq 1 -and $arCaseResult.ResultCode -ceq $arCase.Code -and $arChildCalls.Count -eq 0 -and
                    (& $arAny $arCaseResult ('AFFECTED RESULT: ' + $arCase.Code)) -and @(& $arStarting $arCaseResult 'AFFECTED CLASS: ').Count -eq 0 -and
                    $null -eq $arCaseResult.Class -and @(& $arSelfTestLine $arCaseResult).Count -eq 0 -and
                    $arCaseResult.Line[$arCaseResult.Line.Count - 1] -ceq ('AFFECTED RESULT: ' + $arCase.Code))
            }
            $arProblem = & $arTake
            Test-BRAVOCondition `
                -Condition ($arProblem.Length -eq 0) `
                -Name "Framework/AffectedRunner.CollectorFailuresPassThrough" `
                -Failure ("R15: кожен статус збирача (BASE-MISSING, BASE-INVALID, BASE-EQUALS-HEAD, EMPTY-DIFF, GIT-MISSING, GIT-FAILED, NOT-A-REPOSITORY, ROOT-MISMATCH, SHALLOW-REPOSITORY, NO-MERGE-BASE) мусить давати код 1 і AFFECTED RESULT: <той самий код> останнім рядком без обчислення плану й без дочірнього процесу: " + $arProblem)

            # R16 [I+C]: gate Config parity - за рішенням канонічної функції, включно з видаленням.
            $arParityModule = & $arRun @('modules/BRAVO.Configuration/x.psm1', 'RUNTIME_MANIFEST.json') @() @('modules/BRAVO.Configuration/x.psm1')
            $arParityLoader = & $arRun @('BRAVO_CONFIG_LOADER.ps1')
            $arParityDeleted = & $arRun @('D|modules/BRAVO.Configuration/x.psm1')
            $arParityNone = & $arRun @('README.md')
            Test-BRAVOCondition `
                -Condition (
                    $arParityModule.ResultCode -ceq 'ESCALATED-V3' -and (& $arAny $arParityModule 'Config parity') -and
                    $arParityLoader.ResultCode -ceq 'ESCALATED-V3' -and (& $arAny $arParityLoader 'Config parity') -and
                    $arParityDeleted.ResultCode -ceq 'ESCALATED-V3' -and (& $arAny $arParityDeleted 'Config parity') -and
                    -not (& $arAny $arParityNone 'Config parity')
                ) `
                -Name "Framework/AffectedRunner.ConfigParityGateComesFromCanonicalFunction" `
                -Failure "R16: V3 зі зміною модуля конфігурації, завантажувача чи видаленого файла модуля містить gate Config parity за рішенням ci\Test-BRAVOConfigParityRelevantPath.ps1; для README.md такого gate немає"
            Test-BRAVOCondition `
                -Condition (
                    $arText.Contains('Test-BRAVOConfigParityRelevantPath') -and -not $arText.Contains('Get-BRAVOConfigParityRelevantPathPattern') -and
                    -not [regex]::IsMatch($arText, '(?i)modules[\\/]BRAVO\.Configur|BRAVO_CONFIG_LOADER|config\.example|selftest[\\/]fixtures|config-parity')
                ) `
                -Name "Framework/AffectedRunner.NoCopyOfConfigParityPathList" `
                -Failure "ci\BRAVOAffectedSelfTest.ps1 мусить викликати канонічну Test-BRAVOConfigParityRelevantPath і не містити копії переліку шляхів паритету конфігурації"

            # R17 [C]: вимоги V3.
            $arRequirements = & $arRun @('BRAVO_ARCHIV.ps1', 'RUNTIME_MANIFEST.json') @() @('BRAVO_ARCHIV.ps1')
            Test-BRAVOCondition `
                -Condition (
                    (& $arAny $arRequirements '.\BRAVO_SELF_TEST.ps1 -NoPause') -and (& $arAny $arRequirements 'RELEASE_POLICY.md') -and (& $arAny $arRequirements '13.3') -and
                    (& $arAny $arRequirements "Незалежне рев'ю") -and (& $arAny $arRequirements 'AFFECTED UNKNOWN PATH: BRAVO_ARCHIV.ps1 - ') -and
                    (& $arAny $arRequirements 'Integrity manifests are current') -and
                    (& $arAny $arRequirements 'НЕ запускає') -and $arChildCalls.Count -eq 0
                ) `
                -Name "Framework/AffectedRunner.V3RequirementsAreListed" `
                -Failure "R17: V3 друкує канонічну команду Full, посилання на RELEASE_POLICY.md §13.3, незалежне рев'ю, умовні gate-и й невідомі шляхи з причинами і нічого не запускає"

            # Контракт SelfTestInvoker: невірна форма відповіді - fail closed.
            $arBadInvokers = @(
                @{ Id = 'throws'; Behavior = { param($Request) throw 'simulated child start failure' } },
                @{ Id = 'null'; Behavior = { param($Request) return $null } },
                @{ Id = 'no exit code'; Behavior = { param($Request) return @{ Lines = @('SELF-TEST PARTIAL: Governance,Paths') } } },
                @{ Id = 'string exit code'; Behavior = { param($Request) return @{ ExitCode = '0'; Lines = @('SELF-TEST PARTIAL: Governance,Paths') } } },
                @{ Id = 'start error'; Behavior = { param($Request) return @{ ExitCode = $null; Lines = @(); StartError = 'не стартував' } } },
                @{ Id = 'two objects'; Behavior = { param($Request) return @(@{ ExitCode = 0; Lines = @('SELF-TEST PARTIAL: Governance,Paths') }, @{ ExitCode = 0; Lines = @() }) } })
            foreach ($arBad in $arBadInvokers) {
                $arBadResult = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths) $arBad.Behavior
                & $arCheck $arBad.Id ($arBadResult.ExitCode -eq 1 -and $arBadResult.ResultCode -ceq 'CHILD-FAILED' -and @(& $arSelfTestLine $arBadResult).Count -eq 0)
            }
            $arProblem = & $arTake
            Test-BRAVOCondition `
                -Condition ($arProblem.Length -eq 0) `
                -Name "Framework/AffectedRunner.ChildInvokerContractFailsClosed" `
                -Failure ("виняток invoker-а, порожня чи двозначна відповідь, відсутній чи нечисловий ExitCode, StartError -> код 1 і CHILD-FAILED, ніколи не успіх: " + $arProblem)

            # R18 [R]: runner не змінює вибір suite кореня.
            $arSelectionBefore = $script:BRAVOSelfTestSelectedSuite
            $null = & $arRun @($arPaths, 'RUNTIME_MANIFEST.json') @() @($arPaths)
            Test-BRAVOCondition `
                -Condition ([object]::ReferenceEquals($arSelectionBefore, $script:BRAVOSelfTestSelectedSuite)) `
                -Name "Framework/AffectedRunner.RunnerDoesNotMutateSelection" `
                -Failure "R18: виклик runner-а не змінює `$script:BRAVOSelfTestSelectedSuite кореня"

            # Write-Host runner-а збігається з Line результату (те, що бачить оператор).
            [IO.File]::WriteAllText((Join-Path $arRoot 'RUNTIME_MANIFEST.json'), (& $arManifestText @()), (New-Object System.Text.UTF8Encoding -ArgumentList $false))
            $arGitResponses = @{
                toplevel = (& $arReply 0 ($arRoot + "`n")); shallow = (& $arReply 0 "false`n"); base = (& $arReply 0 ($arSha1 + "`n")); head = (& $arReply 0 ($arSha2 + "`n"))
                mergebase = (& $arReply 0 ($arSha1 + "`n")); diff = (& $arReply 0 ('M' + $arNul + 'README.md' + $arNul)); untracked = (& $arReply 0 ''); show = (& $arReply 0 ''); status = (& $arReply 0 (' M x' + $arNul))
            }
            $arChildBehavior = $arDefaultChild
            $arStream = @(Invoke-BRAVOAffectedSelfTest -RepositoryRoot $arRoot -BaseRef 'main' -GitInvoker $arGitInvoker -SelfTestInvoker $arChildInvoker 6>&1)
            $arStreamResult = @($arStream | Where-Object { $_ -isnot [Management.Automation.InformationRecord] })
            $arStreamText = @($arStream | Where-Object { $_ -is [Management.Automation.InformationRecord] } | ForEach-Object { [string]$_.MessageData })
            Test-BRAVOCondition `
                -Condition (
                    $arStreamResult.Count -eq 1 -and $arStreamText.Count -gt 5 -and $arStreamText.Count -eq @($arStreamResult[0].Line).Count -and
                    [string]::Join("`n", $arStreamText) -ceq [string]::Join("`n", @($arStreamResult[0].Line)) -and
                    @($arStreamText | Where-Object { [regex]::IsMatch($_, '(?i)^\s*SELF-TEST') }).Count -eq 0
                ) `
                -Name "Framework/AffectedRunner.ConsoleOutputEqualsResultLines" `
                -Failure "функція повертає рівно один об'єкт результату, а все, що бачить оператор (Write-Host), збігається з Line і не містить рядків, що починаються з маркера Self-Test; рядків у потоці: $($arStreamText.Count)"

            # R10 динамічно: жоден сценарій не дав рядка з маркером Self-Test на початку і маркера повного прогону.
            $arSelfTestLines = 0
            $arPassedWords = 0
            foreach ($arEach in $arAll) {
                $arSelfTestLines += @(& $arSelfTestLine $arEach).Count
                $arPassedWords += @(@($arEach.Line) | Where-Object { ([string]$_).Contains('SELF-TEST PASSED') }).Count
                & $arCheck ('acceptance ' + $arEach.ResultCode) ($arEach.IsAcceptanceEvidence -eq $false -and ($arEach.ExitCode -eq 0 -or $arEach.ExitCode -eq 1))
            }
            $arAcceptanceProblem = & $arTake
            Test-BRAVOCondition `
                -Condition ($arAll.Count -ge 30 -and $arSelfTestLines -eq 0 -and $arPassedWords -eq 0 -and $arAcceptanceProblem.Length -eq 0) `
                -Name "Framework/AffectedRunner.NeverPrintsSelfTestLinesDynamic" `
                -Failure "R10: у жодному зі сценаріїв (всього $($arAll.Count)) рядок stdout runner-а не починається з маркера Self-Test і не містить маркера повного прогону; IsAcceptanceEvidence завжди `$false, код лише 0 або 1; рядків із маркером: $arSelfTestLines; $arAcceptanceProblem"

            # R11 [C]: порожній -Suite не будується; кодована команда містить лише непорожній -Suite @('..').
            $arBodyOk = $true
            $arBodyCount = 0
            $arChildRuns = 0
            foreach ($arEach in $arAll) {
                if ($arEach.ChildInvoked -eq $true) {
                    $arChildRuns++
                    $arBodyCount++
                    $arBody = [Text.Encoding]::Unicode.GetString([Convert]::FromBase64String([string]$arEach.ChildRequest.EncodedCommand))
                    $arBodyOk = $arBodyOk -and [regex]::IsMatch($arBody, "-Suite @\('[A-Za-z]+'(,'[A-Za-z]+')*\); exit ") -and
                        -not [regex]::IsMatch($arBody, '-Suite\s*(@\(\s*\))?\s*(;|$)') -and $arBody -ceq [string]$arEach.ChildRequest.CommandBody
                }
            }
            Test-BRAVOCondition `
                -Condition ($arBodyOk -and $arBodyCount -ge 5 -and $arBodyCount -eq $arChildRuns) `
                -Name "Framework/AffectedRunner.EmptySuiteArgumentIsNeverBuilt" `
                -Failure "R11: у кожному запуску дочірнього прогону (перевірено $arBodyCount) тіло EncodedCommand містить непорожній -Suite @('A','B'); '-Suite @()' чи '-Suite' без значення не будується"

            # R12 [R]: побудова дочірньої команди.
            $arQuirkRoot = Join-Path ([IO.Path]::GetTempPath()) ("o'brien " + [char]0x2019 + 'x')
            $arRequest = New-BRAVOAffectedChildRequest -RepositoryRoot $arQuirkRoot -Suite @('Governance', 'Paths')
            $arExpectedScript = Join-Path ([IO.Path]::GetFullPath($arQuirkRoot)) 'BRAVO_SELF_TEST.ps1'
            $arExpectedQuoted = "'" + $arExpectedScript.Replace("'", "''").Replace([string][char]0x2019, ([string][char]0x2019 + [char]0x2019)) + "'"
            $arExpectedBody = '& ' + $arExpectedQuoted + " -NoPause -Suite @('Governance','Paths'); exit `$LASTEXITCODE"
            $arDecoded = [Text.Encoding]::Unicode.GetString([Convert]::FromBase64String([string]$arRequest.EncodedCommand))
            $arArgumentOk = (
                [string]::Join(' ', @($arRequest.Argument)) -ceq ('-NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand ' + [string]$arRequest.EncodedCommand) -and
                @($arRequest.Argument | Where-Object { $_ -ceq '-File' -or $_ -ceq '-Command' }).Count -eq 0)
            $arEmptyThrows = $false
            try { [void](New-BRAVOAffectedChildRequest -RepositoryRoot $arRoot -Suite @()) } catch { $arEmptyThrows = $true }
            $arBadNameThrows = $false
            try { [void](New-BRAVOAffectedChildRequest -RepositoryRoot $arRoot -Suite @("Gov'; calc")) } catch { $arBadNameThrows = $true }
            $arControlThrows = $false
            try { [void](New-BRAVOAffectedChildRequest -RepositoryRoot ($arRoot + "`nx") -Suite @('Governance')) } catch { $arControlThrows = $true }
            $arSystemRoot = $env:SystemRoot
            Test-BRAVOCondition `
                -Condition (
                    $arDecoded -ceq $arExpectedBody -and [string]$arRequest.CommandBody -ceq $arExpectedBody -and $arArgumentOk -and
                    [string]::Join(',', @($arRequest.Suite)) -ceq 'Governance,Paths' -and [string]$arRequest.ScriptPath -ceq $arExpectedScript -and
                    $arEmptyThrows -and $arBadNameThrows -and $arControlThrows -and
                    (([string]::IsNullOrEmpty($arSystemRoot) -and [string]$arRequest.FilePath -ceq '') -or
                        (-not [string]::IsNullOrEmpty($arSystemRoot) -and [string]$arRequest.FilePath -ceq (Join-Path $arSystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe')))
                ) `
                -Name "Framework/AffectedRunner.EncodedCommandRoundTrip" `
                -Failure ("R12: EncodedCommand (base64 UTF-16LE) декодується в `"& '<шлях>' -NoPause -Suite @('Governance','Paths'); exit `$LASTEXITCODE`" (апостроф і типографський апостроф у шляху подвоєно); аргументи -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand без -File; порожній чи небезпечний Suite і керувальні символи в шляху відхиляються. Декодовано: [$arDecoded]; очікувано: [$arExpectedBody]")
        } finally {
            Remove-Item -LiteralPath $arRoot -Recurse -Force -ErrorAction SilentlyContinue
        }

        # --- [T]: справжній git-репозиторій (лише в git-робочій копії) -----------
        $arGitCommand = @(Get-Command -Name 'git' -CommandType Application -ErrorAction SilentlyContinue)
        $arRunReal = ((Test-Path -LiteralPath (Join-Path $root '.git')) -and $arGitCommand.Count -gt 0)
        if ($arRunReal) {
            $arTReal = $false
            $arTNote = 'сценарій не виконано'
            $arRealDir = Join-Path ([IO.Path]::GetTempPath()) ('BRAVO_AFFECTEDRUNNER_REAL_' + [guid]::NewGuid().ToString('N'))
            try {
                [void][IO.Directory]::CreateDirectory($arRealDir)
                $arRealGit = {
                    param([string[]]$GitArgument)
                    $fullArgument = @('-c', 'user.name=Test Author', '-c', 'user.email=test@example.invalid', '-c', 'core.autocrlf=false', '-c', 'core.quotepath=true') + $GitArgument
                    $gitRun = Invoke-BRAVOGitCommand -RepositoryRoot $arRealDir -Argument $fullArgument
                    if (-not ($gitRun.Available -and $null -ne $gitRun.ExitCode -and $gitRun.ExitCode -eq 0)) {
                        throw ('git ' + [string]::Join(' ', $GitArgument) + ' завершився з помилкою: ' + [string]$gitRun.StdErr + [string]$gitRun.StartError)
                    }
                    return ($gitRun.StdOut -replace '[\r\n]+\z', '')
                }
                $arRealWrite = {
                    param([string]$Relative, [string]$Content)
                    $target = Join-Path $arRealDir $Relative
                    [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target))
                    [IO.File]::WriteAllText($target, $Content, (New-Object System.Text.UTF8Encoding -ArgumentList $false))
                }
                $null = & $arRealGit @('-c', 'init.defaultBranch=master', 'init', '--quiet')
                & $arRealWrite 'README.md' 'one'
                & $arRealWrite 'docs/keep.md' 'keep'
                $null = & $arRealGit @('add', '-A')
                $null = & $arRealGit @('commit', '--quiet', '-m', 'base')
                $arRealBase = & $arRealGit @('rev-parse', 'HEAD')
                & $arRealWrite 'README.md' 'two'
                $arRealChild = { param($Request) return @{ ExitCode = 0; Lines = @('stub', ('SELF-TEST PARTIAL: ' + [string]::Join(',', @($Request.Suite)))) } }
                $arRealOne = Invoke-BRAVOAffectedSelfTest -RepositoryRoot $arRealDir -BaseRef $arRealBase -SelfTestInvoker $arRealChild 6>$null
                $arRealHead = & $arRealGit @('rev-parse', 'HEAD')
                & $arRealWrite 'docs/new-unknown.md' 'u'
                $arRealTwo = Invoke-BRAVOAffectedSelfTest -RepositoryRoot $arRealDir -BaseRef $arRealBase -SelfTestInvoker { param($Request) throw 'дочірній процес не повинен запускатись для V3' } 6>$null
                $arRealThree = Invoke-BRAVOAffectedSelfTest -RepositoryRoot $arRealDir -BaseRef ('no-such-ref-' + [guid]::NewGuid().ToString('N')) -SelfTestInvoker $arRealChild 6>$null
                $arTReal = (
                    $arRealOne.ExitCode -eq 0 -and $arRealOne.ResultCode -ceq 'PARTIAL-OK' -and $arRealOne.Class -ceq 'V1' -and (& $arSuiteText $arRealOne) -ceq 'Governance' -and
                    (& $arAny $arRealOne ('AFFECTED HEAD: ' + $arRealHead)) -and (& $arAny $arRealOne ('AFFECTED BASE: ' + $arRealBase)) -and (& $arAny $arRealOne 'AFFECTED DIRTY: true') -and
                    $arRealTwo.ExitCode -eq 1 -and $arRealTwo.ResultCode -ceq 'ESCALATED-V3' -and $arRealTwo.ChildInvoked -eq $false -and
                    $arRealThree.ExitCode -eq 1 -and $arRealThree.ResultCode -ceq 'BASE-INVALID')
                $arTNote = "one=$($arRealOne.ResultCode)/$($arRealOne.Class); two=$($arRealTwo.ResultCode); three=$($arRealThree.ResultCode); head=$arRealHead"
            } catch {
                $arTNote = 'виняток сценарію: ' + $_.Exception.Message
            } finally {
                Remove-Item -LiteralPath $arRealDir -Recurse -Force -ErrorAction SilentlyContinue
            }
            Test-BRAVOCondition `
                -Condition $arTReal `
                -Name "Framework/AffectedRunner.RealRepositoryEndToEnd" `
                -Failure ("B48: runner без -GitInvoker на справжньому репозиторії: V1 зі справжнім HEAD, BASE і DIRTY у виводі; untracked невідомий файл -> ESCALATED-V3 без дочірнього процесу; невідомий ref -> BASE-INVALID. Деталі: " + $arTNote)
        } else {
            Write-Host "  Сценарії AffectedRunner на реальному git-репозиторії пропущено: вони виконуються лише в git-робочій копії (потрібні .git і git)."
        }
        Test-BRAVOCondition `
            -Condition (($env:GITHUB_ACTIONS -ne 'true') -or $arRunReal) `
            -Name "Framework/AffectedRunner.RealScenariosRunOnCi" `
            -Failure "на GitHub Actions сценарії AffectedRunner на реальному git-репозиторії мусять виконуватись (потрібні .git у корені та git у PATH); їх відсутність мовчки прибрала б покриття. .git: $(Test-Path -LiteralPath (Join-Path $root '.git')); git знайдено: $($arGitCommand.Count -gt 0)"

        # --- [R]: статичні guard-и файлів ------------------------------------
        $arForbiddenLiterals = @('2>&1', '??', '?.', '&&', '||', '-Parallel', '::new', 'Invoke-Expression', 'SELF-TEST PASSED', '"SELF-TEST', 'Suite @()', "'-File'")
        $arLibraryTexts = @{}
        foreach ($arLibraryPath in @($arPath, $arCliPath, $arCollectorPath, (Join-Path $root 'selftest\BRAVOSelfTestSuiteMap.ps1'))) {
            $arLibraryTexts[$arLibraryPath] = [IO.File]::ReadAllText($arLibraryPath, [Text.Encoding]::UTF8)
        }
        $arForbiddenFound = New-Object System.Collections.Generic.List[string]
        foreach ($arLibraryPath in @($arLibraryTexts.Keys)) {
            foreach ($arLiteral in @('SELF-TEST PASSED', '"SELF-TEST')) {
                if ($arLibraryTexts[$arLibraryPath].IndexOf($arLiteral, [StringComparison]::Ordinal) -ge 0) { [void]$arForbiddenFound.Add([IO.Path]::GetFileName($arLibraryPath) + ':' + $arLiteral) }
            }
        }
        foreach ($arOwnPath in @($arPath, $arCliPath)) {
            foreach ($arLiteral in $arForbiddenLiterals) {
                if ($arLibraryTexts[$arOwnPath].IndexOf($arLiteral, [StringComparison]::Ordinal) -ge 0) { [void]$arForbiddenFound.Add([IO.Path]::GetFileName($arOwnPath) + ':' + $arLiteral) }
            }
        }
        $arParsedLibrary = Get-BRAVOSelfTestParsedFile -Path $arPath
        $arParsedCli = Get-BRAVOSelfTestParsedFile -Path $arCliPath
        $arFunctionNames = [string]::Join(',', @($arParsedLibrary.Ast.FindAll({ param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst] }, $true) |
                    ForEach-Object { $_.Name } | Sort-Object { $_ }))
        $arCliFunctions = @($arParsedCli.Ast.FindAll({ param($node) $node -is [Management.Automation.Language.FunctionDefinitionAst] }, $true))
        $arPs7Nodes = @($arParsedLibrary.Ast.FindAll({ param($node) @('TernaryExpressionAst', 'PipelineChainAst', 'NullConditionalMemberAccessAst', 'NullConditionalIndexExpressionAst', 'ChainableAst') -contains $node.GetType().Name }, $true)) +
            @($arParsedCli.Ast.FindAll({ param($node) @('TernaryExpressionAst', 'PipelineChainAst', 'NullConditionalMemberAccessAst', 'NullConditionalIndexExpressionAst', 'ChainableAst') -contains $node.GetType().Name }, $true))
        Test-BRAVOCondition `
            -Condition (
                $arForbiddenFound.Count -eq 0 -and $arPs7Nodes.Count -eq 0 -and
                $arFunctionNames -ceq 'ConvertTo-BRAVOAffectedPrintableText,Invoke-BRAVOAffectedChildProcess,Invoke-BRAVOAffectedSelfTest,New-BRAVOAffectedChildRequest' -and
                $arCliFunctions.Count -eq 0 -and
                $arText.Contains('-EncodedCommand') -and $arText.Contains('-ExecutionPolicy') -and $arText.Contains('child| ')
            ) `
            -Name "Framework/AffectedRunner.StaticSourceHasNoForbiddenConstructs" `
            -Failure ("ci\BRAVOAffectedSelfTest.ps1 і ci\Invoke-BRAVOAffectedSelfTest.ps1: без 2>&1, ??, ?., &&, ||, -Parallel, ::new, Invoke-Expression, -File, порожнього '-Suite @()', літералів маркера повного прогону чи рядка з лапкою перед маркером (так само у збирача й мапи); без PowerShell 7-вузлів; рівно чотири функції в бібліотеці й жодної в CLI. Знайдено: [" +
                [string]::Join(', ', $arForbiddenFound.ToArray()) + "] PS7-вузлів: $($arPs7Nodes.Count); функції: [$arFunctionNames]; функцій у CLI: $($arCliFunctions.Count)")

        # R19 [R]: CLI - тонка обгортка; лише exit 0/1; нової таблиці exit-кодів немає.
        $arExitTexts = @([regex]::Matches($arCliText, '(?m)^\s*exit\s+(\S+)') | ForEach-Object { $_.Groups[1].Value })
        $arCliLineCount = @($arCliText -split "`n").Count
        Test-BRAVOCondition `
            -Condition (
                $arCliText.Contains('Set-StrictMode -Version 2.0') -and [regex]::IsMatch($arCliText, "\`$ErrorActionPreference\s*=\s*'Stop'") -and
                $arExitTexts.Count -ge 2 -and @($arExitTexts | Where-Object { $_ -cne '0' -and $_ -cne '1' }).Count -eq 0 -and
                -not [regex]::IsMatch($arCliText, '(?i)BRAVO\.ExitCodes|ExitCode\s*=') -and
                $arCliText.Contains('Invoke-BRAVOAffectedSelfTest') -and $arCliLineCount -le 120 -and
                -not [regex]::IsMatch($arText, '(?i)BRAVO\.ExitCodes|\bexit\s+\d')
            ) `
            -Name "Framework/AffectedRunner.CliIsThinAndExitsOnlyZeroOrOne" `
            -Failure "R19: ci\Invoke-BRAVOAffectedSelfTest.ps1 - тонкий CLI (до 120 рядків) зі Set-StrictMode -Version 2.0, `$ErrorActionPreference = 'Stop' і лише exit 0 або exit 1; нових exit-кодів і BRAVO.ExitCodes немає; бібліотека не викликає exit. Знайдено exit: [$([string]::Join(', ', $arExitTexts))]; рядків CLI: $arCliLineCount"

        $arBytesOk = $true
        foreach ($arFilePath in @($arPath, $arCliPath)) {
            $arBytes = [IO.File]::ReadAllBytes($arFilePath)
            $arBareLf = $false
            for ($arByteIndex = 0; $arByteIndex -lt $arBytes.Length; $arByteIndex++) {
                if ($arBytes[$arByteIndex] -eq 10 -and ($arByteIndex -eq 0 -or $arBytes[$arByteIndex - 1] -ne 13)) { $arBareLf = $true; break }
            }
            $arBytesOk = $arBytesOk -and $arBytes.Length -gt 3 -and $arBytes[0] -eq 0xEF -and $arBytes[1] -eq 0xBB -and $arBytes[2] -eq 0xBF -and -not $arBareLf
        }
        Test-BRAVOCondition `
            -Condition (@($arParsedLibrary.Errors).Count -eq 0 -and @($arParsedCli.Errors).Count -eq 0 -and $arBytesOk) `
            -Name "Framework/AffectedRunner.FilesParseAndHaveBomCrlf" `
            -Failure "ci\BRAVOAffectedSelfTest.ps1 і ci\Invoke-BRAVOAffectedSelfTest.ps1 мусять розбиратись без помилок (Windows PowerShell 5.1), мати UTF-8 BOM і CRLF, як сусідні файли ci\. Помилок розбору: $(@($arParsedLibrary.Errors).Count)/$(@($arParsedCli.Errors).Count)"
    }
}
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Framework.AffectedRunner' } }

if (Enter-BRAVOSelfTestSection -Name 'Tail/Framework.SectionIsolation') { try {

# ============================================================
# #219 (частина B): регресійні проби секційної ізоляції.
#
# Кожен сценарій — ОКРЕМИЙ дочірній процес: сценарії навмисно ламають
# фреймворк (підміна Test-BRAVOCondition модулем, зламана реєстрація
# винятку, зламаний звіт) і завершуються через exit, тож у процесі
# головного прогону їх виконувати не можна. Дочірній скрипт збирається
# з РЕАЛЬНОГО коду цього файлу (AST-екстракція функцій фреймворку, його
# ініціалізації та обробників зовнішнього try/catch/finally), а не з
# ручної копії: зміна межі тут одразу перевіряється пробою.
#
# Заглушки лише дві, обидві — зовнішні для фреймворку ефекти:
# Complete-BRAVOHelperLog (друкує маркер і робить exit із тим самим кодом,
# як справжня) і Wait-BRAVOManualExit (без паузи). Маркери перевірок —
# ASCII, щоб результат не залежав від кодової сторінки консолі хоста.
# ============================================================
& {
    $isolationProbeRoot = Join-Path ([IO.Path]::GetTempPath()) ('BRAVO_SECTION_ISOLATION_' + [guid]::NewGuid().ToString('N'))
    [void][IO.Directory]::CreateDirectory($isolationProbeRoot)
    $isolationResults = @{}
    $isolationProbeError = $null
    try {
        $isolationOwnAst = Get-BRAVOSelfTestOwnSourceAst
        $isolationTopStatements = @($isolationOwnAst.EndBlock.Statements)
        $isolationSnapshotCall = @($isolationTopStatements | Where-Object {
                $_ -is [Management.Automation.Language.PipelineAst] -and
                $_.PipelineElements.Count -eq 1 -and
                $_.PipelineElements[0] -is [Management.Automation.Language.CommandAst] -and
                $_.PipelineElements[0].GetCommandName() -eq 'Save-BRAVOSelfTestFrameworkSnapshot' })
        $isolationDataKeyAssignment = @($isolationTopStatements | Where-Object {
                $_ -is [Management.Automation.Language.AssignmentStatementAst] -and
                $_.Left.Extent.Text -eq '$script:BRAVOSelfTestGlobalFatalDataKey' })
        $isolationOuterTry = @($isolationTopStatements | Where-Object {
                $_ -is [Management.Automation.Language.TryStatementAst] -and
                $_.Body.Extent.Text.Contains('BRAVO SELF-TEST (STATIC + RUNTIME)') }) | Select-Object -First 1
        if ($isolationSnapshotCall.Count -ne 1 -or $isolationDataKeyAssignment.Count -ne 1 -or $null -eq $isolationOuterTry) {
            throw 'не знайдено знімок фреймворку, ключ маркера або зовнішній try — межі фреймворку змінено'
        }
        $isolationMainTry = @($isolationOuterTry.Body.Statements |
                Where-Object { $_ -is [Management.Automation.Language.TryStatementAst] }) | Select-Object -First 1
        $isolationOuterStatements = @($isolationOuterTry.Body.Statements)
        $isolationFrameworkNames = @(@($isolationSnapshotCall[0].PipelineElements[0].CommandElements |
                    ForEach-Object { $_.FindAll({ param($node) $node -is [Management.Automation.Language.StringConstantExpressionAst] }, $true) } |
                    ForEach-Object { $_.Value } |
                    Where-Object { $_ -like '*-BRAVO*' }) + @('Initialize-BRAVOSelfTestSectionState', 'Save-BRAVOSelfTestFrameworkSnapshot'))
        $isolationFunctionText = New-Object System.Text.StringBuilder
        foreach ($isolationFunctionName in $isolationFrameworkNames) {
            $isolationDefinition = @($isolationTopStatements | Where-Object {
                    $_ -is [Management.Automation.Language.FunctionDefinitionAst] -and $_.Name -eq $isolationFunctionName }) |
                Select-Object -First 1
            if ($null -eq $isolationDefinition) { throw "функцію фреймворку '$isolationFunctionName' не знайдено" }
            [void]$isolationFunctionText.AppendLine($isolationDefinition.Extent.Text)
        }
        $isolationPrologue = @'
param([string]$RepoRoot, [string]$ProbeRoot)
Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$NoPause = $true
Import-Module -Name (Join-Path $RepoRoot 'modules\BRAVO.Console\BRAVO.Console.psd1') -Force -ErrorAction Stop
function Complete-BRAVOHelperLog { param([int]$ExitCode) Write-Host ('PROBE-HELPERLOG-EXIT=' + $ExitCode); exit $ExitCode }
function Wait-BRAVOManualExit { param([switch]$NoPause) }
$script:failures = New-Object System.Collections.ArrayList
$script:passCount = 0
$script:environmentLimitations = New-Object System.Collections.ArrayList
$script:BRAVOSelfTestSelectedSuite = $null
$script:suiteDurationTotals = [ordered]@{}
$script:currentSuiteName = 'Root (inline)'
$script:currentSuiteSpanStopwatch = $null
$script:testTimings = New-Object System.Collections.Generic.List[object]
$script:lastAssertionCompletedAtMs = 0.0
$script:selfTestTotalStopwatch = [Diagnostics.Stopwatch]::StartNew()
$script:BRAVOSelfTestOwnedRuntimeModules = New-Object System.Collections.Generic.List[object]
$script:selfTestHelperLogPath = Join-Path $ProbeRoot 'probe.log'
$script:selfTestConfigRoot = Join-Path $ProbeRoot 'config-root'
[void][IO.Directory]::CreateDirectory($script:selfTestConfigRoot)
'@
        $isolationFramework = $isolationDataKeyAssignment[0].Extent.Text + "`r`n" + $isolationFunctionText.ToString() +
            "Initialize-BRAVOSelfTestSectionState`r`n" + $isolationSnapshotCall[0].Extent.Text + "`r`n"
        # Обробники — дослівно з реального файлу: головний catch, зовнішні
        # catch/finally і два фінальні оператори зовнішнього try.
        $isolationMainCatch = $isolationMainTry.CatchClauses[0].Extent.Text
        $isolationOuterCatch = $isolationOuterTry.CatchClauses[0].Extent.Text
        $isolationOuterFinally = 'finally ' + $isolationOuterTry.Finally.Extent.Text
        $isolationFinalStatements = $isolationOuterStatements[$isolationOuterStatements.Count - 2].Extent.Text + "`r`n" +
            $isolationOuterStatements[$isolationOuterStatements.Count - 1].Extent.Text

        $isolationScenarios = [ordered]@{
            Pass      = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Root/Alpha') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/PassAlpha' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Alpha' } }
'@
                Tail = @'
if (Enter-BRAVOSelfTestSection -Name 'Tail/Omega') { try {
Test-BRAVOCondition -Condition $true -Name 'Probe/PassOmega' -Failure 'n/a'
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Omega' } }
'@
            }
            StubIsolation = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Suite/Gamma') { try {
    Enter-BRAVOSelfTestSuite -Name 'Gamma'
    [void](New-Module -ScriptBlock { function Start-Sleep { 'stub' }; function Get-Service { 'stub' } })
    Set-Alias -Name Get-Date -Value Get-Process -Scope Global
    Test-BRAVOCondition -Condition ((Start-Sleep) -eq 'stub') -Name 'Probe/StubActiveInSuite' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Suite/Gamma' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/AfterStub') { try {
    Test-BRAVOCondition -Condition (-not (Test-Path 'function:Start-Sleep') -and -not (Test-Path 'function:Get-Service') -and -not (Test-Path 'alias:Get-Date')) -Name 'Probe/StubGoneAfterSuite' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/AfterStub' } }
'@
                Tail = @'
if (Enter-BRAVOSelfTestSection -Name 'Tail/Omega') { try {
Test-BRAVOCondition -Condition $true -Name 'Probe/StubOmega' -Failure 'n/a'
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Omega' } }
'@
            }
            # Перерваний suite, у якого ще й відновлення ізоляції кидає (знімок
            # без CommandStates): первинний Fault має лишитися, збій
            # відновлення — окремим FAIL, а не повторною реєстрацією секції.
            AbortedSuiteCleanupFault = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Suite/Delta') { try {
    Enter-BRAVOSelfTestSuite -Name 'Delta'
    $script:BRAVOSelfTestSectionStack[$script:BRAVOSelfTestSectionStack.Count - 1].SuiteIsolation = [pscustomobject]@{ OwnedStartIndex = 0 }
    throw (New-Object System.IO.InvalidDataException 'probe-primary-fault')
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Suite/Delta' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/AfterDelta') { try {
    $deltaRecord = $script:BRAVOSelfTestSectionIndex['Suite/Delta']
    Test-BRAVOCondition -Condition ($deltaRecord.Status -eq 'Aborted' -and $deltaRecord.Fault.Message -eq 'probe-primary-fault') -Name 'Probe/PrimaryFaultKept' -Failure ('Fault: ' + $deltaRecord.Fault.Message)
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/AfterDelta' } }
'@
                Tail = ''
            }
            MultiFault = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Root/Alpha') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/AlphaBefore' -Failure 'n/a'
    $alphaFixture = Join-Path $ProbeRoot 'alpha-fixture'
    [void][IO.Directory]::CreateDirectory($alphaFixture)
    try {
        throw (New-Object System.IO.InvalidDataException 'probe-alpha-fault')
    } finally {
        [IO.Directory]::Delete($alphaFixture, $true)
    }
    Test-BRAVOCondition -Condition $true -Name 'Probe/AlphaUnreachable' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Alpha' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/AlphaConsumer' -DependsOn 'Root/Alpha') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/AlphaConsumerUnreachable' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/AlphaConsumer' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/Beta') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/BetaBefore' -Failure 'n/a'
    $betaNothing = $null
    $betaNothing.ProbeMissingMethod()
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Beta' } }
    if (Enter-BRAVOSelfTestSection -Name 'Suite/Gamma') { try {
    Enter-BRAVOSelfTestSuite -Name 'Gamma'
    Test-BRAVOCondition -Condition $true -Name 'Probe/GammaBefore' -Failure 'n/a'
    $gammaValue = $script:probeGammaUndefinedVariable
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Suite/Gamma' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/Delta') { try {
    Write-Host ('PROBE-SUITE-AFTER-GAMMA=' + $script:currentSuiteName)
    Test-BRAVOCondition -Condition $false -Name 'Probe/DeltaOrdinaryFail' -Failure 'probe-ordinary-fail'
    Test-BRAVOCondition -Condition $true -Name 'Probe/DeltaRuns' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Delta' } }
'@
                Tail = @'
[void]$script:BRAVOSelfTestOwnedRuntimeModules.Add([pscustomobject]@{ Module = [pscustomobject]@{ ProbeMarker = 'broken' }; FunctionNames = @('Probe-NoSuchFunction') })
if (Enter-BRAVOSelfTestSection -Name 'Tail/Omega') { try {
Test-BRAVOCondition -Condition $true -Name 'Probe/TailOmegaRuns' -Failure 'n/a'
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Omega' } }
'@
            }
            # Імена suite в подвійних лапках: regex-guard-и #187 читають сирий
            # текст цього файлу й інакше побачили б синтетичні Gamma/Other як справжні.
            Selective  = @{
                Pre  = "`$script:BRAVOSelfTestSelectedSuite = @('Gamma')"
                Main = @'
    if (Test-BRAVOSelfTestSuiteEnabled -Name "Gamma") {
        if (Enter-BRAVOSelfTestSection -Name 'Suite/Gamma') { try {
        Enter-BRAVOSelfTestSuite -Name 'Gamma'
        Test-BRAVOCondition -Condition $true -Name 'Probe/SelectiveGammaBefore' -Failure 'n/a'
        throw (New-Object System.FormatException 'probe-selective-fault')
        } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Suite/Gamma' } }
    }
    if (Test-BRAVOSelfTestSuiteEnabled -Name "Other") {
        if (Enter-BRAVOSelfTestSection -Name 'Suite/Other') { try {
        Test-BRAVOCondition -Condition $true -Name 'Probe/OtherMustNotRun' -Failure 'n/a'
        } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Suite/Other' } }
    }
    if (Enter-BRAVOSelfTestSection -Name 'Root/AfterSelective') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/AfterSelectiveRuns' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/AfterSelective' } }
'@
                Tail = ''
            }
            # Успішний вибірковий прогін: код 0 і SELF-TEST PARTIAL (з усіма вибраними
            # іменами), але ніколи SELF-TEST PASSED. Ті самі правила щодо лапок: імена
            # suite в подвійних лапках, щоб regex-guard-и #187 не бачили синтетичні suite.
            SelectivePass = @{
                Pre  = "`$script:BRAVOSelfTestSelectedSuite = @('Gamma', 'Other')"
                Main = @'
    if (Test-BRAVOSelfTestSuiteEnabled -Name "Gamma") {
        if (Enter-BRAVOSelfTestSection -Name 'Suite/Gamma') { try {
        Enter-BRAVOSelfTestSuite -Name 'Gamma'
        Test-BRAVOCondition -Condition $true -Name 'Probe/SelectivePassGamma' -Failure 'n/a'
        } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Suite/Gamma' } }
    }
'@
                Tail = ''
            }
            Shadowed   = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Root/Outer') { try {
    if (Enter-BRAVOSelfTestSection -Name 'Root/Corrupt') { try {
    $null = New-Module -Name 'BRAVOProbeShadow' -ScriptBlock { function Test-BRAVOCondition { param($Condition, $Name, $Failure) } }
    Test-BRAVOCondition -Condition $false -Name 'Probe/ShadowSwallowedFail' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Corrupt' } }
    Write-Host 'PROBE-OUTER-CONTINUED-AFTER-CORRUPT'
    Test-BRAVOCondition -Condition $true -Name 'Probe/OuterAfterCorruptMustNotRun' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Outer' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/AfterCorrupt') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/AfterCorruptMustNotRun' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/AfterCorrupt' } }
'@
                Tail = @'
if (Enter-BRAVOSelfTestSection -Name 'Tail/AfterCorrupt') { try {
Test-BRAVOCondition -Condition $true -Name 'Probe/TailAfterCorruptMustNotRun' -Failure 'n/a'
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/AfterCorrupt' } }
'@
            }
            ShadowedTail = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Root/Alpha') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/ShadowedTailAlpha' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Alpha' } }
'@
                # Найгірший випадок: підміна самого звіту, що друкує PASSED і
                # виходить із кодом 0.
                Tail = @'
if (Enter-BRAVOSelfTestSection -Name 'Tail/CorruptReport') { try {
$null = New-Module -Name 'BRAVOProbeReportShadow' -ScriptBlock { function Complete-BRAVOSelfTestReport { Write-Host 'SELF-TEST PASSED'; exit 0 } }
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/CorruptReport' } }
if (Enter-BRAVOSelfTestSection -Name 'Tail/AfterCorruptReport') { try {
Test-BRAVOCondition -Condition $true -Name 'Probe/TailAfterCorruptReportMustNotRun' -Failure 'n/a'
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/AfterCorruptReport' } }
'@
            }
            BrokenRegistration = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Root/BreakRegistration') { try {
    Set-Item -LiteralPath 'function:Register-BRAVOSelfTestSectionFault' -Value { param($ErrorRecord) }
    throw 'probe-swallowed-fault'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/BreakRegistration' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/AfterBreak') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/AfterBreakMustNotRun' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/AfterBreak' } }
'@
                Tail = ''
            }
            GlobalBoundary = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Root/BoundaryOuter') { try {
    if (Enter-BRAVOSelfTestSection -Name 'ProbeBoundary' -Policy GlobalFatal) { try {
    throw (New-Object System.IO.FileNotFoundException 'probe-boundary-fault')
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'ProbeBoundary' } }
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/BoundaryOuter' } }
    if (Enter-BRAVOSelfTestSection -Name 'Root/AfterBoundary') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/AfterBoundaryMustNotRun' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/AfterBoundary' } }
'@
                Tail = @'
if (Enter-BRAVOSelfTestSection -Name 'Tail/AfterBoundary') { try {
Test-BRAVOCondition -Condition $true -Name 'Probe/TailAfterBoundaryRuns' -Failure 'n/a'
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/AfterBoundary' } }
'@
            }
            UnprotectedTail = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Root/Alpha') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/UnprotectedAlpha' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Alpha' } }
'@
                Tail = "throw (New-Object System.ArgumentException 'probe-unprotected-tail')"
            }
            BrokenReport = @{
                Pre  = ''
                Main = @'
    if (Enter-BRAVOSelfTestSection -Name 'Root/Alpha') { try {
    Test-BRAVOCondition -Condition $true -Name 'Probe/BrokenReportAlpha' -Failure 'n/a'
    } catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Root/Alpha' } }
'@
                # Зламано і звіт, і журнал: єдиним, що лишається, є мінімальний
                # шлях із власним exit 1.
                Tail = "Set-Item -LiteralPath 'function:Write-BRAVOSelfTestSectionReport' -Value { throw 'probe-report-broken' }`r`n" +
                    "Set-Item -LiteralPath 'function:Complete-BRAVOHelperLog' -Value { throw 'probe-helperlog-broken' }"
            }
        }

        $isolationHost = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        $isolationResults = @{}
        foreach ($isolationScenarioName in @($isolationScenarios.Keys)) {
            $isolationScenario = $isolationScenarios[$isolationScenarioName]
            $isolationScenarioRoot = Join-Path $isolationProbeRoot $isolationScenarioName
            [void][IO.Directory]::CreateDirectory($isolationScenarioRoot)
            $isolationScript = $isolationPrologue + "`r`n" + $isolationFramework + $isolationScenario.Pre + "`r`n" +
                "try {`r`ntry {`r`n    Enter-BRAVOSelfTestSuite -Name 'Root (inline)'`r`n" + $isolationScenario.Main + "`r`n" +
                "    Enter-BRAVOSelfTestSuite -Name 'Root (inline)'`r`n} " + $isolationMainCatch + "`r`n" +
                $isolationScenario.Tail + "`r`n" + $isolationFinalStatements + "`r`n} " + $isolationOuterCatch + ' ' +
                $isolationOuterFinally + "`r`n"
            $isolationScriptPath = Join-Path $isolationScenarioRoot ('probe-' + $isolationScenarioName + '.ps1')
            # BOM обов'язковий: Windows PowerShell 5.1 без нього читає
            # кириличні рядки екстрагованих функцій у кодовій сторінці ANSI.
            [IO.File]::WriteAllText($isolationScriptPath, $isolationScript, (New-Object Text.UTF8Encoding($true)))
            # Без 2>&1: у Windows PowerShell 5.1 рядок stderr нативного процесу
            # під ErrorActionPreference = Stop став би термінальною помилкою батька.
            $isolationOutput = @(& $isolationHost -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass `
                    -File $isolationScriptPath $root $isolationScenarioRoot | ForEach-Object { [string]$_ })
            $isolationResults[$isolationScenarioName] = [pscustomobject]@{
                ExitCode = $LASTEXITCODE
                Text     = [string]::Join("`n", $isolationOutput)
                Root     = $isolationScenarioRoot
            }
        }
    } catch {
        $isolationProbeError = $_.Exception.Message
    } finally {
        if ([IO.Directory]::Exists($isolationProbeRoot)) {
            [IO.Directory]::Delete($isolationProbeRoot, $true)
        }
    }

    # Повертає перелік розбіжностей сценарію з очікуванням; порожній — збіг.
    $isolationMismatch = {
        param([string]$ScenarioName, [int]$ExpectedExitCode, [string[]]$Present = @(), [string[]]$Absent = @())
        $scenarioResult = $isolationResults[$ScenarioName]
        if ($null -eq $scenarioResult) { return @("сценарій $ScenarioName не виконано") }
        $scenarioProblems = New-Object System.Collections.Generic.List[string]
        if ($scenarioResult.ExitCode -ne $ExpectedExitCode) {
            [void]$scenarioProblems.Add(("код виходу {0} замість {1}" -f $scenarioResult.ExitCode, $ExpectedExitCode))
        }
        foreach ($presentMarker in $Present) {
            if (-not $scenarioResult.Text.Contains($presentMarker)) { [void]$scenarioProblems.Add("немає '$presentMarker'") }
        }
        foreach ($absentMarker in $Absent) {
            if ($scenarioResult.Text.Contains($absentMarker)) { [void]$scenarioProblems.Add("є зайве '$absentMarker'") }
        }
        return @($scenarioProblems.ToArray())
    }
    # [НЕДОСТУПНО] — лише коли дочірній процес не дав результату ВЗАГАЛІ і
    # хост доведено обмежений; проба, що відпрацювала неправильно, — [FAIL].
    $isolationRestriction = {
        param([string]$ScenarioName)
        $scenarioResult = $isolationResults[$ScenarioName]
        if ($null -ne $scenarioResult -and ($scenarioResult.Text.Contains('PROBE-HELPERLOG-EXIT=') -or
                $scenarioResult.Text.Contains('SELF-TEST '))) { return '' }
        $restrictionReason = Get-BRAVOSelfTestHostRestriction
        if ([string]::IsNullOrWhiteSpace($restrictionReason)) { return '' }
        return $restrictionReason
    }
    if ($null -ne $isolationProbeError) {
        Test-BRAVOCondition `
            -Condition $false `
            -Name 'Framework/SectionIsolation.ProbeExecution' `
            -EnvironmentLimitation (& $isolationRestriction '') `
            -Failure "проби секційної ізоляції не вдалося підготувати чи запустити: $isolationProbeError"
    } else {
        # Негативний контроль: без збоїв той самий зібраний каркас дає 0 і
        # PASSED — інакше решта проб нічого б не доводила.
        $isolationProblems = @(& $isolationMismatch 'Pass' 0 @('[PASS] Probe/PassAlpha', '[PASS] Probe/PassOmega',
                'SELF-TEST PASSED', 'PROBE-HELPERLOG-EXIT=0') @('SELF-TEST FAILED'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.CleanRunPasses' `
            -EnvironmentLimitation (& $isolationRestriction 'Pass') `
            -Failure ('каркас без збоїв має дати код 0 і SELF-TEST PASSED: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'StubIsolation' 0 @('[PASS] Probe/StubActiveInSuite', '[PASS] Probe/StubGoneAfterSuite',
                'SELF-TEST PASSED') @('SELF-TEST FAILED', 'Framework/SuiteIsolation'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.SuiteBoundaryRemovesBuiltinStubs' `
            -EnvironmentLimitation (& $isolationRestriction 'StubIsolation') `
            -Failure ('реальний Enter/Complete для Suite/* має прибрати заглушки вбудованих команд (Start-Sleep, Get-Service, alias Get-Date): ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'AbortedSuiteCleanupFault' 1 @('[PASS] Probe/PrimaryFaultKept',
                'probe-primary-fault', 'Section/Suite/Delta — відновлення ізоляції після перерваного suite', 'SELF-TEST FAILED') @(
                'Section/Suite/Delta: перервано винятком [System.Management.Automation.PropertyNotFoundException]'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.AbortedSuiteCleanupFaultKeepsPrimaryFault' `
            -EnvironmentLimitation (& $isolationRestriction 'AbortedSuiteCleanupFault') `
            -Failure ('збій відновлення ізоляції після перерваного suite не має перезаписувати первинний виняток: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'MultiFault' 1 @('[PASS] Probe/AlphaBefore', '[PASS] Probe/BetaBefore',
                '[PASS] Probe/GammaBefore', '[PASS] Probe/DeltaRuns', '[PASS] Probe/TailOmegaRuns', 'SELF-TEST FAILED',
                'PROBE-HELPERLOG-EXIT=1', 'Total wall-clock') @('Probe/AlphaUnreachable', 'SELF-TEST PASSED'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.FatalSectionFailsAndOthersContinue' `
            -EnvironmentLimitation (& $isolationRestriction 'MultiFault') `
            -Failure ('виняток у секції має провалити прогін, а незалежні секції й хвіст — виконатися: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'MultiFault' 1 @('System.IO.InvalidDataException', 'probe-alpha-fault',
                'probe-MultiFault.ps1:', 'probe-MultiFault.ps1: line', 'VariableIsUndefined', 'probeGammaUndefinedVariable',
                'Section/Root/Beta', 'Probe/DeltaOrdinaryFail: probe-ordinary-fail'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.MultipleFaultsAllReportedWithDiagnostics' `
            -EnvironmentLimitation (& $isolationRestriction 'MultiFault') `
            -Failure ('кожна перервана секція має потрапити у звіт із типом, повідомленням, file:line і стеком: ' +
                [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'MultiFault' 1 @('Section/Root/AlphaConsumer', 'PROBE-SUITE-AFTER-GAMMA=Root (inline)') @('Probe/AlphaConsumerUnreachable'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.DependentOfAbortedSectionIsSkippedAsFailure' `
            -EnvironmentLimitation (& $isolationRestriction 'MultiFault') `
            -Failure ('залежна від перерваної секція має бути пропущена як помилка, а suite-атрибуція — повернутися до Root: ' + [string]::Join('; ', $isolationProblems))

        $isolationMultiFault = $isolationResults['MultiFault']
        $isolationProblems = @(& $isolationMismatch 'MultiFault' 1 @('Framework/FinalCleanup.OwnedRuntimeModules', 'probe-alpha-fault'))
        if ($null -ne $isolationMultiFault) {
            # Фікстура перерваної секції і config root прибрані, попри збій
            # іншого кроку прибирання; першопричина лишилась у звіті ПІСЛЯ нього.
            if ([IO.Directory]::Exists((Join-Path $isolationMultiFault.Root 'alpha-fixture'))) { $isolationProblems += 'фікстуру перерваної секції не прибрано' }
            if ([IO.Directory]::Exists((Join-Path $isolationMultiFault.Root 'config-root'))) { $isolationProblems += 'config root не прибрано' }
            if ($isolationMultiFault.Text.LastIndexOf('probe-alpha-fault') -lt $isolationMultiFault.Text.IndexOf('Framework/FinalCleanup.OwnedRuntimeModules')) {
                $isolationProblems += 'першопричина не повторена у звіті після збою прибирання'
            }
        }
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.CleanupFaultDoesNotMaskCause' `
            -EnvironmentLimitation (& $isolationRestriction 'MultiFault') `
            -Failure ('збій прибирання має бути зареєстрований окремо й не маскувати першопричину: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'Selective' 1 @('[PASS] Probe/SelectiveGammaBefore', '[PASS] Probe/AfterSelectiveRuns',
                'System.FormatException', 'probe-selective-fault', 'SELF-TEST FAILED') @('Probe/OtherMustNotRun', 'SELF-TEST PARTIAL', 'SELF-TEST PASSED'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.SelectiveRunWithFatalSectionFails' `
            -EnvironmentLimitation (& $isolationRestriction 'Selective') `
            -Failure ('вибірковий прогін із перерваною секцією має дати FAILED, а не PARTIAL: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'SelectivePass' 0 @('[PASS] Probe/SelectivePassGamma',
                'SELF-TEST PARTIAL: Gamma,Other', 'PROBE-HELPERLOG-EXIT=0') @('SELF-TEST PASSED', 'SELF-TEST FAILED'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.SelectiveCleanRunPrintsPartialNotPassed' `
            -EnvironmentLimitation (& $isolationRestriction 'SelectivePass') `
            -Failure ('успішний вибірковий прогін має дати код 0 і SELF-TEST PARTIAL, але не SELF-TEST PASSED: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'Shadowed' 1 @('Framework/RunStopped', 'BRAVOProbeShadow', 'Section/Tail/AfterCorrupt',
                'SELF-TEST FAILED', 'PROBE-HELPERLOG-EXIT=1') @('Probe/OuterAfterCorruptMustNotRun', 'Probe/AfterCorruptMustNotRun',
                'Probe/TailAfterCorruptMustNotRun', 'PROBE-OUTER-CONTINUED-AFTER-CORRUPT', 'SELF-TEST PASSED'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.ShadowedAssertionStopsRun' `
            -EnvironmentLimitation (& $isolationRestriction 'Shadowed') `
            -Failure ('затінена модулем Test-BRAVOCondition має зупинити прогін (глобальна межа), а звіт — виконатись справжнім кодом: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'ShadowedTail' 1 @('Framework/RunStopped', 'BRAVOProbeReportShadow',
                'Complete-BRAVOSelfTestReport', 'SELF-TEST FAILED', 'PROBE-HELPERLOG-EXIT=1') @('Probe/TailAfterCorruptReportMustNotRun', 'SELF-TEST PASSED'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.ShadowedReportInTailStillFails' `
            -EnvironmentLimitation (& $isolationRestriction 'ShadowedTail') `
            -Failure ('підмінений у хвості звіт має бути відновлений зі знімка, а прогін — завершитись FAILED із кодом 1: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'BrokenRegistration' 1 @('Framework/RunStopped', 'Register-BRAVOSelfTestSectionFault',
                'SELF-TEST FAILED', 'PROBE-HELPERLOG-EXIT=1') @('Probe/AfterBreakMustNotRun', 'SELF-TEST PASSED'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.BrokenFaultRegistrationStopsRun' `
            -EnvironmentLimitation (& $isolationRestriction 'BrokenRegistration') `
            -Failure ('підмінена реєстрація винятку, що поглинає збої, має зупинити прогін: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'GlobalBoundary' 1 @('System.IO.FileNotFoundException', 'probe-boundary-fault',
                '[PASS] Probe/TailAfterBoundaryRuns', 'SELF-TEST FAILED') @('Probe/AfterBoundaryMustNotRun', 'SELF-TEST PASSED'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.GlobalFatalBoundaryStopsMainBody' `
            -EnvironmentLimitation (& $isolationRestriction 'GlobalBoundary') `
            -Failure ('виняток у GlobalFatal-секції має зупинити основне тіло, але не хвіст і не звіт: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'UnprotectedTail' 1 @('Framework/UnprotectedFatal', 'System.ArgumentException',
                'probe-unprotected-tail', 'SELF-TEST FAILED', 'Total wall-clock', 'PROBE-HELPERLOG-EXIT=1') @('SELF-TEST PASSED'))
        $isolationUnprotected = $isolationResults['UnprotectedTail']
        if ($null -ne $isolationUnprotected -and [IO.Directory]::Exists((Join-Path $isolationUnprotected.Root 'config-root'))) {
            $isolationProblems += 'config root не прибрано'
        }
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.UnprotectedFaultStillReportsAndCleans' `
            -EnvironmentLimitation (& $isolationRestriction 'UnprotectedTail') `
            -Failure ('виняток поза секціями має завершитись повним звітом, прибиранням і кодом 1: ' + [string]::Join('; ', $isolationProblems))

        $isolationProblems = @(& $isolationMismatch 'BrokenReport' 1 @('Framework/UnprotectedFatal', 'probe-report-broken',
                'SELF-TEST FAILED: ') @('SELF-TEST PASSED', 'PROBE-HELPERLOG-EXIT'))
        Test-BRAVOCondition `
            -Condition ($isolationProblems.Count -eq 0) `
            -Name 'Framework/SectionIsolation.BrokenReportFallsBackToMinimalFailure' `
            -EnvironmentLimitation (& $isolationRestriction 'BrokenReport') `
            -Failure ('збій машинерії звіту має дати мінімальний SELF-TEST FAILED і код 1: ' + [string]::Join('; ', $isolationProblems))
    }
}
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Framework.SectionIsolation' } }
if (Enter-BRAVOSelfTestSection -Name 'Tail/Framework.SectionBoundaries') { try {

# ============================================================
# #219 (частина B): структурні guard-и секційної ізоляції.
#
# Ізоляція працює лише доти, доки межі мають ОДНУ форму і покривають усе
# виконуване тіло. Код, доданий МІЖ секціями, знову летів би в головний
# catch і зупиняв решту прогону; break/continue/exit/return на рівні
# файлу у фрагменті чи секції обійшли б і секцію, і звіт. Аналізатор —
# один scriptblock, що працює і на реальному джерелі, і на синтетичних
# фікстурах (IsMeaningful): guard, який нічого не знаходить на навмисно
# зламаному тексті, нічого й не доводить.
# ============================================================
& {
    $boundaryAnalyze = {
        param(
            [Parameter(Mandatory = $true)]$RootAst,
            [Parameter(Mandatory = $true)][hashtable]$FragmentAst,
            [string[]]$GlobalFatalAllowList = @()
        )
        $boundaryProblems = [ordered]@{
            WellFormed = New-Object System.Collections.Generic.List[string]
            Coverage   = New-Object System.Collections.Generic.List[string]
            Jumps      = New-Object System.Collections.Generic.List[string]
            Skeleton   = New-Object System.Collections.Generic.List[string]
        }
        $commandNameOf = {
            param($Statement)
            if ($Statement -is [Management.Automation.Language.PipelineAst] -and $Statement.PipelineElements.Count -eq 1 -and
                $Statement.PipelineElements[0] -is [Management.Automation.Language.CommandAst]) {
                return [string]$Statement.PipelineElements[0].GetCommandName()
            }
            return ''
        }
        # Значення -Name/-DependsOn/-Policy як літерали; $null — не літерал.
        $literalParameters = {
            param($CommandAst)
            $parameterValues = @{}
            $elements = @($CommandAst.CommandElements)
            for ($elementIndex = 1; $elementIndex -lt $elements.Count; $elementIndex++) {
                $element = $elements[$elementIndex]
                if (-not ($element -is [Management.Automation.Language.CommandParameterAst]) -or $elementIndex + 1 -ge $elements.Count) { return $null }
                $valueAst = $elements[$elementIndex + 1]
                $values = @()
                if ($valueAst -is [Management.Automation.Language.StringConstantExpressionAst]) {
                    $values = @($valueAst.Value)
                } elseif ($valueAst -is [Management.Automation.Language.ArrayLiteralAst] -and
                    @($valueAst.Elements | Where-Object { -not ($_ -is [Management.Automation.Language.StringConstantExpressionAst]) }).Count -eq 0) {
                    $values = @($valueAst.Elements | ForEach-Object { $_.Value })
                } else {
                    return $null
                }
                $parameterValues[$element.ParameterName] = $values
                $elementIndex++
            }
            return $parameterValues
        }
        $isSectionIf = {
            param($Node)
            if (-not ($Node -is [Management.Automation.Language.IfStatementAst]) -or $Node.Clauses.Count -lt 1) { return $false }
            $conditionCommand = $Node.Clauses[0].Item1.Find({ param($inner) $inner -is [Management.Automation.Language.CommandAst] }, $true)
            return ($null -ne $conditionCommand -and $conditionCommand.GetCommandName() -eq 'Enter-BRAVOSelfTestSection')
        }
        $analyzeUnit = {
            param($UnitAst, [string]$Domain, [string]$Label)
            $unitSections = New-Object System.Collections.Generic.List[object]
            # ОДИН обхід дерева на одиницю: FindAll викликає предикат на КОЖЕН
            # вузол, тож предикат — лише дешеві перевірки типу, а класифікація
            # — уже по відібраних вузлах (див. Perf/SingleAstPassOverRepositoryFiles).
            $unitNodes = @($UnitAst.FindAll({ param($node)
                        $node -is [Management.Automation.Language.IfStatementAst] -or
                        $node -is [Management.Automation.Language.CommandAst] -or
                        $node -is [Management.Automation.Language.BreakStatementAst] -or
                        $node -is [Management.Automation.Language.ContinueStatementAst] -or
                        $node -is [Management.Automation.Language.ExitStatementAst] -or
                        $node -is [Management.Automation.Language.ReturnStatementAst] }, $true))
            $unitSectionIfs = @($unitNodes | Where-Object { $_ -is [Management.Automation.Language.IfStatementAst] -and (& $isSectionIf $_) })
            $unitBoundaryCalls = @($unitNodes | Where-Object { $_ -is [Management.Automation.Language.CommandAst] -and
                    @('Enter-BRAVOSelfTestSection', 'Register-BRAVOSelfTestSectionFault', 'Complete-BRAVOSelfTestSection') -contains $_.GetCommandName() })
            $unitJumps = @($unitNodes | Where-Object { -not ($_ -is [Management.Automation.Language.IfStatementAst]) -and
                    -not ($_ -is [Management.Automation.Language.CommandAst]) })
            foreach ($sectionIf in $unitSectionIfs) {
                $sectionProblem = ''
                $sectionName = ''
                $sectionDependsOn = @()
                $sectionPolicy = 'Continue'
                $conditionPipeline = $sectionIf.Clauses[0].Item1
                $enterCommand = $null
                if ($sectionIf.Clauses.Count -ne 1 -or $null -ne $sectionIf.ElseClause) {
                    $sectionProblem = 'межа має рівно одну гілку без else'
                } elseif (-not ($conditionPipeline -is [Management.Automation.Language.PipelineAst]) -or $conditionPipeline.PipelineElements.Count -ne 1) {
                    $sectionProblem = 'умова межі — лише виклик Enter-BRAVOSelfTestSection'
                } else {
                    $enterCommand = $conditionPipeline.PipelineElements[0]
                    $enterParameters = & $literalParameters $enterCommand
                    if ($null -eq $enterParameters -or -not $enterParameters.ContainsKey('Name') -or @($enterParameters['Name']).Count -ne 1) {
                        $sectionProblem = 'Enter-BRAVOSelfTestSection приймає лише літеральні -Name/-DependsOn/-Policy'
                    } else {
                        $sectionName = [string]$enterParameters['Name'][0]
                        if ($enterParameters.ContainsKey('DependsOn')) { $sectionDependsOn = @($enterParameters['DependsOn']) }
                        if ($enterParameters.ContainsKey('Policy')) { $sectionPolicy = [string]$enterParameters['Policy'][0] }
                        $unknownParameters = @($enterParameters.Keys | Where-Object { @('Name', 'DependsOn', 'Policy') -notcontains $_ })
                        if ($unknownParameters.Count -gt 0) { $sectionProblem = 'невідомий параметр межі: ' + [string]::Join(', ', $unknownParameters) }
                    }
                }
                $sectionBody = $sectionIf.Clauses[0].Item2
                if ([string]::IsNullOrEmpty($sectionProblem)) {
                    $sectionTry = if ($sectionBody.Statements.Count -eq 1) { $sectionBody.Statements[0] } else { $null }
                    if (-not ($sectionTry -is [Management.Automation.Language.TryStatementAst])) {
                        $sectionProblem = 'тіло межі — рівно один try'
                    } elseif ($sectionTry.CatchClauses.Count -ne 1 -or -not $sectionTry.CatchClauses[0].IsCatchAll -or
                        $sectionTry.CatchClauses[0].Body.Statements.Count -ne 1 -or
                        $sectionTry.CatchClauses[0].Body.Statements[0].Extent.Text -cne 'Register-BRAVOSelfTestSectionFault -ErrorRecord $_') {
                        $sectionProblem = 'catch межі — лише Register-BRAVOSelfTestSectionFault -ErrorRecord $_'
                    } elseif ($null -eq $sectionTry.Finally -or $sectionTry.Finally.Statements.Count -ne 1 -or
                        $sectionTry.Finally.Statements[0].Extent.Text -cne ("Complete-BRAVOSelfTestSection -Name '" + $sectionName + "'")) {
                        $sectionProblem = "finally межі — лише Complete-BRAVOSelfTestSection -Name '$sectionName'"
                    }
                }
                if (-not [string]::IsNullOrEmpty($sectionProblem)) {
                    [void]$boundaryProblems.WellFormed.Add(("{0}:{1} {2}: {3}" -f $Label, $sectionIf.Extent.StartLineNumber, $sectionName, $sectionProblem))
                }
                if ($sectionPolicy -ne 'Continue' -and $GlobalFatalAllowList -notcontains $sectionName) {
                    [void]$boundaryProblems.WellFormed.Add(("{0}:{1} {2}: -Policy {3} дозволено лише межам {4}" -f
                            $Label, $sectionIf.Extent.StartLineNumber, $sectionName, $sectionPolicy, [string]::Join(', ', $GlobalFatalAllowList)))
                }
                $parentSection = $sectionIf.Parent
                while ($null -ne $parentSection -and -not (& $isSectionIf $parentSection)) { $parentSection = $parentSection.Parent }
                [void]$unitSections.Add([pscustomobject]@{
                        Name      = $sectionName
                        DependsOn = $sectionDependsOn
                        Domain    = $Domain
                        Label     = $Label
                        Line      = $sectionIf.Extent.StartLineNumber
                        Ast       = $sectionIf
                        ParentAst = $parentSection
                        Parent    = ''
                    })
            }
            # Кожен виклик межевих функцій — лише всередині канонічної форми.
            foreach ($boundaryCall in $unitBoundaryCalls) {
                $owningFunction = $boundaryCall.Parent
                while ($null -ne $owningFunction -and -not ($owningFunction -is [Management.Automation.Language.FunctionDefinitionAst])) { $owningFunction = $owningFunction.Parent }
                if ($null -ne $owningFunction) { continue }
                $owningSection = $boundaryCall.Parent
                while ($null -ne $owningSection -and -not (& $isSectionIf $owningSection)) { $owningSection = $owningSection.Parent }
                $isCanonicalCall = $false
                if ($null -ne $owningSection) {
                    $owningTry = $owningSection.Clauses[0].Item2.Statements | Select-Object -First 1
                    $isCanonicalCall = ($boundaryCall.Parent -eq $owningSection.Clauses[0].Item1) -or
                        ($owningTry -is [Management.Automation.Language.TryStatementAst] -and
                        (($owningTry.CatchClauses.Count -gt 0 -and $boundaryCall.Parent.Parent -eq $owningTry.CatchClauses[0].Body) -or
                         ($null -ne $owningTry.Finally -and $boundaryCall.Parent.Parent -eq $owningTry.Finally)))
                }
                if (-not $isCanonicalCall) {
                    [void]$boundaryProblems.WellFormed.Add(("{0}:{1}: {2} поза канонічною формою межі" -f $Label, $boundaryCall.Extent.StartLineNumber, $boundaryCall.GetCommandName()))
                }
            }
            # Стрибки на рівні файлу: break/continue поза циклом чи switch,
            # exit/return поза функцією чи scriptblock-ом.
            # У корені — лише всередині секцій: bootstrap до головного try
            # законно завершується exit 1 (глобальна межа 1).
            foreach ($jumpNode in $unitJumps) {
                    $isLoopJump = $jumpNode -is [Management.Automation.Language.BreakStatementAst] -or $jumpNode -is [Management.Automation.Language.ContinueStatementAst]
                    $jumpAncestor = $jumpNode.Parent
                    $jumpContained = $false
                    $jumpInSection = ($Domain -ne 'root')
                    while ($null -ne $jumpAncestor) {
                        if (-not $jumpInSection -and $jumpAncestor -is [Management.Automation.Language.IfStatementAst] -and (& $isSectionIf $jumpAncestor)) {
                            $jumpInSection = $true
                        }
                        if ($jumpAncestor -is [Management.Automation.Language.FunctionDefinitionAst] -or
                            $jumpAncestor -is [Management.Automation.Language.ScriptBlockExpressionAst] -or
                            ($isLoopJump -and $jumpAncestor -is [Management.Automation.Language.LabeledStatementAst])) {
                            $jumpContained = $true
                            break
                        }
                        $jumpAncestor = $jumpAncestor.Parent
                    }
                    if ($jumpContained -or -not $jumpInSection) { continue }
                    [void]$boundaryProblems.Jumps.Add(("{0}:{1}: {2}" -f $Label, $jumpNode.Extent.StartLineNumber, $jumpNode.Extent.Text))
            }
            return @($unitSections.ToArray())
        }

        # --- Корінь: секції, покриття основного тіла й хвоста, каркас ----
        $orderedSections = New-Object System.Collections.Generic.List[object]
        $rootSections = @(& $analyzeUnit $RootAst 'root' 'BRAVO_SELF_TEST.ps1')
        $rootTop = @($RootAst.EndBlock.Statements)
        $outerTry = @($rootTop | Where-Object {
                $_ -is [Management.Automation.Language.TryStatementAst] -and
                @($_.Body.Statements).Count -gt 0 -and $_.Body.Statements[0] -is [Management.Automation.Language.TryStatementAst] })
        if ($outerTry.Count -ne 1 -or -not [object]::ReferenceEquals($outerTry[0], $rootTop[$rootTop.Count - 1])) {
            [void]$boundaryProblems.Skeleton.Add('зовнішній try з головним try першим оператором мусить бути один і останнім оператором файлу')
        } else {
            $outer = $outerTry[0]
            $mainTry = $outer.Body.Statements[0]
            $outerStatements = @($outer.Body.Statements)
            if ($mainTry.CatchClauses.Count -ne 1 -or $mainTry.CatchClauses[0].Body.Statements.Count -ne 1 -or
                $mainTry.CatchClauses[0].Body.Statements[0].Extent.Text -cne 'Register-BRAVOSelfTestGlobalFatal -ErrorRecord $_' -or
                $null -ne $mainTry.Finally) {
                [void]$boundaryProblems.Skeleton.Add('головний catch — лише Register-BRAVOSelfTestGlobalFatal -ErrorRecord $_, без finally')
            }
            if ($outer.CatchClauses.Count -ne 1 -or -not $outer.CatchClauses[0].IsCatchAll -or
                $outer.CatchClauses[0].Body.Statements.Count -ne 1 -or
                $outer.CatchClauses[0].Body.Statements[0].Extent.Text -cne 'Complete-BRAVOSelfTestAbnormalExit -ErrorRecord $_') {
                [void]$boundaryProblems.Skeleton.Add('зовнішній catch — лише Complete-BRAVOSelfTestAbnormalExit -ErrorRecord $_')
            }
            $outerFinallyText = if ($null -ne $outer.Finally) { [string]$outer.Finally.Extent.Text } else { '' }
            if (-not ($outerFinallyText.Contains('$script:BRAVOSelfTestReportIssued') -and
                    $outerFinallyText.Contains('$script:BRAVOSelfTestAbnormalExitStarted') -and
                    $outerFinallyText.Contains('Complete-BRAVOSelfTestAbnormalExit -ErrorRecord $null'))) {
                [void]$boundaryProblems.Skeleton.Add('зовнішній finally мусить гарантувати Complete-BRAVOSelfTestAbnormalExit, якщо звіт не видано')
            }
            if ($outerStatements.Count -lt 3 -or
                (& $commandNameOf $outerStatements[$outerStatements.Count - 2]) -ne 'Invoke-BRAVOSelfTestFinalCleanup' -or
                (& $commandNameOf $outerStatements[$outerStatements.Count - 1]) -ne 'Complete-BRAVOSelfTestReport') {
                [void]$boundaryProblems.Skeleton.Add('зовнішній try завершується Invoke-BRAVOSelfTestFinalCleanup і Complete-BRAVOSelfTestReport')
            }
            $sectionAstSet = @{}
            foreach ($rootSection in $rootSections) { $sectionAstSet[$rootSection.Ast.Extent.StartOffset] = $rootSection }
            $checkCovered = {
                param($Statement, [bool]$AllowGate)
                if ($sectionAstSet.ContainsKey($Statement.Extent.StartOffset) -and [object]::ReferenceEquals($sectionAstSet[$Statement.Extent.StartOffset].Ast, $Statement)) { return $true }
                if ((& $commandNameOf $Statement) -eq 'Enter-BRAVOSelfTestSuite') { return $true }
                if ($AllowGate -and $Statement -is [Management.Automation.Language.IfStatementAst] -and $Statement.Clauses.Count -eq 1 -and
                    $null -eq $Statement.ElseClause -and
                    $Statement.Clauses[0].Item1.Extent.Text -match "^Test-BRAVOSelfTestSuiteEnabled -Name '([^']+)'$") {
                    $gateSuite = $Matches[1]
                    $gateBody = @($Statement.Clauses[0].Item2.Statements)
                    return ($gateBody.Count -eq 2 -and
                        $gateBody[0].Extent.Text -ceq ("Enter-BRAVOSelfTestSuite -Name '" + $gateSuite + "'") -and
                        $sectionAstSet.ContainsKey($gateBody[1].Extent.StartOffset) -and
                        $sectionAstSet[$gateBody[1].Extent.StartOffset].Name -eq ('Suite/' + $gateSuite))
                }
                return $false
            }
            foreach ($mainStatement in @($mainTry.Body.Statements)) {
                if (-not (& $checkCovered $mainStatement $true)) {
                    [void]$boundaryProblems.Coverage.Add(("BRAVO_SELF_TEST.ps1:{0}: оператор основного тіла поза секцією" -f $mainStatement.Extent.StartLineNumber))
                }
            }
            for ($outerIndex = 1; $outerIndex -lt $outerStatements.Count - 2; $outerIndex++) {
                if (-not (& $checkCovered $outerStatements[$outerIndex] $false)) {
                    [void]$boundaryProblems.Coverage.Add(("BRAVO_SELF_TEST.ps1:{0}: оператор хвоста поза секцією" -f $outerStatements[$outerIndex].Extent.StartLineNumber))
                }
            }
        }

        # --- Порядок виконання: фрагмент — усередині своєї Suite/<Ім'я> ---
        foreach ($rootSection in $rootSections) {
            [void]$orderedSections.Add($rootSection)
            if ($rootSection.Name -like 'Suite/*') {
                $fragmentName = $rootSection.Name.Substring(6)
                $rootSection.Domain = $fragmentName
                if (-not $FragmentAst.ContainsKey($fragmentName)) {
                    [void]$boundaryProblems.WellFormed.Add("секція $($rootSection.Name) без фрагмента $fragmentName")
                    continue
                }
                foreach ($fragmentSection in @(& $analyzeUnit $FragmentAst[$fragmentName] $fragmentName ("BRAVO_SELF_TEST.$fragmentName.ps1"))) {
                    if ($null -eq $fragmentSection.ParentAst) { $fragmentSection.Parent = $rootSection.Name }
                    [void]$orderedSections.Add($fragmentSection)
                }
            }
        }
        $sectionPosition = @{}
        $sectionByAst = New-Object 'System.Collections.Generic.Dictionary[object,object]'
        foreach ($orderedSection in $orderedSections) { $sectionByAst[$orderedSection.Ast] = $orderedSection }
        for ($orderIndex = 0; $orderIndex -lt $orderedSections.Count; $orderIndex++) {
            $orderedSection = $orderedSections[$orderIndex]
            if ($null -ne $orderedSection.ParentAst -and $sectionByAst.ContainsKey($orderedSection.ParentAst)) {
                $orderedSection.Parent = $sectionByAst[$orderedSection.ParentAst].Name
            }
            if ([string]::IsNullOrEmpty($orderedSection.Name)) { continue }
            if ($sectionPosition.ContainsKey($orderedSection.Name)) {
                [void]$boundaryProblems.WellFormed.Add(("{0}:{1}: ім'я секції {2} повторюється" -f $orderedSection.Label, $orderedSection.Line, $orderedSection.Name))
                continue
            }
            $sectionPosition[$orderedSection.Name] = $orderIndex
        }
        foreach ($orderedSection in $orderedSections) {
            $ancestorNames = New-Object System.Collections.Generic.List[string]
            $ancestorName = $orderedSection.Parent
            while (-not [string]::IsNullOrEmpty($ancestorName) -and $ancestorNames.Count -lt 64) {
                [void]$ancestorNames.Add($ancestorName)
                $ancestorRecord = if ($sectionPosition.ContainsKey($ancestorName)) { $orderedSections[$sectionPosition[$ancestorName]] } else { $null }
                $ancestorName = if ($null -ne $ancestorRecord) { $ancestorRecord.Parent } else { '' }
            }
            foreach ($dependencyName in @($orderedSection.DependsOn)) {
                $dependencyProblem = ''
                if (-not $sectionPosition.ContainsKey($dependencyName)) {
                    $dependencyProblem = 'невідома секція'
                } elseif ($sectionPosition[$dependencyName] -ge $sectionPosition[$orderedSection.Name]) {
                    $dependencyProblem = 'виконується не раніше залежної'
                } elseif ($ancestorNames.Contains($dependencyName)) {
                    $dependencyProblem = 'є її власною зовнішньою секцією'
                } else {
                    $dependencyDomain = $orderedSections[$sectionPosition[$dependencyName]].Domain
                    if ($dependencyDomain -ne 'root' -and $dependencyDomain -ne $orderedSection.Domain) {
                        $dependencyProblem = "належить gated suite $dependencyDomain — у вибірковому прогоні її може не бути"
                    }
                }
                if (-not [string]::IsNullOrEmpty($dependencyProblem)) {
                    [void]$boundaryProblems.WellFormed.Add(("{0}:{1}: {2} -DependsOn '{3}' {4}" -f
                            $orderedSection.Label, $orderedSection.Line, $orderedSection.Name, $dependencyName, $dependencyProblem))
                }
            }
        }
        return [pscustomobject]@{
            Problems     = $boundaryProblems
            SectionCount = $orderedSections.Count
        }
    }

    $boundaryParse = {
        param([string]$Text)
        $fixtureTokens = $null
        $fixtureErrors = $null
        $fixtureAst = [Management.Automation.Language.Parser]::ParseInput($Text, [ref]$fixtureTokens, [ref]$fixtureErrors)
        if (@($fixtureErrors).Count -gt 0) { throw 'синтаксична помилка у фікстурі guard-а меж' }
        return $fixtureAst
    }
    $boundaryAllowList = @('Bootstrap/RuntimeGuard', 'Phase0')

    # --- Реальне джерело ---------------------------------------------------
    $boundaryResult = $null
    $boundaryError = $null
    try {
        $boundaryFragmentAst = @{}
        foreach ($boundaryFragmentFile in @(Get-ChildItem -LiteralPath (Join-Path $root 'selftest') -Filter 'BRAVO_SELF_TEST.*.ps1' -File)) {
            $boundaryTokens = $null
            $boundaryErrors = $null
            $boundaryParsed = [Management.Automation.Language.Parser]::ParseFile(
                $boundaryFragmentFile.FullName, [ref]$boundaryTokens, [ref]$boundaryErrors)
            if (@($boundaryErrors).Count -gt 0) { throw "синтаксичні помилки у $($boundaryFragmentFile.Name)" }
            $boundaryFragmentAst[($boundaryFragmentFile.Name -replace '^BRAVO_SELF_TEST\.', '' -replace '\.ps1$', '')] = $boundaryParsed
        }
        $boundaryResult = & $boundaryAnalyze -RootAst (Get-BRAVOSelfTestOwnSourceAst) -FragmentAst $boundaryFragmentAst `
            -GlobalFatalAllowList $boundaryAllowList
    } catch {
        $boundaryError = $_.Exception.Message
    }
    $boundaryReport = {
        param($Result, [string]$Category)
        if ($null -eq $Result) { return 'н/д' }
        $categoryProblems = @($Result.Problems[$Category])
        if ($categoryProblems.Count -eq 0) { return 'немає' }
        return ([string]::Join('; ', @($categoryProblems | Select-Object -First 5)) +
            $(if ($categoryProblems.Count -gt 5) { " … ще $($categoryProblems.Count - 5)" } else { '' }))
    }
    foreach ($boundaryCheck in @(
            @{ Category = 'WellFormed'; Name = 'Framework/SectionBoundariesAreWellFormed'
                Failure = 'кожна межа — канонічна форма з літеральним унікальним іменем; -DependsOn — на раніше виконану секцію кореня чи того самого suite; GlobalFatal — лише для дозволених меж' },
            @{ Category = 'Coverage'; Name = 'Framework/SectionsCoverMainBodyAndTail'
                Failure = 'кожен оператор основного тіла й хвоста — секція, гейт фрагмента з Suite/<Ім''я> або Enter-BRAVOSelfTestSuite' },
            @{ Category = 'Jumps'; Name = 'Framework/NoFileLevelJumpInSectionsOrFragments'
                Failure = 'break/continue поза циклом і exit/return поза функцією в секції чи фрагменті обходять межу й звіт' },
            @{ Category = 'Skeleton'; Name = 'Framework/GuaranteedTerminalPathSkeleton'
                Failure = 'зовнішній try/catch/finally мусить гарантувати звіт або мінімальний SELF-TEST FAILED із кодом 1' })) {
        Test-BRAVOCondition `
            -Condition ($null -eq $boundaryError -and $null -ne $boundaryResult -and
                $boundaryResult.SectionCount -gt 0 -and @($boundaryResult.Problems[$boundaryCheck.Category]).Count -eq 0) `
            -Name $boundaryCheck.Name `
            -Failure ($boundaryCheck.Failure + '. Помилка: [' + [string]$boundaryError + ']; знайдено: ' + (& $boundaryReport $boundaryResult $boundaryCheck.Category))
    }

    # --- IsMeaningful: зламаний і чистий синтетичні варіанти ----------------
    $boundaryFixtureError = $null
    $boundaryDirty = $null
    $boundaryClean = $null
    try {
        # Рядки меж складаються форматом, а не лежать дослівно: інакше
        # guard-и, що читають сирий текст цього файлу, бачили б їх як справжні.
        $boundaryOpen = "if (Enter-BRAVOSelfTestSection -Name '{0}'{1}) {{ try {{"
        $boundaryClose = "}} catch {{ Register-BRAVOSelfTestSectionFault -ErrorRecord `$_ }} finally {{ Complete-BRAVOSelfTestSection -Name '{0}' }} }}"
        $boundaryGate = "if (Test-BRAVOSelfTestSuiteEnabled -Name 'Alpha') {`n    Enter-BRAVOSelfTestSuite -Name 'Alpha'`n    " +
            ($boundaryOpen -f 'Suite/Alpha', '') + "`n    . (Join-Path `$root 'x.ps1')`n    " + ($boundaryClose -f 'Suite/Alpha') + "`n}"
        $boundarySkeleton = "try {{`ntry {{`n{0}`n}} catch {{ Register-BRAVOSelfTestGlobalFatal -ErrorRecord `$_ }}`n{1}`n" +
            "Invoke-BRAVOSelfTestFinalCleanup`nComplete-BRAVOSelfTestReport`n}} catch {{ Complete-BRAVOSelfTestAbnormalExit -ErrorRecord `$_ }} " +
            "finally {{ if (-not `$script:BRAVOSelfTestReportIssued -and -not `$script:BRAVOSelfTestAbnormalExitStarted) {{ Complete-BRAVOSelfTestAbnormalExit -ErrorRecord `$null }} }}"
        $boundaryCleanRoot = $boundarySkeleton -f (
            ($boundaryOpen -f 'Root/A', '') + "`n`$a = 1`n" + ($boundaryClose -f 'Root/A') + "`n" +
            $boundaryGate + "`nEnter-BRAVOSelfTestSuite -Name 'Root (inline)'`n" +
            ($boundaryOpen -f 'Root/B', " -DependsOn 'Root/A'") + "`nforeach (`$i in 1) { break }`n" + ($boundaryClose -f 'Root/B')),
            (($boundaryOpen -f 'Tail/C', '') + "`n`$c = 1`n" + ($boundaryClose -f 'Tail/C'))
        $boundaryCleanFragment = ($boundaryOpen -f 'Alpha/X', '') + "`n& { return }`n" + ($boundaryClose -f 'Alpha/X') + "`nfunction F { exit 1 }"
        # Зламаний: оператор поза секцією, неканонічний catch, повтор імені,
        # залежність від пізнішої секції і від іншого gated suite, заборонена
        # GlobalFatal, break і return на рівні файлу, голий хвіст без каркаса.
        $boundaryDirtyRoot = ($boundarySkeleton -f (
                ($boundaryOpen -f 'Root/A', " -DependsOn 'Root/B'") + "`n`$a = 1`n} catch { } finally { Complete-BRAVOSelfTestSection -Name 'Root/A' } }`n" +
                "`$outside = 1`n" + $boundaryGate + "`n" +
                ($boundaryOpen -f 'Root/B', " -DependsOn 'Alpha/X' -Policy GlobalFatal") + "`nbreak`n" + ($boundaryClose -f 'Root/B') + "`n" +
                ($boundaryOpen -f 'Root/B', '') + "`n`$b = 2`n" + ($boundaryClose -f 'Root/B')),
            "`$tailOutside = 1").Replace('catch { Complete-BRAVOSelfTestAbnormalExit -ErrorRecord $_ }', 'catch { }')
        $boundaryDirtyFragment = ($boundaryOpen -f 'Alpha/X', '') + "`n`$x = 1`n" + ($boundaryClose -f 'Alpha/X') + "`nreturn"
        $boundaryDirty = & $boundaryAnalyze -RootAst (& $boundaryParse $boundaryDirtyRoot) `
            -FragmentAst @{ Alpha = (& $boundaryParse $boundaryDirtyFragment) } -GlobalFatalAllowList $boundaryAllowList
        $boundaryClean = & $boundaryAnalyze -RootAst (& $boundaryParse $boundaryCleanRoot) `
            -FragmentAst @{ Alpha = (& $boundaryParse $boundaryCleanFragment) } -GlobalFatalAllowList $boundaryAllowList
    } catch {
        $boundaryFixtureError = $_.Exception.Message
    }
    $boundaryDirtyWellFormed = if ($null -ne $boundaryDirty) { [string]::Join('; ', @($boundaryDirty.Problems.WellFormed)) } else { '' }
    $boundaryCleanTotal = if ($null -ne $boundaryClean) {
        @($boundaryClean.Problems.Values | ForEach-Object { @($_) }).Count
    } else { -1 }
    Test-BRAVOCondition `
        -Condition (
            $null -eq $boundaryFixtureError -and $null -ne $boundaryDirty -and
            $boundaryDirtyWellFormed.Contains('catch межі') -and
            $boundaryDirtyWellFormed.Contains('Root/B повторюється') -and
            $boundaryDirtyWellFormed.Contains("-DependsOn 'Root/B' виконується не раніше залежної") -and
            $boundaryDirtyWellFormed.Contains("-DependsOn 'Alpha/X' належить gated suite Alpha") -and
            $boundaryDirtyWellFormed.Contains('-Policy GlobalFatal') -and
            @($boundaryDirty.Problems.Coverage).Count -gt 0 -and
            @($boundaryDirty.Problems.Jumps | Where-Object { $_ -like '*: break' }).Count -eq 1 -and
            @($boundaryDirty.Problems.Jumps | Where-Object { $_ -like '*: return' }).Count -eq 1 -and
            @($boundaryDirty.Problems.Skeleton).Count -gt 0 -and
            $boundaryCleanTotal -eq 0
        ) `
        -Name 'Framework/SectionBoundaryGuardsAreMeaningful' `
        -Failure ("guard-и меж мусять знаходити кожен клас синтетичного порушення і нуль у чистому варіанті. Помилка: [" +
            [string]$boundaryFixtureError + "]; WellFormed: [" + $boundaryDirtyWellFormed + "]; Coverage: [" + (& $boundaryReport $boundaryDirty 'Coverage') +
            "]; Jumps: [" + (& $boundaryReport $boundaryDirty 'Jumps') + "]; Skeleton: [" + (& $boundaryReport $boundaryDirty 'Skeleton') +
            "]; у чистому варіанті: $boundaryCleanTotal (" + $(if ($null -ne $boundaryClean) {
                    [string]::Join('; ', @($boundaryClean.Problems.Values | ForEach-Object { @($_) })) } else { 'н/д' }) + ')')
}
} catch { Register-BRAVOSelfTestSectionFault -ErrorRecord $_ } finally { Complete-BRAVOSelfTestSection -Name 'Tail/Framework.SectionBoundaries' } }

# P0 fail-fast/telemetry: увесь попередній inline reporting/exit-хвіст
# (exit-code formula, operator summary, SELF-TEST PASSED/FAILED, Complete-
# BRAVOHelperLog/Wait-BRAVOManualExit) екстрагований 1:1 у
# Complete-BRAVOSelfTestReport (визначена вище, перед головним try) —
# та сама функція, що й Phase-0-FAIL short-circuit вище викликає.
# #219 (частина B): перед звітом — ідемпотентне гарантоване прибирання
# (owned runtime modules, config root) навіть якщо його секції хвоста було
# перервано чи пропущено.
Invoke-BRAVOSelfTestFinalCleanup
Complete-BRAVOSelfTestReport
} catch {
    Complete-BRAVOSelfTestAbnormalExit -ErrorRecord $_
} finally {
    # Get-Variable, а не пряме читання: Framework/SectionIsolation-проби
    # копіюють цей finally у дочірній скрипт під Set-StrictMode, де змінна
    # не оголошена.
    [Environment]::SetEnvironmentVariable('BRAVO_SELFTEST_SIMULATED_OUTPUT',
        (Get-Variable -Name 'selfTestSimulatedOutputPrevious' -Scope Script -ValueOnly -ErrorAction SilentlyContinue))
    # Штатний шлях завершується exit усередині Complete-BRAVOHelperLog
    # (ReportIssued уже $true). Сюди без звіту потрапляє лише прогін,
    # що вийшов із тіла в обхід catch — він теж не може дати код 0.
    if (-not $script:BRAVOSelfTestReportIssued -and -not $script:BRAVOSelfTestAbnormalExitStarted) {
        Complete-BRAVOSelfTestAbnormalExit -ErrorRecord $null
    }
}
